def _camera_measurement_payload(raw_measurement: Any) -> dict[str, Any] | None:
    """Copy scalar camera data shared by the online consumer and recordings."""
    if not isinstance(raw_measurement, dict):
        return None
    measurement: dict[str, Any] = {}
    for key in _CAMERA_MEASUREMENT_SCALAR_KEYS:
        value = raw_measurement.get(key)
        if value is None or isinstance(value, (str, bool)):
            measurement[key] = value
        elif isinstance(value, (int, float, np.number)):
            number = float(value)
            # These are covariance entries in m^2 / (m/s)^2. Six decimal
            # places can erase a small variance or change its uncertainty
            # gate. Preserve their numerical precision across camera IPC.
            precision_sensitive = key in ('observation_position_variance',
                'observation_velocity_variance', 'observation_cross_covariance')
            measurement[key] = (number if precision_sensitive else round(number, 6)) if np.isfinite(number) else None
    return measurement or None


def _overlay_policy_trace_joint_feedback(
    ros_payload: dict[str, Any],
    trace: dict[str, Any],
    policy_obs: np.ndarray,
) -> bool:
    """Label recorded feedback with the exact sample consumed by inference."""
    timing = trace.get("jointFeedbackTiming")
    if not isinstance(timing, dict) or not timing:
        return False
    ros_payload.update(timing)
    obs = np.asarray(policy_obs, dtype=np.float32).reshape(-1)
    if obs.shape[0] < 14:
        ros_payload["jointTimingMatchesPolicyObs"] = False
        return False
    # A JointState callback may run after inference but before recording. Keep
    # the atomic raw sample in the ROS fields even when policy-only dq
    # adaptation or observation scaling changes the vector consumed by the
    # actor. This prevents calibrated/scaled dq from being mislabeled as
    # hardware JointState velocity in later sim2real analysis.
    obs_unscaled = np.asarray(
        trace.get("obsUnscaled", obs), dtype=np.float32).reshape(-1)
    raw_q = trace.get("rawJointPosition")
    raw_dq = trace.get("rawJointVelocity")
    if raw_q is None:
        raw_q = obs_unscaled[0:7]
    if raw_dq is None:
        raw_dq = obs_unscaled[7:14]
    raw_q = np.asarray(raw_q, dtype=np.float32).reshape(-1)
    raw_dq = np.asarray(raw_dq, dtype=np.float32).reshape(-1)
    if raw_q.shape != (7,) or raw_dq.shape != (7,):
        ros_payload["jointTimingMatchesPolicyObs"] = False
        return False
    policy_dq_unscaled = obs_unscaled[7:14]
    policy_dq_scaled = obs[7:14]
    ros_payload["jointPosition"] = _rounded_vector(raw_q)
    ros_payload["jointVelocity"] = _rounded_vector(raw_dq)
    ros_payload["jointVelocityRaw"] = _rounded_vector(raw_dq)
    ros_payload["policyJointVelocityUnscaled"] = _rounded_vector(
        policy_dq_unscaled)
    ros_payload["policyJointVelocityScaled"] = _rounded_vector(
        policy_dq_scaled)
    ros_payload["jointVelocityMatchesPolicyObsUnscaled"] = bool(
        np.array_equal(raw_dq, policy_dq_unscaled))
    ros_payload["jointTimingMatchesPolicyObs"] = True
    return True


def _reset_initial_pose_id(value: Any) -> str:
    preset = str(value or RESET_INITIAL_POSE_DEFAULT).strip().lower()
    preset = preset.replace("-", "_").replace(" ", "_")
    if preset == RESET_INITIAL_POSE_FPLC:
        return RESET_INITIAL_POSE_FPLC
    if preset in {
            "1", "default1", "default_1", "config1", "config_1",
            "preset1", "preset_1"}:
        return RESET_INITIAL_POSE_DEFAULT
    if preset in {
            "2", "default2", "default_2", "config2", "config_2",
            "preset2", "preset_2", "horizontal", "level",
            "default_2_horizontal"}:
        return RESET_INITIAL_POSE_HORIZONTAL
    return RESET_INITIAL_POSE_DEFAULT


def _reset_initial_pose_q_rad(preset: Any) -> tuple[str, np.ndarray]:
    preset_id = _reset_initial_pose_id(preset)
    if preset_id == RESET_INITIAL_POSE_FPLC:
        raise ValueError("simcode9_native reset requires the selected FPLC controller")
    if preset_id == RESET_INITIAL_POSE_HORIZONTAL:
        q = np.deg2rad(RESET_HORIZONTAL_RIGHT_ARM_Q_DEG)
    else:
        q = target_right_arm_q_rad()
    return preset_id, np.asarray(q, dtype=np.float64).reshape(
        len(RIGHT_ARM_JOINTS))


def _reset_initial_pose_presets_payload(fplc_controller=None) -> dict[str, Any]:
    presets = []
    for preset_id, label in (
            (RESET_INITIAL_POSE_DEFAULT, "Default 1"),
            (RESET_INITIAL_POSE_HORIZONTAL, "Default 2 horizontal")):
        _selected_id, q_rad = _reset_initial_pose_q_rad(preset_id)
        presets.append({
            "id": preset_id,
            "label": label,
            "rightArmJointPositionRad": _rounded_vector(q_rad),
            "rightArmJointPositionDeg": _rounded_vector(np.rad2deg(q_rad), 3),
        })
    native = {"id": RESET_INITIAL_POSE_FPLC, "label": "FPLC native racket-launch (simcode9/10)"}
    if fplc_controller is not None:
        native.update({
            "rightArmJointPositionRad": _rounded_vector(fplc_controller.native_reset_arm_q),
            "rightArmJointPositionDeg": _rounded_vector(np.rad2deg(fplc_controller.native_reset_arm_q), 3),
            "racketPositionM": _rounded_vector(fplc_controller.native_reset_position_m),
        })
    presets.append(native)
    return {
        "default": RESET_INITIAL_POSE_FPLC if fplc_controller is not None else RESET_INITIAL_POSE_DEFAULT,
        "presets": presets,
    }


def _write_jsonl(handle, payload: dict[str, Any]) -> None:
    handle.write(json.dumps(payload, separators=(",", ":")) + "\n")


def _strict_json_dumps(payload: Any, **kwargs: Any) -> str:
    """Serialize browser-facing data as standards-compliant JSON."""
    def finite_or_none(value: Any) -> Any:
        if isinstance(value, (float, np.floating)):
            number = float(value)
            return number if math.isfinite(number) else None
        if isinstance(value, np.integer):
            return int(value)
        if isinstance(value, np.bool_):
            return bool(value)
        if isinstance(value, dict):
            return {key: finite_or_none(item) for key, item in value.items()}
        if isinstance(value, (list, tuple)):
            return [finite_or_none(item) for item in value]
        return value

    return json.dumps(finite_or_none(payload), allow_nan=False, **kwargs)


def _policy_release_contract_payload() -> dict[str, Any]:
    raw = os.environ.get("POLICY_RELEASE_CONTRACT_JSON", "")
    if not raw:
        return {"validated": False, "reason": "contract_environment_missing"}
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError as exc:
        return {"validated": False, "reason": f"invalid_contract_json: {exc}"}
    if not isinstance(payload, dict):
        return {"validated": False, "reason": "contract_not_object"}
    return dict(payload)


def _recording_writer_main(
    run_dir_text: str,
    event_q,
    status_q,
    metadata: dict[str, Any],
) -> None:
    # Writing recordings must always lose CPU scheduling priority to the
    # controller.  This is best-effort because nice(2) may be unavailable on
    # non-POSIX hosts, while an inability to lower priority is not fatal.
    try:
        os.nice(10)
    except (AttributeError, OSError):
        pass
    if not run_dir_text:
        # The writer is spawned before the control loop starts, then waits for
        # a recording request.  This keeps Python/JAX module import completely
        # outside the live 200 Hz interval.
        try:
            configure = event_q.get()
        except (EOFError, OSError, KeyboardInterrupt):
            return
        if not isinstance(configure, dict):
            return
        if str(configure.get("kind", "")) == "shutdown":
            return
        if str(configure.get("kind", "")) != "configure":
            return
        run_dir_text = str(configure.get("runDir", ""))
        configured_metadata = configure.get("metadata")
        if not run_dir_text or not isinstance(configured_metadata, dict):
            return
        metadata = dict(configured_metadata)
    run_dir = Path(run_dir_text)
    frames_dir = run_dir / "frames"
    sim_frames_dir = run_dir / "sim_frames"
    counts = {
        "control": 0,
        "ballSensors": 0,
        "simControl": 0,
        "snapshots": 0,
        "views": 0,
        "frames": 0,
        "simFrames": 0,
        "events": 0,
    }
    started_wall = time.time()
    parent_dropped = 0
    juggle_counter = RecordingJuggleCounter()
    save_camera_images = bool(metadata.get("recording", {}).get("saveCameraImages", True))
    trajectory_only = bool(metadata.get("recording", {}).get("trajectoryOnly", False))

    def publish_status(active: bool, error: str | None = None) -> None:
        _queue_replace_latest(status_q, {
            "active": bool(active),
            "runDir": str(run_dir),
            "counts": dict(counts),
            "elapsedS": round(float(time.time() - started_wall), 3),
            "saveCameraImages": save_camera_images,
            "trajectoryOnly": trajectory_only,
            "juggle": juggle_counter.summary(complete=not active, dropped=parent_dropped),
            "error": error,
        })

    try:
        run_dir.mkdir(parents=True, exist_ok=True)
        if save_camera_images:
            frames_dir.mkdir(parents=True, exist_ok=True)
        if not trajectory_only:
            sim_frames_dir.mkdir(parents=True, exist_ok=True)
        metadata = dict(metadata)
        metadata["runDir"] = str(run_dir)
        metadata["startedWallTimeS"] = started_wall
        metadata["startedLocalTime"] = time.strftime(
            "%Y-%m-%d %H:%M:%S", time.localtime(started_wall))
        (run_dir / "metadata.json").write_text(
            json.dumps(metadata, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        with ExitStack() as files:
            def open_log(name, enabled=True):
                return (files.enter_context((run_dir / name).open("a", buffering=1, encoding="utf-8"))
                        if enabled else None)
            control_f = open_log("control_samples.jsonl")
            ball_sensors_f = open_log("ball_sensor_samples.jsonl", not trajectory_only)
            sim_control_f = open_log("sim_control_samples.jsonl", not trajectory_only)
            snapshots_f = open_log("snapshots.jsonl", not trajectory_only)
            views_f = open_log("browser_view.jsonl", not trajectory_only)
            frames_f = open_log("frames.jsonl", not trajectory_only or save_camera_images)
            sim_frames_f = open_log("sim_frames.jsonl", not trajectory_only)
            events_f = open_log("events.jsonl")
            publish_status(True)
            next_status_wall = time.time() + 0.5
            running = True
            while running:
                try:
                    item = event_q.get(timeout=0.25)
                except Empty:
                    item = None
                if isinstance(item, dict):
                    kind = str(item.get("kind", ""))
                    if kind == "stop":
                        parent_dropped = max(
                            0, int(item.get("dropped", 0) or 0))
                        running = False
                    elif kind == "control":
                        sample = dict(item.get("sample", {}))
                        sensor_snapshot = sample.pop("_ballSensorSnapshot", None)
                        if sensor_snapshot is not None:
                            sample["ballSensors"] = complete_ball_sensor_recording_snapshot(sensor_snapshot)
                        if trajectory_only:
                            sample = compact_trajectory_sample(sample)
                        _write_jsonl(control_f, sample)
                        counts["control"] += 1
                        bounce = juggle_counter.consume(sample)
                        if bounce is not None:
                            _write_jsonl(events_f, bounce)
                            counts["events"] += 1
                        sensors = sample.get("ballSensors")
                        if isinstance(sensors, dict) and not trajectory_only:
                            _write_jsonl(ball_sensors_f, {
                                key: sample.get(key) for key in (
                                    "schemaVersion", "sourceSeq", "sourceTimeS",
                                    "wallTimeS", "time", "tick", "ballSource",
                                )
                            } | sensors)
                            counts["ballSensors"] += 1
                    elif kind == "sim_control_batch" and not trajectory_only:
                        samples = item.get("samples", [])
                        if isinstance(samples, list):
                            for sample in samples:
                                if isinstance(sample, dict):
                                    _write_jsonl(sim_control_f, sample)
                                    counts["simControl"] += 1
                    elif kind == "snapshot" and not trajectory_only:
                        _write_jsonl(snapshots_f, item.get("snapshot", {}))
                        counts["snapshots"] += 1
                    elif kind == "view" and not trajectory_only:
                        _write_jsonl(views_f, item.get("view", {}))
                        counts["views"] += 1
                    elif kind == "frame" and save_camera_images:
                        frame = item.get("frame")
                        info = item.get("info", {})
                        if isinstance(frame, (bytes, bytearray)):
                            counts["frames"] += 1
                            seq = int((info or {}).get("seq", 0) or 0)
                            filename = (
                                f"frame_{counts['frames']:06d}_seq_{seq:06d}.jpg")
                            rel_path = f"frames/{filename}"
                            (frames_dir / filename).write_bytes(bytes(frame))
                            capture_wall_time = (info or {}).get("wallTimeS")
                            try:
                                capture_wall_time = float(capture_wall_time)
                            except (TypeError, ValueError):
                                capture_wall_time = time.time()
                            row = {
                                "wallTimeS": round(capture_wall_time, 6),
                                "path": rel_path,
                                "bytes": len(frame),
                                "info": dict(info) if isinstance(info, dict) else {},
                            }
                            _write_jsonl(frames_f, row)
                    elif kind == "sim_frame" and not trajectory_only:
                        frame = item.get("frame")
                        info = item.get("info", {})
                        if isinstance(frame, (bytes, bytearray)):
                            counts["simFrames"] += 1
                            seq = int((info or {}).get("seq", 0) or 0)
                            filename = (
                                f"sim_frame_{counts['simFrames']:06d}_seq_{seq:06d}.jpg")
                            rel_path = f"sim_frames/{filename}"
                            (sim_frames_dir / filename).write_bytes(bytes(frame))
                            capture_wall_time = (info or {}).get("wallTimeS")
                            try:
                                capture_wall_time = float(capture_wall_time)
                            except (TypeError, ValueError):
                                capture_wall_time = time.time()
                            row = {
                                "wallTimeS": round(capture_wall_time, 6),
                                "path": rel_path,
                                "bytes": len(frame),
                                "info": dict(info) if isinstance(info, dict) else {},
                            }
                            _write_jsonl(sim_frames_f, row)
                    elif kind == "event":
                        _write_jsonl(events_f, item.get("event", {}))
                        counts["events"] += 1
                now = time.time()
                if now >= next_status_wall:
                    publish_status(True)
                    next_status_wall = now + 0.5
            summary = {
                "active": False,
                "runDir": str(run_dir),
                "counts": dict(counts),
                "dropped": int(parent_dropped),
                "saveCameraImages": save_camera_images,
                "trajectoryOnly": trajectory_only,
                "juggle": juggle_counter.summary(complete=True, dropped=parent_dropped),
                "elapsedS": round(float(time.time() - started_wall), 3),
                "stoppedWallTimeS": time.time(),
            }
            (run_dir / "summary.json").write_text(
                json.dumps(summary, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
            publish_status(False)
    except BaseException as exc:  # noqa: BLE001 - propagate to UI.
        publish_status(False, error=str(exc))
    else:
        # Reuse the already-imported writer for the next recording.  This
        # recursive wait adds one tiny Python frame per completed recording
        # and avoids ever spawning/importing while control is live.
        _recording_writer_main("", event_q, status_q, {})


def _read_jsonl(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not path.is_file():
        return rows
    with path.open("r", encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line:
                continue
            try:
                item = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(item, dict):
                rows.append(item)
    return rows


def _numeric_array(
    rows: list[dict[str, Any]],
    key: str,
    width: int | None = None,
) -> np.ndarray:
    values: list[list[float]] = []
    for row in rows:
        raw = row.get(key)
        if raw is None and "." in key:
            raw_any: Any = row
            for part in key.split("."):
                if not isinstance(raw_any, dict):
                    raw_any = None
                    break
                raw_any = raw_any.get(part)
            raw = raw_any
        if isinstance(raw, list):
            vals = []
            for item in raw:
                try:
                    vals.append(float(item))
                except (TypeError, ValueError):
                    vals.append(float("nan"))
            if width is not None:
                vals = (vals + [float("nan")] * width)[:width]
            values.append(vals)
    if not values:
        w = 0 if width is None else width
        return np.zeros((0, w), dtype=np.float64)
    return np.asarray(values, dtype=np.float64)


def _row_float(row: dict[str, Any], key: str, default: float = float("nan")) -> float:
    try:
        value = float(row.get(key, default))
    except (TypeError, ValueError):
        return default
    return value if math.isfinite(value) else default


def _analysis_write_status(
    status_q,
    *,
    active: bool,
    phase: str,
    analysis_dir: Path,
    outputs: dict[str, str] | None = None,
    error: str | None = None,
) -> None:
    _queue_replace_latest(status_q, {
        "active": bool(active),
        "phase": str(phase),
        "analysisDir": str(analysis_dir),
        "outputs": dict(outputs or {}),
        "error": error,
        "wallTimeS": round(float(time.time()), 6),
    })


def _analysis_outputs_from_dir(analysis_dir: Path) -> dict[str, str]:
    outputs: dict[str, str] = {}
    summary_path = analysis_dir / "analysis_summary.json"
    if summary_path.is_file():
        try:
            summary = json.loads(summary_path.read_text(encoding="utf-8"))
            raw_outputs = summary.get("outputs", {})
            if isinstance(raw_outputs, dict):
                outputs.update({
                    str(k): str(v)
                    for k, v in raw_outputs.items()
                    if isinstance(k, str) and isinstance(v, str)
                })
        except Exception:
            outputs = {}
    known_files = {
        "analysisData": "analysis_data.json",
        "trajectoryPlayer": "trajectory_player.html",
        "policyTraceCsv": "policy_trace.csv",
        "ballTrajectoryCsv": "ball_trajectory.csv",
        "alignmentManifest": "alignment_manifest.json",
        "cameraVideo": "camera_video.mp4",
        "simVideo": "sim_video.mp4",
        "cameraVideoInfo": "camera_video_info.json",
        "simVideoInfo": "sim_video_info.json",
        "ballNoiseReport": "ball_noise_report.json",
        "ballNoiseResiduals": "ball_noise_residuals.png",
        "simRealComparison": "sim_real_comparison.json",
        "simRealComparisonCsv": "sim_real_comparison.csv",
        "simRealComparisonText": "sim_real_comparison.txt",
        "simRealComparisonPlot": "sim_real_comparison_rms.png",
        "sim2RealGapTimeSeries": "sim2real_gap_timeseries.csv",
        "sim2RealGapPlot": "sim2real_gap_timeseries.png",
        "jointAccelerationComparisonCsv": "joint_acceleration_comparison.csv",
        "jointAccelerationComparisonPlot": "joint_acceleration_comparison.png",
        "policyObservationCurves": "policy_observation_curves.png",
        "policyActionCurves": "policy_action_curves.png",
        "ballPositionXCurve": "ball_position_x_curve.png",
        "ballPositionYCurve": "ball_position_y_curve.png",
        "ballPositionZCurve": "ball_position_z_curve.png",
        "ballVelocityXCurve": "ball_velocity_x_curve.png",
        "ballVelocityYCurve": "ball_velocity_y_curve.png",
        "ballVelocityZCurve": "ball_velocity_z_curve.png",
        "ballRacketPositionCurves": "ball_racket_position_curves.png",
        "ballRacketContactGapsCsv": "ball_racket_contact_gaps.csv",
        "ballRacketContactGapsJson": "ball_racket_contact_gaps.json",
        "ballRacketContactGapsText": "ball_racket_contact_gaps.txt",
        "cameraIrCxCurve": "camera_ir_cx_curve.png",
        "cameraIrCyCurve": "camera_ir_cy_curve.png",
        "cameraSensorDepthCurve": "camera_sensor_depth_curve.png",
        "cameraGeometryDepthCurve": "camera_geometry_depth_curve.png",
    }
    for key, filename in known_files.items():
        if key not in outputs and (analysis_dir / filename).is_file():
            outputs[key] = filename
    return outputs


def _analysis_schema_version_from_dir(analysis_dir: Path) -> int:
    summary_path = analysis_dir / "analysis_summary.json"
    if not summary_path.is_file():
        return 0
    try:
        summary = json.loads(summary_path.read_text(encoding="utf-8"))
        return int(summary.get("analysisSchemaVersion", 0) or 0)
    except (OSError, TypeError, ValueError, json.JSONDecodeError):
        return 0


def _build_frame_video(
    run_dir: Path,
    analysis_dir: Path,
    fps: float,
    *,
    manifest_name: str,
    output_name: str,
    label: str,
) -> tuple[Path | None, dict[str, Any]]:
    frames = _read_jsonl(run_dir / manifest_name)
    frame_rows = [
        (row, run_dir / str(row.get("path", "")))
        for row in frames
        if row.get("path")
    ]
    frame_rows = [(row, path) for row, path in frame_rows if path.is_file()]
    frame_paths = [path for _row, path in frame_rows]
    info: dict[str, Any] = {
        "frames": len(frame_paths),
        "fps": float(fps),
        "label": label,
    }
    if not frame_paths:
        info["warning"] = "no frames recorded"
        return None, info
    if cv2 is None:
        info["warning"] = f"cv2 unavailable; {label} mp4 not generated"
        return None, info
    first = cv2.imread(str(frame_paths[0]))
    if first is None:
        info["warning"] = "first frame unreadable"
        return None, info
    height, width = first.shape[:2]
    out = analysis_dir / output_name
    writer = cv2.VideoWriter(
        str(out),
        cv2.VideoWriter_fourcc(*"mp4v"),
        max(1.0, float(fps)),
        (width, height),
    )
    if not writer.isOpened():
        info["warning"] = "cv2 VideoWriter failed to open"
        return None, info
    # OpenCV writes a constant-frame-rate stream and has no per-frame PTS API.
    # Preserve the wall-clock duration by resampling the timestamped captures
    # onto the requested CFR timeline.  Without this, a 40 Hz capture written
    # with a 60 fps header plays 1.5x too fast.
    timestamps: list[float] = []
    for row, _path in frame_rows:
        info_row = row.get("info")
        info_row = info_row if isinstance(info_row, dict) else {}
        try:
            timestamp = float(info_row.get(
                "monotonicTimeS",
                info_row.get("wallTimeS", row.get("wallTimeS"))))
        except (TypeError, ValueError):
            timestamps = []
            break
        if not math.isfinite(timestamp):
            timestamps = []
            break
        timestamps.append(timestamp)
    timestamped = (
        len(timestamps) == len(frame_paths)
        and all(b > a for a, b in zip(timestamps, timestamps[1:]))
    )
    output_paths = frame_paths
    duration_s = 0.0
    if timestamped and len(timestamps) > 1:
        duration_s = timestamps[-1] - timestamps[0]
        output_count = max(1, int(round(duration_s * float(fps))) + 1)
        output_paths = []
        source_idx = 0
        for output_idx in range(output_count):
            target_time = timestamps[0] + output_idx / float(fps)
            while (source_idx + 1 < len(timestamps)
                    and timestamps[source_idx + 1] <= target_time):
                source_idx += 1
            output_paths.append(frame_paths[source_idx])

    written = 0
    previous_path: Path | None = None
    previous_image: np.ndarray | None = None
    for path in output_paths:
        if path == previous_path and previous_image is not None:
            image = previous_image
        else:
            image = cv2.imread(str(path))
            previous_path = path
            previous_image = image
        if image is None:
            continue
        if image.shape[:2] != (height, width):
            image = cv2.resize(image, (width, height))
        writer.write(image)
        written += 1
    writer.release()
    duplicated = max(0, len(output_paths) - len(set(output_paths)))
    source_rate_hz = (
        (len(frame_paths) - 1) / duration_s
        if timestamped and duration_s > 0.0 else None)
    info.update({
        "written": written,
        "width": width,
        "height": height,
        "timestampResampled": bool(timestamped and len(timestamps) > 1),
        "sourceDurationS": round(float(duration_s), 6),
        "sourceRateHz": (
            None if source_rate_hz is None
            else round(float(source_rate_hz), 3)),
        "duplicatedOutputFrames": int(duplicated),
    })
    return out if written > 0 else None, info


def _build_camera_video(
    run_dir: Path,
    analysis_dir: Path,
    fps: float,
) -> tuple[Path | None, dict[str, Any]]:
    return _build_frame_video(
        run_dir,
        analysis_dir,
        fps,
        manifest_name="frames.jsonl",
        output_name="camera_video.mp4",
        label="camera",
    )


def _build_sim_video(
    run_dir: Path,
    analysis_dir: Path,
    fps: float,
) -> tuple[Path | None, dict[str, Any]]:
    return _build_frame_video(
        run_dir,
        analysis_dir,
        fps,
        manifest_name="sim_frames.jsonl",
        output_name="sim_video.mp4",
        label="sim",
    )


def _sample_source_seq(row: dict[str, Any]) -> int | None:
    raw = row.get("sourceSeq", row.get("tick"))
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


def _sim_source_seq(row: dict[str, Any]) -> int | None:
    sync = row.get("sync")
    raw = sync.get("sourceSeq") if isinstance(sync, dict) else None
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


def _sample_policy_executed(row: dict[str, Any]) -> bool:
    if "policyExecuted" in row:
        return bool(row.get("policyExecuted"))
    return str(row.get("mode", "")) == "policy"


def _policy_inputs_match(
    real_row: dict[str, Any],
    sim_row: dict[str, Any],
) -> bool:
    policy_input = real_row.get("policyInput")
    sync = sim_row.get("sync")
    if not isinstance(policy_input, dict) or not isinstance(sync, dict):
        return False
    try:
        runtime = real_row.get("runtime")
        runtime = runtime if isinstance(runtime, dict) else {}
        real_profile = normalize_observation_profile(runtime.get(
            "activePolicyProfile",
            runtime.get(
                "policyProfile", OBSERVATION_PROFILE_LEGACY_BUG_COMPAT),
        ))
        sim_profile = normalize_observation_profile(sync.get(
            "policyProfile", OBSERVATION_PROFILE_LEGACY_BUG_COMPAT))
        real_generation = int(runtime.get("policyGeneration", 0) or 0)
        sim_generation = int(sync.get("policyGeneration", 0) or 0)
        real_ball = np.asarray(
            policy_input.get("ball"), dtype=np.float32).reshape(3)
        sim_ball = np.asarray(
            sync.get("inputBall"), dtype=np.float32).reshape(3)
        real_vel = np.asarray(
            policy_input.get("velocity"), dtype=np.float32).reshape(3)
        sim_vel = np.asarray(
            sync.get("inputVelocity"), dtype=np.float32).reshape(3)
        age_match = abs(
            float(policy_input.get("age", 0.0))
            - float(sync.get("inputAgeS", 0.0))) <= 1e-9
        envelope_match = bool(
            np.array_equal(real_ball, sim_ball)
            and np.array_equal(real_vel, sim_vel)
            and bool(policy_input.get("valid", False))
            == bool(sync.get("inputValid", False))
            and int(policy_input.get("ballObservationSeq", 0) or 0)
            == int(sync.get("ballObservationSeq", 0) or 0)
            and age_match
            and real_profile == sim_profile
            and real_generation == sim_generation
        )
        real_policy_ball = real_row.get("policyBallObservation")
        sim_policy_ball = sim_row.get("policyBallObservation")
        if real_policy_ball is None and sim_policy_ball is None:
            return envelope_match
        try:
            ball_dimension = 24 if real_profile in FPLC_PROFILES else 6
            policy_ball_match = np.array_equal(
                np.asarray(real_policy_ball, dtype=np.float32).reshape(ball_dimension),
                np.asarray(sim_policy_ball, dtype=np.float32).reshape(ball_dimension),
            )
        except (TypeError, ValueError):
            policy_ball_match = False
        return bool(envelope_match and policy_ball_match)
    except (TypeError, ValueError):
        return False


def _align_sim_real_samples(
    real_samples: list[dict[str, Any]],
    sim_samples: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Join asynchronous streams only by the canonical real control tick."""
    real_by_seq: dict[int, dict[str, Any]] = {}
    sim_by_seq: dict[int, dict[str, Any]] = {}
    duplicate_real: list[int] = []
    duplicate_sim: list[int] = []
    for row in real_samples:
        seq = _sample_source_seq(row)
        if seq is None:
            continue
        if seq in real_by_seq:
            duplicate_real.append(seq)
        else:
            real_by_seq[seq] = row
    for row in sim_samples:
        seq = _sim_source_seq(row)
        if seq is None:
            continue
        if seq in sim_by_seq:
            duplicate_sim.append(seq)
        else:
            sim_by_seq[seq] = row

    expected = {
        seq for seq, row in real_by_seq.items()
        if _sample_policy_executed(row)
    }
    matched = sorted(expected & set(sim_by_seq))
    missing = sorted(expected - set(sim_by_seq))
    orphan = sorted(set(sim_by_seq) - set(real_by_seq))
    real_source_gaps: list[int] = []
    real_source_gap_count = 0
    sorted_real_seqs = sorted(real_by_seq)
    for previous, current in zip(sorted_real_seqs, sorted_real_seqs[1:]):
        if current <= previous + 1:
            continue
        gap_size = current - previous - 1
        real_source_gap_count += gap_size
        remaining = max(0, 100 - len(real_source_gaps))
        if remaining:
            real_source_gaps.extend(
                range(previous + 1, min(current, previous + 1 + remaining)))
    if sorted_real_seqs:
        first_real_seq = sorted_real_seqs[0]
        last_real_seq = sorted_real_seqs[-1]
        orphan_in_window = [
            seq for seq in orphan
            if first_real_seq <= seq <= last_real_seq
        ]
    else:
        orphan_in_window = []
    input_mismatch = [
        seq for seq in matched
        if not _policy_inputs_match(real_by_seq[seq], sim_by_seq[seq])
    ]
    invalid_stream = []
    for seq in matched:
        sync = sim_by_seq[seq].get("sync")
        if not isinstance(sync, dict):
            invalid_stream.append(seq)
            continue
        if (not bool(sync.get("streamContinuous", False))
                or int(sync.get("resultDrops", 0) or 0) > 0
                or not bool(sync.get("runtimeConfigMatch", True))):
            invalid_stream.append(seq)

    merged: list[dict[str, Any]] = []
    for row in real_samples:
        copied = dict(row)
        seq = _sample_source_seq(row)
        sim_row = sim_by_seq.get(seq) if seq is not None else None
        if sim_row is not None and _sample_policy_executed(row):
            copied["sim"] = dict(sim_row)
            copied["simInputMatch"] = _policy_inputs_match(row, sim_row)
            copied["simAligned"] = bool(copied["simInputMatch"])
        merged.append(copied)

    alignment_mode = "source_seq" if sim_samples else "unavailable"
    valid = bool(
        expected
        and not missing
        and not duplicate_real
        and not duplicate_sim
        and not input_mismatch
        and not invalid_stream
        and real_source_gap_count == 0
        and not orphan_in_window
    )
    report = {
        "alignmentMode": alignment_mode,
        "alignmentValid": valid,
        "realCount": len(real_samples),
        "simCount": len(sim_samples),
        "policyFrameCount": len(expected),
        "matchedCount": len(matched),
        "missingSimCount": len(missing),
        "missingSimSeq": missing[:100],
        "orphanSimCount": len(orphan),
        "orphanSimSeq": orphan[:100],
        "orphanSimInWindowCount": len(orphan_in_window),
        "orphanSimInWindowSeq": orphan_in_window[:100],
        "realSourceGapCount": real_source_gap_count,
        "realSourceGapSeq": real_source_gaps,
        "duplicateRealCount": len(duplicate_real),
        "duplicateRealSeq": sorted(set(duplicate_real))[:100],
        "duplicateSimCount": len(duplicate_sim),
        "duplicateSimSeq": sorted(set(duplicate_sim))[:100],
        "inputMismatchCount": len(input_mismatch),
        "inputMismatchSeq": input_mismatch[:100],
        "invalidStreamCount": len(invalid_stream),
        "invalidStreamSeq": invalid_stream[:100],
    }
    if not sim_samples:
        report["warning"] = (
            "no sourceSeq-tagged sim_control_samples.jsonl; legacy latest-sim "
            "telemetry is intentionally not used for numeric comparison")
    return merged, report


def _realtime_alignment_report(
    real_samples: list[dict[str, Any]],
    sim_samples: list[dict[str, Any]],
    control_rate_hz: float,
) -> dict[str, Any]:
    """Measure online completion cadence separately from eventual seq alignment."""
    target_hz = max(1e-6, float(control_rate_hz))
    dt_s = 1.0 / target_hz
    expected = {
        seq for row in real_samples
        if _sample_policy_executed(row)
        for seq in [_sample_source_seq(row)]
        if seq is not None
    }
    timed: list[tuple[int, int, float, float]] = []
    for row in sim_samples:
        source_seq = _sim_source_seq(row)
        sync = row.get("sync")
        if source_seq not in expected or not isinstance(sync, dict):
            continue
        try:
            episode = int(sync.get("episode", 0) or 0)
            stream_seq = int(sync.get("streamSeq", 0) or 0)
            submitted = float(sync["submittedWallTimeS"])
            completed = float(sync["completedWallTimeS"])
        except (KeyError, TypeError, ValueError):
            continue
        if not (math.isfinite(submitted) and math.isfinite(completed)):
            continue
        timed.append((episode, stream_seq, submitted, completed))
    timed.sort(key=lambda item: (item[0], item[1]))
    latencies = np.asarray(
        [completed - submitted for _, _, submitted, completed in timed],
        dtype=np.float64,
    )
    submitted_elapsed = 0.0
    completed_elapsed = 0.0
    interval_count = 0
    for previous, current in zip(timed, timed[1:]):
        if current[0] != previous[0] or current[1] != previous[1] + 1:
            continue
        submitted_dt = current[2] - previous[2]
        completed_dt = current[3] - previous[3]
        if submitted_dt < 0.0 or completed_dt < 0.0:
            continue
        submitted_elapsed += submitted_dt
        completed_elapsed += completed_dt
        interval_count += 1
    submission_hz = (
        interval_count / submitted_elapsed if submitted_elapsed > 0.0 else 0.0)
    completion_hz = (
        interval_count / completed_elapsed if completed_elapsed > 0.0 else 0.0)
    rate_ratio = (
        completion_hz / submission_hz if submission_hz > 0.0 else 0.0)
    enough_samples = len(timed) >= 20 and interval_count >= 10
    nonnegative_latency = bool(
        latencies.size and np.all(np.isfinite(latencies))
        and np.all(latencies >= 0.0))
    latency_p50_s = (
        float(np.percentile(latencies, 50)) if latencies.size else None)
    latency_p95_s = (
        float(np.percentile(latencies, 95)) if latencies.size else None)
    latency_max_s = float(np.max(latencies)) if latencies.size else None
    latency_limit_s = max(0.010, 2.0 * dt_s)
    realtime_aligned = bool(
        enough_samples
        and nonnegative_latency
        and latency_p95_s is not None
        and latency_p95_s <= latency_limit_s
        and abs(submission_hz - target_hz) / target_hz <= 0.05
        and abs(rate_ratio - 1.0) <= 0.05
    )
    return {
        "realtimeAligned": realtime_aligned,
        "sampleCount": len(timed),
        "intervalCount": interval_count,
        "targetHz": target_hz,
        "submissionHz": submission_hz,
        "completionHz": completion_hz,
        "completionToSubmissionRateRatio": rate_ratio,
        "latencyP50S": latency_p50_s,
        "latencyP95S": latency_p95_s,
        "latencyMaxS": latency_max_s,
        "latencyP95Ticks": (
            None if latency_p95_s is None else latency_p95_s / dt_s),
        "latencyMaxTicks": (
            None if latency_max_s is None else latency_max_s / dt_s),
        "latencyLimitS": latency_limit_s,
        "enoughSamples": enough_samples,
    }


def _write_policy_trace_csv(samples: list[dict[str, Any]], analysis_dir: Path) -> Path:
    obs_width = max((len(r.get("policyObs", [])) for r in samples), default=0)
    action_width = max((len(r.get("policyAction", [])) for r in samples), default=0)
    executed_action_width = max((
        len(r.get("policyExecutedAction", [])) for r in samples
    ), default=0)
    sim_obs_width = max((
        len(r.get("sim", {}).get("policyObs", []))
        for r in samples if isinstance(r.get("sim"), dict)
    ), default=0)
    sim_action_width = max((
        len(r.get("sim", {}).get("policyAction", []))
        for r in samples if isinstance(r.get("sim"), dict)
    ), default=0)
    sim_executed_action_width = max((
        len(r.get("sim", {}).get("policyExecutedAction", []))
        for r in samples if isinstance(r.get("sim"), dict)
    ), default=0)
    out = analysis_dir / "policy_trace.csv"
    point_prefixes = [
        "raw_ball",
        "measured_ball",
        "observed_ball",
        "measured_vel",
        "observed_vel",
        "predicted_ball",
        "predicted_vel",
        "real_ee",
        "command_ee",
        "ros_cart",
        "sim_ee",
        "sim_ball",
    ]
    point_fields = [
        f"{prefix}_{axis}"
        for prefix in point_prefixes
        for axis in ("x", "y", "z")
    ]
    vector_prefixes = [
        "real_q", "real_dq", "nominal_q", "compensated_q",
        "published_q", "sim_q", "sim_dq", "sim_nominal_q",
    ]
    vector_fields = [
        f"{prefix}_{idx}"
        for prefix in vector_prefixes
        for idx in range(len(RIGHT_ARM_JOINTS))
    ]
    fieldnames = (
        [
            "time", "tick", "sourceSeq", "mode", "policyExecuted",
            "valid", "age",
            "ballSource", "simSourceSeq", "simInputMatch",
            "simAligned", "estimatorPredicted", "estimatorState",
            "estimatorOutputMode", "estimatorLossS",
            "estimatorExtrapolationS", "policyProfile",
            "policyGeneration", "simEpisode",
            "camera_ir_cx_px", "camera_ir_cy_px",
            "camera_sensor_depth_mm", "camera_geometry_depth_mm",
            "camera_selected_depth_mm", "camera_depth_method",
        ]
        + point_fields
        + vector_fields
        + [f"obs_{i:03d}" for i in range(obs_width)]
        + [f"action_{i}" for i in range(action_width)]
        + [f"executed_action_{i}" for i in range(executed_action_width)]
        + [f"sim_obs_{i:03d}" for i in range(sim_obs_width)]
        + [f"sim_action_{i}" for i in range(sim_action_width)]
        + [
            f"sim_executed_action_{i}"
            for i in range(sim_executed_action_width)
        ]
    )

    def put_point(out_row: dict[str, Any], prefix: str, raw: Any) -> None:
        point = _point_or_none(raw)
        if point is None:
            return
        for axis, value in zip(("x", "y", "z"), point):
            out_row[f"{prefix}_{axis}"] = value

    def put_vector(out_row: dict[str, Any], prefix: str, raw: Any) -> None:
        if not isinstance(raw, list):
            return
        for idx, value in enumerate(raw[:len(RIGHT_ARM_JOINTS)]):
            out_row[f"{prefix}_{idx}"] = value

    with out.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        for row in samples:
            obs = row.get("policyObs", [])
            action = row.get("policyAction", [])
            executed_action = row.get("policyExecutedAction", [])
            sim = row.get("sim") if isinstance(row.get("sim"), dict) else {}
            sim_obs = sim.get("policyObs", [])
            sim_action = sim.get("policyAction", [])
            sim_executed_action = sim.get("policyExecutedAction", [])
            estimator = (
                row.get("estimator")
                if isinstance(row.get("estimator"), dict) else {}
            )
            ros = row.get("ros") if isinstance(row.get("ros"), dict) else {}
            command = (
                row.get("command")
                if isinstance(row.get("command"), dict) else {}
            )
            runtime = (
                row.get("runtime")
                if isinstance(row.get("runtime"), dict) else {}
            )
            sim_sync = (
                sim.get("sync") if isinstance(sim.get("sync"), dict) else {})
            camera_measurement = (
                row.get("cameraMeasurement")
                if isinstance(row.get("cameraMeasurement"), dict) else {})
            out_row: dict[str, Any] = {
                "time": row.get("time"),
                "tick": row.get("tick"),
                "sourceSeq": row.get("sourceSeq", row.get("tick")),
                "mode": row.get("mode"),
                "policyExecuted": _sample_policy_executed(row),
                "valid": row.get("valid"),
                "age": row.get("age"),
                "ballSource": row.get("ballSource"),
                "simSourceSeq": _sim_source_seq(
                    row.get("sim", {})
                    if isinstance(row.get("sim"), dict) else {}),
                "simInputMatch": row.get("simInputMatch"),
                "simAligned": row.get("simAligned"),
                "estimatorPredicted": estimator.get(
                    "predicted", row.get("predictedBallIsPredicted")),
                "estimatorState": estimator.get("state"),
                "estimatorOutputMode": estimator.get("outputMode"),
                "estimatorLossS": estimator.get("lossS"),
                "estimatorExtrapolationS": estimator.get("extrapolationS"),
                "policyProfile": runtime.get(
                    "activePolicyProfile", runtime.get("policyProfile")),
                "policyGeneration": runtime.get("policyGeneration"),
                "simEpisode": sim_sync.get("episode"),
                "camera_ir_cx_px": camera_measurement.get("cx"),
                "camera_ir_cy_px": camera_measurement.get("cy"),
                "camera_sensor_depth_mm": camera_measurement.get(
                    "sensor_depth_mm"),
                "camera_geometry_depth_mm": camera_measurement.get(
                    "geom_depth_mm"),
                "camera_selected_depth_mm": camera_measurement.get(
                    "depth_mm"),
                "camera_depth_method": camera_measurement.get(
                    "depth_method"),
            }
            put_point(out_row, "raw_ball", row.get("rawBall"))
            put_point(out_row, "measured_ball", row.get("measuredBall"))
            put_point(out_row, "observed_ball", row.get("observedBall"))
            put_point(out_row, "measured_vel", row.get("measuredVelocity"))
            put_point(out_row, "observed_vel", row.get("observedVelocity"))
            put_point(
                out_row, "predicted_ball",
                row.get("predictedBall") or estimator.get("positionM"))
            put_point(
                out_row, "predicted_vel",
                row.get("predictedVelocity") or estimator.get("velocityMps"))
            real_ee = row.get("racket") or ros.get("jointEe")
            if real_ee is None and isinstance(obs, list) and len(obs) >= 29:
                real_ee = obs[52:55] if len(obs) in (72, 117, 156) else obs[26:29]
            put_point(out_row, "real_ee", real_ee)
            put_point(out_row, "command_ee", row.get("commandRacket"))
            put_point(out_row, "ros_cart", ros.get("cartPosition"))
            put_point(out_row, "sim_ee", sim.get("racket"))
            put_point(out_row, "sim_ball", sim.get("ball"))
            put_vector(
                out_row, "real_q",
                obs[:7] if isinstance(obs, list) and len(obs) >= 7 else [])
            put_vector(
                out_row, "real_dq",
                obs[7:14] if isinstance(obs, list) and len(obs) >= 14 else [])
            put_vector(
                out_row, "nominal_q",
                command.get("policyNominalPosition", []))
            put_vector(
                out_row, "compensated_q",
                command.get("compensatedReferencePosition", []))
            put_vector(
                out_row, "published_q",
                command.get("publishedSafePosition", []))
            put_vector(
                out_row, "sim_q",
                sim_obs[:7] if isinstance(sim_obs, list) and len(sim_obs) >= 7 else [])
            put_vector(
                out_row, "sim_dq",
                sim_obs[7:14] if isinstance(sim_obs, list) and len(sim_obs) >= 14 else [])
            put_vector(out_row, "sim_nominal_q", sim.get("policyCommand", []))
            if isinstance(obs, list):
                for i, value in enumerate(obs[:obs_width]):
                    out_row[f"obs_{i:03d}"] = value
            if isinstance(action, list):
                for i, value in enumerate(action[:action_width]):
                    out_row[f"action_{i}"] = value
            if isinstance(executed_action, list):
                for i, value in enumerate(
                        executed_action[:executed_action_width]):
                    out_row[f"executed_action_{i}"] = value
            if isinstance(sim_obs, list):
                for i, value in enumerate(sim_obs[:sim_obs_width]):
                    out_row[f"sim_obs_{i:03d}"] = value
            if isinstance(sim_action, list):
                for i, value in enumerate(sim_action[:sim_action_width]):
                    out_row[f"sim_action_{i}"] = value
            if isinstance(sim_executed_action, list):
                for i, value in enumerate(
                        sim_executed_action[:sim_executed_action_width]):
                    out_row[f"sim_executed_action_{i}"] = value
            writer.writerow(out_row)
    return out


def _plot_policy_curves(samples: list[dict[str, Any]], analysis_dir: Path) -> list[Path]:
    if not samples:
        return []
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    t = np.asarray([_row_float(r, "time", i * 0.005)
                    for i, r in enumerate(samples)], dtype=np.float64)
    obs = _numeric_array(samples, "policyObs")
    action = _numeric_array(samples, "policyAction")
    executed_action = _numeric_array(samples, "policyExecutedAction")
    outputs: list[Path] = []
    if obs.size:
        groups = [
            ("joint q", 0, 7),
            ("joint dq", 7, 14),
            ("base pose/vel", 14, 20),
            ("ball pos", 20, 23),
            ("ball vel", 23, 26),
            ("racket pos/vel", 26, 32),
            ("relative", 32, 35),
            ("prev action", 35, 42),
            ("cmd error", 42, 49),
            ("age/delay", 49, min(obs.shape[1], 67)),
        ]
        fig, axes = plt.subplots(len(groups), 1, figsize=(15, 20), sharex=True)
        for ax, (title, start, end) in zip(axes, groups):
            end = min(end, obs.shape[1])
            if start >= end:
                ax.set_visible(False)
                continue
            for idx in range(start, end):
                ax.plot(t, obs[:, idx], linewidth=0.9, label=f"obs[{idx}]")
            ax.set_title(title)
            ax.grid(True, alpha=0.25)
            ax.legend(loc="upper right", ncol=4, fontsize=7)
        axes[-1].set_xlabel("time (s)")
        fig.tight_layout()
        out = analysis_dir / "policy_observation_curves.png"
        fig.savefig(out, dpi=130)
        plt.close(fig)
        outputs.append(out)
    if action.size:
        fig, ax = plt.subplots(1, 1, figsize=(14, 5))
        show_executed = bool(
            executed_action.shape == action.shape
            and not np.allclose(executed_action, action, atol=1e-8))
        for idx in range(action.shape[1]):
            ax.plot(
                t, action[:, idx], linewidth=0.9,
                label=f"raw action[{idx}]")
            if show_executed:
                ax.plot(
                    t, executed_action[:, idx], linewidth=1.1,
                    linestyle="--", label=f"executed action[{idx}]")
        ax.set_title("Policy Action Output (raw and conditioned)")
        ax.set_xlabel("time (s)")
        ax.grid(True, alpha=0.25)
        ax.legend(loc="upper right", ncol=4)
        fig.tight_layout()
        out = analysis_dir / "policy_action_curves.png"
        fig.savefig(out, dpi=130)
        plt.close(fig)
        outputs.append(out)
    return outputs


def _sample_ball_state_6d(sample: dict[str, Any]) -> np.ndarray | None:
    """Return the policy-facing [x, y, z, vx, vy, vz] ball state.

    ``ballState6D`` is written by recording schema v7.  The remaining sources
    keep analysis compatible with recordings made before that field existed.
    """
    def combined(position: Any, velocity: Any) -> list[Any] | None:
        vector_types = (list, tuple, np.ndarray)
        if not isinstance(position, vector_types):
            return None
        if not isinstance(velocity, vector_types):
            return None
        return list(position) + list(velocity)

    actor_ball = sample.get("policyBallObservation")
    if isinstance(actor_ball, (list, tuple, np.ndarray)) and len(actor_ball) == 24:
        actor_ball = None  # FPLC holds eight positions; adjacent XYZ is not velocity.
    candidates: list[Any] = [
        sample.get("ballState6D"),
        actor_ball,
    ]
    policy_input = sample.get("policyInput")
    if isinstance(policy_input, dict):
        candidates.append(combined(
            policy_input.get("ball"), policy_input.get("velocity")))
    candidates.append(combined(
        sample.get("observedBall"), sample.get("observedVelocity")))
    policy_obs = sample.get("policyObs")
    if (isinstance(policy_obs, (list, tuple)) and len(policy_obs) >= 26
            and len(policy_obs) not in (72, 117, 156)):
        candidates.append(policy_obs[20:26])

    for candidate in candidates:
        if not isinstance(candidate, (list, tuple, np.ndarray)):
            continue
        if len(candidate) < 6:
            continue
        try:
            state = np.asarray(candidate[:6], dtype=np.float64)
        except (TypeError, ValueError):
            continue
        if state.shape == (6,) and np.any(np.isfinite(state)):
            return state
    return None


def _plot_ball_state_curves(
    samples: list[dict[str, Any]],
    analysis_dir: Path,
) -> list[Path]:
    """Plot each component of the recorded 6D ball state separately."""
    if not samples:
        return []
    states = np.full((len(samples), 6), np.nan, dtype=np.float64)
    predicted = np.zeros(len(samples), dtype=bool)
    for index, sample in enumerate(samples):
        state = _sample_ball_state_6d(sample)
        if state is not None:
            states[index] = state
        high_prediction = sample.get("highBallOcclusionPrediction")
        estimator = sample.get("estimator")
        predicted[index] = bool(
            sample.get("predictedBallIsPredicted", False)
            or (isinstance(high_prediction, dict)
                and high_prediction.get("predicted", False))
            or (isinstance(estimator, dict)
                and estimator.get("predicted", False)))
    if not np.any(np.isfinite(states)):
        return []

    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    t = np.asarray([
        _row_float(row, "time", index * 0.005)
        for index, row in enumerate(samples)
    ], dtype=np.float64)
    # Remove the two aggregate figures produced by analysis schema v4.  They
    # are generated artifacts and would otherwise leave eight ball-state
    # images in a re-analyzed recording directory instead of the requested six.
    for legacy_filename in (
        "ball_position_curves.png", "ball_velocity_curves.png"):
        (analysis_dir / legacy_filename).unlink(missing_ok=True)

    specs = [
        ("Ball Position X", 0, "x", "position (m)",
         "ball_position_x_curve.png"),
        ("Ball Position Y", 1, "y", "position (m)",
         "ball_position_y_curve.png"),
        ("Ball Position Z", 2, "z", "position (m)",
         "ball_position_z_curve.png"),
        ("Ball Velocity X", 3, "vx", "velocity (m/s)",
         "ball_velocity_x_curve.png"),
        ("Ball Velocity Y", 4, "vy", "velocity (m/s)",
         "ball_velocity_y_curve.png"),
        ("Ball Velocity Z", 5, "vz", "velocity (m/s)",
         "ball_velocity_z_curve.png"),
    ]
    outputs: list[Path] = []
    for title, column, label, ylabel, filename in specs:
        values = states[:, column]
        if not np.any(np.isfinite(values)):
            continue
        fig, ax = plt.subplots(1, 1, figsize=(14, 5))
        # Keep both sources on the same axes.  NaN-masking preserves the
        # original samples and makes every predicted interval immediately
        # visible without inventing interpolation across a state transition.
        measured_values = np.where(~predicted, values, np.nan)
        predicted_values = np.where(predicted, values, np.nan)
        ax.plot(
            t, measured_values, color="#1f77b4", linewidth=1.0,
            label=f"measured {label}")
        if np.any(np.isfinite(predicted_values)):
            ax.plot(
                t, predicted_values, color="#d62728", linewidth=1.25,
                label=f"predicted {label}")
        ax.set_title(title)
        ax.set_xlabel("time (s)")
        ax.set_ylabel(ylabel)
        ax.grid(True, alpha=0.25)
        ax.legend(loc="upper right")
        fig.tight_layout()
        out = analysis_dir / filename
        fig.savefig(out, dpi=130)
        plt.close(fig)
        outputs.append(out)
    return outputs


def _plot_camera_measurement_curves(
    samples: list[dict[str, Any]],
    analysis_dir: Path,
) -> list[Path]:
    """Plot IR center and both detector depth estimates independently."""
    if not samples:
        return []
    t = np.asarray([
        _row_float(row, "time", index * 0.005)
        for index, row in enumerate(samples)
    ], dtype=np.float64)
    specs = [
        ("IR Center X", "cx", "IR x (px)", "camera_ir_cx_curve.png"),
        ("IR Center Y", "cy", "IR y (px)", "camera_ir_cy_curve.png"),
        (
            "Sensor Depth", "sensor_depth_mm", "depth (mm)",
            "camera_sensor_depth_curve.png",
        ),
        (
            "Geometry Depth", "geom_depth_mm", "depth (mm)",
            "camera_geometry_depth_curve.png",
        ),
    ]
    series: dict[str, np.ndarray] = {}
    for _title, key, _ylabel, _filename in specs:
        values = np.full(len(samples), np.nan, dtype=np.float64)
        for index, sample in enumerate(samples):
            measurement = sample.get("cameraMeasurement")
            if not isinstance(measurement, dict):
                continue
            try:
                value = float(measurement.get(key))
            except (TypeError, ValueError):
                continue
            if math.isfinite(value):
                values[index] = value
        series[key] = values
    if not any(np.any(np.isfinite(values)) for values in series.values()):
        return []

    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    outputs: list[Path] = []
    for title, key, ylabel, filename in specs:
        values = series[key]
        if not np.any(np.isfinite(values)):
            continue
        fig, ax = plt.subplots(1, 1, figsize=(14, 5))
        ax.plot(t, values, linewidth=1.0, label=key)
        ax.set_title(title)
        ax.set_xlabel("time (s)")
        ax.set_ylabel(ylabel)
        ax.grid(True, alpha=0.25)
        ax.legend(loc="upper right")
        fig.tight_layout()
        out = analysis_dir / filename
        fig.savefig(out, dpi=130)
        plt.close(fig)
        outputs.append(out)
    return outputs


def _per_dim_comparison(
    real: np.ndarray,
    sim: np.ndarray,
    *,
    group: str,
    names: list[str],
) -> list[dict[str, Any]]:
    n = min(real.shape[0], sim.shape[0])
    width = min(real.shape[1] if real.ndim == 2 else 0,
                sim.shape[1] if sim.ndim == 2 else 0)
    rows: list[dict[str, Any]] = []
    if n <= 0 or width <= 0:
        return rows
    real = real[:n, :width]
    sim = sim[:n, :width]
    for idx in range(width):
        r = real[:, idx]
        s = sim[:, idx]
        mask = np.isfinite(r) & np.isfinite(s)
        if not np.any(mask):
            continue
        rv = r[mask]
        sv = s[mask]
        diff = rv - sv
        # JSON has no representation for NaN.  A constant real or simulated
        # dimension has an undefined correlation, so expose it as JSON null
        # instead of letting Python emit a non-standard bare NaN token that
        # browsers reject while loading analysis_data.json.
        corr: float | None = None
        if rv.size >= 3 and np.nanstd(rv) > 1e-12 and np.nanstd(sv) > 1e-12:
            corr_value = float(np.corrcoef(rv, sv)[0, 1])
            corr = corr_value if math.isfinite(corr_value) else None
        rows.append({
            "group": group,
            "dim": idx,
            "name": names[idx] if idx < len(names) else f"{group}[{idx}]",
            "count": int(rv.size),
            "real_mean": float(np.nanmean(rv)),
            "sim_mean": float(np.nanmean(sv)),
            "diff_mean": float(np.nanmean(diff)),
            "diff_rms": float(np.sqrt(np.nanmean(diff * diff))),
            "diff_abs_max": float(np.nanmax(np.abs(diff))),
            "corr": corr,
        })
    return rows


def _sim2real_cohort_key(row: dict[str, Any]) -> tuple[str, int, int]:
    runtime = row.get("runtime")
    runtime = runtime if isinstance(runtime, dict) else {}
    sim = row.get("sim")
    sim = sim if isinstance(sim, dict) else {}
    sync = sim.get("sync")
    sync = sync if isinstance(sync, dict) else {}
    profile = normalize_observation_profile(runtime.get(
        "activePolicyProfile",
        runtime.get(
            "policyProfile",
            sync.get("policyProfile", OBSERVATION_PROFILE_LEGACY_BUG_COMPAT),
        ),
    ))
    try:
        generation = int(runtime.get(
            "policyGeneration", sync.get("policyGeneration", 0)) or 0)
    except (TypeError, ValueError):
        generation = 0
    try:
        episode = int(sync.get("episode", 0) or 0)
    except (TypeError, ValueError):
        episode = 0
    return profile, generation, episode


def _analysis_point_series(
    samples: list[dict[str, Any]],
    *keys: str,
) -> np.ndarray:
    values = np.full((len(samples), 3), np.nan, dtype=np.float64)
    for index, sample in enumerate(samples):
        point: list[float] | None = None
        for key in keys:
            raw: Any = sample
            for part in key.split("."):
                if not isinstance(raw, dict):
                    raw = None
                    break
                raw = raw.get(part)
            point = _point_or_none(raw)
            if point is not None:
                break
        if point is not None:
            values[index] = np.asarray(point, dtype=np.float64)
    return values


def _observed_ball_position_series(samples: list[dict[str, Any]]) -> np.ndarray:
    values = np.full((len(samples), 3), np.nan, dtype=np.float64)
    for index, sample in enumerate(samples):
        state = _sample_ball_state_6d(sample)
        if state is not None and np.all(np.isfinite(state[:3])):
            values[index] = state[:3]
            continue
        point = _point_or_none(sample.get("observedBall"))
        if point is not None:
            values[index] = np.asarray(point, dtype=np.float64)
    return values


def _predicted_ball_position_series(samples: list[dict[str, Any]]) -> np.ndarray:
    values = np.full((len(samples), 3), np.nan, dtype=np.float64)
    for index, sample in enumerate(samples):
        estimator = sample.get("estimator")
        estimator = estimator if isinstance(estimator, dict) else {}
        point = _point_or_none(sample.get("predictedBall"))
        if point is None:
            point = _point_or_none(estimator.get("positionM"))
        if point is not None:
            values[index] = np.asarray(point, dtype=np.float64)
    return values


def _contact_candidate_indices(
    samples: list[dict[str, Any]],
    observed_ball: np.ndarray,
    racket: np.ndarray,
    observed_velocity: np.ndarray,
) -> list[int]:
    if not samples:
        return []
    indices: list[int] = []
    last_time = -float("inf")
    for index in range(1, min(len(samples), observed_ball.shape[0], racket.shape[0])):
        prev_vz = observed_velocity[index - 1, 2]
        curr_vz = observed_velocity[index, 2]
        if not (math.isfinite(prev_vz) and math.isfinite(curr_vz)):
            continue
        if prev_vz > -0.05 or curr_vz < 0.05:
            continue
        if not (np.all(np.isfinite(observed_ball[index]))
                and np.all(np.isfinite(racket[index]))):
            continue
        distance = float(np.linalg.norm(observed_ball[index] - racket[index]))
        if not math.isfinite(distance) or distance > 0.18:
            continue
        t = _row_float(samples[index], "time", index * 0.005)
        if not math.isfinite(t):
            t = index * 0.005
        if t - last_time < 0.08:
            continue
        indices.append(index)
        last_time = t
    return indices


def _finite_mean_abs(values: np.ndarray) -> float | None:
    finite = values[np.isfinite(values)]
    if finite.size == 0:
        return None
    return float(np.nanmean(np.abs(finite)))


def _finite_percentile_abs(values: np.ndarray, percentile: float) -> float | None:
    finite = values[np.isfinite(values)]
    if finite.size == 0:
        return None
    return float(np.nanpercentile(np.abs(finite), percentile))


def _plot_ball_racket_position_curves(
    samples: list[dict[str, Any]],
    analysis_dir: Path,
) -> list[Path]:
    """Plot racket, raw ball, observed ball, and predicted ball positions."""
    if not samples:
        return []
    t = np.asarray([_row_float(r, "time", i * 0.005)
                    for i, r in enumerate(samples)], dtype=np.float64)
    raw_ball = _analysis_point_series(samples, "rawBall")
    observed_ball = _observed_ball_position_series(samples)
    predicted_ball = _predicted_ball_position_series(samples)
    racket = _analysis_point_series(
        samples, "racket", "ros.eePosition", "workspaceSafety.eePosition",
        "commandRacket")
    observed_velocity = _analysis_point_series(
        samples, "observedVelocity", "policyInput.velocity")
    if not any(np.any(np.isfinite(values)) for values in (
            raw_ball, observed_ball, predicted_ball, racket)):
        return []

    contacts = _contact_candidate_indices(
        samples, observed_ball, racket, observed_velocity)

    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    series = [
        ("racket", racket, "#4e79a7", "-", 1.25),
        ("raw ball", raw_ball, "#59a14f", "-", 1.0),
        ("observed/policy ball", observed_ball, "#9c6ade", "--", 1.15),
        ("predicted ball", predicted_ball, "#e15759", ":", 1.35),
    ]
    axes_names = ("x", "y", "z")
    fig, axes = plt.subplots(3, 1, figsize=(15, 10), sharex=True)
    for dim, ax in enumerate(axes):
        for label, values, color, linestyle, linewidth in series:
            if np.any(np.isfinite(values[:, dim])):
                ax.plot(
                    t, values[:, dim], label=label, color=color,
                    linestyle=linestyle, linewidth=linewidth)
        for contact in contacts:
            contact_t = t[contact] if contact < t.size else float("nan")
            if math.isfinite(contact_t):
                ax.axvline(contact_t, color="#b07aa1", alpha=0.35,
                           linewidth=1.0)
        ax.set_ylabel(f"{axes_names[dim]} (m)")
        ax.grid(True, alpha=0.22)
    axes[0].set_title(
        "Racket, raw ball, observed ball, and predicted ball position")
    axes[-1].set_xlabel("time (s)")
    handles, labels = axes[0].get_legend_handles_labels()
    if handles:
        axes[0].legend(handles, labels, loc="upper right", ncol=2)
    if contacts:
        z_ax = axes[2]
        for contact in contacts[:8]:
            if contact >= t.size:
                continue
            obs_gap = observed_ball[contact, 2] - racket[contact, 2]
            if not math.isfinite(obs_gap):
                continue
            z_ax.annotate(
                f"{obs_gap * 1000.0:.0f} mm",
                (t[contact], observed_ball[contact, 2]),
                textcoords="offset points",
                xytext=(4, 4),
                fontsize=7,
                color="#3f3f46",
            )
    fig.tight_layout()
    out = analysis_dir / "ball_racket_position_curves.png"
    fig.savefig(out, dpi=150)
    plt.close(fig)
    return [out]


def _analyze_ball_racket_contact_gaps(
    samples: list[dict[str, Any]],
    analysis_dir: Path,
) -> dict[str, Any]:
    """Summarize ball/racket z gaps near contact-like velocity reversals."""
    raw_ball = _analysis_point_series(samples, "rawBall")
    measured_ball = _analysis_point_series(samples, "measuredBall")
    observed_ball = _observed_ball_position_series(samples)
    predicted_ball = _predicted_ball_position_series(samples)
    racket = _analysis_point_series(
        samples, "racket", "ros.eePosition", "workspaceSafety.eePosition",
        "commandRacket")
    observed_velocity = _analysis_point_series(
        samples, "observedVelocity", "policyInput.velocity")
    contacts = _contact_candidate_indices(
        samples, observed_ball, racket, observed_velocity)

    csv_path = analysis_dir / "ball_racket_contact_gaps.csv"
    fieldnames = [
        "time_s", "source_seq", "observed_vz_m_s", "racket_z_m",
        "raw_ball_z_m", "measured_ball_z_m", "observed_ball_z_m",
        "predicted_ball_z_m", "raw_z_gap_mm", "measured_z_gap_mm",
        "observed_z_gap_mm", "predicted_z_gap_mm", "raw_to_observed_z_mm",
        "predicted_to_observed_z_mm", "raw_distance_m", "observed_distance_m",
        "predicted_distance_m", "age_s", "estimator_loss_s",
        "estimator_extrapolation_s", "camera_sensor_depth_mm",
        "camera_geometry_depth_mm", "camera_selected_depth_mm",
        "camera_depth_method", "sim_aligned", "sim_input_match",
    ]

    def scalar(values: np.ndarray, index: int, dim: int) -> float:
        if index >= values.shape[0]:
            return float("nan")
        value = float(values[index, dim])
        return value if math.isfinite(value) else float("nan")

    def distance(values: np.ndarray, index: int) -> float:
        if index >= values.shape[0] or index >= racket.shape[0]:
            return float("nan")
        if not (np.all(np.isfinite(values[index]))
                and np.all(np.isfinite(racket[index]))):
            return float("nan")
        return float(np.linalg.norm(values[index] - racket[index]))

    rows: list[dict[str, Any]] = []
    for index in contacts:
        sample = samples[index]
        estimator = sample.get("estimator")
        estimator = estimator if isinstance(estimator, dict) else {}
        camera = sample.get("cameraMeasurement")
        camera = camera if isinstance(camera, dict) else {}
        rz = scalar(racket, index, 2)
        raw_z = scalar(raw_ball, index, 2)
        measured_z = scalar(measured_ball, index, 2)
        observed_z = scalar(observed_ball, index, 2)
        predicted_z = scalar(predicted_ball, index, 2)
        row = {
            "time_s": _row_float(sample, "time", index * 0.005),
            "source_seq": _sample_source_seq(sample),
            "observed_vz_m_s": scalar(observed_velocity, index, 2),
            "racket_z_m": rz,
            "raw_ball_z_m": raw_z,
            "measured_ball_z_m": measured_z,
            "observed_ball_z_m": observed_z,
            "predicted_ball_z_m": predicted_z,
            "raw_z_gap_mm": (raw_z - rz) * 1000.0,
            "measured_z_gap_mm": (measured_z - rz) * 1000.0,
            "observed_z_gap_mm": (observed_z - rz) * 1000.0,
            "predicted_z_gap_mm": (predicted_z - rz) * 1000.0,
            "raw_to_observed_z_mm": (raw_z - observed_z) * 1000.0,
            "predicted_to_observed_z_mm": (predicted_z - observed_z) * 1000.0,
            "raw_distance_m": distance(raw_ball, index),
            "observed_distance_m": distance(observed_ball, index),
            "predicted_distance_m": distance(predicted_ball, index),
            "age_s": _row_float(sample, "age", float("nan")),
            "estimator_loss_s": _row_float(estimator, "lossS", float("nan")),
            "estimator_extrapolation_s": _row_float(
                estimator, "extrapolationS", float("nan")),
            "camera_sensor_depth_mm": _row_float(
                camera, "sensor_depth_mm", float("nan")),
            "camera_geometry_depth_mm": _row_float(
                camera, "geom_depth_mm", float("nan")),
            "camera_selected_depth_mm": _row_float(
                camera, "selected_depth_mm", float("nan")),
            "camera_depth_method": camera.get("depth_method"),
            "sim_aligned": sample.get("simAligned"),
            "sim_input_match": sample.get("simInputMatch"),
        }
        rows.append(row)

    with csv_path.open("w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for row in rows:
            writer.writerow(row)

    def array_from_rows(name: str) -> np.ndarray:
        return np.asarray([float(row.get(name, float("nan")))
                           for row in rows], dtype=np.float64)

    raw_obs = array_from_rows("raw_to_observed_z_mm")
    pred_obs = array_from_rows("predicted_to_observed_z_mm")
    obs_gap = array_from_rows("observed_z_gap_mm")
    age = array_from_rows("age_s")
    depth_delta = (
        array_from_rows("camera_sensor_depth_mm")
        - array_from_rows("camera_geometry_depth_mm"))

    hints: list[str] = []
    mean_raw_obs = _finite_mean_abs(raw_obs)
    mean_pred_obs = _finite_mean_abs(pred_obs)
    mean_gap = _finite_mean_abs(obs_gap)
    mean_age = _finite_mean_abs(age)
    mean_depth_delta = _finite_mean_abs(depth_delta)
    if not rows:
        hints.append(
            "No contact-like observed z-velocity reversals near the racket were detected.")
    else:
        if mean_raw_obs is not None and mean_raw_obs > 25.0:
            hints.append(
                "Raw and policy-facing ball z differ near contact; inspect estimator smoothing, hold, prediction, or handover.")
        if mean_pred_obs is not None and mean_pred_obs > 25.0:
            hints.append(
                "Predicted ball z diverges from observed ball z near contact; inspect prediction horizon and stale-state handling.")
        if mean_depth_delta is not None and mean_depth_delta > 35.0:
            hints.append(
                "Sensor and geometry depth disagree near contact; inspect depth calibration, masking, and reflective-ball depth selection.")
        if mean_age is not None and mean_age > 0.04:
            hints.append(
                "Ball observation age is high near contact; timing skew or held observations may explain the z gap.")
        if (mean_gap is not None and mean_gap > 35.0
                and (mean_raw_obs is None or mean_raw_obs <= 25.0)
                and (mean_pred_obs is None or mean_pred_obs <= 25.0)):
            hints.append(
                "Raw, observed, and predicted ball streams are similar while the racket gap remains; inspect racket site/frame, ball radius, contact timing, or collision geometry before blaming the detector.")
    if not hints:
        hints.append(
            "No single dominant observation fault was detected from contact gaps alone; compare the PNG around each impact marker.")

    report: dict[str, Any] = {
        "contactCount": len(rows),
        "summary": {
            "observedZGapMeanAbsMm": mean_gap,
            "observedZGapP95AbsMm": _finite_percentile_abs(obs_gap, 95.0),
            "rawToObservedZMeanAbsMm": mean_raw_obs,
            "predictedToObservedZMeanAbsMm": mean_pred_obs,
            "sensorMinusGeometryDepthMeanAbsMm": mean_depth_delta,
            "ageMeanAbsS": mean_age,
        },
        "hints": hints,
        "csv": csv_path.name,
    }
    json_path = analysis_dir / "ball_racket_contact_gaps.json"
    json_path.write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    lines = ["Ball/Racket Contact Gap Diagnostics", ""]
    lines.append(f"contacts: {len(rows)}")
    for key, value in report["summary"].items():
        lines.append(f"{key}: {value}")
    lines.append("")
    lines.append("hints:")
    lines.extend(f"- {hint}" for hint in hints)
    (analysis_dir / "ball_racket_contact_gaps.txt").write_text(
        "\n".join(lines) + "\n", encoding="utf-8")
    return report
def _matrix_slice(
    rows: list[dict[str, Any]],
    key: str,
    start: int,
    stop: int,
) -> np.ndarray:
    matrix = _numeric_array(rows, key)
    if matrix.ndim != 2 or matrix.shape[1] <= start:
        return np.zeros((len(rows), 0), dtype=np.float64)
    return matrix[:, start:min(stop, matrix.shape[1])]


def _aligned_joint_acceleration(
    rows: list[dict[str, Any]],
    velocity_key: str,
    *,
    time_key: str = "sourceTimeS",
) -> np.ndarray:
    """Difference velocity using its source clock over contiguous policy rows."""
    velocity = _matrix_slice(rows, velocity_key, 7, 14)
    result = np.full(velocity.shape, np.nan, dtype=np.float64)
    if velocity.ndim != 2 or velocity.shape[0] < 2:
        return result

    def time_value(row: dict[str, Any]) -> float:
        raw: Any = row
        for part in time_key.split("."):
            if not isinstance(raw, dict):
                return float("nan")
            raw = raw.get(part)
        try:
            value = float(raw)
        except (TypeError, ValueError):
            return float("nan")
        return value if math.isfinite(value) else float("nan")

    for index in range(velocity.shape[0] - 1):
        seq = _sample_source_seq(rows[index])
        next_seq = _sample_source_seq(rows[index + 1])
        if seq is None or next_seq != seq + 1:
            continue
        start_s = time_value(rows[index])
        end_s = time_value(rows[index + 1])
        dt_s = end_s - start_s
        if not math.isfinite(dt_s) or not 1e-4 <= dt_s <= 0.10:
            continue
        result[index] = (velocity[index + 1] - velocity[index]) / dt_s
    return result


def _per_tick_rms(
    real: np.ndarray,
    sim: np.ndarray | None = None,
) -> np.ndarray:
    values = np.asarray(real, dtype=np.float64)
    if sim is not None:
        other = np.asarray(sim, dtype=np.float64)
        n = min(values.shape[0], other.shape[0])
        width = min(
            values.shape[1] if values.ndim == 2 else 0,
            other.shape[1] if other.ndim == 2 else 0,
        )
        values = values[:n, :width] - other[:n, :width]
    if values.ndim != 2 or values.shape[1] == 0:
        return np.full((values.shape[0] if values.ndim else 0,), np.nan)
    finite = np.isfinite(values)
    count = np.sum(finite, axis=1)
    squared = np.where(finite, values * values, 0.0)
    out = np.full(values.shape[0], np.nan, dtype=np.float64)
    good = count > 0
    out[good] = np.sqrt(np.sum(squared[good], axis=1) / count[good])
    return out


def _signal_summary(
    values: np.ndarray,
    names: list[str],
) -> dict[str, Any]:
    matrix = np.asarray(values, dtype=np.float64)
    if matrix.ndim != 2 or matrix.size == 0 or matrix.shape[1] == 0:
        return {"sampleCount": 0, "dims": 0}
    per_dim = []
    for idx in range(matrix.shape[1]):
        column = matrix[:, idx]
        column = column[np.isfinite(column)]
        if column.size == 0:
            continue
        per_dim.append({
            "dim": idx,
            "name": names[idx] if idx < len(names) else f"dim[{idx}]",
            "count": int(column.size),
            "mean": float(np.mean(column)),
            "rms": float(np.sqrt(np.mean(column * column))),
            "p95Abs": float(np.percentile(np.abs(column), 95)),
            "maxAbs": float(np.max(np.abs(column))),
        })
    flat = matrix[np.isfinite(matrix)]
    tick_rms = _per_tick_rms(matrix)
    tick_rms = tick_rms[np.isfinite(tick_rms)]
    return {
        "sampleCount": int(matrix.shape[0]),
        "dims": int(matrix.shape[1]),
        "overallRms": (
            None if flat.size == 0
            else float(np.sqrt(np.mean(flat * flat)))),
        "tickRmsP50": (
            None if tick_rms.size == 0 else float(np.percentile(tick_rms, 50))),
        "tickRmsP95": (
            None if tick_rms.size == 0 else float(np.percentile(tick_rms, 95))),
        "tickRmsMax": (
            None if tick_rms.size == 0 else float(np.max(tick_rms))),
        "perDimension": per_dim,
    }


def _first_threshold_crossing(
    rows: list[dict[str, Any]],
    values: np.ndarray,
    threshold: float,
) -> dict[str, Any] | None:
    series = np.asarray(values, dtype=np.float64).reshape(-1)
    if not rows or series.size == 0:
        return None
    start_time = _row_float(rows[0], "time", 0.0)
    for idx, value in enumerate(series[:len(rows)]):
        if not math.isfinite(value) or value <= threshold:
            continue
        row = rows[idx]
        row_time = _row_float(row, "time", start_time)
        return {
            "sourceSeq": _sample_source_seq(row),
            "timeS": row_time,
            "elapsedS": max(0.0, row_time - start_time),
            "value": float(value),
            "threshold": float(threshold),
        }
    return None


def _analyze_sim_real_gap(
    samples: list[dict[str, Any]],
    analysis_dir: Path,
    alignment: dict[str, Any] | None = None,
) -> dict[str, Any]:
    aligned_rows = [
        row for row in samples
        if (row.get("simAligned") is True
            and row.get("simInputMatch") is True
            and str(row.get("mode", "")) == "policy"
            and isinstance(row.get("sim"), dict))
    ]
    cohorts: dict[tuple[str, int, int], list[dict[str, Any]]] = {}
    for row in aligned_rows:
        cohorts.setdefault(_sim2real_cohort_key(row), []).append(row)
    ideal_cohorts = {
        key: rows for key, rows in cohorts.items()
        if uses_corrected_67d_observation(key[0])
    }
    candidates = ideal_cohorts or cohorts
    selected_key = (
        max(candidates, key=lambda key: len(candidates[key]))
        if candidates else None
    )
    sim_rows = [] if selected_key is None else candidates[selected_key]
    cohort_rows = [
        {
            "policyProfile": key[0],
            "policyGeneration": int(key[1]),
            "simEpisode": int(key[2]),
            "sampleCount": len(rows),
            "selected": key == selected_key,
        }
        for key, rows in sorted(
            cohorts.items(), key=lambda item: len(item[1]), reverse=True)
    ]
    report: dict[str, Any] = {
        "sampleCount": len(samples),
        "alignedPolicySampleCount": len(aligned_rows),
        "simSampleCount": len(sim_rows),
        "excludedAlignedSampleCount": len(aligned_rows) - len(sim_rows),
        "cohorts": cohort_rows,
        "selectedCohort": (
            None if selected_key is None else {
                "policyProfile": selected_key[0],
                "policyGeneration": int(selected_key[1]),
                "simEpisode": int(selected_key[2]),
                "sampleCount": len(sim_rows),
            }
        ),
        "groups": {},
        "alignment": dict(alignment or {}),
        "alignmentValid": bool(
            (alignment or {}).get("alignmentValid", False)),
        "phaseSemantics": {
            "policyObs": (
                "tick-start state used by both policies; q/dq are obs[0:14] "
                "and racket xyz is obs[26:29]"
            ),
            "policyAction": "same-tick raw clipped actor output",
            "policyExecutedAction": (
                "same-tick normalized action after checkpoint LPF/slew; "
                "this is obs[35:42] on the next tick"
            ),
            "commandPosition": "same-tick nominal policy command",
            "simSnapshotState": (
                "jointPosition/jointVelocity/jointAcceleration/racket are "
                "tick-end and are not "
                "compared against same-tick real feedback"
            ),
            "jointAcceleration": (
                "forward difference of tick-start policyObs joint velocity; "
                "real dt uses the exact JointState source-sample clock and "
                "sim dt uses sourceTimeS; repeated samples and sourceSeq gaps "
                "are excluded"
            ),
        },
    }
    if not sim_rows:
        report["warning"] = (
            (alignment or {}).get("warning")
            or "no exactly sourceSeq-aligned sim mirror samples")
        (analysis_dir / "sim_real_comparison.json").write_text(
            _strict_json_dumps(report, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        (analysis_dir / "sim_real_comparison.csv").write_text(
            "group,dim,name,count,real_mean,sim_mean,diff_mean,diff_rms,diff_abs_max,corr\n",
            encoding="utf-8",
        )
        (analysis_dir / "sim_real_comparison.txt").write_text(
            f"Sim2Real Comparison\n\n{report['warning']}\n",
            encoding="utf-8",
        )
        return report
    if not report["alignmentValid"]:
        report["warning"] = (
            "alignment is incomplete/invalid; metrics below cover only exact "
            "sourceSeq and input-matched frames and must not be treated as a "
            "complete lockstep run")

    comparisons: list[dict[str, Any]] = []
    obs_names = _obs_names(max(
        (len(r.get("policyObs", [])) for r in sim_rows), default=0))
    real_ddq = _aligned_joint_acceleration(
        sim_rows, "policyObs", time_key="ros.jointSampleStampS")
    sim_ddq = _aligned_joint_acceleration(sim_rows, "sim.policyObs")
    group_specs: list[tuple[str, np.ndarray, np.ndarray, list[str], str]] = [
        ("policy_obs", _numeric_array(sim_rows, "policyObs"),
         _numeric_array(sim_rows, "sim.policyObs"), obs_names, "mixed"),
        ("joint_position", _matrix_slice(sim_rows, "policyObs", 0, 7),
         _matrix_slice(sim_rows, "sim.policyObs", 0, 7),
         list(RIGHT_ARM_JOINTS), "rad"),
        ("joint_velocity", _matrix_slice(sim_rows, "policyObs", 7, 14),
         _matrix_slice(sim_rows, "sim.policyObs", 7, 14),
         list(RIGHT_ARM_JOINTS), "rad/s"),
        ("base_pose", _matrix_slice(sim_rows, "policyObs", 14, 17),
         _matrix_slice(sim_rows, "sim.policyObs", 14, 17),
         ["base_x", "base_y", "base_yaw"], "m,m,rad"),
        ("base_velocity", _matrix_slice(sim_rows, "policyObs", 17, 20),
         _matrix_slice(sim_rows, "sim.policyObs", 17, 20),
         ["base_vx", "base_vy", "base_yaw_rate"], "m/s,m/s,rad/s"),
        ("joint_acceleration", real_ddq, sim_ddq,
         list(RIGHT_ARM_JOINTS), "rad/s^2"),
        ("ball_observation", _matrix_slice(sim_rows, "policyObs", 20, 26),
         _matrix_slice(sim_rows, "sim.policyObs", 20, 26),
         ["ball_x", "ball_y", "ball_z", "ball_vx", "ball_vy", "ball_vz"],
         "m,m/s"),
        ("racket_position", _matrix_slice(sim_rows, "policyObs", 26, 29),
         _matrix_slice(sim_rows, "sim.policyObs", 26, 29),
         ["racket_x", "racket_y", "racket_z"], "m"),
        ("racket_velocity", _matrix_slice(sim_rows, "policyObs", 29, 32),
         _matrix_slice(sim_rows, "sim.policyObs", 29, 32),
         ["racket_vx", "racket_vy", "racket_vz"], "m/s"),
        ("relative_ball_racket", _matrix_slice(sim_rows, "policyObs", 32, 35),
         _matrix_slice(sim_rows, "sim.policyObs", 32, 35),
         ["rel_x", "rel_y", "rel_z"], "m"),
        ("previous_executed_action", _matrix_slice(
            sim_rows, "policyObs", 35, 42),
         _matrix_slice(sim_rows, "sim.policyObs", 35, 42),
         [f"prev_action[{i}]" for i in range(7)], "normalized"),
        ("tracking_error", _matrix_slice(sim_rows, "policyObs", 42, 49),
         _matrix_slice(sim_rows, "sim.policyObs", 42, 49),
         list(RIGHT_ARM_JOINTS), "rad"),
        ("ball_age_normalized", _matrix_slice(
            sim_rows, "policyObs", 49, 50),
         _matrix_slice(sim_rows, "sim.policyObs", 49, 50),
         ["ball_age_norm"], "normalized"),
        ("actuator_delay_normalized", _matrix_slice(
            sim_rows, "policyObs", 50, 51),
         _matrix_slice(sim_rows, "sim.policyObs", 50, 51),
         ["tau_act_norm"], "normalized"),
        ("nominal_command_velocity", _matrix_slice(
            sim_rows, "policyObs", 51, 58),
         _matrix_slice(sim_rows, "sim.policyObs", 51, 58),
         list(RIGHT_ARM_JOINTS), "rad/s"),
        ("delayed_tracking_error", _matrix_slice(
            sim_rows, "policyObs", 58, 65),
         _matrix_slice(sim_rows, "sim.policyObs", 58, 65),
         list(RIGHT_ARM_JOINTS), "rad"),
        ("contact_phase", _matrix_slice(sim_rows, "policyObs", 65, 67),
         _matrix_slice(sim_rows, "sim.policyObs", 65, 67),
         ["t_contact_est", "t_margin"], "s"),
        ("policy_action", _numeric_array(sim_rows, "policyAction"),
         _numeric_array(sim_rows, "sim.policyAction"),
         [f"action[{i}]" for i in range(7)], "normalized"),
        ("executed_action", _numeric_array(
            sim_rows, "policyExecutedAction"),
         _numeric_array(sim_rows, "sim.policyExecutedAction"),
         [f"executed_action[{i}]" for i in range(7)], "normalized"),
        ("command_position", _numeric_array(
            sim_rows, "policyCommand.position"),
         _numeric_array(sim_rows, "sim.policyCommand"),
         list(RIGHT_ARM_JOINTS), "rad"),
    ]
    fplc_observation = len(obs_names) in (72, 117, 156)
    if fplc_observation:
        # Keep only fields actually present in these independent actor schemas.
        group_specs = [spec for spec in group_specs if spec[0] in {
            "policy_obs", "joint_position", "joint_velocity", "joint_acceleration",
            "policy_action", "executed_action", "command_position"}]
        age_start = 61 if len(obs_names) in (72, 117) else 124
        for name, start, stop, unit in (
                ("ball_observation", 28, 31, "m"),
                ("ball_position_history", 28, 52, "m"),
                ("racket_position", 52, 55, "m"),
                ("previous_executed_action", 21, 28, "normalized"),
                ("tracking_error", 14, 21, "rad"),
                ("ball_age_normalized", age_start, age_start + 8, "age/0.25")):
            group_specs.append((name, _matrix_slice(sim_rows, "policyObs", start, stop),
                                _matrix_slice(sim_rows, "sim.policyObs", start, stop),
                                obs_names[start:stop], unit))
        report["phaseSemantics"]["policyObs"] = (
            "FPLC tick-start q/dq obs[0:14], persistent q_ref error obs[14:21], "
            "held direct ball history obs[28:52], current racket xyz obs[52:55]; "
            "no direct actor ball/racket velocity slots")
        report["phaseSemantics"]["policyExecutedAction"] = (
            "same-tick Cartesian-projected normalized QVEL; next tick obs[21:28]")
    group_matrices: dict[str, tuple[np.ndarray, np.ndarray]] = {}
    for group, real, sim, names, unit in group_specs:
        rows = _per_dim_comparison(real, sim, group=group, names=names)
        comparisons.extend(rows)
        group_matrices[group] = (real, sim)
        if rows:
            report["groups"][group] = {
                "dims": len(rows),
                "unit": unit,
                "meanRms": float(np.nanmean([r["diff_rms"] for r in rows])),
                "maxAbs": float(np.nanmax([r["diff_abs_max"] for r in rows])),
            }

    real_q, sim_q = group_matrices.get(
        "joint_position", (np.zeros((0, 0)), np.zeros((0, 0))))
    real_dq, sim_dq = group_matrices.get(
        "joint_velocity", (np.zeros((0, 0)), np.zeros((0, 0))))
    real_ddq, sim_ddq = group_matrices.get(
        "joint_acceleration", (np.zeros((0, 0)), np.zeros((0, 0))))
    real_racket, sim_racket = group_matrices.get(
        "racket_position", (np.zeros((0, 0)), np.zeros((0, 0))))
    real_action, sim_action = group_matrices.get(
        "policy_action", (np.zeros((0, 0)), np.zeros((0, 0))))
    real_command, sim_command = group_matrices.get(
        "command_position", (np.zeros((0, 0)), np.zeros((0, 0))))
    tracking_start = 14 if fplc_observation else 42
    real_tracking = _matrix_slice(sim_rows, "policyObs", tracking_start, tracking_start + 7)
    sim_tracking = _matrix_slice(sim_rows, "sim.policyObs", tracking_start, tracking_start + 7)
    compensated = _numeric_array(
        sim_rows, "command.compensatedReferencePosition")
    published = _numeric_array(sim_rows, "command.publishedSafePosition")
    compensation_offset = (
        compensated - real_command
        if compensated.shape == real_command.shape else np.zeros((0, 0)))
    safety_intervention = (
        published - compensated
        if published.shape == compensated.shape else np.zeros((0, 0)))

    q_gap = _per_tick_rms(real_q, sim_q)
    dq_gap = _per_tick_rms(real_dq, sim_dq)
    ddq_gap = _per_tick_rms(real_ddq, sim_ddq)
    racket_gap = _per_tick_rms(real_racket, sim_racket)
    action_gap = _per_tick_rms(real_action, sim_action)
    command_gap = _per_tick_rms(real_command, sim_command)
    real_tracking_rms = _per_tick_rms(real_tracking)
    sim_tracking_rms = _per_tick_rms(sim_tracking)
    compensation_offset_rms = _per_tick_rms(compensation_offset)
    safety_intervention_rms = _per_tick_rms(safety_intervention)
    start_time = _row_float(sim_rows[0], "time", 0.0)

    def finite_or_none(value: float) -> float | None:
        return float(value) if math.isfinite(float(value)) else None

    time_series: list[dict[str, Any]] = []
    for idx, row in enumerate(sim_rows):
        row_time = _row_float(row, "time", start_time)
        time_series.append({
            "sourceSeq": _sample_source_seq(row),
            "timeS": row_time,
            "elapsedS": max(0.0, row_time - start_time),
            "jointPositionRmsRad": finite_or_none(q_gap[idx]),
            "jointVelocityRmsRadS": finite_or_none(dq_gap[idx]),
            "jointAccelerationRmsRadS2": finite_or_none(ddq_gap[idx]),
            "racketPositionRmsM": finite_or_none(racket_gap[idx]),
            "policyActionRms": finite_or_none(action_gap[idx]),
            "nominalCommandRmsRad": finite_or_none(command_gap[idx]),
            "realTrackingRmsRad": finite_or_none(real_tracking_rms[idx]),
            "simTrackingRmsRad": finite_or_none(sim_tracking_rms[idx]),
            "compensationOffsetRmsRad": finite_or_none(
                compensation_offset_rms[idx]
                if idx < compensation_offset_rms.size else float("nan")),
            "safetyInterventionRmsRad": finite_or_none(
                safety_intervention_rms[idx]
                if idx < safety_intervention_rms.size else float("nan")),
        })

    first_count = min(20, len(sim_rows))
    reset_q_rms = (
        float(np.sqrt(np.nanmean(np.square(real_q[0] - sim_q[0]))))
        if len(sim_rows) and real_q.shape == sim_q.shape else None)
    early_q_rms = (
        float(np.sqrt(np.nanmean(np.square(
            real_q[:first_count] - sim_q[:first_count]))))
        if first_count and real_q.shape == sim_q.shape else None)
    ball_summary = report["groups"].get("ball_observation", {})
    real_tracking_summary = _signal_summary(
        real_tracking, list(RIGHT_ARM_JOINTS))
    sim_tracking_summary = _signal_summary(
        sim_tracking, list(RIGHT_ARM_JOINTS))
    acceleration_limits = np.deg2rad(np.asarray(
        DEFAULT_ARM_ACC_LIMIT_DEG_S2, dtype=np.float64))

    def acceleration_summary(values: np.ndarray) -> dict[str, Any]:
        summary = _signal_summary(values, list(RIGHT_ARM_JOINTS))
        if (values.ndim != 2 or values.shape[1] != acceleration_limits.size
                or values.shape[0] == 0):
            summary["limitExceedance"] = None
            return summary
        finite = np.isfinite(values)
        exceeded = finite & (np.abs(values) > acceleration_limits[None, :])
        valid_rows = np.any(finite, axis=1)
        summary["limitExceedance"] = {
            "limitsRadS2": acceleration_limits.tolist(),
            "limitsDegS2": list(DEFAULT_ARM_ACC_LIMIT_DEG_S2),
            "anyJointIntervalFraction": (
                float(np.mean(np.any(exceeded[valid_rows], axis=1)))
                if np.any(valid_rows) else None),
            "perJointIntervalFraction": [
                (float(np.mean(exceeded[finite[:, index], index]))
                 if np.any(finite[:, index]) else None)
                for index in range(values.shape[1])
            ],
        }
        return summary

    real_acceleration_summary = acceleration_summary(real_ddq)
    sim_acceleration_summary = acceleration_summary(sim_ddq)
    compensation_limit = None
    first_command = sim_rows[0].get("command")
    first_command = first_command if isinstance(first_command, dict) else {}
    first_compensation = first_command.get("compensation")
    first_compensation = (
        first_compensation if isinstance(first_compensation, dict) else {})
    try:
        compensation_limit = float(first_compensation.get("mpcMaxDeltaRad"))
    except (TypeError, ValueError):
        compensation_limit = None
    compensation_saturation = None
    if (compensation_offset.size and compensation_limit is not None
            and math.isfinite(compensation_limit) and compensation_limit > 0.0):
        saturated = np.abs(compensation_offset) >= max(
            0.0, compensation_limit - 1e-3)
        compensation_saturation = {
            "limitRad": compensation_limit,
            "anyJointTickFraction": float(np.mean(np.any(saturated, axis=1))),
            "elementFraction": float(np.mean(saturated)),
            "perJointFraction": [
                float(value) for value in np.mean(saturated, axis=0)
            ],
        }
    diagnostics = {
        "initialWindowTicks": first_count,
        "resetJointPositionRmsRad": reset_q_rms,
        "earlyWindowJointPositionRmsRad": early_q_rms,
        "ballObservationMaxAbs": ball_summary.get("maxAbs"),
        "realPlantNominalTrackingError": real_tracking_summary,
        "simIdealPdNominalTrackingError": sim_tracking_summary,
        "realRealizedJointAcceleration": real_acceleration_summary,
        "simRealizedJointAcceleration": sim_acceleration_summary,
        "compensationOffset": _signal_summary(
            compensation_offset, list(RIGHT_ARM_JOINTS)),
        "compensationSaturation": compensation_saturation,
        "safetyIntervention": _signal_summary(
            safety_intervention, list(RIGHT_ARM_JOINTS)),
        "divergenceOnset": {
            "jointPositionRms20mrad": _first_threshold_crossing(
                sim_rows, q_gap, 0.020),
            "jointVelocityRms200mradS": _first_threshold_crossing(
                sim_rows, dq_gap, 0.200),
            "jointAccelerationRms5radS2": _first_threshold_crossing(
                sim_rows, ddq_gap, 5.0),
            "racketPositionRms10mm": _first_threshold_crossing(
                sim_rows, racket_gap, 0.010),
            "policyActionRms020": _first_threshold_crossing(
                sim_rows, action_gap, 0.20),
            "nominalCommandRms20mrad": _first_threshold_crossing(
                sim_rows, command_gap, 0.020),
        },
    }
    real_tracking_overall = real_tracking_summary.get("overallRms")
    sim_tracking_overall = sim_tracking_summary.get("overallRms")
    ball_max = diagnostics.get("ballObservationMaxAbs")
    findings: list[str] = []
    if ball_max is not None and float(ball_max) <= 1e-7:
        findings.append(
            "The policy-facing ball position/velocity is bit-level aligned; "
            "ball input transport is not the observed closed-loop gap source.")
    elif ball_max is not None:
        findings.append(
            f"Policy-facing ball input differs (max abs {float(ball_max):.6g}); "
            "fix this observation/input mismatch before attributing plant gap.")
    if reset_q_rms is not None and reset_q_rms <= 1e-3:
        findings.append(
            "The first aligned policy tick starts from a matched arm state.")
    elif reset_q_rms is not None:
        findings.append(
            f"Reset/initial arm state is already mismatched "
            f"(RMS {reset_q_rms:.6g} rad).")
    if (compensation_saturation is not None
            and compensation_saturation["anyJointTickFraction"] > 0.01):
        findings.append(
            "Inverse-MPC compensation reaches its configured max delta on "
            f"{100.0 * compensation_saturation['anyJointTickFraction']:.1f}% "
            "of aligned ticks; inspect compensation saturation and downstream "
            "drive response.")
    real_acc_exceed = (
        real_acceleration_summary.get("limitExceedance") or {}).get(
            "anyJointIntervalFraction")
    sim_acc_exceed = (
        sim_acceleration_summary.get("limitExceedance") or {}).get(
            "anyJointIntervalFraction")
    if sim_acc_exceed is not None and real_acc_exceed is not None:
        findings.append(
            "Realized acceleration limit exceedance (forward-difference, "
            f"any joint): real={100.0 * real_acc_exceed:.2f}%, "
            f"sim={100.0 * sim_acc_exceed:.2f}%.")
    if (real_tracking_overall is not None
            and sim_tracking_overall is not None
            and real_tracking_overall > max(
                0.020, 2.0 * sim_tracking_overall)):
        diagnostics["primaryGapHint"] = "real_actuation_tracking"
        findings.append(
            "Real nominal-to-feedback tracking error is much larger than the "
            "ideal-PD mirror; inspect compensation, command transport, drive "
            "tracking and measured q/dq first.")
    elif reset_q_rms is not None and reset_q_rms > 0.010:
        diagnostics["primaryGapHint"] = "reset_state_alignment"
    elif ball_max is not None and float(ball_max) > 1e-7:
        diagnostics["primaryGapHint"] = "policy_input_alignment"
    else:
        diagnostics["primaryGapHint"] = "closed_loop_divergence"
        findings.append(
            "Use the divergence-onset ordering below to identify whether joint "
            "state, racket FK, action, or nominal command separates first.")
    diagnostics["findings"] = findings
    report["diagnostics"] = diagnostics
    # Keep the JSON/UI payload bounded for long hardware runs.  The CSV below
    # remains the lossless, per-control-tick export used for offline analysis.
    time_series_stride = max(1, int(math.ceil(len(time_series) / 4000.0)))
    report["timeSeries"] = time_series[::time_series_stride]
    report["timeSeriesDecimation"] = time_series_stride

    csv_path = analysis_dir / "sim_real_comparison.csv"
    with csv_path.open("w", newline="", encoding="utf-8") as handle:
        fieldnames = [
            "group", "dim", "name", "count",
            "real_mean", "sim_mean", "diff_mean",
            "diff_rms", "diff_abs_max", "corr",
        ]
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        writer.writeheader()
        for row in comparisons:
            writer.writerow(row)
    report["comparisonCsv"] = csv_path.name
    report["rows"] = comparisons

    time_series_path = analysis_dir / "sim2real_gap_timeseries.csv"
    time_series_fields = [
        "sourceSeq", "timeS", "elapsedS", "jointPositionRmsRad",
        "jointVelocityRmsRadS", "jointAccelerationRmsRadS2",
        "racketPositionRmsM",
        "policyActionRms", "nominalCommandRmsRad",
        "realTrackingRmsRad", "simTrackingRmsRad",
        "compensationOffsetRmsRad", "safetyInterventionRmsRad",
    ]
    with time_series_path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=time_series_fields)
        writer.writeheader()
        writer.writerows(time_series)
    report["timeSeriesCsv"] = time_series_path.name

    acceleration_path = analysis_dir / "joint_acceleration_comparison.csv"
    acceleration_fields = ["sourceSeq", "timeS", "elapsedS"]
    acceleration_fields.extend(
        f"real_{name}_rad_s2" for name in RIGHT_ARM_JOINTS)
    acceleration_fields.extend(
        f"sim_{name}_rad_s2" for name in RIGHT_ARM_JOINTS)
    with acceleration_path.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=acceleration_fields)
        writer.writeheader()
        for index, row in enumerate(sim_rows):
            record: dict[str, Any] = {
                "sourceSeq": _sample_source_seq(row),
                "timeS": _row_float(row, "time", start_time),
                "elapsedS": max(
                    0.0, _row_float(row, "time", start_time) - start_time),
            }
            for joint_index, name in enumerate(RIGHT_ARM_JOINTS):
                record[f"real_{name}_rad_s2"] = finite_or_none(
                    real_ddq[index, joint_index])
                record[f"sim_{name}_rad_s2"] = finite_or_none(
                    sim_ddq[index, joint_index])
            writer.writerow(record)
    report["jointAccelerationCsv"] = acceleration_path.name

    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        fig, ax = plt.subplots(1, 1, figsize=(14, 6))
        labels = [f"{r['group']}:{r['dim']}" for r in comparisons]
        vals = [r["diff_rms"] for r in comparisons]
        if vals:
            ax.bar(np.arange(len(vals)), vals, color="#4e79a7")
            ax.set_xticks(np.arange(len(vals))[::max(1, len(vals) // 40)])
            ax.set_xticklabels(labels[::max(1, len(vals) // 40)], rotation=70, ha="right", fontsize=7)
            ax.set_ylabel("RMS(real - sim)")
            ax.set_title("Sim2Real Per-Dimension Difference")
            ax.grid(True, axis="y", alpha=0.25)
            fig.tight_layout()
            plot_path = analysis_dir / "sim_real_comparison_rms.png"
            fig.savefig(plot_path, dpi=130)
            report["comparisonPlot"] = plot_path.name
        plt.close(fig)
    except Exception as exc:  # noqa: BLE001 - report but keep CSV.
        report["plotWarning"] = str(exc)

    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        elapsed = np.asarray(
            [row["elapsedS"] for row in time_series], dtype=np.float64)
        fig, axes = plt.subplots(4, 2, figsize=(16, 13), sharex=True)
        flat_axes = axes.reshape(-1)
        for joint_index, name in enumerate(RIGHT_ARM_JOINTS):
            axis = flat_axes[joint_index]
            axis.plot(elapsed, real_ddq[:, joint_index], label="real", lw=0.9)
            axis.plot(elapsed, sim_ddq[:, joint_index], label="sim", lw=0.9)
            limit = acceleration_limits[joint_index]
            axis.axhline(limit, color="black", ls="--", lw=0.6, alpha=0.5)
            axis.axhline(-limit, color="black", ls="--", lw=0.6, alpha=0.5)
            axis.set_title(f"{name} (limit ±{limit:.2f} rad/s²)")
            axis.grid(True, alpha=0.25)
            axis.legend(loc="upper right")
        flat_axes[-1].set_visible(False)
        for axis in flat_axes[-2:]:
            axis.set_xlabel("elapsed time (s)")
        fig.suptitle(
            "Aligned realized joint acceleration "
            "(forward difference of tick-start velocity)")
        fig.tight_layout()
        acceleration_plot_path = (
            analysis_dir / "joint_acceleration_comparison.png")
        fig.savefig(acceleration_plot_path, dpi=130)
        plt.close(fig)
        report["jointAccelerationPlot"] = acceleration_plot_path.name
    except Exception as exc:  # noqa: BLE001 - report but keep numeric output.
        report["jointAccelerationPlotWarning"] = str(exc)

    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        elapsed = np.asarray(
            [row["elapsedS"] for row in time_series], dtype=np.float64)
        fig, axes = plt.subplots(4, 1, figsize=(14, 12), sharex=True)
        axes[0].plot(elapsed, q_gap, label="joint q RMS (rad)")
        axes[0].plot(elapsed, racket_gap, label="racket xyz RMS (m)")
        axes[1].plot(elapsed, dq_gap, label="joint dq RMS (rad/s)")
        axes[1].plot(elapsed, ddq_gap, label="joint ddq RMS (rad/s²)")
        axes[2].plot(elapsed, action_gap, label="policy action RMS")
        axes[2].plot(elapsed, command_gap, label="nominal command RMS (rad)")
        axes[3].plot(elapsed, real_tracking_rms,
                     label="real nominal-feedback RMS (rad)")
        axes[3].plot(elapsed, sim_tracking_rms,
                     label="sim ideal-PD nominal-feedback RMS (rad)")
        if compensation_offset_rms.size == elapsed.size:
            axes[3].plot(elapsed, compensation_offset_rms,
                         label="compensation offset RMS (rad)", alpha=0.8)
        for axis in axes:
            axis.grid(True, alpha=0.25)
            axis.legend(loc="upper right")
        axes[0].set_title("Sim2Real Gap: aligned selected cohort")
        axes[-1].set_xlabel("elapsed time in cohort (s)")
        fig.tight_layout()
        gap_plot_path = analysis_dir / "sim2real_gap_timeseries.png"
        fig.savefig(gap_plot_path, dpi=130)
        plt.close(fig)
        report["timeSeriesPlot"] = gap_plot_path.name
    except Exception as exc:  # noqa: BLE001 - report but keep numeric output.
        report["timeSeriesPlotWarning"] = str(exc)

    (analysis_dir / "sim_real_comparison.json").write_text(
        _strict_json_dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    lines = [
        "Sim2Real Comparison",
        "",
        "State phase: policyObs is tick-start; sim snapshot joint/racket "
        "fields are tick-end and are excluded from same-tick RMS.",
        "",
        f"selected cohort: {report.get('selectedCohort')}",
        f"primary gap hint: {diagnostics.get('primaryGapHint')}",
        f"reset joint RMS: {reset_q_rms}",
        f"early-window joint RMS: {early_q_rms}",
        f"ball observation max abs: {ball_max}",
        f"real tracking RMS: {real_tracking_overall}",
        f"sim ideal-PD tracking RMS: {sim_tracking_overall}",
        "",
    ]
    for group, summary in report.get("groups", {}).items():
        lines.append(
            f"{group}: dims={summary['dims']} "
            f"mean_rms={summary['meanRms']:.6g} "
            f"max_abs={summary['maxAbs']:.6g}")
    lines.append("")
    lines.extend(f"- {finding}" for finding in findings)
    if report.get("warning"):
        lines.append(str(report["warning"]))
    (analysis_dir / "sim_real_comparison.txt").write_text(
        "\n".join(lines) + "\n", encoding="utf-8")
    return report


def _robust_axis_stats_mm(values_m: np.ndarray) -> dict[str, Any]:
    if values_m.size == 0:
        return {}
    vals_mm = values_m * 1000.0
    return {
        "meanMm": [round(float(v), 4) for v in np.nanmean(vals_mm, axis=0)],
        "stdMm": [round(float(v), 4) for v in np.nanstd(vals_mm, axis=0)],
        "rmsMm": [
            round(float(v), 4)
            for v in np.sqrt(np.nanmean(np.square(vals_mm), axis=0))
        ],
        "madMm": [
            round(float(v), 4)
            for v in np.nanmedian(
                np.abs(vals_mm - np.nanmedian(vals_mm, axis=0)), axis=0)
        ],
    }


def _analyze_ball_noise(samples: list[dict[str, Any]], analysis_dir: Path) -> dict[str, Any]:
    valid_rows = [r for r in samples if bool(r.get("rawValid", r.get("valid", False)))]
    measured = _numeric_array(valid_rows, "measuredBall", 3)
    observed = _numeric_array(valid_rows, "observedBall", 3)
    raw = _numeric_array(valid_rows, "rawBall", 3)
    t = np.asarray([_row_float(r, "time", i * 0.005)
                    for i, r in enumerate(valid_rows)], dtype=np.float64)
    report: dict[str, Any] = {
        "sampleCount": len(samples),
        "validSampleCount": len(valid_rows),
    }
    if measured.shape[0] == 0 or observed.shape[0] == 0:
        report["warning"] = "no valid ball samples"
    else:
        residual = measured - observed
        report["measuredMinusEstimator"] = _robust_axis_stats_mm(residual)
        raw_residual = raw - observed if raw.shape == observed.shape else residual
        report["rawMinusEstimator"] = _robust_axis_stats_mm(raw_residual)
        if measured.shape[0] >= 3:
            changed = np.ones(measured.shape[0], dtype=bool)
            changed[1:] = np.linalg.norm(np.diff(measured, axis=0), axis=1) > 1e-7
            unique_measured = measured[changed]
            report["uniqueMeasurementCount"] = int(unique_measured.shape[0])
            if unique_measured.shape[0] >= 3:
                second_diff = (
                    unique_measured[1:-1]
                    - 0.5 * (unique_measured[:-2] + unique_measured[2:])
                )
                report["secondDifferenceJitter"] = _robust_axis_stats_mm(second_diff)
                report["stepDelta"] = _robust_axis_stats_mm(
                    np.diff(unique_measured, axis=0))
        try:
            import matplotlib
            matplotlib.use("Agg")
            import matplotlib.pyplot as plt
            fig, axes = plt.subplots(3, 1, figsize=(14, 9), sharex=True)
            labels = ("x", "y", "z")
            for axis_idx, label in enumerate(labels):
                axes[axis_idx].plot(
                    t, residual[:, axis_idx] * 1000.0,
                    linewidth=0.9,
                    label=f"measured - estimator {label}")
                axes[axis_idx].axhline(0.0, color="k", linestyle=":", linewidth=0.8)
                axes[axis_idx].set_ylabel("mm")
                axes[axis_idx].grid(True, alpha=0.25)
                axes[axis_idx].legend(loc="upper right")
            axes[-1].set_xlabel("time (s)")
            fig.suptitle("Ball Observation Residuals")
            fig.tight_layout()
            fig.savefig(analysis_dir / "ball_noise_residuals.png", dpi=130)
            plt.close(fig)
        except Exception as exc:  # noqa: BLE001 - report, do not fail analysis.
            report["plotWarning"] = str(exc)
    (analysis_dir / "ball_noise_report.json").write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    lines = ["Ball Observation Noise Report", ""]
    for key, value in report.items():
        lines.append(f"{key}: {value}")
    (analysis_dir / "ball_noise_report.txt").write_text(
        "\n".join(lines) + "\n", encoding="utf-8")
    return report


def _point_or_none(raw: Any) -> list[float] | None:
    try:
        arr = np.asarray(raw, dtype=np.float64).reshape(-1)
    except (TypeError, ValueError):
        return None
    if arr.shape[0] < 3:
        return None
    values = [float(arr[0]), float(arr[1]), float(arr[2])]
    if not all(math.isfinite(v) for v in values):
        return None
    return [round(v, 6) for v in values]


def _scaled_point_or_none(raw: Any, scale: float) -> list[float] | None:
    try:
        arr = np.asarray(raw, dtype=np.float64).reshape(-1)
    except (TypeError, ValueError):
        return None
    if arr.shape[0] < 3:
        return None
    values = [float(arr[0]), float(arr[1]), float(arr[2])]
    if not all(math.isfinite(v) for v in values):
        return None
    return [round(v * float(scale), 6) for v in values]


class HybridBallTrackerProbeAdapter:
    """Adapt the SI-unit 9-state estimator to the probe's legacy contract."""

    backend_name = "hybrid_ekf9"

    def __init__(
        self,
        config_path: Path,
        *,
        prediction_enabled: bool,
        frame_rotation: np.ndarray | None,
        ballistic_dynamics_enabled: bool,
    ) -> None:
        self.config_path = Path(config_path).expanduser().resolve()
        config = HybridBallTrackerConfig.from_yaml(self.config_path)
        self.estimator = HybridBallStateEstimator(config)
        self.max_prediction_duration_s = float(
            config.max_prediction_duration_s)
        self.prediction_enabled = bool(prediction_enabled)
        self._racket_pose: dict[str, Any] | None = None
        self._last_measurement_estimate: HybridBallEstimate | None = None
        self._measurement_sequence = 0

        measurement_std = np.asarray(
            config.measurement_std_m, dtype=np.float64)
        covariance = np.diag(np.square(measurement_std))
        if frame_rotation is not None:
            rotation = np.asarray(frame_rotation, dtype=np.float64)
            if rotation.shape == (3, 3) and np.all(np.isfinite(rotation)):
                covariance = rotation @ covariance @ rotation.T
        self._measurement_covariance_m2 = covariance
        self.set_ballistic_dynamics(ballistic_dynamics_enabled)

    def set_racket_pose(
        self,
        position_m: np.ndarray,
        normal: np.ndarray,
        velocity_m_s: np.ndarray | None = None,
    ) -> None:
        """Set the racket plane used by contact and impact prediction."""
        position = np.asarray(position_m, dtype=np.float64).reshape(3)
        racket_normal = np.asarray(normal, dtype=np.float64).reshape(3)
        norm = float(np.linalg.norm(racket_normal))
        if not np.all(np.isfinite(position)) or norm <= 1e-9:
            self._racket_pose = None
            return
        racket_normal = racket_normal / norm
        if racket_normal[2] < 0.0:
            racket_normal = -racket_normal
        velocity = (
            np.zeros(3, dtype=np.float64)
            if velocity_m_s is None
            else np.asarray(velocity_m_s, dtype=np.float64).reshape(3))
        self._racket_pose = {
            "position": position.tolist(),
            "normal": racket_normal.tolist(),
            "linear_velocity": velocity.tolist(),
        }

    def update(self, position_mm: Any, timestamp_s: float) -> bool:
        """Fuse one millimetre-space probe measurement."""
        position_m = np.asarray(
            position_mm, dtype=np.float64).reshape(3) * 1e-3
        estimate = self.estimator.update(
            position_m,
            float(timestamp_s),
            racket_pose=self._racket_pose,
            measurement_covariance=self._measurement_covariance_m2,
        )
        self._last_measurement_estimate = estimate
        if estimate.measurement_accepted:
            self._measurement_sequence += 1
        return bool(estimate.measurement_accepted)

    def predict_to(self, timestamp_s: float) -> dict[str, Any]:
        """Return the old probe dictionary with additional hybrid fields."""
        projected = self.estimator.predict_to(
            float(timestamp_s), racket_pose=self._racket_pose)
        selected = projected
        extrapolation_s = projected.time_since_measurement_s
        predicted = bool(
            projected.metadata.get("predicted", False)
            and self.prediction_enabled)
        if (not self.prediction_enabled
                and projected.valid
                and self._last_measurement_estimate is not None):
            selected = self._last_measurement_estimate
            extrapolation_s = 0.0

        valid = bool(projected.valid and selected.valid)
        age_s = float(projected.time_since_measurement_s)
        return {
            "position": (selected.position * 1e3).tolist(),
            "velocity": (selected.velocity * 1e3).tolist(),
            "acceleration": (selected.acceleration * 1e3).tolist(),
            "state_covariance_si": selected.state_covariance.tolist(),
            "position_std_mm": (selected.position_std * 1e3).tolist(),
            "velocity_std_mm_s": (selected.velocity_std * 1e3).tolist(),
            "acceleration_std_mm_s2": (
                selected.acceleration_std * 1e3).tolist(),
            "impact_prediction": (
                selected.impact_prediction
                if self.prediction_enabled else None),
            "detected": valid,
            "valid": valid,
            "age_s": age_s,
            "loss_s": age_s,
            "predicted": predicted,
            "state": selected.mode if valid else "lost",
            "extrapolation_s": float(extrapolation_s),
            "clamped": False,
            "output_mode": (
                "hybrid_ekf9_continuous"
                if self.prediction_enabled
                else "hybrid_ekf9_measurement_hold"),
            "snapshot_sequence": int(self._measurement_sequence),
            "snapshot_new": False,
            "snapshot_hold_s": 0.0,
            "control_age_s": age_s,
            "reject_reason": projected.metadata.get("reject_reason"),
        }

    def set_ballistic_dynamics(
        self,
        enabled: bool,
        *,
        reinitialize_from_history: bool = False,
    ) -> None:
        self.estimator.set_ballistic_dynamics(
            enabled,
            reinitialize_from_history=reinitialize_from_history,
        )

    def diagnostics(self) -> dict[str, Any]:
        diagnostics = self.estimator.diagnostics()
        diagnostics.update({
            "backend": self.backend_name,
            "reinits": 0,
            "bounces_detected": int(
                diagnostics.get("impacts_detected", 0)),
            "measurement_sequence": self._measurement_sequence,
        })
        return diagnostics


def _write_trajectory_player_html(
    run_dir: Path,
    analysis_dir: Path,
    snapshots: list[dict[str, Any]],
    metadata: dict[str, Any],
    outputs: dict[str, str],
) -> Path:
    config = metadata.get("config", {}) if isinstance(metadata, dict) else {}
    limits = config.get("limits", {}) if isinstance(config, dict) else {}
    frames = _read_jsonl(run_dir / "frames.jsonl")
    points = []
    for row in snapshots:
        ros = row.get("ros", {}) if isinstance(row.get("ros"), dict) else {}
        sim = row.get("sim") if isinstance(row.get("sim"), dict) else {}
        estimator = (
            row.get("estimator")
            if isinstance(row.get("estimator"), dict) else {}
        )
        points.append({
            "time": row.get("time"),
            "mode": row.get("mode"),
            "valid": bool(row.get("valid", False)),
            "raw": _point_or_none(row.get("rawBall")),
            "obs": _point_or_none(row.get("observedBall")),
            "measured": _point_or_none(row.get("measuredBall")),
            "predicted": _point_or_none(
                row.get("predictedBall") or estimator.get("positionM")),
            "predictedVelocity": _point_or_none(
                row.get("predictedVelocity") or estimator.get("velocityMps")),
            "racket": _point_or_none(row.get("racket")),
            "cmdRacket": _point_or_none(row.get("commandRacket")),
            "joint": _point_or_none(ros.get("jointEe")),
            "cart": _point_or_none(ros.get("cartPosition")),
            "simRacket": _point_or_none(row.get("simRacket") or sim.get("racket")),
            "simBall": _point_or_none(row.get("simBall") or sim.get("ball")),
        })
    if not points:
        samples = _read_jsonl(run_dir / "control_samples.jsonl")
        for row in samples[::max(1, int(len(samples) / 2000) or 1)]:
            sim = row.get("sim") if isinstance(row.get("sim"), dict) else {}
            estimator = (
                row.get("estimator")
                if isinstance(row.get("estimator"), dict) else {}
            )
            points.append({
                "time": row.get("time"),
                "mode": row.get("mode"),
                "valid": bool(row.get("valid", False)),
                "raw": _point_or_none(row.get("rawBall")),
                "obs": _point_or_none(row.get("observedBall")),
                "measured": _point_or_none(row.get("measuredBall")),
                "predicted": _point_or_none(
                    row.get("predictedBall") or estimator.get("positionM")),
                "predictedVelocity": _point_or_none(
                    row.get("predictedVelocity") or estimator.get("velocityMps")),
                "racket": _point_or_none(row.get("racket")),
                "cmdRacket": None,
                "joint": None,
                "cart": None,
                "simRacket": _point_or_none(sim.get("racket")),
                "simBall": _point_or_none(sim.get("ball")),
            })
    payload = {
        "limits": limits,
        "anchor": config.get("anchor") if isinstance(config, dict) else None,
        "ballBox": config.get("ballBox") if isinstance(config, dict) else None,
        "eeBox": config.get("eeBox") if isinstance(config, dict) else None,
        "points": points,
        "frames": frames,
        "outputs": outputs,
    }
    safe_payload = json.dumps(payload, separators=(",", ":"))
    doc = f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Probe Recording Analysis</title>
<style>
body {{ margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; background:#f8fafc; color:#172033; }}
header {{ display:flex; gap:14px; align-items:center; padding:12px 16px; border-bottom:1px solid #d7dee8; background:white; }}
h1 {{ margin:0; font-size:18px; }}
main {{ display:grid; grid-template-columns:minmax(0,1fr) 360px; min-height:calc(100vh - 54px); }}
.views {{ display:grid; grid-template-columns:1.3fr .9fr; grid-template-rows:1fr 1fr; min-height:0; }}
canvas {{ width:100%; height:100%; min-height:260px; border-right:1px solid #d7dee8; border-bottom:1px solid #d7dee8; background:linear-gradient(#fff,#edf2f7); }}
#view3d {{ grid-row:1 / span 2; }}
aside {{ padding:14px; background:white; border-left:1px solid #d7dee8; overflow:auto; }}
img {{ width:100%; background:#0f172a; margin:10px 0; }}
.row {{ display:flex; gap:8px; align-items:center; margin:10px 0; }}
input[type=range] {{ flex:1; }}
.mono {{ font-variant-numeric:tabular-nums; font-family:ui-monospace,SFMono-Regular,Menlo,monospace; font-size:12px; line-height:1.6; }}
a {{ color:#0f766e; }}
</style>
</head>
<body>
<header><h1>Probe Recording Analysis</h1><button id="play">Play</button><div id="status" class="mono"></div></header>
<main>
<div class="views">
<canvas id="view3d"></canvas>
<canvas id="top"></canvas>
<canvas id="side"></canvas>
</div>
<aside>
<div class="row"><input id="scrub" type="range" min="0" max="0" value="0"><span id="idx" class="mono">0</span></div>
<img id="cameraFrame" alt="recorded camera frame">
<div id="cameraStatus" class="mono">camera frames</div>
<div class="mono" id="readout"></div>
<h3>Outputs</h3>
<ul id="links"></ul>
</aside>
</main>
<script>
const DATA = {safe_payload};
const points = DATA.points || [];
let i = 0, playing = false, timer = null;
const limits = DATA.limits || {{x0:-1,x1:1,y0:-1,y1:1,z0:0,z1:2}};
const canvases = {{view3d:document.getElementById('view3d'), top:document.getElementById('top'), side:document.getElementById('side')}};
const scrub = document.getElementById('scrub');
const idx = document.getElementById('idx');
const status = document.getElementById('status');
const readout = document.getElementById('readout');
const play = document.getElementById('play');
const cameraFrame = document.getElementById('cameraFrame');
const cameraStatus = document.getElementById('cameraStatus');
scrub.max = Math.max(0, points.length - 1);
function resize(c) {{ const r=c.getBoundingClientRect(), d=window.devicePixelRatio||1; c.width=Math.max(1,r.width*d); c.height=Math.max(1,r.height*d); c.getContext('2d').setTransform(d,0,0,d,0,0); }}
function pObj(a) {{ return a ? {{x:a[0],y:a[1],z:a[2]}} : null; }}
function topP(p,c) {{ const r=c.getBoundingClientRect(); return {{x:(p.x-limits.x0)/(limits.x1-limits.x0)*r.width,y:r.height-(p.y-limits.y0)/(limits.y1-limits.y0)*r.height}}; }}
function sideP(p,c) {{ const r=c.getBoundingClientRect(); return {{x:(p.x-limits.x0)/(limits.x1-limits.x0)*r.width,y:r.height-(p.z-limits.z0)/(limits.z1-limits.z0)*r.height}}; }}
function sceneCenter() {{ return {{x:(limits.x0+limits.x1)/2,y:(limits.y0+limits.y1)/2,z:(limits.z0+limits.z1)/2}}; }}
function sceneRadius() {{ return Math.max(limits.x1-limits.x0, limits.y1-limits.y0, limits.z1-limits.z0) * 0.58; }}
function p3(p,c) {{ const r=c.getBoundingClientRect(), ce=sceneCenter(); let x=p.x-ce.x,y=p.y-ce.y,z=p.z-ce.z; const yaw=-0.72,pitch=0.46,cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch); const x1=cy*x-sy*y,y1=sy*x+cy*y,y2=cp*y1-sp*z; const scale=Math.min(r.width,r.height)*0.42/Math.max(sceneRadius(),1e-6); return {{x:r.width*0.52+x1*scale,y:r.height*0.54-y2*scale}}; }}
function dot(ctx,q,color,rad) {{ ctx.fillStyle=color; ctx.strokeStyle='white'; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(q.x,q.y,rad,0,Math.PI*2); ctx.fill(); ctx.stroke(); }}
function trail(ctx,c,proj,key,color,n=180) {{ ctx.strokeStyle=color; ctx.lineWidth=2; ctx.globalAlpha=.45; ctx.beginPath(); let moved=false; for (let k=Math.max(0,i-n); k<=i; k++) {{ const p=pObj(points[k]&&points[k][key]); if(!p) continue; const q=proj(p,c); if(!moved) {{ctx.moveTo(q.x,q.y); moved=true;}} else ctx.lineTo(q.x,q.y); }} ctx.stroke(); ctx.globalAlpha=1; }}
function drawCanvas(c, title, proj) {{ const ctx=c.getContext('2d'), r=c.getBoundingClientRect(); ctx.clearRect(0,0,r.width,r.height); trail(ctx,c,proj,'raw','#f28e2b'); trail(ctx,c,proj,'obs','#e15759'); trail(ctx,c,proj,'predicted','#8b5cf6'); trail(ctx,c,proj,'racket','#4e79a7'); trail(ctx,c,proj,'simRacket','#0f766e'); trail(ctx,c,proj,'simBall','#22c55e'); const row=points[i]||{{}}; [['raw','#f28e2b',8],['obs','#e15759',6],['measured','#f59e0b',5],['predicted','#8b5cf6',6],['racket','#4e79a7',8],['simRacket','#0f766e',7],['simBall','#22c55e',5],['joint','#16a34a',6],['cart','#9333ea',6]].forEach(([k,col,rad])=>{{const p=pObj(row[k]); if(p) dot(ctx,proj(p,c),col,rad);}}); ctx.fillStyle='#273445'; ctx.font='14px sans-serif'; ctx.fillText(title,14,22); }}
function draw() {{ for (const c of Object.values(canvases)) resize(c); drawCanvas(canvases.view3d,'3D replay',p3); drawCanvas(canvases.top,'Top x/y',topP); drawCanvas(canvases.side,'Side x/z',sideP); const row=points[i]||{{}}; const frame=(DATA.frames||[])[Math.min(i,Math.max(0,(DATA.frames||[]).length-1))]; if(frame&&frame.path) {{ cameraFrame.style.display='block'; cameraFrame.src=`../${{frame.path}}`; }} else {{ cameraFrame.style.display='none'; }} cameraStatus.textContent=`camera frames=${{(DATA.frames||[]).length}}`; scrub.value=i; idx.textContent=`${{i+1}}/${{points.length}}`; status.textContent=`t=${{Number(row.time||0).toFixed(3)}}s mode=${{row.mode||''}}`; readout.textContent=JSON.stringify(row,null,2); }}
function step() {{ if(!playing) return; i=(i+1)%Math.max(1,points.length); draw(); timer=setTimeout(step, 1000/60); }}
play.onclick=()=>{{ playing=!playing; play.textContent=playing?'Pause':'Play'; if(playing) step(); }};
scrub.oninput=()=>{{ i=Number(scrub.value)||0; draw(); }};
const links=document.getElementById('links'); Object.entries(DATA.outputs||{{}}).forEach(([k,v])=>{{ if(!v) return; const li=document.createElement('li'), a=document.createElement('a'); a.href=v; a.textContent=`${{k}}: ${{v}}`; li.appendChild(a); links.appendChild(li); }});
window.addEventListener('resize', draw); draw();
</script>
</body>
</html>
"""
    out = analysis_dir / "trajectory_player.html"
    out.write_text(doc, encoding="utf-8")
    return out


def _obs_names(width: int) -> list[str]:
    if width in (72, 117, 156):
        prefix = [*(f"arm_q[{i}]" for i in range(7)),
                  *(f"arm_dq[{i}]" for i in range(7)),
                  *(f"q_ref_error[{i}]" for i in range(7)),
                  *(f"projected_previous_action[{i}]" for i in range(7)),
                  *(f"held_ball_history[{tick}].{axis}" for tick in range(8) for axis in "xyz")]
        if width in (72, 117):
            names = prefix + [*(f"racket_pose[{i}]" for i in range(9)),
                             *(f"ball_age_history[{i}]/0.25" for i in range(8)),
                             "episode_target_x", "episode_target_y", "ball_observed"]
            if width == 117:
                for lag_ms in (50, 100, 200):
                    names += [*(f"history_{lag_ms}ms.local_ball_delta_{axis}" for axis in "xyz"),
                              *(f"history_{lag_ms}ms.local_normal_delta_{axis}" for axis in "xyz"),
                              *(f"history_{lag_ms}ms.q_ref_error[{i}]" for i in range(7)),
                              f"history_{lag_ms}ms.ball_age/0.25", f"history_{lag_ms}ms.valid"]
            return names
        return prefix + [*(f"racket_pose_history[{tick}][{i}]" for tick in range(8) for i in range(9)),
                         *(f"ball_age_history[{i}]/0.25" for i in range(8)),
                         "desired_apex_z", "episode_target_x", "episode_target_y", "ball_valid", "hit_count/4",
                         *(f"predicted_contact_ball_{a}" for a in "xyz"), "time_to_contact", "contact_valid",
                         *(f"racket_target_{a}" for a in "xyz"), *(f"target_rotation6d[{i}]" for i in range(6)),
                         *(f"target_minus_surface_{a}" for a in "xyz"), "next_crossing_x", "next_crossing_y"]
    if width == 57:
        return [
            *(f"arm_q[{i}]" for i in range(7)),
            *(f"arm_dq[{i}]" for i in range(7)),
            "base_q_x", "base_q_y", "base_q_yaw",
            "base_dq_x", "base_dq_y", "base_dq_yaw",
            "ball_pos_x", "ball_pos_y", "ball_pos_z",
            "ball_vel_x", "ball_vel_y", "ball_vel_z",
            "racket_pos_x", "racket_pos_y", "racket_pos_z",
            "racket_vel_x", "racket_vel_y", "racket_vel_z",
            "rel_x", "rel_y", "rel_z",
            *(f"prev_action[{i}]" for i in range(7)),
            *(f"arm_dq_delta[{i}]" for i in range(7)),
            "ball_age_norm",
            *(f"q_ref_error[{i}]" for i in range(7)),
        ]
    names = [
        "arm_q[0]", "arm_q[1]", "arm_q[2]", "arm_q[3]", "arm_q[4]", "arm_q[5]", "arm_q[6]",
        "arm_dq[0]", "arm_dq[1]", "arm_dq[2]", "arm_dq[3]", "arm_dq[4]", "arm_dq[5]", "arm_dq[6]",
        "base_q_x", "base_q_y", "base_q_yaw",
        "base_dq_x", "base_dq_y", "base_dq_yaw",
        "ball_pos_x", "ball_pos_y", "ball_pos_z",
        "ball_vel_x", "ball_vel_y", "ball_vel_z",
        "racket_pos_x", "racket_pos_y", "racket_pos_z",
        "racket_vel_x", "racket_vel_y", "racket_vel_z",
        "rel_x", "rel_y", "rel_z",
        "prev_action[0]", "prev_action[1]", "prev_action[2]", "prev_action[3]",
        "prev_action[4]", "prev_action[5]", "prev_action[6]",
        "arm_cmd_error[0]", "arm_cmd_error[1]", "arm_cmd_error[2]", "arm_cmd_error[3]",
        "arm_cmd_error[4]", "arm_cmd_error[5]", "arm_cmd_error[6]",
        "ball_age_norm",
        "tau_act_norm",
        "arm_cmd_qvel[0]", "arm_cmd_qvel[1]", "arm_cmd_qvel[2]",
        "arm_cmd_qvel[3]", "arm_cmd_qvel[4]", "arm_cmd_qvel[5]",
        "arm_cmd_qvel[6]",
        "active_cmd_error[0]", "active_cmd_error[1]", "active_cmd_error[2]",
        "active_cmd_error[3]", "active_cmd_error[4]", "active_cmd_error[5]",
        "active_cmd_error[6]",
        "t_contact_est", "t_margin",
    ]
    if width <= len(names):
        return names[:width]
    return names + [f"obs[{i}]" for i in range(len(names), width)]


def _policy_observation_scales(value: object, width: int) -> tuple[float, ...]:
    """Return a finite, bounded, independent scale for every actor obs."""
    scales = np.ones(max(0, int(width)), dtype=np.float32)
    if isinstance(value, (list, tuple, np.ndarray)):
        try:
            candidate = np.asarray(value, dtype=np.float64).reshape(-1)
        except (TypeError, ValueError):
            return tuple(float(item) for item in scales)
        count = min(scales.size, candidate.size)
        finite = np.isfinite(candidate[:count])
        scales[:count] = np.where(
            finite,
            np.clip(candidate[:count], -100.0, 100.0),
            1.0,
        ).astype(np.float32)
    return tuple(float(item) for item in scales)


def _default_policy_observation_scales(
    width: int,
    dq_scale: float,
) -> tuple[float, ...]:
    """Build launch defaults, with arm dq occupying obs indices 7..13."""
    scales = np.ones(max(0, int(width)), dtype=np.float32)
    scale = float(dq_scale)
    if not math.isfinite(scale):
        scale = 1.0
    if scales.size > 7:
        scales[7:min(14, scales.size)] = np.float32(
            np.clip(scale, -100.0, 100.0))
    return tuple(float(item) for item in scales)


def _decimate_rows(rows: list[dict[str, Any]], max_rows: int) -> list[dict[str, Any]]:
    if len(rows) <= max_rows:
        return rows
    step = max(1, int(math.ceil(len(rows) / max_rows)))
    return rows[::step]


def _make_analysis_data(
    run_dir: Path,
    snapshots: list[dict[str, Any]],
    samples: list[dict[str, Any]],
    metadata: dict[str, Any],
    outputs: dict[str, str],
    noise_report: dict[str, Any],
) -> dict[str, Any]:
    config = metadata.get("config", {}) if isinstance(metadata, dict) else {}
    frames_raw = _read_jsonl(run_dir / "frames.jsonl")
    frames = []
    for row in frames_raw:
        path_text = str(row.get("path", ""))
        filename = Path(path_text).name
        if filename:
            frames.append({
                "filename": filename,
                "wallTimeS": row.get("wallTimeS"),
                "info": row.get("info") if isinstance(row.get("info"), dict) else {},
            })
    sim_frames_raw = _read_jsonl(run_dir / "sim_frames.jsonl")
    sim_frames = []
    for row in sim_frames_raw:
        path_text = str(row.get("path", ""))
        filename = Path(path_text).name
        if filename:
            sim_frames.append({
                "filename": filename,
                "wallTimeS": row.get("wallTimeS"),
                "info": row.get("info") if isinstance(row.get("info"), dict) else {},
            })
    points = []
    for row in _decimate_rows(snapshots, 3000):
        ros = row.get("ros", {}) if isinstance(row.get("ros"), dict) else {}
        sim = row.get("sim") if isinstance(row.get("sim"), dict) else {}
        estimator = (
            row.get("estimator")
            if isinstance(row.get("estimator"), dict) else {}
        )
        points.append({
            "time": row.get("time"),
            "mode": row.get("mode"),
            "valid": bool(row.get("valid", False)),
            "raw": _point_or_none(row.get("rawBall")),
            "measured": _point_or_none(row.get("measuredBall")),
            "obs": _point_or_none(row.get("observedBall")),
            "predictedBall": _point_or_none(
                row.get("predictedBall") or estimator.get("positionM")),
            "predictedVelocity": _point_or_none(
                row.get("predictedVelocity") or estimator.get("velocityMps")),
            "racket": _point_or_none(row.get("racket")),
            "cmdRacket": _point_or_none(row.get("commandRacket")),
            "joint": _point_or_none(ros.get("jointEe")),
            "cart": _point_or_none(ros.get("cartPosition")),
            "simRacket": _point_or_none(sim.get("racket")),
            "simBall": _point_or_none(sim.get("ball")),
        })
    curve_rows = []
    sample_subset = _decimate_rows(samples, 8000)
    obs_width = max((len(r.get("policyObs", [])) for r in sample_subset), default=0)
    action_width = max((len(r.get("policyAction", [])) for r in sample_subset), default=0)
    sim_obs_width = max((
        len(r.get("sim", {}).get("policyObs", []))
        for r in sample_subset if isinstance(r.get("sim"), dict)
    ), default=0)
    sim_action_width = max((
        len(r.get("sim", {}).get("policyAction", []))
        for r in sample_subset if isinstance(r.get("sim"), dict)
    ), default=0)
    for row in sample_subset:
        ros = row.get("ros") if isinstance(row.get("ros"), dict) else {}
        command = row.get("command") if isinstance(row.get("command"), dict) else {}
        sim = row.get("sim") if isinstance(row.get("sim"), dict) else {}
        estimator = (
            row.get("estimator")
            if isinstance(row.get("estimator"), dict) else {}
        )
        runtime = row.get("runtime") if isinstance(
            row.get("runtime"), dict) else {}
        sim_sync = sim.get("sync") if isinstance(
            sim.get("sync"), dict) else {}
        policy_obs = (
            row.get("policyObs", [])
            if isinstance(row.get("policyObs"), list) else [])
        sim_policy_obs = (
            sim.get("policyObs", [])
            if isinstance(sim.get("policyObs"), list) else [])
        curve_rows.append({
            "time": row.get("time"),
            "tick": row.get("tick"),
            "sourceSeq": _sample_source_seq(row),
            "mode": row.get("mode"),
            "policyExecuted": _sample_policy_executed(row),
            "simAligned": bool(row.get("simAligned", False)),
            "ballSource": row.get("ballSource"),
            "policyProfile": runtime.get(
                "activePolicyProfile", runtime.get("policyProfile")),
            "policyGeneration": runtime.get("policyGeneration"),
            "simEpisode": sim_sync.get("episode"),
            "valid": bool(row.get("valid", False)),
            "age": row.get("age"),
            "rawBall": _point_or_none(row.get("rawBall")),
            "measuredBall": _point_or_none(row.get("measuredBall")),
            "observedBall": _point_or_none(row.get("observedBall")),
            "measuredVelocity": _point_or_none(row.get("measuredVelocity")),
            "observedVelocity": _point_or_none(row.get("observedVelocity")),
            "predictedBall": _point_or_none(
                row.get("predictedBall") or estimator.get("positionM")),
            "predictedVelocity": _point_or_none(
                row.get("predictedVelocity") or estimator.get("velocityMps")),
            "estimatorPredicted": bool(estimator.get(
                "predicted", row.get("predictedBallIsPredicted", False))),
            "estimatorState": estimator.get("state"),
            "estimatorOutputMode": estimator.get("outputMode"),
            "policyObs": policy_obs,
            "policyAction": row.get("policyAction", []) if isinstance(row.get("policyAction"), list) else [],
            "policyExecutedAction": row.get(
                "policyExecutedAction", []) if isinstance(
                    row.get("policyExecutedAction"), list) else [],
            "rosJointPosition": ros.get("jointPosition", []) if isinstance(ros.get("jointPosition"), list) else [],
            "rosJointVelocity": ros.get("jointVelocity", []) if isinstance(ros.get("jointVelocity"), list) else [],
            "rosJointAcceleration": ros.get("jointAcceleration", []) if isinstance(ros.get("jointAcceleration"), list) else [],
            "rosJointAccelerationSource": ros.get("jointAccelerationSource", "unavailable"),
            "commandPosition": command.get("position", []) if isinstance(command.get("position"), list) else [],
            "policyNominalPosition": command.get(
                "policyNominalPosition", []) if isinstance(
                    command.get("policyNominalPosition"), list) else [],
            "compensatedPosition": command.get(
                "compensatedReferencePosition", []) if isinstance(
                    command.get("compensatedReferencePosition"), list) else [],
            "publishedPosition": command.get(
                "publishedSafePosition", []) if isinstance(
                    command.get("publishedSafePosition"), list) else [],
            "racket": _point_or_none(row.get("racket") or ros.get("jointEe")),
            "commandRacket": _point_or_none(row.get("commandRacket")),
            "simPolicyObs": sim_policy_obs,
            "simPolicyAction": sim.get("policyAction", []) if isinstance(sim.get("policyAction"), list) else [],
            "simPolicyExecutedAction": sim.get(
                "policyExecutedAction", []) if isinstance(
                    sim.get("policyExecutedAction"), list) else [],
            "simPolicyCommand": sim.get("policyCommand", []) if isinstance(sim.get("policyCommand"), list) else [],
            "simJointPosition": sim.get("jointPosition", []) if isinstance(sim.get("jointPosition"), list) else [],
            "simJointVelocity": sim.get("jointVelocity", []) if isinstance(sim.get("jointVelocity"), list) else [],
            "simJointAcceleration": sim.get("jointAcceleration", []) if isinstance(sim.get("jointAcceleration"), list) else [],
            "simJointAccelerationSource": sim.get("jointAccelerationSource", "unavailable"),
            "simRacket": _point_or_none(sim.get("racket")),
            "simEe": _point_or_none(sim.get("racket")),
            "simBall": _point_or_none(sim.get("ball")),
            "realJointPositionObs": policy_obs[0:7],
            "simJointPositionObs": sim_policy_obs[0:7],
            "realJointVelocityObs": policy_obs[7:14],
            "simJointVelocityObs": sim_policy_obs[7:14],
            **{side + feature: _policy_observation_feature(values, feature)
               for side, values in (("real", policy_obs), ("sim", sim_policy_obs))
               for feature in ("BallObservationObs", "RacketPositionObs", "RacketVelocityObs",
                               "RelativeBallRacketObs", "TrackingErrorObs", "NominalVelocityObs",
                               "DelayedTrackingErrorObs", "ContactPhaseObs")},
        })
    sim_comparison = {}
    sim_comparison_path = run_dir / "analysis" / "sim_real_comparison.json"
    if sim_comparison_path.is_file():
        try:
            sim_comparison = json.loads(sim_comparison_path.read_text(encoding="utf-8"))
        except Exception:
            sim_comparison = {}
    selected_cohort = sim_comparison.get("selectedCohort")
    selected_cohort = (
        selected_cohort if isinstance(selected_cohort, dict) else None)
    for row in curve_rows:
        if selected_cohort is None:
            row["simAnalysisSelected"] = bool(row.get("simAligned", False))
            continue
        row["simAnalysisSelected"] = bool(
            row.get("simAligned", False)
            and str(row.get("policyProfile"))
            == str(selected_cohort.get("policyProfile"))
            and int(row.get("policyGeneration", 0) or 0)
            == int(selected_cohort.get("policyGeneration", 0) or 0)
            and int(row.get("simEpisode", 0) or 0)
            == int(selected_cohort.get("simEpisode", 0) or 0)
        )
    return {
        "metadata": {
            "analysisSchemaVersion": ANALYSIS_SCHEMA_VERSION,
            "runDir": str(run_dir),
            "sampleCount": len(samples),
            "snapshotCount": len(snapshots),
            "curveSampleCount": len(curve_rows),
        },
        "limits": config.get("limits", {}) if isinstance(config, dict) else {},
        "anchor": config.get("anchor") if isinstance(config, dict) else None,
        "ballBox": config.get("ballBox") if isinstance(config, dict) else None,
        "eeBox": config.get("eeBox") if isinstance(config, dict) else None,
        "frames": frames,
        "simFrames": sim_frames,
        "points": points,
        "samples": curve_rows,
        "obsNames": _obs_names(obs_width),
        "actionNames": [f"action[{i}]" for i in range(action_width)],
        "simObsNames": _obs_names(sim_obs_width),
        "simActionNames": [f"action[{i}]" for i in range(sim_action_width)],
        "noiseReport": noise_report,
        "simRealComparison": sim_comparison,
        "outputs": dict(outputs),
    }


def _analyze_trajectory_recording(run_dir, analysis_dir, metadata, status_q):
    """Stream all records to CSV and bound every in-memory plot/replay list."""
    _analysis_write_status(status_q, active=True, phase="ball_trajectory", analysis_dir=analysis_dir)
    samples, report = export_ball_trajectory(run_dir, analysis_dir)
    outputs = {"ballTrajectoryCsv": report["fullResolutionFile"]}
    for path in _plot_ball_state_curves(samples, analysis_dir):
        outputs[path.stem] = path.name
    summary_path = run_dir / "summary.json"
    summary = json.loads(summary_path.read_text()) if summary_path.is_file() else {}
    config = metadata.get("config") or {}
    point_stride = max(1, math.ceil(max(0, len(samples) - 1) / 2999))
    points = [{"time": row.get("time"), "mode": row.get("mode"), "valid": row.get("valid"),
               "raw": row.get("rawBall"), "measured": row.get("measuredBall"),
               "obs": row.get("observedBall"), "predictedBall": row.get("predictedBall"),
               "racket": row.get("racket")} for index, row in enumerate(samples)
              if index % point_stride == 0 or index == len(samples) - 1]
    frames = [{"filename": Path(row.get("path", "")).name,
               "wallTimeS": row.get("wallTimeS"), "info": row.get("info", {})}
              for row in preview_jsonl(run_dir / "frames.jsonl")]
    outputs["analysisData"] = "analysis_data.json"
    data = {
        "metadata": {"analysisSchemaVersion": ANALYSIS_SCHEMA_VERSION,
                     "runDir": str(run_dir), "trajectoryOnly": True, **report},
        **{key: config.get(key) for key in ("limits", "anchor", "ballBox", "eeBox")},
        "frames": frames, "simFrames": [], "points": points, "samples": samples,
        "obsNames": [], "actionNames": [], "simObsNames": [], "simActionNames": [],
        "juggle": summary.get("juggle", {}), "outputs": outputs,
    }
    (analysis_dir / "analysis_data.json").write_text(_strict_json_dumps(data) + "\n", encoding="utf-8")
    (analysis_dir / "analysis_summary.json").write_text(json.dumps({
        "analysisSchemaVersion": ANALYSIS_SCHEMA_VERSION, "runDir": str(run_dir),
        "trajectoryOnly": True, "samples": report["sampleCount"], "trajectory": report,
        "juggle": summary.get("juggle", {}), "outputs": outputs,
        "completedWallTimeS": time.time(),
    }, indent=2) + "\n", encoding="utf-8")
    _analysis_write_status(status_q, active=False, phase="done", analysis_dir=analysis_dir, outputs=outputs)


def _recording_analysis_main(
    run_dir_text: str,
    status_q,
    video_fps: float,
    ball_sensors_only: bool = False,
) -> None:
    try:
        os.nice(10)
    except (AttributeError, OSError):
        pass
    os.environ.setdefault("MPLCONFIGDIR", "/tmp/matplotlib")
    run_dir = Path(run_dir_text)
    analysis_dir = run_dir / "analysis"
    outputs: dict[str, str] = {}
    try:
        analysis_dir.mkdir(parents=True, exist_ok=True)
        metadata_path = run_dir / "metadata.json"
        metadata = json.loads(metadata_path.read_text()) if metadata_path.is_file() else {}
        if (metadata.get("recording") or {}).get("trajectoryOnly", False):
            _analyze_trajectory_recording(run_dir, analysis_dir, metadata, status_q)
            return
        from pingpong_controller.ball_sensor_comparison import analyze_ball_sensor_comparison
        if ball_sensors_only:
            _analysis_write_status(status_q, active=True, phase="ball_sensor_comparison", analysis_dir=analysis_dir)
            sensor_report = analyze_ball_sensor_comparison(run_dir, analysis_dir)
            summary_path = analysis_dir / "analysis_summary.json"
            previous = json.loads(summary_path.read_text(encoding="utf-8")) if summary_path.is_file() else {}
            outputs.update(previous.get("outputs") or {})
            outputs.update(sensor_report["outputs"])
            # A comparison-only directory must still be re-analyzed when
            # the operator later requests the full trajectory/video report.
            previous.update(
                analysisSchemaVersion=(ANALYSIS_SCHEMA_VERSION if previous.get("analysisSchemaVersion", 0) >= 8 else 0),
                runDir=str(run_dir), analysisDir=str(analysis_dir), outputs=outputs,
                ballSensorComparison=sensor_report, completedWallTimeS=time.time())
            summary_path.write_text(json.dumps(previous, indent=2) + "\n", encoding="utf-8")
            _analysis_write_status(status_q, active=False, phase="done", analysis_dir=analysis_dir, outputs=outputs)
            return
        _analysis_write_status(
            status_q, active=True, phase="loading", analysis_dir=analysis_dir)
        metadata_path = run_dir / "metadata.json"
        metadata = (
            json.loads(metadata_path.read_text(encoding="utf-8"))
            if metadata_path.is_file() else {}
        )
        raw_samples = _read_jsonl(run_dir / "control_samples.jsonl")
        sim_samples = _read_jsonl(run_dir / "sim_control_samples.jsonl")
        samples, alignment_report = _align_sim_real_samples(
            raw_samples, sim_samples)
        summary_path = run_dir / "summary.json"
        summary_present = summary_path.is_file()
        recording_summary = (
            json.loads(summary_path.read_text(encoding="utf-8"))
            if summary_present else {}
        )
        try:
            recorder_dropped = max(
                0, int(recording_summary.get("dropped", 0) or 0))
        except (TypeError, ValueError):
            recorder_dropped = 0
        alignment_events = [
            row for row in _read_jsonl(run_dir / "events.jsonl")
            if str(row.get("event", "")) == "sim_alignment"
        ]
        final_alignment_event = (
            dict(alignment_events[-1]) if alignment_events else {})
        invalid_reasons: list[str] = []
        sequence_aligned = bool(
            alignment_report.get("alignmentValid", False))
        schema_v2 = any(
            int(row.get("schemaVersion", 0) or 0) >= 2
            for row in raw_samples
        )
        config = metadata.get("config", {}) if isinstance(metadata, dict) else {}
        try:
            control_rate_hz = max(
                1e-6, float(config.get("controlRateHz", 200.0)))
        except (TypeError, ValueError):
            control_rate_hz = 200.0
        realtime_report = _realtime_alignment_report(
            raw_samples, sim_samples, control_rate_hz)
        if schema_v2 and not summary_present:
            invalid_reasons.append("recording_summary_missing")
        if schema_v2 and sim_samples and not final_alignment_event:
            invalid_reasons.append("final_sim_alignment_event_missing")
        if (schema_v2 and sim_samples
                and not bool(realtime_report.get("realtimeAligned", False))):
            invalid_reasons.append("sim_not_realtime_aligned")
        if recorder_dropped > 0:
            invalid_reasons.append("recorder_queue_dropped_samples")
        if (final_alignment_event.get("simEnabled") is True
                and not bool(final_alignment_event.get("alignmentValid", False))):
            invalid_reasons.append("sim_flush_or_stream_invalid")
        alignment_report["alignmentValid"] = bool(
            sequence_aligned and not invalid_reasons)
        alignment_report.update({
            "sequenceAligned": sequence_aligned,
            "realtimeAligned": bool(
                realtime_report.get("realtimeAligned", False)),
            "realtime": realtime_report,
            "recorderDropped": recorder_dropped,
            "recordingSummaryPresent": summary_present,
            "finalAlignmentEvent": final_alignment_event,
            "invalidReasons": invalid_reasons,
        })
        (analysis_dir / "alignment_manifest.json").write_text(
            json.dumps(alignment_report, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        outputs["alignmentManifest"] = "alignment_manifest.json"
        snapshots = _read_jsonl(run_dir / "snapshots.jsonl")

        _analysis_write_status(status_q, active=True, phase="ball_sensor_comparison", analysis_dir=analysis_dir, outputs=outputs)
        sensor_report = analyze_ball_sensor_comparison(run_dir, analysis_dir, control_samples=raw_samples)
        outputs.update(sensor_report["outputs"])

        _analysis_write_status(
            status_q, active=True, phase="camera_video",
            analysis_dir=analysis_dir, outputs=outputs)
        video_path, video_info = _build_camera_video(
            run_dir, analysis_dir, fps=max(1.0, float(video_fps)))
        (analysis_dir / "camera_video_info.json").write_text(
            json.dumps(video_info, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        if video_path is not None:
            outputs["cameraVideo"] = video_path.name
        sim_video_path, sim_video_info = _build_sim_video(
            run_dir, analysis_dir, fps=max(1.0, float(video_fps)))
        (analysis_dir / "sim_video_info.json").write_text(
            json.dumps(sim_video_info, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        outputs["simVideoInfo"] = "sim_video_info.json"
        if sim_video_path is not None:
            outputs["simVideo"] = sim_video_path.name

        _analysis_write_status(
            status_q, active=True, phase="policy_curves",
            analysis_dir=analysis_dir, outputs=outputs)
        trace_csv = _write_policy_trace_csv(samples, analysis_dir)
        outputs["policyTraceCsv"] = trace_csv.name
        for plot_path in _plot_policy_curves(samples, analysis_dir):
            outputs[plot_path.stem] = plot_path.name
        for plot_path in _plot_ball_state_curves(samples, analysis_dir):
            outputs[plot_path.stem] = plot_path.name
        for plot_path in _plot_ball_racket_position_curves(samples, analysis_dir):
            outputs["ballRacketPositionCurves"] = plot_path.name
        contact_gap_report = _analyze_ball_racket_contact_gaps(
            samples, analysis_dir)
        outputs["ballRacketContactGapsCsv"] = "ball_racket_contact_gaps.csv"
        outputs["ballRacketContactGapsJson"] = "ball_racket_contact_gaps.json"
        outputs["ballRacketContactGapsText"] = "ball_racket_contact_gaps.txt"
        for plot_path in _plot_camera_measurement_curves(samples, analysis_dir):
            outputs[plot_path.stem] = plot_path.name

        _analysis_write_status(
            status_q, active=True, phase="noise",
            analysis_dir=analysis_dir, outputs=outputs)
        noise_report = _analyze_ball_noise(samples, analysis_dir)
        outputs["ballNoiseReport"] = "ball_noise_report.json"
        outputs["ballNoiseResiduals"] = "ball_noise_residuals.png"
        sim_report = _analyze_sim_real_gap(
            samples, analysis_dir, alignment=alignment_report)
        outputs["simRealComparison"] = "sim_real_comparison.json"
        outputs["simRealComparisonCsv"] = "sim_real_comparison.csv"
        outputs["simRealComparisonText"] = "sim_real_comparison.txt"
        if sim_report.get("timeSeriesCsv"):
            outputs["sim2RealGapTimeSeries"] = str(
                sim_report["timeSeriesCsv"])
        if sim_report.get("timeSeriesPlot"):
            outputs["sim2RealGapPlot"] = str(
                sim_report["timeSeriesPlot"])
        if sim_report.get("comparisonPlot"):
            outputs["simRealComparisonPlot"] = str(sim_report["comparisonPlot"])
        if sim_report.get("jointAccelerationCsv"):
            outputs["jointAccelerationComparisonCsv"] = str(
                sim_report["jointAccelerationCsv"])
        if sim_report.get("jointAccelerationPlot"):
            outputs["jointAccelerationComparisonPlot"] = str(
                sim_report["jointAccelerationPlot"])

        _analysis_write_status(
            status_q, active=True, phase="player",
            analysis_dir=analysis_dir, outputs=outputs)
        player = _write_trajectory_player_html(
            run_dir, analysis_dir, snapshots, metadata, outputs)
        outputs["trajectoryPlayer"] = player.name
        analysis_data = _make_analysis_data(
            run_dir, snapshots, samples, metadata, outputs, noise_report)
        (analysis_dir / "analysis_data.json").write_text(
            _strict_json_dumps(analysis_data, separators=(",", ":")) + "\n",
            encoding="utf-8",
        )
        outputs["analysisData"] = "analysis_data.json"
        summary = {
            "analysisSchemaVersion": ANALYSIS_SCHEMA_VERSION,
            "runDir": str(run_dir),
            "analysisDir": str(analysis_dir),
            "samples": len(samples),
            "simSamples": len(sim_samples),
            "alignmentValid": bool(
                alignment_report.get("alignmentValid", False)),
            "sim2RealSelectedCohort": sim_report.get("selectedCohort"),
            "sim2RealPrimaryGapHint": (
                (sim_report.get("diagnostics") or {}).get(
                    "primaryGapHint")),
            "ballRacketContactDiagnostics": contact_gap_report,
            "ballSensorComparison": sensor_report,
            "snapshots": len(snapshots),
            "outputs": outputs,
            "completedWallTimeS": time.time(),
        }
        (analysis_dir / "analysis_summary.json").write_text(
            json.dumps(summary, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        _analysis_write_status(
            status_q, active=False, phase="done",
            analysis_dir=analysis_dir, outputs=outputs)
    except BaseException as exc:  # noqa: BLE001 - report to UI.
        _analysis_write_status(
            status_q,
            active=False,
            phase="error",
            analysis_dir=analysis_dir,
            outputs=outputs,
            error=f"{exc}\n{traceback.format_exc()}",
        )


def _compact_sim_record_sample(sample: dict[str, Any]) -> dict[str, Any]:
    """Keep exact sim2real evidence without re-sending static sim metadata."""
    compact = {
        "schemaVersion": RECORDING_SCHEMA_VERSION,
        "enabled": bool(sample.get("enabled", True)),
        "available": bool(sample.get("available", True)),
        "active": bool(sample.get("active", False)),
        "backend": sample.get("backend"),
        "policyProfile": sample.get("policyProfile"),
        "policyModel": sample.get("policyModel"),
        "timeWallS": sample.get("timeWallS"),
        "valid": bool(sample.get("valid", False)),
        "age": sample.get("age"),
        "ball": sample.get("ball"),
        "velocity": sample.get("velocity"),
        "jointPosition": sample.get("jointPosition"),
        "jointVelocity": sample.get("jointVelocity"),
        "jointAcceleration": sample.get("jointAcceleration"),
        "jointAccelerationSource": sample.get("jointAccelerationSource"),
        "actuatorTarget": sample.get("actuatorTarget"),
        "policyCommand": sample.get("policyCommand"),
        "compensatedCommand": sample.get("compensatedCommand"),
        "activeCommand": sample.get("activeCommand"),
        "activeCompensatedCommand": sample.get("activeCompensatedCommand"),
        "appliedCommand": sample.get("appliedCommand"),
        "racket": sample.get("racket"),
        "racketQuatXyzw": sample.get("racketQuatXyzw"),
        "policyObs": sample.get("policyObs"),
        "policyBallObservation": sample.get("policyBallObservation"),
        "policyAction": sample.get("policyAction"),
        "policyExecutedAction": sample.get(
            "policyExecutedAction", sample.get("policyAction")),
        "command": sample.get("command"),
        "sync": dict(sample.get("sync") or {}),
    }
    unscaled = sample.get("policyObsUnscaled")
    if (unscaled is not None
            and not np.array_equal(unscaled, sample.get("policyObs"))):
        compact["policyObsUnscaled"] = unscaled
    policy_dq = sample.get("policyJointVelocity")
    if sample.get("fplcProjection"):
        compact["fplcProjection"] = dict(sample["fplcProjection"])
    if policy_dq is not None:
        compact["policyJointVelocity"] = policy_dq
    dq_contract = sample.get("dqObservationContract")
    if dq_contract:
        compact["dqObservationContract"] = dict(dq_contract)
    return compact


def _compact_inactive_diagnostic(payload: Any) -> dict[str, Any]:
    """Retain full intervention evidence, summarize the common idle case."""
    if not isinstance(payload, dict):
        return {}
    if bool(
        payload.get("active", False)
        or payload.get("intervened", False)
        or payload.get("predicted", False)
    ):
        return dict(payload)
    return {
        key: payload.get(key)
        for key in (
            "configuredEnabled", "enabled", "active", "intervened",
            "predicted", "state", "reason", "sampleIndex",
        )
        if key in payload
    }


class AsyncProbeRecorder:
    def __init__(self, cfg: ProbeConfig):
        self.cfg = cfg
        self.lock = threading.Lock()
        # The writer is spawned during probe construction, before ROS/camera
        # control starts.  Clicking Record only configures this standby child,
        # so heavyweight module import never occurs in a live control period.
        self.start_method = "spawn"
        self.ctx = mp.get_context(self.start_method)
        self.event_q = None
        self.status_q = None
        self.process: mp.Process | None = None
        self.analysis_status_q = None
        self.analysis_process: mp.Process | None = None
        self.retired_analysis_workers: list[tuple[Any, Any]] = []
        self.run_dir: Path | None = None
        self.active = False
        self.last_status: dict[str, Any] = {
            "active": False,
            "runDir": None,
            "counts": {},
            "elapsedS": 0.0,
            "dropped": 0,
            "error": None,
        }
        self.analysis_status: dict[str, Any] = {
            "active": False,
            "phase": "idle",
            "analysisDir": None,
            "outputs": {},
            "error": None,
        }
        self.dropped = 0
        self.next_control_record_wall = 0.0
        self.next_snapshot_record_wall = 0.0
        self.next_frame_record_wall = 0.0
        self.next_sim_frame_record_wall = 0.0
        self.last_frame_seq = -1
        self.last_sim_frame_seq = -1
        self.save_camera_images = bool(cfg.recording_save_camera_images)
        self.trajectory_only = bool(cfg.recording_trajectory_only)
        self.frozen_source_seq: int | None = None
        self._spawn_standby_writer()

    def _spawn_standby_writer(self) -> None:
        self.event_q = self.ctx.Queue(
            maxsize=max(8, int(self.cfg.recording_queue_size)))
        self.status_q = self.ctx.Queue(maxsize=1)
        self.process = self.ctx.Process(
            target=_recording_writer_main,
            args=("", self.event_q, self.status_q, {}),
            name="policy_probe_recording_writer",
            daemon=False,
        )
        self.process.start()

    def start(
        self,
        config: dict[str, Any],
        initial_view: dict[str, Any] | None = None,
        save_camera_images: bool | None = None,
        trajectory_only: bool | None = None,
    ) -> dict[str, Any]:
        with self.lock:
            if self.active:
                return self.status_locked()
            self.save_camera_images = (
                self.cfg.recording_save_camera_images
                if save_camera_images is None else save_camera_images)
            self.trajectory_only = (self.cfg.recording_trajectory_only
                                    if trajectory_only is None else trajectory_only)
            stamp = time.strftime("%Y%m%d_%H%M%S", time.localtime())
            self.run_dir = self.cfg.recording_output_root / f"probe_recording_{stamp}"
            metadata = {
                "config": ({key: config[key] for key in (
                    "controlRateHz", "limits", "anchor", "ballBox", "eeBox", "policyRelease") if key in config}
                           if self.trajectory_only else config),
                "recording": {
                    "controlRateHz": float(self.cfg.recording_control_rate_hz),
                    "snapshotRateHz": float(RECORDING_SNAPSHOT_RATE_HZ),
                    "imageRateHz": float(self.cfg.recording_image_rate_hz),
                    "saveCameraImages": bool(self.save_camera_images),
                    "trajectoryOnly": bool(self.trajectory_only),
                    "queueSize": int(self.cfg.recording_queue_size),
                    "schemaVersion": int(RECORDING_SCHEMA_VERSION),
                    "ballSensorFile": ("control_samples.jsonl" if self.trajectory_only else "ball_sensor_samples.jsonl"),
                    "ballSensorSources": ["camera", "mocap"],
                    "ballSensorSampling": "latest_cache_per_recorded_control_tick",
                    "ballSensorFormatting": "sensor_producer_and_writer_process",
                    "ballSensorControlRead": "immutable_cache_references_without_sensor_locks",
                    "ballSensorPositionUnit": "m",
                    "ballSensorVelocityUnit": "m/s",
                    "ballSensorTimestampDomain": "ROS",
                    "priority": "control_first",
                    "writerStartMethod": str(self.start_method),
                    "writerPrestarted": True,
                },
            }
            if (self.process is None or not self.process.is_alive()
                    or self.event_q is None):
                self.last_status = {
                    "active": False,
                    "runDir": str(self.run_dir),
                    "counts": {},
                    "elapsedS": 0.0,
                    "dropped": int(self.dropped),
                    "error": (
                        "standby recording writer is unavailable; recording "
                        "was not started so control timing stays unaffected"),
                }
                return self.status_locked()
            try:
                self.event_q.put({
                    "kind": "configure",
                    "runDir": str(self.run_dir),
                    "metadata": metadata,
                }, timeout=1.0)
            except (Full, OSError) as exc:
                self.last_status = {
                    "active": False,
                    "runDir": str(self.run_dir),
                    "counts": {},
                    "elapsedS": 0.0,
                    "dropped": int(self.dropped),
                    "error": f"standby recording writer did not accept start: {exc}",
                }
                return self.status_locked()
            self.active = True
            self.dropped = 0
            self.next_control_record_wall = 0.0
            self.next_snapshot_record_wall = 0.0
            self.next_frame_record_wall = 0.0
            self.next_sim_frame_record_wall = 0.0
            self.last_frame_seq = -1
            self.last_sim_frame_seq = -1
            self.frozen_source_seq = None
            self.last_status = {
                "active": True,
                "runDir": str(self.run_dir),
                "counts": {},
                "elapsedS": 0.0,
                "dropped": 0,
                "saveCameraImages": bool(self.save_camera_images),
                "trajectoryOnly": bool(self.trajectory_only),
                "juggle": RecordingJuggleCounter().summary(),
                "error": None,
            }
        self.record_event({"event": "start", "wallTimeS": time.time()})
        if initial_view:
            self.record_view(initial_view)
        return self.status()

    def stop(
        self,
        final_view: dict[str, Any] | None = None,
        analyze: bool = False,
    ) -> dict[str, Any]:
        with self.lock:
            active = self.active
        if not active:
            status = self.status()
            if analyze and status.get("runDir"):
                return self.start_analysis(str(status["runDir"]))
            return status
        if final_view:
            self.record_view(final_view)
        self.record_event({"event": "stop", "wallTimeS": time.time()})
        with self.lock:
            q = self.event_q
            process = self.process
            dropped = int(self.dropped)
        if q is not None:
            try:
                q.put({"kind": "stop", "dropped": dropped}, timeout=5.0)
            except Full:
                with self.lock:
                    self.dropped += 1
                    self.last_status["error"] = (
                        "recording queue did not drain; stop marker was not written")
        flush_complete = False
        flush_deadline = time.monotonic() + 5.0
        while process is not None and time.monotonic() < flush_deadline:
            with self.lock:
                self._drain_status_locked()
                flush_complete = bool(
                    self.last_status.get("active") is False
                    and self.last_status.get("runDir")
                    == (str(self.run_dir) if self.run_dir is not None else None)
                )
            if flush_complete or not process.is_alive():
                break
            time.sleep(0.01)
        with self.lock:
            self.active = False
            run_dir = str(self.run_dir) if self.run_dir is not None else None
            if not flush_complete:
                self.last_status["error"] = (
                    self.last_status.get("error")
                    or "recording writer did not confirm flush within 5 seconds")
        status = self.status()
        if analyze and run_dir:
            status = self.start_analysis(run_dir)
        return status

    def shutdown(self) -> None:
        self.stop()
        with self.lock:
            writer = self.process
            writer_q = self.event_q
            process = self.analysis_process
        if writer is not None and writer.is_alive():
            if writer_q is not None:
                try:
                    writer_q.put({"kind": "shutdown"}, timeout=0.5)
                except (Full, OSError):
                    pass
            writer.join(timeout=1.0)
            if writer.is_alive():
                _terminate_process_tree(writer, "standby recording writer")
        with self.lock:
            self.process = None
            self.event_q = None
            self.status_q = None
        _close_mp_queue(writer_q)
        if process is not None and process.is_alive():
            process.join(timeout=1.0)
            if process.is_alive():
                _terminate_process_tree(process, "analysis process")
        for old_process, old_q in self.retired_analysis_workers:
            old_process.join(timeout=1.0)
            if old_process.is_alive():
                _terminate_process_tree(old_process, "previous recording analysis process")
            _close_mp_queue(old_q)
        self.retired_analysis_workers.clear()

    def _drain_status_locked(self) -> None:
        q = self.status_q
        if q is None:
            pass
        else:
            while True:
                try:
                    item = q.get_nowait()
                except Empty:
                    break
                if isinstance(item, dict):
                    item = dict(item)
                    item["dropped"] = int(self.dropped)
                    self.last_status = item
                    if item.get("active") is False:
                        self.active = False
        aq = self.analysis_status_q
        if aq is not None:
            while True:
                try:
                    item = aq.get_nowait()
                except Empty:
                    break
                if isinstance(item, dict):
                    self.analysis_status = dict(item)

    def status_locked(self) -> dict[str, Any]:
        self._drain_status_locked()
        status = dict(self.last_status)
        status["active"] = bool(self.active)
        status["dropped"] = int(self.dropped)
        if self.run_dir is not None and not status.get("runDir"):
            status["runDir"] = str(self.run_dir)
        if self.process is not None and self.active and not self.process.is_alive():
            status["active"] = False
            status["error"] = (
                status.get("error")
                or f"recording writer exited: {self.process.exitcode}")
            self.active = False
        if (self.analysis_process is not None
                and self.analysis_status.get("active")
                and not self.analysis_process.is_alive()):
            self.analysis_status["active"] = False
            if self.analysis_process.exitcode not in (0, None):
                self.analysis_status["error"] = (
                    self.analysis_status.get("error")
                    or f"analysis exited: {self.analysis_process.exitcode}")
        status["analysis"] = dict(self.analysis_status)
        return status

    def status(self) -> dict[str, Any]:
        with self.lock:
            return self.status_locked()

    def select_analysis_run(
        self,
        run_dir_text: str | Path | None,
        *,
        analyze_missing: bool = True,
    ) -> dict[str, Any]:
        analyze_run_dir: str | None = None
        with self.lock:
            self._drain_status_locked()
            if (self.analysis_process is not None
                    and self.analysis_process.is_alive()):
                return self.status_locked()
            if not run_dir_text:
                self.analysis_status = {
                    "active": False,
                    "phase": "error",
                    "analysisDir": None,
                    "outputs": {},
                    "error": "no analysis recording directory selected",
                }
                return self.status_locked()
            selected = Path(run_dir_text).expanduser()
            try:
                selected = selected.resolve()
            except OSError:
                selected = selected.absolute()
            if selected.name == "analysis":
                analysis_dir = selected
                run_dir = selected.parent
            else:
                run_dir = selected
                analysis_dir = selected / "analysis"
            self.run_dir = run_dir
            if not run_dir.is_dir():
                self.analysis_status = {
                    "active": False,
                    "phase": "error",
                    "analysisDir": str(analysis_dir),
                    "outputs": {},
                    "error": f"recording directory not found: {run_dir}",
                }
                return self.status_locked()
            outputs = _analysis_outputs_from_dir(analysis_dir)
            analysis_schema_version = _analysis_schema_version_from_dir(
                analysis_dir)
            analysis_current = (
                analysis_schema_version >= ANALYSIS_SCHEMA_VERSION)
            if (outputs.get("analysisData")
                    and (analysis_current or not analyze_missing)):
                self.analysis_status = {
                    "active": False,
                    "phase": "done",
                    "analysisDir": str(analysis_dir),
                    "outputs": outputs,
                    "error": None,
                    "analysisSchemaVersion": analysis_schema_version,
                }
                return self.status_locked()
            self.analysis_status = {
                "active": False,
                "phase": (
                    "upgrading" if outputs.get("analysisData")
                    else "selected"),
                "analysisDir": str(analysis_dir),
                "outputs": outputs,
                "error": None,
                "analysisSchemaVersion": analysis_schema_version,
                "targetAnalysisSchemaVersion": ANALYSIS_SCHEMA_VERSION,
            }
            if analyze_missing:
                analyze_run_dir = str(run_dir)
            else:
                return self.status_locked()
        if analyze_run_dir:
            return self.start_analysis(analyze_run_dir)
        with self.lock:
            return self.status_locked()

    def start_analysis(self, run_dir_text: str | None = None, *, ball_sensors_only: bool = False) -> dict[str, Any]:
        with self.lock:
            self._drain_status_locked()
            run_dir = Path(run_dir_text) if run_dir_text else self.run_dir
            if run_dir is not None and run_dir.name == "analysis":
                run_dir = run_dir.parent
            if run_dir is None:
                self.analysis_status = {
                    "active": False,
                    "phase": "error",
                    "analysisDir": None,
                    "outputs": {},
                    "error": "no recording directory available",
                }
                return self.status_locked()
            if self.analysis_process is not None and self.analysis_process.is_alive():
                if self.analysis_status.get("analysisDir") == str(run_dir / "analysis"):
                    return self.status_locked()
                # A previous recording's video analysis must not suppress
                # the newly stopped recording's required comparison plots.
                self.retired_analysis_workers.append((self.analysis_process, self.analysis_status_q))
            remaining = []
            for old_process, old_q in self.retired_analysis_workers:
                if old_process.is_alive():
                    remaining.append((old_process, old_q))
                else:
                    old_process.join(timeout=0.)
                    _close_mp_queue(old_q)
            self.retired_analysis_workers = remaining
            self.run_dir = run_dir
            self.analysis_status_q = self.ctx.Queue(maxsize=1)
            analysis_dir = run_dir / "analysis"
            self.analysis_status = {
                "active": True,
                "phase": "starting",
                "analysisDir": str(analysis_dir),
                "outputs": {},
                "error": None,
            }
            self.analysis_process = self.ctx.Process(
                target=_recording_analysis_main,
                args=(
                    str(run_dir),
                    self.analysis_status_q,
                    float(self.cfg.recording_analysis_video_fps),
                    bool(ball_sensors_only),
                ),
                name="policy_probe_recording_analysis",
                daemon=False,
            )
            self.analysis_process.start()
            return self.status_locked()

    def _put(self, item: dict[str, Any]) -> bool:
        with self.lock:
            if not self.active or self.event_q is None:
                return False
            q = self.event_q
        try:
            q.put(item, block=False)
            return True
        except Full:
            with self.lock:
                self.dropped += 1
            return False

    def record_event(self, event: dict[str, Any]) -> None:
        if not event:
            return
        if getattr(self, "trajectory_only", False) and event.get("event") not in ("start", "stop"):
            return
        self._put({"kind": "event", "event": dict(event)})

    def record_view(self, view: dict[str, Any] | None) -> None:
        if getattr(self, "trajectory_only", False):
            return
        if not isinstance(view, dict):
            return
        payload = dict(view)
        payload.setdefault("wallTimeS", round(float(time.time()), 6))
        self._put({"kind": "view", "view": payload})

    def record_snapshot(self, snapshot: dict[str, Any] | None) -> None:
        if getattr(self, "trajectory_only", False):
            return
        if not isinstance(snapshot, dict):
            return
        now = time.perf_counter()
        with self.lock:
            if not self.active or now < self.next_snapshot_record_wall:
                return
            self.next_snapshot_record_wall = (
                now + 1.0 / max(RECORDING_SNAPSHOT_RATE_HZ, 1e-6))
        self._put({"kind": "snapshot", "snapshot": dict(snapshot)})

    def record_control_sample(self, sample: dict[str, Any]) -> None:
        rate = float(self.cfg.recording_control_rate_hz)
        if rate <= 0.0:
            return
        now = time.perf_counter()
        with self.lock:
            if not self.active:
                return
            if (self.frozen_source_seq is not None
                    and int(sample.get("sourceSeq", -1))
                    > self.frozen_source_seq):
                return
            # At the configured control rate, record every logical tick.  A
            # wall-clock `next = now + period` gate loses roughly every other
            # sample under normal timer jitter and breaks sourceSeq alignment.
            if rate + 1e-6 < float(self.cfg.control_rate_hz):
                if now < self.next_control_record_wall:
                    return
                self.next_control_record_wall = now + 1.0 / max(rate, 1e-6)
        if getattr(self, "trajectory_only", False):
            sample = compact_trajectory_sample(sample)
        self._put({"kind": "control", "sample": sample})

    def record_sim_control_samples(
        self,
        samples: list[dict[str, Any]] | None,
    ) -> None:
        if getattr(self, "trajectory_only", False):
            return
        if not samples or float(self.cfg.recording_control_rate_hz) <= 0.0:
            return
        with self.lock:
            frozen_source_seq = self.frozen_source_seq
        batch = []
        for sample in samples:
            if not isinstance(sample, dict):
                continue
            sync = sample.get("sync")
            source_seq = (
                sync.get("sourceSeq") if isinstance(sync, dict) else None)
            if (frozen_source_seq is not None
                    and source_seq is not None
                    and int(source_seq) > frozen_source_seq):
                continue
            batch.append(_compact_sim_record_sample(sample))
        if not batch:
            return
        self._put({"kind": "sim_control_batch", "samples": batch})

    def freeze(self, source_seq: int) -> int:
        with self.lock:
            self.frozen_source_seq = int(source_seq)
            return self.frozen_source_seq

    def record_camera_frame(
        self,
        frame: bytes | None,
        info: dict[str, Any] | None,
    ) -> None:
        if frame is None or not self.save_camera_images:
            return
        rate = float(self.cfg.recording_image_rate_hz)
        if rate <= 0.0:
            return
        info = dict(info) if isinstance(info, dict) else {}
        seq = int(info.get("seq", 0) or 0)
        now = time.perf_counter()
        with self.lock:
            if not self.active:
                return
            if seq > 0 and seq == self.last_frame_seq:
                return
            # The visualization producer is already capped.  Applying an
            # identical 60 Hz wall-clock gate here turns ordinary scheduler
            # jitter into false drops (often alternating 17/35 ms frames).
            producer_rate = float(self.cfg.camera_visualization_rate_hz)
            needs_downsample = rate + 1e-6 < producer_rate
            if needs_downsample and now < self.next_frame_record_wall:
                return
            self.last_frame_seq = seq
            if needs_downsample:
                period = 1.0 / max(rate, 1e-6)
                if self.next_frame_record_wall <= 0.0:
                    self.next_frame_record_wall = now + period
                else:
                    while self.next_frame_record_wall <= now:
                        self.next_frame_record_wall += period
        info.setdefault("monotonicTimeS", time.perf_counter())
        info.setdefault("wallTimeS", time.time())
        self._put({"kind": "frame", "frame": bytes(frame), "info": info})

    def record_sim_frame(
        self,
        frame: bytes | None,
        info: dict[str, Any] | None,
    ) -> None:
        if getattr(self, "trajectory_only", False):
            return
        if frame is None:
            return
        rate = float(self.cfg.recording_image_rate_hz)
        if rate <= 0.0:
            return
        info = dict(info) if isinstance(info, dict) else {}
        seq = int(info.get("seq", 0) or 0)
        now = time.perf_counter()
        with self.lock:
            if not self.active:
                return
            if seq > 0 and seq == self.last_sim_frame_seq:
                return
            producer_rate = float(self.cfg.sim_frame_rate_hz)
            needs_downsample = rate + 1e-6 < producer_rate
            if needs_downsample and now < self.next_sim_frame_record_wall:
                return
            self.last_sim_frame_seq = seq
            if needs_downsample:
                period = 1.0 / max(rate, 1e-6)
                if self.next_sim_frame_record_wall <= 0.0:
                    self.next_sim_frame_record_wall = now + period
                else:
                    while self.next_sim_frame_record_wall <= now:
                        self.next_sim_frame_record_wall += period
        info.setdefault("monotonicTimeS", time.perf_counter())
        info.setdefault("wallTimeS", time.time())
        self._put({"kind": "sim_frame", "frame": bytes(frame), "info": info})


@dataclass(frozen=True)
class CameraRuntimeOptions:
    detect: bool
    visualize: bool
    yolo_enabled: bool
    use_depth_sensor: bool
    depth_mode: str
    sensor_surface_to_center_depth_enabled: bool
    use_undistort: bool
    use_kalman: bool
    ir_depth_kalman_enabled: bool
    synchronized_depth_enabled: bool
    depth_temporal_window_frames: int
    velocity_least_squares_enabled: bool
    velocity_window_frames: int
    clear_buffers_on_detection_loss_enabled: bool
    motion_consistency_gate_enabled: bool
    physics_constrained_velocity_enabled: bool
    trajectory_position_smoothing_enabled: bool
    impact_velocity_reset_enabled: bool
    impact_min_downward_velocity_m_s: float
    impact_min_upward_velocity_m_s: float
    impact_min_velocity_jump_m_s: float
    impact_refractory_s: float
    pixel_kalman_enabled: bool
    pixel_kalman_process_noise_pos: float
    pixel_kalman_process_noise_vel: float
    pixel_kalman_measurement_noise: float
    pixel_kalman_innovation_gate_px: float
    pixel_kalman_reset_after_outliers: int
    candidate_filter_enabled: bool
    candidate_min_brightness: float
    candidate_max_depth_disagreement_mm: float
    candidate_motion_scale_px: float
    enable_ellipse_fit: bool
    enable_temporal_tracker: bool
    enable_color_filter: bool

    def detector_key(self) -> tuple[Any, ...]:
        return (
            bool(self.use_depth_sensor),
            str(self.depth_mode),
            bool(self.use_undistort),
            bool(self.use_kalman),
            bool(self.enable_ellipse_fit),
            bool(self.enable_temporal_tracker),
            bool(self.enable_color_filter),
        )

    def pixel_kalman_key(self) -> tuple[Any, ...]:
        return (
            bool(self.pixel_kalman_enabled),
            round(float(self.pixel_kalman_process_noise_pos), 6),
            round(float(self.pixel_kalman_process_noise_vel), 6),
            round(float(self.pixel_kalman_measurement_noise), 6),
            round(float(self.pixel_kalman_innovation_gate_px), 6),
            int(self.pixel_kalman_reset_after_outliers),
        )

    def ir_depth_processing_key(self) -> tuple[bool, bool, int]:
        return (
            bool(self.ir_depth_kalman_enabled),
            bool(self.synchronized_depth_enabled),
            int(self.depth_temporal_window_frames),
        )

    def sensor_depth_correction_key(self) -> tuple[bool]:
        return (bool(self.sensor_surface_to_center_depth_enabled),)

    def velocity_estimation_key(self) -> tuple[Any, ...]:
        return (
            bool(self.velocity_least_squares_enabled),
            int(self.velocity_window_frames),
            bool(self.impact_velocity_reset_enabled),
            round(float(self.impact_min_downward_velocity_m_s), 6),
            round(float(self.impact_min_upward_velocity_m_s), 6),
            round(float(self.impact_min_velocity_jump_m_s), 6),
            round(float(self.impact_refractory_s), 6),
        )

    def observation_quality_key(self) -> tuple[bool, bool, bool, bool]:
        return (
            bool(self.clear_buffers_on_detection_loss_enabled),
            bool(self.motion_consistency_gate_enabled),
            bool(self.physics_constrained_velocity_enabled),
            bool(self.trajectory_position_smoothing_enabled),
        )

    def candidate_filter_key(self) -> tuple[Any, ...]:
        return (
            bool(self.candidate_filter_enabled),
            round(float(self.candidate_min_brightness), 3),
            round(float(self.candidate_max_depth_disagreement_mm), 3),
            round(float(self.candidate_motion_scale_px), 3),
        )

    def key(self) -> tuple[Any, ...]:
        return (self.detector_key() + self.pixel_kalman_key()
                + self.candidate_filter_key())

    def payload(self) -> dict[str, Any]:
        return {
            "detect": bool(self.detect),
            "visualize": bool(self.visualize),
            "yolo": bool(self.yolo_enabled),
            "sensorDepth": bool(self.use_depth_sensor),
            "depthMode": str(self.depth_mode),
            "sensorSurfaceToCenterDepth": bool(
                self.sensor_surface_to_center_depth_enabled),
            "undistort": bool(self.use_undistort),
            "kalman": bool(self.use_kalman),
            "irDepthKalman": bool(self.ir_depth_kalman_enabled),
            "synchronizedDepth": bool(self.synchronized_depth_enabled),
            "depthTemporalWindowFrames": int(
                self.depth_temporal_window_frames),
            "velocityLeastSquares": bool(
                self.velocity_least_squares_enabled),
            "velocityWindowFrames": int(self.velocity_window_frames),
            "clearBuffersOnDetectionLoss": bool(
                self.clear_buffers_on_detection_loss_enabled),
            "motionConsistencyGate": bool(
                self.motion_consistency_gate_enabled),
            "physicsConstrainedVelocity": bool(
                self.physics_constrained_velocity_enabled),
            "trajectoryPositionSmoothing": bool(
                self.trajectory_position_smoothing_enabled),
            "impactVelocityReset": bool(
                self.impact_velocity_reset_enabled),
            "impactMinDownwardVelocityMps": round(
                float(self.impact_min_downward_velocity_m_s), 6),
            "impactMinUpwardVelocityMps": round(
                float(self.impact_min_upward_velocity_m_s), 6),
            "impactMinVelocityJumpMps": round(
                float(self.impact_min_velocity_jump_m_s), 6),
            "impactRefractoryS": round(
                float(self.impact_refractory_s), 6),
            "pixelKalman": bool(self.pixel_kalman_enabled),
            "pixelKalmanProcessNoisePos": round(
                float(self.pixel_kalman_process_noise_pos), 6),
            "pixelKalmanProcessNoiseVel": round(
                float(self.pixel_kalman_process_noise_vel), 6),
            "pixelKalmanMeasurementNoise": round(
                float(self.pixel_kalman_measurement_noise), 6),
            "pixelKalmanInnovationGatePx": round(
                float(self.pixel_kalman_innovation_gate_px), 6),
            "pixelKalmanResetAfterOutliers": int(
                self.pixel_kalman_reset_after_outliers),
            "candidateFilter": bool(self.candidate_filter_enabled),
            "candidateMinBrightness": round(
                float(self.candidate_min_brightness), 3),
            "candidateMaxDepthDisagreementMm": round(
                float(self.candidate_max_depth_disagreement_mm), 3),
            "candidateMotionScalePx": round(
                float(self.candidate_motion_scale_px), 3),
            "ellipseFit": bool(self.enable_ellipse_fit),
            "temporalTracker": bool(self.enable_temporal_tracker),
            "colorFilter": bool(self.enable_color_filter),
        }


@dataclass(frozen=True)
class ContactActionShieldOptions:
    enabled: bool
    pre_contact_window_s: float
    post_contact_window_s: float
    contact_tolerance_m: float
    max_lateral_distance_m: float
    min_downward_velocity_m_s: float
    max_normal_lateral: float
    max_lateral_speed_m_s: float
    workspace_margin_m: float
    dls_damping: float
    vertical_energy_enabled: bool = False
    vertical_pre_contact_window_s: float = 0.12
    vertical_target_apex_height_m: float = 0.30
    vertical_restitution: float = 0.66
    vertical_max_racket_upward_speed_m_s: float = 0.90

    def payload(self) -> dict[str, Any]:
        return {
            "enabled": bool(self.enabled),
            "preContactWindowS": round(
                float(self.pre_contact_window_s), 6),
            "postContactWindowS": round(
                float(self.post_contact_window_s), 6),
            "contactToleranceM": round(
                float(self.contact_tolerance_m), 6),
            "maxLateralDistanceM": round(
                float(self.max_lateral_distance_m), 6),
            "minDownwardVelocityMps": round(
                float(self.min_downward_velocity_m_s), 6),
            "maxNormalLateral": round(
                float(self.max_normal_lateral), 6),
            "maxLateralSpeedMps": round(
                float(self.max_lateral_speed_m_s), 6),
            "workspaceMarginM": round(
                float(self.workspace_margin_m), 6),
            "dlsDamping": round(float(self.dls_damping), 6),
            "verticalEnergyEnabled": bool(self.vertical_energy_enabled),
            "verticalPreContactWindowS": round(
                float(self.vertical_pre_contact_window_s), 6),
            "verticalTargetApexHeightM": round(
                float(self.vertical_target_apex_height_m), 6),
            "verticalRestitution": round(
                float(self.vertical_restitution), 6),
            "verticalMaxRacketUpwardSpeedMps": round(
                float(self.vertical_max_racket_upward_speed_m_s), 6),
        }


