    def _configure_camera_racket_context(self):
        """Configure ball-observer FK at startup/profile changes, never a tick."""
        bridge = getattr(self, 'ros_bridge', None)
        node = getattr(bridge, 'node', None)
        camera = getattr(node, 'camera_process', None)
        if (camera is None or not hasattr(camera, 'set_racket_context_source')
                or not bool(getattr(self.cfg, 'ros_bridge', False))):
            return
        from pingpong_controller.ball_observation_model import BallObservationProcessor
        if not getattr(BallObservationProcessor,'SUPPORTS_RACKET_CONTEXT',False):
            return  # Frozen v1.0/v1.1 rollback keeps its original context path.
        from pingpong_controller.ball_racket_context import model_spec, FeedbackReader
        spec = model_spec(self.controller)
        if spec is not None:
            camera.set_racket_context_source(spec, FeedbackReader(node))

    def _build_release_locked_policy_controller(
        self,
        profile: str,
        policy_model: str | None = None,
    ):
        cfg = self.cfg
        if profile in FPLC_PROFILES:
            model, xml = fplc_assets(profile)
            return FPLCPolicyController(
                str(model), observation_profile=profile,
                dt=cfg.control_dt, robot_xml_path=str(xml))
        gpu0_model_paths = {
            GPU0_RMP_MODEL_V85: cfg.simcode7_v85_model_path,
            GPU0_RMP_MODEL_V91: cfg.simcode7_v91_model_path,
            GPU0_RMP_MODEL_V97: cfg.simcode7_v97_model_path,
            GPU0_RMP_MODEL_V97_SOURCE_CLOCK: cfg.simcode7_v97_model_path,
        }
        selected_gpu0_model = (
            None
            if policy_model is None
            else _normalize_gpu0_rmp_model(policy_model)
        )
        if (selected_gpu0_model is None
                and str(getattr(cfg, "policy_release_id", "")).strip().lower()
                == "gpu0_qvel_real_rmp_v97_source_clock"):
            selected_gpu0_model = GPU0_RMP_MODEL_V97_SOURCE_CLOCK
        gpu0_model_path = (
            cfg.simcode7_model_path
            if policy_model is None
            else gpu0_model_paths[selected_gpu0_model]
        )
        gpu0_controller_cls = (
            Gpu0QvelRealRmpV97SourceClockPolicyController
            if selected_gpu0_model == GPU0_RMP_MODEL_V97_SOURCE_CLOCK
            else Gpu0QvelRealRmpV85PolicyController
        )
        builders = {
            OBSERVATION_PROFILE_LEGACY_BUG_COMPAT: lambda: MjxRLPolicyController(
                str(cfg.model_path),
                dt=cfg.control_dt,
                robot_xml_path=str(cfg.robot_xml_path),
                # This checkpoint is 67-D.  Do not inherit a 57-D GPU0
                # launch manifest here when legacy is selected at runtime.
                enable_delay_conditioning=(cfg.policy_obs_dim != 50),
                use_valid_ball_obs_age=cfg.rl_use_valid_ball_obs_age,
                observation_profile=OBSERVATION_PROFILE_LEGACY_BUG_COMPAT,
            ),
            OBSERVATION_PROFILE_SIMCODE2_IDEALPD67: lambda: (
                Simcode2IdealPd67PolicyController(
                    str(cfg.simcode2_model_path),
                    dt=cfg.control_dt,
                    robot_xml_path=str(cfg.simcode2_policy_xml_path),
                    use_valid_ball_obs_age=cfg.rl_use_valid_ball_obs_age,
                )),
            OBSERVATION_PROFILE_SIMCODE3_ACTUATOR67: lambda: (
                Simcode3Actuator67PolicyController(
                    str(cfg.simcode3_model_path),
                    dt=cfg.control_dt,
                    robot_xml_path=str(cfg.simcode3_policy_xml_path),
                    use_valid_ball_obs_age=True,
                )),
            OBSERVATION_PROFILE_SIMCODE4_SERVO67: lambda: (
                Simcode4Servo67PolicyController(
                    str(cfg.simcode4_model_path),
                    dt=cfg.control_dt,
                    robot_xml_path=str(cfg.simcode4_policy_xml_path),
                )),
            OBSERVATION_PROFILE_SIMCODE5_PURE_ACTUATOR67: lambda: (
                Simcode5PureActuator67PolicyController(
                    str(cfg.simcode5_model_path),
                    dt=cfg.control_dt,
                    robot_xml_path=str(cfg.simcode5_policy_xml_path),
                )),
            OBSERVATION_PROFILE_SIMCODE6_QVEL67: lambda: (
                Simcode6Qvel67PolicyController(
                    str(cfg.simcode6_model_path),
                    dt=cfg.control_dt,
                    robot_xml_path=str(cfg.simcode6_policy_xml_path),
                )),
            OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85: lambda: (
                gpu0_controller_cls(
                    str(gpu0_model_path),
                    dt=cfg.control_dt,
                    robot_xml_path=str(
                        cfg.simcode8_policy_xml_path
                        if (selected_gpu0_model in {
                                GPU0_RMP_MODEL_V97,
                                GPU0_RMP_MODEL_V97_SOURCE_CLOCK,
                            }
                            or (policy_model is None
                                and Path(gpu0_model_path)
                                == Path(cfg.simcode7_v97_model_path)))
                        else cfg.simcode7_policy_xml_path),
                )),
            OBSERVATION_PROFILE_GPU1_QACC_FT_V153: lambda: (
                Gpu1QaccFtV153PolicyController(
                    str(cfg.gpu1_qacc_ft_model_path),
                    dt=cfg.control_dt,
                    robot_xml_path=str(cfg.gpu1_qacc_ft_policy_xml_path),
                )),
        }
        try:
            return builders[normalize_observation_profile(profile)]()
        except KeyError as exc:
            raise RuntimeError(
                f"no controller builder for release profile {profile!r}") from exc

    def _init_policy_plant_matcher(self) -> None:
        mode = PlantMatcherMode.parse(self.cfg.policy_plant_matcher_mode)
        if self.active_policy_profile not in {
                OBSERVATION_PROFILE_SIMCODE5_PURE_ACTUATOR67,
                OBSERVATION_PROFILE_SIMCODE6_QVEL67}:
            if mode is not PlantMatcherMode.OFF:
                raise RuntimeError(
                    "policy plant matcher is only defined for release-locked "
                    "simcode5/simcode6 second-order plants")
            return
        env_cfg = dict(getattr(
            self.controller, "_checkpoint_env_cfg", {}) or {})
        target = JointPlantParameters.from_checkpoint_env_cfg(env_cfg)
        fit_metadata, real, solver = load_real_plant_fit(
            self.cfg.policy_plant_matcher_real_config)
        release_contract = _policy_release_contract_payload()
        release_hash_match = bool(
            release_contract.get("validated", False)
            and release_contract.get("policy_profile")
            == self.active_policy_profile)
        warm_q = np.asarray(
            self.controller.current_arm_cmd_q(), dtype=np.float64).reshape(7)
        self.policy_plant_matcher = PolicyPlantModelReference(
            target_parameters=target,
            real_parameters=real,
            solver=solver,
            mode=mode.value,
            dt_s=self.cfg.control_dt,
            warm_q=warm_q,
            q_low=self.controller.arm_q_low,
            q_high=self.controller.arm_q_high,
            dq_limit=self.controller.arm_vel_limit_rad_s,
            allow_apply=self.cfg.allow_policy_plant_matcher_apply,
            release_hash_match=release_hash_match,
            real_fit_metadata=fit_metadata,
        )
        self.last_policy_plant_matcher_info = {
            "mode": mode.value,
            "initialized": True,
            "applyAuthorized": self.policy_plant_matcher.apply_authorized,
            "realFitId": fit_metadata.get("fit_id"),
            "realFitVersion": fit_metadata.get("fit_version"),
            "provenanceStatus": fit_metadata.get("provenance_status"),
            "applyEligible": bool(fit_metadata.get("apply_eligible", False)),
            "holdoutMetrics": fit_metadata.get("holdout_metrics"),
        }

    @staticmethod
    def _control_client_session_id(payload: dict[str, Any]) -> str:
        session_id = str(payload.get("clientSessionId", "") or "").strip()
        if session_id:
            return session_id
        # Preserve compatibility for non-browser tools whose arm token changes
        # on every explicit enable gesture.
        return "legacy-client"

    def _accept_control_client_payload(
        self,
        payload: dict[str, Any],
        *,
        allow_reset_takeover: bool = False,
    ) -> bool:
        """Enforce a single writer for command and drag-ball state.

        Multiple browser tabs run independent timers. A background tab is
        commonly throttled to about 1 Hz and must not overwrite the active
        tab's Send-command or drag-ball state. An explicit reset is the safe
        ownership-transfer operation.
        """
        request_session_id = self._control_client_session_id(payload)
        owner_session_id = str(getattr(
            self, "command_owner_session_id", "") or "")
        publish_requested = bool(payload.get("publishCommands", False))
        if allow_reset_takeover:
            self.command_owner_session_id = request_session_id
            accepted = True
            reason = "reset_owner_takeover"
        elif not owner_session_id:
            if publish_requested:
                self.command_owner_session_id = request_session_id
                reason = "publish_owner_acquired"
            else:
                reason = "unowned_read_only_update"
            accepted = True
        elif request_session_id == owner_session_id:
            accepted = True
            reason = "owner_request"
        else:
            accepted = False
            reason = "non_owner_control_request_ignored"
        self.last_command_ownership = {
            "accepted": bool(accepted),
            "reason": reason,
            "requestSessionId": request_session_id,
            "ownerSessionId": str(getattr(
                self, "command_owner_session_id", "") or ""),
            "publishRequested": publish_requested,
        }
        return bool(accepted)

    def _command_ownership_payload(self) -> dict[str, Any]:
        payload = dict(getattr(self, "last_command_ownership", {}))
        payload["ownerSessionId"] = str(getattr(
            self, "command_owner_session_id", "") or "")
        return payload

    def reset(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = payload if isinstance(payload, dict) else {}
        requested_arm_token = str(
            payload.get("publishArmToken", "") or "").strip()
        if requested_arm_token:
            self.last_publish_arm_token = requested_arm_token
        preset_raw = (
            payload.get("resetInitialPose")
            if "resetInitialPose" in payload
            else payload.get(
                "resetPose",
                payload.get("initialPose", self.reset_initial_pose_id),
            ))
        with self.lock:
            self._accept_control_client_payload(
                payload, allow_reset_takeover=True)
            self.camera_observation_continuity.reset()
            self.camera_observation_wait_q = None
            policy_selection_changed = False
            if "policyProfile" in payload:
                policy_selection_changed = bool(
                    self._select_policy_profile(payload["policyProfile"])
                    or policy_selection_changed)
            if "policyModel" in payload:
                policy_selection_changed = bool(
                    self._select_policy_model(payload["policyModel"])
                    or policy_selection_changed)
            reset_pose_id, requested_reset_q = self._resolve_reset_initial_pose(preset_raw)
            if self.runtime_options is not None:
                runtime_updates = {
                    "policy_profile": self.active_policy_profile,
                    "policy_model": (
                        self.active_policy_model or GPU0_RMP_MODEL_V85),
                }
                if policy_selection_changed:
                    # Do not let the 200 Hz loop reapply the old profile while
                    # the browser's next step payload is still in flight.
                    runtime_updates["publish_commands"] = False
                self.runtime_options = replace(
                    self.runtime_options,
                    **runtime_updates,
                )
            try:
                reset_request_id = int(payload.get(
                    "_controlResetRequestId", self.control_reset_request_id))
            except (TypeError, ValueError):
                reset_request_id = int(self.control_reset_request_id)
            self.control_reset_request_id = max(
                int(self.control_reset_request_id), reset_request_id)
            reset_seed_q = self._current_arm_reset_reference()
            reset_target_q = np.clip(
                np.asarray(requested_reset_q, dtype=np.float64).reshape(
                    len(RIGHT_ARM_JOINTS)),
                self.controller.arm_q_low,
                self.controller.arm_q_high,
            )
            self.reset_initial_pose_id = reset_pose_id
            self.reset_initial_pose_q = reset_target_q.copy()
            self.controller.reset()
            self.sim_needs_policy_reset = True
            self.policy_needs_reentry_reset = True
            self.policy_reentry_reset_q = np.asarray(
                reset_target_q, dtype=np.float32).copy()
            self.last_policy_execution_trace = None
            self.current_policy_joint_sample = None
            self.last_policy_joint_sample = None
            self.policy_joint_sample_error = "joint_state_uninitialized"
            self.previous_policy_action_for_handover = None
            if self.policy_plant_matcher is not None:
                self.policy_plant_matcher.initialized = False
                self.policy_plant_matcher.previous_sample = None
            self._sync_policy_to_safe_pose(reset_seed_q)
            if self.active_policy_profile not in FPLC_PROFILES:
                self.safety_limiter.last_cmd = np.asarray(
                    reset_seed_q, dtype=np.float64).copy()
                self.safety_limiter.last_vel = np.zeros(
                    len(RIGHT_ARM_JOINTS), dtype=np.float64)
            reset_ball_pos, reset_ball_vel, reset_ball_contract = (
                self._reset_ball_state(reset_target_q))
            self.reset_ball_contract = dict(reset_ball_contract)
            if self.sim_mirror is not None:
                try:
                    if isinstance(self.sim_mirror, SimMirrorSubprocess):
                        self.latest_sim_snapshot = self.sim_mirror.reset(
                            arm_q=reset_target_q,
                            ball_pos=reset_ball_pos,
                            ball_vel=reset_ball_vel,
                            ball_valid=False,
                            ball_obs_age_s=0.0,
                            policy_profile=self.active_policy_profile,
                            policy_model=self.active_policy_model,
                            policy_generation=self.policy_generation,
                        )
                    else:
                        self.latest_sim_snapshot = self.sim_mirror.reset(
                            arm_q=reset_target_q,
                            ball_pos=reset_ball_pos,
                            ball_vel=reset_ball_vel,
                            ball_valid=False,
                            ball_obs_age_s=0.0,
                        )
                except Exception as exc:  # noqa: BLE001 - keep reset usable.
                    self.sim_mirror_error = str(exc)
                    self.latest_sim_snapshot = self._sim_unavailable_payload(str(exc))
            # Reset is the operator's explicit recovery command.  It must be
            # allowed to move back to the known reset pose even when the current
            # EE pose is outside the workspace box that just latched done.
            self._start_supervised_reset(
                reset_seed_q,
                reset_target_q,
                reason="operator_reset",
            )
            self.reset_workspace_bypass_until_wall = time.monotonic() + 30.0
            self.reset_workspace_bypass_target_q = reset_target_q.copy()
            self.done_monitor.reset_counters()
            self.now_s = 0.0
            self.has_captured = False
            self.has_released = False
            self.release_candidate_ticks = 0
            self.release_samples: list[tuple[float, float, float]] = []
            self.last_valid_time_s: float | None = None
            self.failsafe_active = False
            self.done_failsafe_active = False
            self.done_failsafe_reason = ""
            self.done_failsafe_conditions: dict[str, bool] = {}
            self.hard_workspace_stop_latched = False
            self.hard_workspace_stop_reason = ""
            self.hard_workspace_stop_conditions: dict[str, bool] = {}
            self.hard_workspace_stop_hold_sent = False
            self.hard_workspace_stop_hold_attempted = False
            self.soft_workspace_reset_latched = False
            self.soft_workspace_reset_reason = ""
            self.soft_workspace_reset_conditions: dict[str, bool] = {}
            self.ball_done_streaks: dict[str, int] = {}
            self.ball_done_raw_conditions: dict[str, bool] = {}
            self.workspace_soft_prediction_active = False
            self.workspace_soft_conditions: dict[str, bool] = {}
            self.workspace_soft_filter: dict[str, Any] = {
                "active": False,
                "predictive": False,
                "alpha": 1.0,
            }
            self.contact_shield_post_until_s = -float("inf")
            self.contact_shield_last_descending_s = -float("inf")
            self.last_contact_action_shield_info = {
                "enabled": bool(self.cfg.enable_contact_action_shield),
                "verticalEnergyEnabled": bool(
                    self.cfg.enable_vertical_contact_energy_shield),
                "active": False,
                "intervened": False,
                "reason": "reset",
            }
            self.workspace_soft_entry_q: np.ndarray | None = None
            self.workspace_hold_active = False
            self.workspace_hold_q = np.asarray(
                reset_target_q, dtype=np.float64).copy()
            self.workspace_hold_last_safe_q = self.workspace_hold_q.copy()
            self.workspace_hold_trigger_reason = ""
            self.workspace_hold_constraint = ""
            self.last_policy_nominal_reference = np.asarray(
                reset_seed_q, dtype=np.float64).copy()
            self.last_compensated_reference = np.asarray(
                reset_seed_q, dtype=np.float64).copy()
            self.last_published_safe_reference = np.asarray(
                reset_seed_q, dtype=np.float64).copy()
            self._done_motion_prev_t_s = None
            self._done_motion_prev_pos_m = None
            self._done_motion_prev_vel_m_s = None
            self._done_motion_prev_psi_rad = None
            self._done_motion_prev_abc_rad = None
            self.last_ball_pos = reset_ball_pos.copy()
            self.last_ball_vel = reset_ball_vel.copy()
            self.last_observed_ball_pos = self.last_ball_pos.copy()
            self.last_observed_ball_vel = np.zeros(3, dtype=np.float32)
            self.last_measured_ball_pos = self.last_ball_pos.copy()
            self.last_measured_ball_vel = np.zeros(3, dtype=np.float32)
            self.last_done_ball_pos = self.last_ball_pos.copy()
            self.last_done_ball_valid = False
            self.ball_estimator = None
            self.ball_estimator_key = None
            self.high_ball_occlusion_predictor = None
            self.high_ball_occlusion_predictor_key = None
            self.last_ball_observation_stamp_s = None
            self.ball_observation_clock_domain = None
            self.next_ball_observation_s = 0.0
            self.policy_ball_sample_step = 0
            self.policy_ball_sample_sequence = 0
            self.policy_ball_sample_profile = None
            self.policy_ball_sample_pos = reset_ball_pos.astype(np.float32).copy()
            self.policy_ball_sample_vel = reset_ball_vel.astype(np.float32).copy()
            self.policy_ball_sample_age_s = 0.0
            self.policy_ball_sample_has_valid = False
            self.policy_ball_sample_source_stamp_s = None
            self.policy_ball_hold_source_key = None
            self.policy_ball_hold_monotonic_s = None
            self.policy_confirmed_hit_count = 0
            self._previous_inferred_contact_flag = False
            self.last_estimator_info = self._estimator_off_payload()
            self.last_high_ball_occlusion_info = (
                self._high_ball_occlusion_off_payload())
            self.last_release_gate_info = self._release_gate_payload(
                valid=False,
                age_s=None,
                vz_m_s=None,
                z_drop_m=0.0,
                candidate=False,
            )
            self._reset_servo_target_planner(reset_seed_q)
            self._reset_compensator_to_current_arm(reset_seed_q)
            self._sync_policy_to_safe_pose(reset_seed_q)
            _tracking_q, self.last_tracking_info = self.racket_tracker.hold(
                reset_seed_q, reason="reset")
            self.juggle_tracker.hold(reset_seed_q, reason="reset")
            self.juggle_controller.deactivate("reset")
            self.last_juggle_info = dict(
                self.juggle_controller.last_diagnostics)
            self.last_control_mode = None
            self.web_drag_ball_pos = self.last_ball_pos.copy()
            self.web_drag_ball_vel = self.last_ball_vel.copy()
            self.web_drag_valid = True
            self.web_noise_std_m = float(self.cfg.ball_noise_std_m)
            snapshot = self.snapshot(
                "reset", "", {}, self.last_ball_pos,
                self.last_observed_ball_pos, self.last_observed_ball_vel,
                False, 0.0, 0.0,
                measured_ball_pos=self.last_measured_ball_pos,
                measured_ball_vel=self.last_measured_ball_vel,
                estimator_info=self.last_estimator_info,
                ball_source="drag",
                camera_feedback=self.camera_feedback())
            self.latest_snapshot_payload = snapshot
            self.recorder.record_event({
                "event": "reset",
                "wallTimeS": time.time(),
                "time": round(float(self.now_s), 6),
                "resetInitialPose": str(self.reset_initial_pose_id),
                "resetTargetJointPosition": _rounded_vector(reset_target_q),
                "resetTargetJointPositionDeg": _rounded_vector(
                    np.rad2deg(reset_target_q), 3),
                "policyProfile": str(self.active_policy_profile),
                "policyGeneration": int(self.policy_generation),
                "resetBall": dict(self.reset_ball_contract),
            })
            self.recorder.record_snapshot(snapshot)
            return snapshot

    def initial_ball_pos(self) -> tuple[float, float, float]:
        anchor = self.anchor()
        return (
            float(anchor[0]),
            float(anchor[1]),
            min(self.cfg.done_z_max_m - 0.12, max(self.cfg.done_z_min_m + 0.12, float(anchor[2]) + 0.30)),
        )

    def _reset_ball_state(
        self,
        reset_q: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray, dict[str, Any]]:
        """Return the profile-specific reset ball contract."""
        velocity = np.zeros(3, dtype=np.float32)
        if (uses_corrected_67d_observation(self.active_policy_profile)
                or self.active_policy_profile in FPLC_PROFILES
                or self.active_policy_profile
                == OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85):
            env_cfg = dict(getattr(
                self.controller, "_checkpoint_env_cfg", {}) or {})
            frame_getter = getattr(
                self.controller, "_compute_racket_launch_frame_base", None)
            if callable(frame_getter):
                (
                    racket_center, tangent_x, tangent_y, racket_normal,
                    racket_radius, racket_half_thickness, fk_ok,
                ) = frame_getter(np.asarray(reset_q, dtype=np.float32))
            else:
                racket_center = np.asarray(self.anchor(), dtype=np.float32)
                tangent_x = np.array([1.0, 0.0, 0.0], dtype=np.float32)
                tangent_y = np.array([0.0, 1.0, 0.0], dtype=np.float32)
                racket_normal = np.array([0.0, 0.0, 1.0], dtype=np.float32)
                racket_radius = 0.08
                racket_half_thickness = 0.002
                fk_ok = False
            if not fk_ok or not np.all(np.isfinite(racket_center)):
                racket_center = np.asarray(self.anchor(), dtype=np.float32)
                tangent_x = np.array([1.0, 0.0, 0.0], dtype=np.float32)
                tangent_y = np.array([0.0, 1.0, 0.0], dtype=np.float32)
                racket_normal = np.array([0.0, 0.0, 1.0], dtype=np.float32)
                racket_radius = 0.08
                racket_half_thickness = 0.002
            racket_center = np.asarray(
                racket_center, dtype=np.float32).reshape(3)
            tangent_x = np.asarray(tangent_x, dtype=np.float32).reshape(3)
            tangent_y = np.asarray(tangent_y, dtype=np.float32).reshape(3)
            racket_normal = np.asarray(
                racket_normal, dtype=np.float32).reshape(3)
            gap_range = env_cfg.get(
                "racket_launch_surface_gap_range_m",
                SIMCODE2_RACKET_LAUNCH_GAP_RANGE_M)
            try:
                gap_lo, gap_hi = sorted(float(v) for v in gap_range)
            except (TypeError, ValueError):
                gap_lo, gap_hi = SIMCODE2_RACKET_LAUNCH_GAP_RANGE_M
            xy_jitter = max(0.0, float(env_cfg.get(
                "racket_launch_xy_jitter",
                SIMCODE2_RACKET_LAUNCH_XY_JITTER_M)))
            vxy_max = max(0.0, float(env_cfg.get(
                "racket_launch_vxy_max",
                SIMCODE2_RACKET_LAUNCH_VXY_MAX_M_S)))
            vnormal_max = max(0.0, float(env_cfg.get(
                "racket_launch_vnormal_max",
                SIMCODE2_RACKET_LAUNCH_VNORMAL_MAX_M_S)))
            edge_margin = max(0.0, float(env_cfg.get(
                "racket_launch_edge_margin",
                SIMCODE2_RACKET_LAUNCH_EDGE_MARGIN_M)))
            rng = getattr(self, "reset_ball_rng", None)
            if rng is None:
                rng = np.random.default_rng(0)
                self.reset_ball_rng = rng
            surface_gap = float(rng.uniform(
                gap_lo, max(gap_lo + 1e-6, gap_hi)))
            launch_uv = np.asarray(rng.uniform(
                -xy_jitter, xy_jitter, size=2), dtype=np.float32)
            max_center_offset = max(
                0.0,
                float(racket_radius) - SIMCODE2_BALL_RADIUS_M - edge_margin,
            )
            offset_norm = float(np.linalg.norm(launch_uv))
            if offset_norm > max_center_offset and offset_norm > 1e-8:
                launch_uv *= np.float32(max_center_offset / offset_norm)
            tangent_offset = (
                tangent_x * launch_uv[0] + tangent_y * launch_uv[1])
            racket_surface_center = (
                racket_center
                + racket_normal * np.float32(racket_half_thickness))
            center_offset_m = (
                float(racket_half_thickness)
                + SIMCODE2_BALL_RADIUS_M
                + surface_gap)
            position = (
                racket_surface_center
                + racket_normal * np.float32(
                    SIMCODE2_BALL_RADIUS_M + surface_gap)
                + tangent_offset).astype(np.float32)
            velocity_uv = np.asarray(rng.uniform(
                -vxy_max, vxy_max, size=2), dtype=np.float32)
            velocity_normal = float(rng.uniform(
                -vnormal_max, vnormal_max))
            velocity = (
                tangent_x * velocity_uv[0]
                + tangent_y * velocity_uv[1]
                + racket_normal * np.float32(velocity_normal)
            ).astype(np.float32)
            contract = {
                "mode": "racket_launch",
                "profile": str(self.active_policy_profile),
                "racketCenter": _rounded_vector(racket_center),
                "racketSurfaceCenter": _rounded_vector(
                    racket_surface_center),
                "racketNormal": _rounded_vector(racket_normal),
                "surfaceGapM": round(float(surface_gap), 6),
                "centerOffsetAlongNormalM": round(
                    float(center_offset_m), 6),
                "tangentOffsetUvM": _rounded_vector(launch_uv),
                "position": _rounded_vector(position),
                "velocity": _rounded_vector(velocity),
                "xyJitterLimitM": float(xy_jitter),
                "tangentVelocityUvMps": _rounded_vector(velocity_uv),
                "normalVelocityMps": round(float(velocity_normal), 6),
                "velocityJitterMps": max(vxy_max, vnormal_max),
                "checkpointBallLaunchHeightIgnoredM": env_cfg.get(
                    "ball_launch_height"),
            }
            return position, velocity, contract

        position = np.asarray(self.initial_ball_pos(), dtype=np.float32)
        return position, velocity, {
            "mode": "legacy_probe",
            "profile": OBSERVATION_PROFILE_LEGACY_BUG_COMPAT,
            "position": _rounded_vector(position),
            "velocity": _rounded_vector(velocity),
        }

    def anchor(self) -> np.ndarray:
        anchor = getattr(self.controller, "_racket_anchor_pos_base", None)
        if anchor is None or not np.all(np.isfinite(anchor)):
            return np.zeros(3, dtype=np.float32)
        return np.asarray(anchor, dtype=np.float32).reshape(3)

    def _current_reset_pose_q(self) -> np.ndarray:
        q = self._right_arm_joint_vector_or_none(getattr(
            self, "reset_initial_pose_q", None))
        if q is None:
            return self.safe_q.astype(np.float64)
        return q.astype(np.float64)

    def _resolve_reset_initial_pose(self, preset: Any) -> tuple[str, np.ndarray]:
        if self.active_policy_profile in FPLC_PROFILES:
            q = self.controller.native_reset_arm_q.astype(np.float64).copy()
            limits = fplc_workspace_intersection((
                self.cfg.ee_x_limits_m, self.cfg.ee_y_limits_m, self.cfg.ee_z_limits_m))
            if not self.controller.pose_is_safe(q, limits):
                raise RuntimeError("simcode9 native reset lies outside the configured real safety workspace")
            return RESET_INITIAL_POSE_FPLC, q
        if _reset_initial_pose_id(preset) == RESET_INITIAL_POSE_FPLC:
            preset = RESET_INITIAL_POSE_HORIZONTAL
        return _reset_initial_pose_q_rad(preset)

    def _sync_policy_to_safe_pose(
        self,
        q_reference: np.ndarray | None = None,
    ) -> None:
        q = self._right_arm_joint_vector_or_none(q_reference)
        if q is None:
            q = self._current_reset_pose_q()
        q = np.clip(
            q.astype(np.float32),
            self.controller.arm_q_low,
            self.controller.arm_q_high,
        ).astype(np.float32)
        self.controller.arm_cmd_q = q.copy()
        self.controller.arm_cmd_qvel = np.zeros(len(RIGHT_ARM_JOINTS), dtype=np.float32)
        self.controller.last_cmd_q = q.copy()
        self.controller.last_cmd_qvel = self.controller.arm_cmd_qvel.copy()
        self.controller.last_cmd_qacc = np.zeros(len(RIGHT_ARM_JOINTS), dtype=np.float32)
        self.controller.last_action = np.zeros(len(RIGHT_ARM_JOINTS), dtype=np.float32)
        if getattr(self, "active_policy_profile", "") in FPLC_PROFILES:
            self.controller.invalidate_after_intervention()
        if (getattr(self, "active_policy_profile", "")
                == OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85):
            self.controller.prev_action = np.zeros(
                len(RIGHT_ARM_JOINTS), dtype=np.float32)
            self.controller._gpu0_requires_measured_reset = True
        if (getattr(self, "active_policy_profile", "")
                == OBSERVATION_PROFILE_GPU1_QACC_FT_V153):
            self.controller.prev_action = np.zeros(
                len(RIGHT_ARM_JOINTS), dtype=np.float32)
            self.controller._gpu1_requires_measured_reset = True
        try:
            rpos_base, ok = self.controller._compute_racket_pose_base(q)
            if ok:
                self.controller._racket_anchor_pos_base = np.asarray(
                    rpos_base, dtype=np.float32).reshape(3).copy()
                self.controller._prev_racket_pos_base = np.asarray(
                    rpos_base, dtype=np.float32).reshape(3).copy()
                self.controller._prev_racket_sample_pos_base = None
                self.controller._prev_racket_sample_stamp_s = None
                self.controller._last_racket_sample_vel_base = np.zeros(
                    3, dtype=np.float32)
        except Exception:
            pass

    def _sync_controller_to_tracking_command(
        self,
        command_q: np.ndarray,
        command_dq: np.ndarray,
        *,
        reset_acceleration: bool = False,
    ) -> None:
        """Expose tracker output through the controller's common command API."""
        q = np.asarray(command_q, dtype=np.float32).reshape(
            len(RIGHT_ARM_JOINTS))
        dq = np.asarray(command_dq, dtype=np.float32).reshape(
            len(RIGHT_ARM_JOINTS))
        previous_dq = np.asarray(
            getattr(self.controller, "last_cmd_qvel", np.zeros_like(dq)),
            dtype=np.float32,
        ).reshape(len(RIGHT_ARM_JOINTS))
        ddq = (
            np.zeros_like(dq)
            if reset_acceleration else
            (dq - previous_dq) / max(float(self.cfg.control_dt), 1e-6)
        )
        self.controller.arm_cmd_q = q.copy()
        self.controller.arm_cmd_qvel = dq.copy()
        self.controller.last_cmd_q = q.copy()
        self.controller.last_cmd_qvel = dq.copy()
        self.controller.last_cmd_qacc = ddq.astype(np.float32)
        self.controller.last_action = np.zeros(
            len(RIGHT_ARM_JOINTS), dtype=np.float32)

    def _hold_racket_tracker(
        self,
        reason: str,
        q_reference: np.ndarray | None = None,
    ) -> None:
        tracker = getattr(self, "racket_tracker", None)
        if tracker is None:
            return
        if q_reference is None:
            current_q = getattr(self.controller, "current_arm_cmd_q", None)
            if callable(current_q):
                q_reference = current_q()
            else:
                q_reference = getattr(
                    self.controller, "arm_cmd_q", self.safe_q)
        command_q, info = tracker.hold(
            q_reference, reason=reason)
        self.last_tracking_info = info
        self._sync_controller_to_tracking_command(
            command_q, np.zeros(len(RIGHT_ARM_JOINTS), dtype=np.float32))

    def _hold_juggle_controller(
        self,
        reason: str,
        q_reference: np.ndarray | None = None,
        *,
        fault: bool = False,
    ) -> None:
        """Hold the independent juggling command trajectory at a finite pose."""

        tracker = getattr(self, "juggle_tracker", None)
        controller = getattr(self, "juggle_controller", None)
        if tracker is None or controller is None:
            return
        if q_reference is None:
            current_q = getattr(self.controller, "current_arm_cmd_q", None)
            q_reference = (
                current_q() if callable(current_q)
                else getattr(self.controller, "arm_cmd_q", self.safe_q))
        command_q, tracker_info = tracker.hold(
            q_reference, reason=reason)
        if fault:
            controller.fail(reason)
        self.last_juggle_info = dict(
            getattr(controller, "last_diagnostics", {}))
        self.last_juggle_info.update({
            "state": controller.state,
            "active": controller.active,
            "fault": (
                controller.fault_reason if fault else reason),
            "lowLevel": tracker_info,
        })
        self._sync_controller_to_tracking_command(
            command_q, np.zeros(len(RIGHT_ARM_JOINTS), dtype=np.float32))

    def _reset_recovery_active(self) -> bool:
        if bool(getattr(self, "reset_hold_latched", False)):
            return True
        trajectory = getattr(self, "slow_reset_trajectory", None)
        if trajectory is not None and bool(trajectory.active):
            return True
        deadline = float(getattr(
            self, "reset_workspace_bypass_until_wall", 0.0) or 0.0)
        if deadline <= 0.0:
            return False
        now = time.monotonic()
        if now >= deadline:
            self.reset_workspace_bypass_until_wall = 0.0
            self.reset_workspace_bypass_target_q = None
            return False
        return True

    def _start_supervised_reset(
        self,
        position_rad: object,
        target_rad: object,
        *,
        reason: str,
        new_reset_cycle: bool = True,
    ) -> None:
        """Start/reset the independent trajectory and its terminal hold.

        A ROS-capable process keeps the terminal hold latched until physical
        feedback settles and the operator performs a fresh Send-command
        off -> on gesture.  ROS-free tests and dry local probes retain their
        non-latching behavior.
        """
        position = np.asarray(position_rad, dtype=np.float64).reshape(
            len(RIGHT_ARM_JOINTS))
        target = np.asarray(target_rad, dtype=np.float64).reshape(
            len(RIGHT_ARM_JOINTS))
        self._ensure_slow_reset_trajectory().start(
            position,
            target,
            # The two-second comfort minimum belongs to the operator's reset
            # cycle. A feedback replan must retain analytic speed/acceleration
            # limits without restarting that entire minimum duration.
            minimum_duration_s=None if new_reset_cycle else 0.0,
        )
        cfg = getattr(self, "cfg", None)
        hardware_capable = bool(
            getattr(self, "ros_bridge", None) is not None
            and getattr(cfg, "ros_publish_commands", True))
        self.reset_hold_latched = hardware_capable
        self.reset_hold_reason = str(reason or "reset")
        self.reset_command_trajectory_complete = False
        self.reset_settled = False
        self.reset_settle_ticks = 0
        self.reset_tracking_paused = False
        self.reset_publish_blocked = False
        if new_reset_cycle:
            # Capture the authorization that existed before this reset.  A
            # feedback re-anchor is still the same reset cycle and must never
            # replace this baseline with a token issued after reset began.
            self.reset_start_publish_arm_token = str(getattr(
                self, "last_publish_arm_token", ""))
            self.reset_policy_arm_required = False
            self.reset_policy_arm_reason = "reset_in_progress"
            self.last_reset_reanchor = {
                "reanchored": False,
                "reason": "new_reset_cycle",
                "positionErrorAbsMaxRad": 0.0,
            }
        self.last_reset_feedback = {
            "available": False,
            "fresh": False,
            "ageS": None,
            "positionErrorAbsMaxRad": None,
            "velocityAbsMaxRadS": None,
        }
        self.reset_workspace_bypass_target_q = target.copy()
        if hardware_capable:
            self.publish_rearm_required = False
            self.publish_rearm_off_seen = False
            self.publish_rearm_reason = ""
            self.publish_rearm_details = {}

    def _resume_or_reanchor_active_reset(
        self,
        feedback_q: np.ndarray,
    ) -> bool:
        """Resume a tracked reset, replanning only after real divergence."""
        if (not self._reset_recovery_active()
                or bool(getattr(self, "reset_settled", False))
                or bool(getattr(
                    self, "reset_command_trajectory_complete", False))):
            return False
        trajectory = self._ensure_slow_reset_trajectory()
        status = trajectory.status()
        feedback = np.asarray(feedback_q, dtype=np.float64).reshape(
            len(RIGHT_ARM_JOINTS))
        error = float(np.max(np.abs(status.position_rad - feedback)))
        if error <= RESET_REANCHOR_RESUME_ERROR_RAD:
            self.last_reset_reanchor = {
                "reanchored": False,
                "reason": "tracked_trajectory_resumed",
                "positionErrorAbsMaxRad": error,
                "preservedElapsedS": float(status.elapsed_s),
            }
            return False
        self._start_supervised_reset(
            feedback,
            status.target_rad,
            reason=str(getattr(self, "reset_hold_reason", "reset")),
            new_reset_cycle=False,
        )
        replanned = self._ensure_slow_reset_trajectory().status()
        self.last_reset_reanchor = {
            "reanchored": True,
            "reason": "feedback_diverged_from_reset_reference",
            "positionErrorAbsMaxRad": error,
            "segmentDurationS": float(np.max(
                self._ensure_slow_reset_trajectory()._duration_s)),
            "segmentElapsedS": float(replanned.elapsed_s),
        }
        return True

    def _require_publish_rearm(self, reason: str, *, details: dict[str, Any] | None = None) -> None:
        normalized_reason = str(reason or "safety_transition")
        if (bool(getattr(self, "publish_rearm_required", False))
                and str(getattr(
                    self, "publish_rearm_reason", "")) == normalized_reason):
            return
        self.publish_rearm_required = True
        self.publish_rearm_off_seen = False
        self.publish_rearm_reason = normalized_reason
        # Preserve the first triggering sample until an explicit re-arm/reset.
        # Live feedback may already be fresh when the browser sees the stop.
        self.publish_rearm_details = dict(details or {})
        print(f"[CommandSafety][STOP] Send command disabled: {normalized_reason} "
              f"details={json.dumps(self.publish_rearm_details, ensure_ascii=False)}", flush=True)
        self.policy_switch_publish_rearm_required = bool(
            self.publish_rearm_reason in {
                "policy_profile_changed",
                "policy_model_changed",
            })
        if getattr(self, "runtime_options", None) is not None:
            self.runtime_options = replace(
                self.runtime_options, publish_commands=False)

    def _release_reset_hold_for_rearm(self) -> None:
        """Release a completed reset only at an explicit re-arm edge."""
        if (not bool(getattr(self, "reset_hold_latched", False))
                or not bool(getattr(self, "reset_settled", False))):
            return
        self.reset_hold_latched = False
        self.reset_workspace_bypass_until_wall = 0.0
        self.reset_workspace_bypass_target_q = None
        self.soft_workspace_reset_latched = False
        self.soft_workspace_reset_reason = ""
        self.soft_workspace_reset_conditions = {}
        self.done_failsafe_active = False
        self.done_failsafe_reason = ""
        self.done_failsafe_conditions = {}
        self.reset_policy_arm_required = False
        self.reset_policy_arm_reason = ""
        # Force one fresh measured-position arm hold before the next policy
        # command.
        self.command_stream_active = False
        self.last_control_mode = "reset_hold"
        self._mark_policy_paused()

    def _consume_reset_policy_arm_request(
        self,
        payload: dict[str, Any],
        *,
        publish_requested: bool,
        switch_requested: bool,
    ) -> bool:
        """Consume a fresh post-reset Send-command arm token.

        A boolean heartbeat cannot distinguish the stale pre-reset checked
        state from a deliberate new operator arm.  The browser therefore
        creates a unique token on every real unchecked -> checked gesture.
        Only a token different from the one captured at reset start may unlock
        settled reset recovery.
        """
        arm_token = str(payload.get("publishArmToken", "") or "").strip()
        if publish_requested and arm_token:
            self.last_publish_arm_token = arm_token
        pending = bool(
            getattr(self, "reset_policy_arm_required", False)
            and getattr(self, "reset_hold_latched", False)
            and getattr(self, "reset_settled", False))
        if not pending or switch_requested:
            return False
        fresh_arm = bool(
            publish_requested
            and arm_token
            and arm_token != str(getattr(
                self, "reset_start_publish_arm_token", "")))
        if not fresh_arm:
            return True
        self._release_reset_hold_for_rearm()
        self.reset_policy_arm_reason = "fresh_send_command_token"
        self.last_command_arm = {
            "armed": False,
            "reason": "reset_released_by_fresh_send_command",
            "feedbackAgeS": None,
            "jointPosition": None,
        }
        return False

    def _publish_rearm_blocks_request(
        self,
        *,
        publish_requested: bool,
        switch_requested: bool,
    ) -> bool:
        """Consume an explicit off -> on edge for a latched command stop."""
        legacy_switch_rearm = bool(getattr(
            self, "policy_switch_publish_rearm_required", False))
        rearm_required = bool(
            getattr(self, "publish_rearm_required", False)
            or legacy_switch_rearm)
        if legacy_switch_rearm and not bool(getattr(
                self, "publish_rearm_required", False)):
            self.publish_rearm_required = True
            self.publish_rearm_off_seen = False
            self.publish_rearm_reason = "policy_switch"
        if rearm_required and not publish_requested and not switch_requested:
            self.publish_rearm_off_seen = True
        elif (rearm_required and publish_requested and not switch_requested
                and bool(getattr(
                    self, "publish_rearm_off_seen", False))):
            self.publish_rearm_required = False
            self.publish_rearm_off_seen = False
            self.publish_rearm_reason = ""
            self.publish_rearm_details = {}
            self.policy_switch_publish_rearm_required = False
            self.reset_publish_blocked = False
            self._release_reset_hold_for_rearm()
            rearm_required = False
        return bool(rearm_required)

    def _reset_feedback_sample(
        self,
        target_q: np.ndarray,
    ) -> tuple[np.ndarray | None, np.ndarray | None, bool]:
        bridge = getattr(self, "ros_bridge", None)
        if bridge is None:
            self.last_reset_feedback = {
                "available": False,
                "fresh": True,
                "ageS": None,
                "positionErrorAbsMaxRad": 0.0,
                "velocityAbsMaxRadS": 0.0,
            }
            return None, None, True
        q = None
        dq = None
        age_s = None
        try:
            getter = getattr(bridge, "get_joint_feedback_with_age", None)
            if callable(getter):
                q, dq, age_s, _source = getter()
            else:
                q, dq = bridge.get_joint_feedback()
        except Exception:
            q = None
            dq = None
        q_value = self._right_arm_joint_vector_or_none(q)
        dq_value = self._right_arm_joint_vector_or_none(dq)
        fresh = bool(q_value is not None and dq_value is not None)
        if age_s is not None:
            try:
                age_value = float(age_s)
                fresh = bool(
                    fresh
                    and math.isfinite(age_value)
                    and 0.0 <= age_value <= RESET_FEEDBACK_MAX_AGE_S)
            except (TypeError, ValueError):
                fresh = False
                age_value = None
        else:
            age_value = None
        position_error = (
            None if q_value is None
            else float(np.max(np.abs(
                np.asarray(target_q, dtype=np.float64) - q_value))))
        velocity_abs_max = (
            None if dq_value is None
            else float(np.max(np.abs(dq_value))))
        self.last_reset_feedback = {
            "available": bool(q_value is not None and dq_value is not None),
            "fresh": bool(fresh),
            "ageS": age_value,
            "positionErrorAbsMaxRad": position_error,
            "velocityAbsMaxRadS": velocity_abs_max,
        }
        return q_value, dq_value, fresh

    def _ensure_slow_reset_trajectory(self) -> SlowResetTrajectory:
        trajectory = getattr(self, "slow_reset_trajectory", None)
        if trajectory is not None:
            return trajectory
        cfg = getattr(self, "cfg", None)
        trajectory = SlowResetTrajectory(
            dt_s=float(getattr(cfg, "control_dt", 0.005)),
            velocity_limit_deg_s=float(getattr(
                cfg, "reset_velocity_limit_deg_s", 15.0)),
            acceleration_limit_deg_s2=float(getattr(
                cfg, "reset_acceleration_limit_deg_s2", 40.0)),
        )
        self.slow_reset_trajectory = trajectory
        return trajectory

    def _reset_recovery_payload(self) -> dict[str, Any]:
        deadline = float(getattr(
            self, "reset_workspace_bypass_until_wall", 0.0) or 0.0)
        active = self._reset_recovery_active()
        trajectory = getattr(self, "slow_reset_trajectory", None)
        status = trajectory.status() if trajectory is not None else None
        remaining_s = max(0.0, deadline - time.monotonic()) if active else 0.0
        return {
            "active": bool(active),
            "holdLatched": bool(getattr(
                self, "reset_hold_latched", False)),
            "reason": str(getattr(self, "reset_hold_reason", "")),
            "commandTrajectoryComplete": bool(getattr(
                self, "reset_command_trajectory_complete", False)),
            "settled": bool(getattr(self, "reset_settled", False)),
            "trackingPaused": bool(getattr(
                self, "reset_tracking_paused", False)),
            "publishBlocked": bool(getattr(
                self, "reset_publish_blocked", False)),
            "policyArmRequired": bool(getattr(
                self, "reset_policy_arm_required", False)),
            "policyArmReason": str(getattr(
                self, "reset_policy_arm_reason", "")),
            "reanchor": dict(getattr(
                self, "last_reset_reanchor", {})),
            "freshPolicyArmSeen": bool(
                str(getattr(self, "last_publish_arm_token", ""))
                and str(getattr(self, "last_publish_arm_token", ""))
                != str(getattr(
                    self, "reset_start_publish_arm_token", ""))),
            "rearmRequired": bool(getattr(
                self, "publish_rearm_required", False)),
            "rearmOffSeen": bool(getattr(
                self, "publish_rearm_off_seen", False)),
            "rearmReason": str(getattr(
                self, "publish_rearm_reason", "")),
            "feedback": dict(getattr(self, "last_reset_feedback", {})),
            "remainingS": round(float(remaining_s), 6),
            "trajectory": (
                None if status is None else {
                    "active": bool(status.active),
                    "progress": round(float(status.progress), 6),
                    "elapsedS": round(float(status.elapsed_s), 6),
                    "velocityLimitDegS": float(
                        getattr(self.cfg, "reset_velocity_limit_deg_s", 15.0)),
                    "accelerationLimitDegS2": float(
                        getattr(
                            self.cfg,
                            "reset_acceleration_limit_deg_s2",
                            40.0,
                        )),
                    "commandJointPosition": _rounded_vector(
                        status.position_rad),
                    "commandJointVelocity": _rounded_vector(
                        status.velocity_rad_s),
                }),
            "target": (
                None
                if self._right_arm_joint_vector_or_none(getattr(
                    self, "reset_workspace_bypass_target_q", None)) is None
                else _rounded_vector(self.reset_workspace_bypass_target_q)),
        }

    def _advance_slow_reset_command(
        self,
        *,
        advance: bool = True,
    ) -> np.ndarray:
        trajectory = self._ensure_slow_reset_trajectory()
        status = trajectory.status()
        q = np.asarray(status.position_rad, dtype=np.float64)
        dq = np.asarray(status.velocity_rad_s, dtype=np.float64)
        if not advance:
            return q.copy()

        feedback_q, feedback_dq, feedback_fresh = (
            self._reset_feedback_sample(q))
        if getattr(self, "ros_bridge", None) is not None and not feedback_fresh:
            # Continuing an open-loop reset after losing JointState can leave a
            # large stored position error. Stop publishing and demand a fresh
            # operator re-arm; the trajectory will be re-anchored from measured
            # q by `_arm_command_stream_from_feedback`.
            self.reset_tracking_paused = True
            self.reset_publish_blocked = True
            self.command_stream_active = False
            self._require_publish_rearm("reset_joint_feedback_stale", details={
                "jointFeedbackAgeS": self.last_reset_feedback.get("ageS"),
                "maximumJointFeedbackAgeS": RESET_FEEDBACK_MAX_AGE_S,
            })
            if getattr(self, "runtime_options", None) is not None:
                self.runtime_options = replace(
                    self.runtime_options, publish_commands=False)
            return q.copy()

        if trajectory.active and feedback_q is not None and feedback_dq is not None:
            tracking_error = float(np.max(np.abs(q - feedback_q)))
            feedback_speed = float(np.max(np.abs(feedback_dq)))
            if (tracking_error > RESET_TRACKING_ERROR_LIMIT_RAD
                    or feedback_speed > RESET_ADVANCE_MAX_SPEED_RAD_S):
                # Hold the current reset reference until the physical arm has
                # caught up and slowed down.  Never accumulate an open-loop
                # reset target far ahead of the real joints.
                self.reset_tracking_paused = True
                self.reset_settle_ticks = 0
                return q.copy()
        self.reset_tracking_paused = False
        q, dq, done = trajectory.step()
        if getattr(self, "active_policy_profile", "") not in FPLC_PROFILES:
            self.safety_limiter.last_cmd = np.asarray(q, dtype=np.float64).copy()
            self.safety_limiter.last_vel = np.asarray(dq, dtype=np.float64).copy()
        if getattr(self, "controller", None) is not None:
            self._sync_controller_to_tracking_command(
                q, dq, reset_acceleration=False)
        if done:
            self.reset_command_trajectory_complete = True
            if getattr(self, "controller", None) is not None:
                self._sync_policy_to_safe_pose(q)
        if bool(getattr(self, "reset_command_trajectory_complete", False)):
            target_q = np.asarray(trajectory.target_rad, dtype=np.float64)
            feedback_q, feedback_dq, feedback_fresh = (
                self._reset_feedback_sample(target_q))
            if getattr(self, "ros_bridge", None) is None:
                settled_now = True
            else:
                settled_now = bool(
                    feedback_fresh
                    and feedback_q is not None
                    and feedback_dq is not None
                    and np.max(np.abs(target_q - feedback_q))
                    <= RESET_SETTLE_POSITION_TOLERANCE_RAD
                    and np.max(np.abs(feedback_dq))
                    <= RESET_SETTLE_VELOCITY_TOLERANCE_RAD_S)
            self.reset_settle_ticks = (
                int(getattr(self, "reset_settle_ticks", 0)) + 1
                if settled_now else 0)
            required_ticks = max(
                1,
                int(math.ceil(
                    RESET_SETTLE_DURATION_S
                    / max(float(getattr(
                        getattr(self, "cfg", None),
                        "control_dt",
                        0.005,
                    )), 1e-6))),
            )
            if (self.reset_settle_ticks >= required_ticks
                    and not bool(getattr(self, "reset_settled", False))):
                self.reset_settled = True
                if bool(getattr(self, "reset_hold_latched", False)):
                    self.reset_policy_arm_required = True
                    self.reset_policy_arm_reason = (
                        "fresh_send_command_required_after_reset")
                    options = getattr(self, "runtime_options", None)
                    fresh_arm_already_requested = bool(
                        options is not None
                        and bool(getattr(options, "publish_commands", False))
                        and str(getattr(
                            self, "last_publish_arm_token", ""))
                        and str(getattr(
                            self, "last_publish_arm_token", ""))
                        != str(getattr(
                            self, "reset_start_publish_arm_token", "")))
                    if fresh_arm_already_requested:
                        # The operator explicitly armed after this reset began.
                        # Finish this reset tick, force a fresh feedback hold on
                        # the next tick, then allow normal policy execution.
                        self._release_reset_hold_for_rearm()
                        self.reset_policy_arm_reason = (
                            "fresh_send_command_seen_during_reset")
                        self.last_command_arm = {
                            "armed": False,
                            "reason": (
                                "reset_released_by_fresh_send_command"),
                            "jointPosition": _rounded_vector(q),
                        }
                    else:
                        # The checked state predates reset and is stale. Disarm
                        # policy publication, but do not rely on observing an
                        # asynchronous off payload. A new UI arm token releases
                        # the terminal hold deterministically.
                        if options is not None:
                            self.runtime_options = replace(
                                options, publish_commands=False)
                        self.last_command_arm = {
                            "armed": False,
                            "reason": (
                                "reset_complete_fresh_send_required"),
                            "jointPosition": _rounded_vector(q),
                        }
                else:
                    self.reset_workspace_bypass_until_wall = 0.0
                    self.reset_workspace_bypass_target_q = None
        return np.asarray(q, dtype=np.float64)

    def _slow_reset_current_q(self) -> np.ndarray:
        trajectory = getattr(self, "slow_reset_trajectory", None)
        if trajectory is not None:
            return np.asarray(
                trajectory.status().position_rad,
                dtype=np.float64,
            )
        target = self._right_arm_joint_vector_or_none(getattr(
            self, "reset_workspace_bypass_target_q", None))
        if target is not None:
            return target
        return np.asarray(self._current_reset_pose_q(), dtype=np.float64)

    def _reset_policy_dq_adapter(self, reason: str) -> None:
        adapter = getattr(self, "policy_dq_adapter", None)
        if adapter is None:
            return
        adapter.reset(reason)
        self.last_policy_dq_adapter_info = adapter.status()

    def _mark_policy_paused(self) -> None:
        """Fence real-policy histories at a non-policy control interval.

        The simulation mirror is observational and cannot affect hardware.
        A transient real-side hold must therefore not destroy its plant,
        policy, or delay history.  Mirror resets are reserved for actual
        policy-session boundaries such as an explicit reset or profile/model
        switch.
        """
        self.policy_publish_last_perf = None
        self.policy_needs_reentry_reset = True
        self._reset_policy_dq_adapter("policy_paused")

    def _set_policy_workspace_limits(self, profile: str) -> None:
        """Select from the original envelope, never the previous policy's box."""
        limits = self.base_ee_limits_m
        if profile in FPLC_PROFILES:
            limits = fplc_workspace_intersection(limits)
        self.cfg.ee_x_limits_m, self.cfg.ee_y_limits_m, self.cfg.ee_z_limits_m = limits
        # Reset/profile selection can produce a snapshot before the next
        # control tick. Keep its done monitor on the same envelope immediately.
        monitor = getattr(self, "done_monitor", None)
        if monitor is not None:
            mode = ("position" if profile in FPLC_PROFILES else getattr(
                self, "active_workspace_safety_mode", self.cfg.workspace_safety_mode))
            enabled = mode != "off"
            monitor.ee_x_limits, monitor.ee_y_limits, monitor.ee_z_limits = (
                limits if enabled else (None, None, None))

    def _select_policy_profile(self, requested_profile: object) -> bool:
        """Atomically switch between pre-authenticated deployment profiles."""
        profile = normalize_observation_profile(requested_profile)
        if profile == self.active_policy_profile:
            return False
        if profile not in RUNTIME_SWITCHABLE_POLICY_PROFILES:
            raise RuntimeError(
                f"runtime policy profile {profile!r} is disabled in this UI")
        # Never carry a live hardware command stream across an actor/profile
        # boundary.  This publishes at most one measured-position hold and
        # closes the stream without entering safety_limiter.  A later explicit
        # Send-command off -> on action is required to arm the new actor.
        if bool(getattr(self, "command_stream_active", False)):
            self._publish_hold_on_command_disable()
        self._require_publish_rearm("policy_profile_changed")
        controller = self.policy_controllers.get(profile)
        if controller is None:
            controller = self._build_release_locked_policy_controller(profile)
            self.policy_controllers[profile] = controller
        reset_q = np.asarray(
            self._safety_limiter_reset_reference(), dtype=np.float32).reshape(-1)
        self._set_policy_workspace_limits(profile)
        self.active_policy_profile = profile
        self.controller = controller
        if (profile in FPLC_PROFILES or getattr(self, "reset_initial_pose_id", None) == RESET_INITIAL_POSE_FPLC):
            self.reset_initial_pose_id, self.reset_initial_pose_q = self._resolve_reset_initial_pose(
                getattr(self, "reset_initial_pose_id", RESET_INITIAL_POSE_DEFAULT))
        self.active_policy_model = _controller_policy_model_id(
            profile,
            self.controller,
            self.active_policy_model or GPU0_RMP_MODEL_V85,
        )
        self.policy_generation += 1
        self.controller.reset()
        self._sync_policy_to_safe_pose(reset_q)
        self._reset_compensator_to_current_arm(reset_q)
        self._reset_servo_target_planner(reset_q)
        self._reset_policy_ball_sampling_contract()
        # The next policy tick will reseed once more from the exact atomic q
        # included in that actor observation, closing a callback race between
        # profile selection/reentry and inference.
        self.compensation_was_enabled = False
        self.policy_reentry_reset_q = reset_q.copy()
        self.policy_needs_reentry_reset = True
        self.sim_needs_policy_reset = True
        self.last_policy_execution_trace = None
        self._reset_policy_dq_adapter("policy_profile_changed")
        self._configure_camera_racket_context()
        self.last_control_mode = None
        return True

    def _select_policy_model(self, requested_model: object) -> bool:
        """Switch the active profile's approved hash-pinned actor."""
        if self.active_policy_profile in FPLC_PROFILES:
            return False
        if self.active_policy_profile == OBSERVATION_PROFILE_GPU1_QACC_FT_V153:
            # GPU1 has one authenticated actor.  Ignore the disabled GPU0
            # selector's stale value and keep the runtime identity explicit.
            self.active_policy_model = GPU1_QACC_FT_MODEL_V153
            return False
        if self.active_policy_profile != (
                OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85):
            return False
        model_id = _normalize_gpu0_rmp_model(
            requested_model,
            self.active_policy_model or GPU0_RMP_MODEL_V85,
        )
        if model_id == self.active_policy_model:
            return False
        controller = self.policy_model_controllers.get(model_id)
        if controller is None:
            controller = self._build_release_locked_policy_controller(
                self.active_policy_profile, model_id)
            loaded_model_id = str(getattr(
                controller, "policy_model_id", ""))
            if loaded_model_id != model_id:
                raise RuntimeError(
                    "GPU0-QVEL/REAL-RMP selected model does not match its "
                    f"approved checkpoint: requested={model_id}, "
                    f"loaded={loaded_model_id or 'unknown'}")
            self.policy_model_controllers[model_id] = controller
        if bool(getattr(self, "command_stream_active", False)):
            self._publish_hold_on_command_disable()
        self._require_publish_rearm("policy_model_changed")
        reset_q = np.asarray(
            self._safety_limiter_reset_reference(), dtype=np.float32).reshape(-1)
        self.active_policy_model = model_id
        self.controller = controller
        self.policy_controllers[self.active_policy_profile] = controller
        self.policy_generation += 1
        self.controller.reset()
        self._sync_policy_to_safe_pose(reset_q)
        self._reset_compensator_to_current_arm(reset_q)
        self._reset_servo_target_planner(reset_q)
        self._reset_policy_ball_sampling_contract()
        self.compensation_was_enabled = False
        self.policy_reentry_reset_q = reset_q.copy()
        self.policy_needs_reentry_reset = True
        self.sim_needs_policy_reset = True
        self.last_policy_execution_trace = None
        self._reset_policy_dq_adapter("policy_model_changed")
        self._configure_camera_racket_context()
        self.last_control_mode = None
        return True

    def _reset_real_policy_for_sim_reentry(self) -> np.ndarray:
        """Reset real policy history and seed it from the current real arm."""
        reset_q = np.asarray(
            self._safety_limiter_reset_reference(), dtype=np.float32).reshape(-1)
        reset_q = np.clip(
            reset_q, self.controller.arm_q_low, self.controller.arm_q_high,
        ).astype(np.float32)
        self.controller.reset()
        # This also anchors previous racket FK at the actual pose.  It is
        # observable in the corrected simcode2 profile: failing to do this
        # creates a large fictitious first-tick racket velocity after a switch.
        self._sync_policy_to_safe_pose(reset_q)
        self._reset_compensator_to_current_arm(reset_q)
        self._reset_servo_target_planner(reset_q)
        # `_run_one_control_step` captures its coherent JointState before this
        # reentry helper. Force the publish path to replace this provisional
        # seed with the exact q consumed by the actor on the same tick.
        self.compensation_was_enabled = False
        self.policy_reentry_reset_q = reset_q.copy()
        self.policy_needs_reentry_reset = False
        self._reset_policy_dq_adapter("policy_reentry")
        return reset_q

    def _right_arm_joint_vector_or_none(self, value: Any) -> np.ndarray | None:
        if value is None:
            return None
        try:
            q = np.asarray(value, dtype=np.float64).reshape(-1)
        except Exception:
            return None
        if q.shape[0] != len(RIGHT_ARM_JOINTS) or not np.all(np.isfinite(q)):
            return None
        return q

    def _current_arm_reset_reference(self) -> np.ndarray:
        if self.ros_bridge is not None:
            timed_getter = getattr(
                self.ros_bridge, "get_joint_feedback_with_age", None)
            if callable(timed_getter):
                try:
                    q_fb, _dq_fb, age_s, _source = timed_getter()
                    age = float(age_s)
                    q = self._right_arm_joint_vector_or_none(q_fb)
                    if (q is not None and math.isfinite(age)
                            and 0.0 <= age <= 0.05):
                        return q
                except Exception:
                    pass
            else:
                q_fb, _dq_fb = self.ros_bridge.get_joint_feedback()
                q = self._right_arm_joint_vector_or_none(q_fb)
                if q is not None:
                    return q
        q = self._right_arm_joint_vector_or_none(
            getattr(self, "last_published_safe_reference", None))
        if q is not None:
            return q
        try:
            q = self._right_arm_joint_vector_or_none(
                self.controller.current_arm_cmd_q())
            if q is not None:
                return q
        except Exception:
            pass
        return self.safe_q.astype(np.float64)

    def _safety_limiter_reset_reference(self) -> np.ndarray:
        """Compatibility alias; reset no longer reads limiter state."""
        return self._current_arm_reset_reference()

    def _limiter_free_joint_candidate(
        self,
        desired: object,
        *,
        profile: str = "normal",
    ) -> np.ndarray:
        """Advance the local rate state without entering ``safety_limiter``.

        This deliberately reproduces only the position/velocity/acceleration
        envelope required by the workspace controller.  It is implemented in
        this runtime so neither normal policy execution nor reset can call the
        separately maintained (and unsafe for this deployment) limiter.
        """
        state = self.safety_limiter
        previous = np.asarray(state.last_cmd, dtype=np.float64).reshape(
            len(RIGHT_ARM_JOINTS))
        try:
            candidate = np.asarray(desired, dtype=np.float64).reshape(
                len(RIGHT_ARM_JOINTS))
        except Exception:
            candidate = previous.copy()
        if not np.all(np.isfinite(candidate)):
            candidate = previous.copy()
        candidate = np.clip(
            candidate,
            RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
            RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
        )
        dt = max(float(state.dt), 1e-9)
        velocity_limit, acceleration_limit = (
            self._workspace_profile_limits(profile))
        desired_velocity = np.clip(
            (candidate - previous) / dt,
            -velocity_limit,
            velocity_limit,
        )
        previous_velocity = np.asarray(
            state.last_vel, dtype=np.float64).reshape(
                len(RIGHT_ARM_JOINTS))
        reachable_velocity = np.clip(
            desired_velocity,
            previous_velocity - acceleration_limit * dt,
            previous_velocity + acceleration_limit * dt,
        )
        candidate = np.clip(
            previous + reachable_velocity * dt,
            RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
            RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
        )
        state.last_vel = (candidate - previous) / dt
        state.last_cmd = candidate.copy()
        return candidate.copy()

    def _limiter_free_parking_candidate(self, desired: object) -> np.ndarray:
        """Start every parking transition from fresh measured/issued q."""
        if str(getattr(
                self, "last_published_command_profile", "none")) != "parking":
            anchor_q = self._current_arm_reset_reference()
            self.safety_limiter.last_cmd = np.asarray(
                anchor_q, dtype=np.float64).copy()
            self.safety_limiter.last_vel = np.zeros(
                len(RIGHT_ARM_JOINTS), dtype=np.float64)
        return self._limiter_free_joint_candidate(
            desired, profile="parking")

    def _workspace_profile_limits(
        self, profile: str,
    ) -> tuple[np.ndarray, np.ndarray]:
        velocity = np.deg2rad(np.asarray(
            RightArmCommandSafetyLimiter.VEL_LIMIT_DEG_S,
            dtype=np.float64))
        acceleration = np.deg2rad(np.asarray(
            RightArmCommandSafetyLimiter.ACC_LIMIT_DEG_S2,
            dtype=np.float64))
        if str(profile).strip().lower() == "parking":
            velocity *= float(self.cfg.safety_parking_velocity_scale)
            acceleration *= float(self.cfg.safety_parking_acceleration_scale)
        return velocity, acceleration

    def _reset_servo_target_planner(self, q: np.ndarray) -> None:
        """Re-anchor the optional simcode4 drive planner to a hold/reset."""
        reset = getattr(getattr(
            self, "servo_target_planner", None), "reset", None)
        if callable(reset):
            reset(q)
        self.last_servo_planner_input_q = np.asarray(
            q, dtype=np.float64).copy()
        self.last_servo_planner_output_q = np.asarray(
            q, dtype=np.float64).copy()
        self.last_servo_drive_model_advanced = False

    def _init_sim_mirror(self) -> None:
        self.sim_mirror = None
        self.sim_mirror_error = None
        self.latest_sim_snapshot = self._sim_unavailable_payload(
            "disabled" if not self.cfg.enable_sim_mirror else "not initialized")
        if not self.cfg.enable_sim_mirror:
            return
        backend = str(self.cfg.sim_backend or "mujoco").strip().lower()
        if backend not in {"mujoco", "mjx", "auto"}:
            backend = "mujoco"
        sim_cfg = SimMirrorConfig(
            model_path=self.cfg.model_path,
            policy_xml_path=self.cfg.robot_xml_path,
            sim_xml_path=self.cfg.sim_xml_path,
            policy_obs_dim=self.cfg.policy_obs_dim,
            control_dt=self.cfg.control_dt,
            policy_profile=self.cfg.policy_profile,
            policy_model=(
                getattr(self, "active_policy_model", "")
                or GPU0_RMP_MODEL_V85),
            simcode2_model_path=self.cfg.simcode2_model_path,
            simcode2_policy_xml_path=self.cfg.simcode2_policy_xml_path,
            simcode2_sim_xml_path=self.cfg.simcode2_sim_xml_path,
            simcode3_model_path=getattr(
                self.cfg, "simcode3_model_path", DEFAULT_SIMCODE3_MODEL_PATH),
            simcode3_policy_xml_path=getattr(
                self.cfg, "simcode3_policy_xml_path",
                DEFAULT_SIMCODE3_POLICY_XML),
            simcode3_sim_xml_path=getattr(
                self.cfg, "simcode3_sim_xml_path", DEFAULT_SIMCODE3_POLICY_XML),
            simcode4_model_path=getattr(
                self.cfg, "simcode4_model_path", DEFAULT_SIMCODE4_MODEL_PATH),
            simcode4_policy_xml_path=getattr(
                self.cfg, "simcode4_policy_xml_path",
                DEFAULT_SIMCODE4_POLICY_XML),
            simcode4_sim_xml_path=getattr(
                self.cfg, "simcode4_sim_xml_path", DEFAULT_SIMCODE4_POLICY_XML),
            simcode5_model_path=getattr(
                self.cfg, "simcode5_model_path", DEFAULT_SIMCODE5_MODEL_PATH),
            simcode5_policy_xml_path=getattr(
                self.cfg, "simcode5_policy_xml_path",
                DEFAULT_SIMCODE5_POLICY_XML),
            simcode5_sim_xml_path=getattr(
                self.cfg, "simcode5_sim_xml_path", DEFAULT_SIMCODE5_POLICY_XML),
            simcode6_model_path=getattr(
                self.cfg, "simcode6_model_path", DEFAULT_SIMCODE6_MODEL_PATH),
            simcode6_policy_xml_path=getattr(
                self.cfg, "simcode6_policy_xml_path",
                DEFAULT_SIMCODE6_POLICY_XML),
            simcode6_sim_xml_path=getattr(
                self.cfg, "simcode6_sim_xml_path", DEFAULT_SIMCODE6_POLICY_XML),
            simcode7_model_path=getattr(
                self.cfg, "simcode7_model_path", DEFAULT_SIMCODE7_MODEL_PATH),
            simcode7_v85_model_path=getattr(
                self.cfg, "simcode7_v85_model_path",
                DEFAULT_SIMCODE7_V85_MODEL_PATH),
            simcode7_v91_model_path=getattr(
                self.cfg, "simcode7_v91_model_path",
                DEFAULT_SIMCODE7_V91_MODEL_PATH),
            simcode7_v97_model_path=getattr(
                self.cfg, "simcode7_v97_model_path",
                DEFAULT_SIMCODE7_V97_MODEL_PATH),
            simcode7_policy_xml_path=getattr(
                self.cfg, "simcode7_policy_xml_path",
                DEFAULT_SIMCODE7_POLICY_XML),
            simcode7_sim_xml_path=getattr(
                self.cfg, "simcode7_sim_xml_path", DEFAULT_SIMCODE7_POLICY_XML),
            simcode8_policy_xml_path=getattr(
                self.cfg, "simcode8_policy_xml_path",
                DEFAULT_SIMCODE8_POLICY_XML),
            simcode8_sim_xml_path=getattr(
                self.cfg, "simcode8_sim_xml_path",
                DEFAULT_SIMCODE8_POLICY_XML),
            gpu1_qacc_ft_model_path=getattr(
                self.cfg, "gpu1_qacc_ft_model_path",
                DEFAULT_GPU1_QACC_FT_MODEL_PATH),
            gpu1_qacc_ft_policy_xml_path=getattr(
                self.cfg, "gpu1_qacc_ft_policy_xml_path",
                DEFAULT_SIMCODE8_POLICY_XML),
            gpu1_qacc_ft_sim_xml_path=getattr(
                self.cfg, "gpu1_qacc_ft_sim_xml_path",
                DEFAULT_SIMCODE8_POLICY_XML),
            backend=backend,
            frame_rate_hz=self.cfg.sim_frame_rate_hz,
            render_width=self.cfg.sim_render_width,
            render_height=self.cfg.sim_render_height,
            enable_video_frames=self.cfg.sim_enable_video_frames,
            use_mujoco_renderer=self.cfg.sim_use_mujoco_renderer,
            enable_compensation=self.cfg.enable_compensation,
            compensation_mode=self.cfg.compensation_mode,
            comp_delay_ms=self.cfg.comp_delay_ms,
            comp_actuator_tau_s=self.cfg.comp_actuator_tau_s,
            comp_actuator_gain=self.cfg.comp_actuator_gain,
            comp_mpc_beta=self.cfg.comp_mpc_beta,
            comp_mpc_delay_scale=self.cfg.comp_mpc_delay_scale,
            comp_mpc_tau_scale=self.cfg.comp_mpc_tau_scale,
            comp_mpc_horizon_steps=self.cfg.comp_mpc_horizon_steps,
            comp_mpc_tracking_weight=self.cfg.comp_mpc_tracking_weight,
            comp_mpc_nominal_weight=self.cfg.comp_mpc_nominal_weight,
            comp_mpc_delta_weight=self.cfg.comp_mpc_delta_weight,
            comp_mpc_max_delta_rad=self.cfg.comp_mpc_max_delta_rad,
            rl_use_valid_ball_obs_age=self.cfg.rl_use_valid_ball_obs_age,
        )
        self.sim_base_config = sim_cfg
        sim_cfg = sim_mirror_config_for_policy_profile(
            replace(
                sim_cfg,
                policy_model=(
                    getattr(self, "active_policy_model", "")
                    or GPU0_RMP_MODEL_V85),
            ),
            self.active_policy_profile,
        )
        if bool(self.cfg.sim_subprocess):
            try:
                # Keep the unresolved legacy-primary + simcode2-alternate
                # bundle in the long-lived subprocess.  Passing ``sim_cfg``
                # here loses the legacy paths when the process starts in the
                # simcode2 profile, so a later switch back to legacy would
                # retain the simcode2 checkpoint/XML pair.
                self.sim_mirror = SimMirrorSubprocess(self.sim_base_config)
                try:
                    startup_timeout_s = float(os.environ.get(
                        "SIM_STARTUP_TIMEOUT_S",
                        os.environ.get(
                            "PROBE_CONTROL_SUBPROCESS_STARTUP_TIMEOUT_S",
                            "300.0"),
                    ))
                except (TypeError, ValueError):
                    startup_timeout_s = 300.0
                self.latest_sim_snapshot = self.sim_mirror.wait_until_ready(
                    max(10.0, startup_timeout_s))
                return
            except Exception as exc:  # noqa: BLE001 - keep real control alive.
                failed_mirror = self.sim_mirror
                self.sim_mirror = None
                if failed_mirror is not None:
                    try:
                        failed_mirror.close()
                    except Exception:
                        pass
                self.sim_mirror_error = str(exc)
                self.latest_sim_snapshot = self._sim_unavailable_payload(str(exc))
                return
        last_error: Exception | None = None
        backends = (
            ("mjx", "mujoco") if backend == "auto"
            else (backend,)
        )
        for candidate in backends:
            try:
                mirror_cls = (
                    RealBallMjxJaxSimMirror
                    if candidate == "mjx" else RealBallSimMirror
                )
                self.sim_mirror = mirror_cls(sim_cfg, logger=self.controller._logger)
                self.latest_sim_snapshot = self.sim_mirror.snapshot()
                return
            except Exception as exc:  # noqa: BLE001 - keep real control alive.
                last_error = exc
                if backend != "auto":
                    break
        try:
            raise last_error or RuntimeError("simulation mirror initialization failed")
        except Exception as exc:  # noqa: BLE001 - keep real control alive.
            self.sim_mirror = None
            self.sim_mirror_error = str(exc)
            self.latest_sim_snapshot = self._sim_unavailable_payload(str(exc))

    def _sim_unavailable_payload(self, reason: str | None = None) -> dict[str, Any]:
        return {
            "enabled": bool(self.cfg.enable_sim_mirror),
            "available": False,
            "active": False,
            "backend": str(getattr(self.cfg, "sim_backend", "mujoco")),
            "policyProfile": str(getattr(
                self, "active_policy_profile", self.cfg.policy_profile)),
            "policyModel": str(getattr(
                self, "active_policy_model", GPU0_RMP_MODEL_V85)),
            "policyGeneration": int(getattr(self, "policy_generation", 0)),
            "error": reason or self.sim_mirror_error,
        }

    def _step_sim_mirror(
        self,
        ball_pos: np.ndarray,
        ball_vel: np.ndarray,
        *,
        ball_valid: bool,
        age_s: float,
        options: RuntimeOptions,
        source_seq: int,
        source_time_s: float,
        ball_observation_seq: int,
        camera_stamp_s: float | None,
        control_mode: str,
        policy_active: bool,
    ) -> dict[str, Any]:
        if not self.cfg.enable_sim_mirror:
            self.latest_sim_snapshot = self._sim_unavailable_payload("disabled")
            return dict(self.latest_sim_snapshot)
        if not bool(options.enable_sim_mirror):
            self.sim_needs_policy_reset = True
            self.policy_needs_reentry_reset = True
            payload = self._sim_unavailable_payload("runtime disabled")
            payload["available"] = bool(self.sim_mirror is not None)
            self.latest_sim_snapshot = payload
            return payload
        # The web UI can tune either the real plant or the simulation plant.
        # When real is selected, keep the mirror on the launch/checkpoint
        # compensation contract instead of leaking live hardware tuning into
        # the simulation reference.
        options = self._sim_compensation_options(options)
        if self.sim_mirror is None:
            if self.sim_mirror_error is None:
                self._init_sim_mirror()
            if self.sim_mirror is None:
                self.latest_sim_snapshot = self._sim_unavailable_payload(
                    self.sim_mirror_error or "initialization failed")
                return dict(self.latest_sim_snapshot)
        if not bool(policy_active):
            self._mark_policy_paused()
            try:
                if hasattr(self.sim_mirror, "drain_completed_samples"):
                    self.recorder.record_sim_control_samples(
                        self.sim_mirror.drain_completed_samples())
                payload = self.sim_mirror.snapshot()
            except Exception:
                payload = dict(
                    self.latest_sim_snapshot
                    or self._sim_unavailable_payload())
            payload["active"] = False
            payload["holdReason"] = f"real control mode: {control_mode}"
            self.latest_sim_snapshot = payload
            return payload
        try:
            if (not isinstance(self.sim_mirror, SimMirrorSubprocess)
                    and (normalize_observation_profile(getattr(
                        getattr(self.sim_mirror, "cfg", None),
                        "policy_profile",
                        OBSERVATION_PROFILE_LEGACY_BUG_COMPAT,
                    )) != self.active_policy_profile
                    or str(getattr(
                        getattr(self.sim_mirror, "cfg", None),
                        "policy_model", GPU0_RMP_MODEL_V85,
                    )) != str(
                        self.active_policy_model or GPU0_RMP_MODEL_V85))):
                old_mirror = self.sim_mirror
                try:
                    old_mirror.close()
                except Exception:
                    pass
                active_cfg = sim_mirror_config_for_policy_profile(
                    replace(
                        self.sim_base_config,
                        policy_model=(
                            self.active_policy_model or GPU0_RMP_MODEL_V85),
                    ),
                    self.active_policy_profile,
                )
                self.sim_mirror = _make_sim_mirror(active_cfg)
                self.sim_needs_policy_reset = True
            if self.sim_needs_policy_reset:
                reset_q = (
                    self.policy_reentry_reset_q.copy()
                    if self.policy_reentry_reset_q is not None
                    else np.asarray(
                        self._safety_limiter_reset_reference(),
                        dtype=np.float32,
                    )
                )
                try:
                    if isinstance(self.sim_mirror, SimMirrorSubprocess):
                        self.sim_mirror.reset(
                            arm_q=reset_q,
                            ball_pos=ball_pos,
                            ball_vel=ball_vel,
                            ball_valid=bool(ball_valid),
                            ball_obs_age_s=float(max(0.0, age_s)),
                            policy_profile=self.active_policy_profile,
                            policy_model=self.active_policy_model,
                            policy_generation=self.policy_generation,
                        )
                    else:
                        self.sim_mirror.reset(
                            arm_q=reset_q,
                            ball_pos=ball_pos,
                            ball_vel=ball_vel,
                            ball_valid=bool(ball_valid),
                            ball_obs_age_s=float(max(0.0, age_s)),
                        )
                except TypeError:
                    self.sim_mirror.reset(reset_q)
                self.sim_needs_policy_reset = False
                self.policy_reentry_reset_q = None
            if isinstance(self.sim_mirror, SimMirrorSubprocess):
                snap = self.sim_mirror.step(
                    ball_pos,
                    ball_vel,
                    ball_valid=bool(ball_valid),
                    ball_obs_age_s=float(max(0.0, age_s)),
                    options=options,
                    source_seq=int(source_seq),
                    source_time_s=float(source_time_s),
                    ball_observation_seq=int(ball_observation_seq),
                    camera_stamp_s=camera_stamp_s,
                    control_mode=str(control_mode),
                    policy_profile=self.active_policy_profile,
                    policy_model=self.active_policy_model,
                    policy_generation=self.policy_generation,
                    confirmed_hit_count=int(getattr(
                        self, "policy_confirmed_hit_count", 0)),
                    direct_ball_input={
                        key: value.tolist() if isinstance(value, np.ndarray) else value
                        for key, value in dict(getattr(
                            self, "fplc_direct_ball_input", {}) or {}).items()},
                )
                self.recorder.record_sim_control_samples(
                    self.sim_mirror.drain_completed_samples())
            else:
                submitted_wall_s = time.time()
                direct_step_kwargs = {}
                if self.active_policy_profile in (OBSERVATION_PROFILE_GPU1_QACC_FT_V153, *FPLC_PROFILES):
                    direct_step_kwargs["confirmed_hit_count"] = int(getattr(
                        self, "policy_confirmed_hit_count", 0))
                if self.active_policy_profile in FPLC_PROFILES:
                    direct_step_kwargs["direct_ball_input"] = dict(getattr(
                        self, "fplc_direct_ball_input", {}) or {})
                snap = self.sim_mirror.step(
                    ball_pos,
                    ball_vel,
                    ball_valid=bool(ball_valid),
                    ball_obs_age_s=float(max(0.0, age_s)),
                    options=options,
                    **direct_step_kwargs,
                )
                snap["sync"] = {
                    "ready": True,
                    "episode": 0,
                    "sourceSeq": int(source_seq),
                    "sourceTimeS": float(source_time_s),
                    "submittedWallTimeS": float(submitted_wall_s),
                    "completedWallTimeS": float(time.time()),
                    "streamSeq": int(source_seq),
                    "ballObservationSeq": int(ball_observation_seq),
                    "cameraStampS": camera_stamp_s,
                    "inputBall": _float32_vector(ball_pos),
                    "inputVelocity": _float32_vector(ball_vel),
                    "inputValid": bool(ball_valid),
                    "inputAgeS": float(max(0.0, age_s)),
                    "controlMode": str(control_mode),
                    "policyProfile": str(self.active_policy_profile),
                    "policyModel": str(self.active_policy_model),
                    "policyGeneration": int(self.policy_generation),
                    "runtimeConfigMatch": _sim_runtime_config_matches(
                        self.sim_mirror.cfg,
                        options,
                        str(snap.get("backend", "")),
                    ),
                    "streamContinuous": True,
                    "alignmentValid": _sim_runtime_config_matches(
                        self.sim_mirror.cfg,
                        options,
                        str(snap.get("backend", "")),
                    ),
                    "lagTicks": 0,
                    "lagS": 0.0,
                }
                self.recorder.record_sim_control_samples([snap])
            if snap.get("available") is not False:
                snap["active"] = True
            self.latest_sim_snapshot = snap
            return snap
        except Exception as exc:  # noqa: BLE001 - keep real control alive.
            self.sim_mirror_error = str(exc)
            self.latest_sim_snapshot = self._sim_unavailable_payload(str(exc))
            return dict(self.latest_sim_snapshot)

    def _startup_compensation_options(
        self,
        options: RuntimeOptions,
    ) -> RuntimeOptions:
        """Return options with the sim compensation launch contract restored."""

        return replace(
            options,
            compensation_mode=self.cfg.compensation_mode,
            comp_delay_ms=self.cfg.comp_delay_ms,
            comp_actuator_tau_s=self.cfg.comp_actuator_tau_s,
            comp_actuator_gain=self.cfg.comp_actuator_gain,
            comp_mpc_beta=self.cfg.comp_mpc_beta,
            comp_mpc_delay_scale=self.cfg.comp_mpc_delay_scale,
            comp_mpc_tau_scale=self.cfg.comp_mpc_tau_scale,
            comp_mpc_horizon_steps=self.cfg.comp_mpc_horizon_steps,
            comp_mpc_tracking_weight=self.cfg.comp_mpc_tracking_weight,
            comp_mpc_nominal_weight=self.cfg.comp_mpc_nominal_weight,
            comp_mpc_delta_weight=self.cfg.comp_mpc_delta_weight,
            comp_mpc_max_delta_rad=self.cfg.comp_mpc_max_delta_rad,
        )

    def _real_startup_compensation_options(
        self,
        options: RuntimeOptions,
    ) -> RuntimeOptions:
        """Return the launch defaults for real-only compensation tuning."""

        restored = self._startup_compensation_options(options)
        def real_value(name: str, fallback: Any) -> Any:
            value = getattr(self.cfg, name, None)
            return fallback if value is None else value

        return replace(
            restored,
            comp_delay_ms=float(real_value(
                "real_comp_delay_ms", restored.comp_delay_ms)),
            comp_actuator_tau_s=float(real_value(
                "real_comp_actuator_tau_s", restored.comp_actuator_tau_s)),
            comp_actuator_gain=float(real_value(
                "real_comp_actuator_gain", restored.comp_actuator_gain)),
            comp_mpc_beta=float(real_value(
                "real_comp_mpc_beta", restored.comp_mpc_beta)),
            comp_mpc_delay_scale=float(real_value(
                "real_comp_mpc_delay_scale", restored.comp_mpc_delay_scale)),
            comp_mpc_tau_scale=float(real_value(
                "real_comp_mpc_tau_scale", restored.comp_mpc_tau_scale)),
            comp_mpc_horizon_steps=int(real_value(
                "real_comp_mpc_horizon_steps",
                restored.comp_mpc_horizon_steps)),
            comp_mpc_tracking_weight=float(real_value(
                "real_comp_mpc_tracking_weight",
                restored.comp_mpc_tracking_weight)),
            comp_mpc_nominal_weight=float(real_value(
                "real_comp_mpc_nominal_weight",
                restored.comp_mpc_nominal_weight)),
            comp_mpc_delta_weight=float(real_value(
                "real_comp_mpc_delta_weight",
                restored.comp_mpc_delta_weight)),
            comp_mpc_max_delta_rad=float(real_value(
                "real_comp_mpc_max_delta_rad",
                restored.comp_mpc_max_delta_rad)),
        )

    def _real_compensation_options(
        self,
        options: RuntimeOptions,
    ) -> RuntimeOptions:
        target = _compensation_parameter_target(
            getattr(options, "compensation_parameter_target", "both"))
        if target == COMPENSATION_PARAMETER_TARGET_SIM:
            return self._real_startup_compensation_options(options)
        return options

    def _sim_compensation_options(
        self,
        options: RuntimeOptions,
    ) -> RuntimeOptions:
        target = _compensation_parameter_target(
            getattr(options, "compensation_parameter_target", "both"))
        if target == COMPENSATION_PARAMETER_TARGET_REAL:
            return self._startup_compensation_options(options)
        return options

    def _compensator_key(self, options: RuntimeOptions | None = None) -> tuple[Any, ...]:
        mode = (
            self.cfg.compensation_mode if options is None
            else options.compensation_mode)
        delay_ms = (
            self.cfg.comp_delay_ms if options is None else options.comp_delay_ms)
        tau_s = (
            self.cfg.comp_actuator_tau_s
            if options is None else options.comp_actuator_tau_s)
        gain = (
            self.cfg.comp_actuator_gain
            if options is None else options.comp_actuator_gain)
        beta = self.cfg.comp_mpc_beta if options is None else options.comp_mpc_beta
        delay_scale = (
            self.cfg.comp_mpc_delay_scale
            if options is None else options.comp_mpc_delay_scale)
        tau_scale = (
            self.cfg.comp_mpc_tau_scale
            if options is None else options.comp_mpc_tau_scale)
        horizon = (
            self.cfg.comp_mpc_horizon_steps
            if options is None else options.comp_mpc_horizon_steps)
        tracking = (
            self.cfg.comp_mpc_tracking_weight
            if options is None else options.comp_mpc_tracking_weight)
        nominal = (
            self.cfg.comp_mpc_nominal_weight
            if options is None else options.comp_mpc_nominal_weight)
        delta = (
            self.cfg.comp_mpc_delta_weight
            if options is None else options.comp_mpc_delta_weight)
        max_delta = (
            self.cfg.comp_mpc_max_delta_rad
            if options is None else options.comp_mpc_max_delta_rad)
        return (
            str(mode).strip().lower().replace("-", "_"),
            round(float(delay_ms), 6),
            round(float(tau_s), 6),
            round(float(gain), 6),
            int(self.cfg.comp_buffer_extra_steps),
            bool(self.cfg.comp_delay_conditioning),
            round(float(beta), 6),
            round(float(delay_scale), 6),
            round(float(tau_scale), 6),
            int(horizon),
            round(float(tracking), 6),
            round(float(nominal), 6),
            round(float(delta), 6),
            round(float(max_delta), 6),
        )

    def _init_compensator(self, options: RuntimeOptions | None = None) -> None:
        self.compensator = None
        self.compensation_error = None
        self.compensator_key = None
        if not self.cfg.enable_compensation:
            return
        if not _COMPENSATION_AVAILABLE or CommandCompensator is None:
            self.compensation_error = (
                "CommandCompensator unavailable"
                if _COMPENSATION_IMPORT_ERROR is None
                else f"CommandCompensator unavailable: {_COMPENSATION_IMPORT_ERROR}"
            )
            return
        try:
            self.compensator = CommandCompensator(
                n_joints=len(RIGHT_ARM_JOINTS),
                dt=float(self.cfg.control_dt),
                mode=str(
                    self.cfg.compensation_mode if options is None
                    else options.compensation_mode),
                delay_ms=float(
                    self.cfg.comp_delay_ms if options is None
                    else options.comp_delay_ms),
                actuator_tau_s=float(
                    self.cfg.comp_actuator_tau_s if options is None
                    else options.comp_actuator_tau_s),
                actuator_gain=float(
                    self.cfg.comp_actuator_gain if options is None
                    else options.comp_actuator_gain),
                command_buffer_extra_steps=int(
                    self.cfg.comp_buffer_extra_steps),
                delay_conditioning=bool(self.cfg.comp_delay_conditioning),
                mpc_beta=float(
                    self.cfg.comp_mpc_beta if options is None
                    else options.comp_mpc_beta),
                mpc_delay_scale=float(
                    self.cfg.comp_mpc_delay_scale if options is None
                    else options.comp_mpc_delay_scale),
                mpc_tau_scale=float(
                    self.cfg.comp_mpc_tau_scale if options is None
                    else options.comp_mpc_tau_scale),
                mpc_horizon_steps=int(
                    self.cfg.comp_mpc_horizon_steps if options is None
                    else options.comp_mpc_horizon_steps),
                mpc_tracking_weight=float(
                    self.cfg.comp_mpc_tracking_weight if options is None
                    else options.comp_mpc_tracking_weight),
                mpc_nominal_weight=float(
                    self.cfg.comp_mpc_nominal_weight if options is None
                    else options.comp_mpc_nominal_weight),
                mpc_delta_weight=float(
                    self.cfg.comp_mpc_delta_weight if options is None
                    else options.comp_mpc_delta_weight),
                mpc_max_delta_rad=float(
                    self.cfg.comp_mpc_max_delta_rad if options is None
                    else options.comp_mpc_max_delta_rad),
                q_low=self.controller.arm_q_low,
                q_high=self.controller.arm_q_high,
            )
            self.compensator_key = self._compensator_key(options)
        except Exception as exc:  # noqa: BLE001 - keep probe usable.
            self.compensator = None
            self.compensation_error = str(exc)
            self.compensator_key = None

    def _ensure_compensator(self, options: RuntimeOptions) -> None:
        if not bool(options.enable_compensation):
            return
        key = self._compensator_key(options)
        if self.compensator is not None and self.compensator_key == key:
            return
        self._init_compensator(options)
        self.compensation_was_enabled = False

    def _reset_compensator_to_current_arm(
        self,
        current_q_override: np.ndarray | None = None,
    ) -> None:
        if self.compensator is None:
            return
        try:
            current_q = self._right_arm_joint_vector_or_none(current_q_override)
            if current_q is None and self.ros_bridge is not None:
                current_q, _ = self.ros_bridge.get_joint_feedback()
                current_q = self._right_arm_joint_vector_or_none(current_q)
            if current_q is None:
                current_q = self._right_arm_joint_vector_or_none(
                    self.controller.current_arm_cmd_q())
            if current_q is not None:
                self.compensator.reset(current_q.astype(np.float32))
        except Exception as exc:  # noqa: BLE001 - compensation is optional.
            self.compensation_error = f"reset failed: {exc}"

    def _compensation_payload(self, options: RuntimeOptions | None = None) -> dict[str, Any]:
        requested = (
            self.cfg.enable_compensation
            if options is None else bool(options.enable_compensation)
        )
        active = bool(
            requested and self.compensator is not None
            and self.compensation_was_enabled)
        mode = (
            self.cfg.compensation_mode if options is None
            else options.compensation_mode)
        delay_ms = (
            self.cfg.comp_delay_ms if options is None else options.comp_delay_ms)
        tau_s = (
            self.cfg.comp_actuator_tau_s
            if options is None else options.comp_actuator_tau_s)
        gain = (
            self.cfg.comp_actuator_gain
            if options is None else options.comp_actuator_gain)
        payload = {
            "enabled": bool(requested),
            "available": bool(self.compensator is not None),
            "active": active,
            "mode": str(mode),
            "delayMs": round(float(delay_ms), 3),
            "tauS": round(float(tau_s), 6),
            "gain": round(float(gain), 6),
            "error": self.compensation_error,
            "feedbackSource": str(getattr(
                self, "last_compensation_feedback_source", "not_applied")),
            "feedbackPosition": (
                None
                if self._right_arm_joint_vector_or_none(getattr(
                    self, "last_compensation_feedback_q", None)) is None
                else _rounded_vector(self.last_compensation_feedback_q)),
        }
        if options is not None:
            payload.update({
                "mpcBeta": round(float(options.comp_mpc_beta), 6),
                "mpcDelayScale": round(
                    float(options.comp_mpc_delay_scale), 6),
                "mpcTauScale": round(float(options.comp_mpc_tau_scale), 6),
                "mpcHorizonSteps": int(options.comp_mpc_horizon_steps),
                "mpcTrackingWeight": round(
                    float(options.comp_mpc_tracking_weight), 6),
                "mpcNominalWeight": round(
                    float(options.comp_mpc_nominal_weight), 6),
                "mpcDeltaWeight": round(
                    float(options.comp_mpc_delta_weight), 6),
                "mpcMaxDeltaRad": round(
                    float(options.comp_mpc_max_delta_rad), 6),
            })
        if self.compensator is not None:
            payload["bufferLen"] = int(
                getattr(self.compensator, "command_buffer_len", 0))
        return payload

    def _apply_actuator_compensation(
        self,
        q: np.ndarray,
        options: RuntimeOptions,
        *,
        feedback_q_override: np.ndarray | None = None,
    ) -> np.ndarray:
        raw = np.asarray(q, dtype=np.float64).reshape(-1)
        nominal_q = raw.copy()
        if not options.enable_compensation:
            self.compensation_was_enabled = False
            self.last_compensation_feedback_source = "disabled"
            self.last_compensation_feedback_q = None
            return raw
        self._ensure_compensator(options)
        if (self.compensator is None
                or not getattr(self.compensator, "enabled", True)):
            self.compensation_was_enabled = False
            self.last_compensation_feedback_source = "unavailable"
            self.last_compensation_feedback_q = None
            return raw
        override_q = self._right_arm_joint_vector_or_none(feedback_q_override)
        if not self.compensation_was_enabled:
            # On a policy tick the compensator must be seeded from the exact
            # joint sample consumed by the actor. Reading the bridge again here
            # can observe a callback that arrived during inference and mix two
            # physical states in one logical control transition.
            self._reset_compensator_to_current_arm(override_q)
            self.compensation_was_enabled = True
        try:
            cmd_state = self.controller.latest_command_state()
            nominal_qvel = np.asarray(
                cmd_state.get("velocity", np.zeros_like(raw)),
                dtype=np.float32,
            ).reshape(-1)
            nominal_qdd = np.asarray(
                cmd_state.get("acceleration", np.zeros_like(raw)),
                dtype=np.float32,
            ).reshape(-1)
            simcode3_feedback = (
                normalize_observation_profile(getattr(
                    options,
                    "policy_profile",
                    OBSERVATION_PROFILE_LEGACY_BUG_COMPAT,
                ))
                == OBSERVATION_PROFILE_SIMCODE3_ACTUATOR67)
            current_applied_q = getattr(
                self.compensator, "current_applied_q", None)
            if simcode3_feedback and callable(current_applied_q):
                applied_q = np.asarray(
                    current_applied_q(), dtype=np.float32).reshape(-1)
                feedback_source = "modeled_actuator_applied"
            else:
                actual_q = override_q
                feedback_source = (
                    "policy_atomic_snapshot"
                    if actual_q is not None else "bridge_latest")
                if actual_q is None and self.ros_bridge is not None:
                    bridge_q, _ = self.ros_bridge.get_joint_feedback()
                    actual_q = self._right_arm_joint_vector_or_none(bridge_q)
                if actual_q is None:
                    feedback_source = "nominal_command_fallback"
                    applied_q = raw.astype(np.float32)
                else:
                    applied_q = np.asarray(
                        actual_q, dtype=np.float32).reshape(-1)
            self.last_compensation_feedback_source = feedback_source
            self.last_compensation_feedback_q = applied_q.copy()
            if (nominal_qvel.shape[0] != raw.shape[0]
                    or nominal_qdd.shape[0] != raw.shape[0]
                    or applied_q.shape[0] != raw.shape[0]):
                return raw
            compensated = self.compensator.step(
                q_cmd=raw.astype(np.float32),
                qdot_cmd=nominal_qvel,
                qdd_cmd=nominal_qdd,
                applied_q=applied_q,
            )
            self.compensation_error = None
            return np.asarray(compensated, dtype=np.float64).reshape(-1)
        except Exception as exc:  # noqa: BLE001 - fall back to nominal command.
            self.compensation_error = str(exc)
            return raw

    def _parking_workspace_violation_score(self, q: np.ndarray) -> float:
        q_vec = self._right_arm_joint_vector_or_none(q)
        if q_vec is None:
            return float("inf")
        try:
            racket_pos, ee_quat_xyzw, fk_ok = (
                self.controller._compute_racket_pose_quat_base(q_vec))
        except Exception:
            return float("inf")
        if not fk_ok:
            return float("inf")

        racket = np.asarray(racket_pos, dtype=np.float64).reshape(-1)
        if racket.shape[0] != 3 or not np.all(np.isfinite(racket)):
            return float("inf")
        anchor = np.asarray(self.anchor(), dtype=np.float64).reshape(3)
        score = 0.0

        def add_range_violation(
            value: float,
            lo: float,
            hi: float,
            scale: float,
        ) -> None:
            nonlocal score
            if value < lo:
                score += ((lo - value) / max(scale, 1e-6)) ** 2
            elif value > hi:
                score += ((value - hi) / max(scale, 1e-6)) ** 2

        dist = float(np.linalg.norm(racket - anchor))
        limit = max(1e-6, float(self.cfg.done_racket_anchor_distance_m))
        if dist > limit:
            score += ((dist - limit) / limit) ** 2

        dz = float(racket[2] - anchor[2])
        add_range_violation(
            dz,
            float(self.cfg.done_racket_z_low_offset_m),
            float(self.cfg.done_racket_z_high_offset_m),
            max(1e-6, abs(float(self.cfg.done_racket_z_high_offset_m)
                          - float(self.cfg.done_racket_z_low_offset_m))),
        )

        for value, limits in (
            (float(racket[0]), self.cfg.ee_x_limits_m),
            (float(racket[1]), self.cfg.ee_y_limits_m),
            (float(racket[2]), self.cfg.ee_z_limits_m),
        ):
            if limits is None:
                continue
            lo, hi = [float(v) for v in limits]
            add_range_violation(value, lo, hi, max(1e-6, abs(hi - lo)))

        abc = _quat_to_euler_xyz_rad(ee_quat_xyzw)
        if abc is not None:
            if (self.cfg.ee_b_limits_rad is not None
                    and not _angle_in_limits_rad(
                        float(abc[1]), self.cfg.ee_b_limits_rad)):
                score += 1.0
            if (self.cfg.ee_b_min_rad is not None
                    and not _angle_above_min_rad(
                        float(abc[1]), self.cfg.ee_b_min_rad)):
                score += 1.0
            if (self.cfg.ee_b_max_rad is not None
                    and not _angle_below_max_rad(
                        float(abc[1]), self.cfg.ee_b_max_rad)):
                score += 1.0
            if (self.cfg.ee_c_limits_rad is not None
                    and not _angle_in_limits_rad(
                        float(abc[2]), self.cfg.ee_c_limits_rad)):
                score += 1.0
            if (self.cfg.ee_c_min_rad is not None
                    and not _angle_above_min_rad(
                        float(abc[2]), self.cfg.ee_c_min_rad)):
                score += 1.0
            if (self.cfg.ee_c_max_rad is not None
                    and not _angle_below_max_rad(
                        float(abc[2]), self.cfg.ee_c_max_rad)):
                score += 1.0
        elif (self.cfg.ee_b_limits_rad is not None
              or self.cfg.ee_b_min_rad is not None
              or self.cfg.ee_b_max_rad is not None
              or self.cfg.ee_c_limits_rad is not None
              or self.cfg.ee_c_min_rad is not None
              or self.cfg.ee_c_max_rad is not None):
            score += 1.0

        if (self.cfg.ee_orientation_reference_xyzw is not None
                and self.cfg.ee_max_orientation_error_deg > 0.0):
            angle_error_deg = _quat_angle_error_deg(
                ee_quat_xyzw, self.cfg.ee_orientation_reference_xyzw)
            if angle_error_deg is None:
                score += 1.0
            elif angle_error_deg > self.cfg.ee_max_orientation_error_deg:
                span = max(1e-6, float(self.cfg.ee_max_orientation_error_deg))
                score += ((angle_error_deg
                           - self.cfg.ee_max_orientation_error_deg)
                          / span) ** 2
        return float(score)

    def _predictive_workspace_translation_direction(
        self,
    ) -> np.ndarray | None:
        """Return the Cartesian direction of the current predicted violation."""
        monitor = getattr(self, "done_monitor", None)
        prediction = getattr(monitor, "last_prediction", None)
        if not isinstance(prediction, dict):
            return None
        condition = str(prediction.get("condition", ""))
        try:
            value = np.asarray(
                prediction.get("value"), dtype=np.float64).reshape(-1)
        except (TypeError, ValueError):
            return None
        if value.shape[0] < 3 or not np.all(np.isfinite(value[:3])):
            return None
        predicted_pos = value[:3]

        direction = np.zeros(3, dtype=np.float64)
        axis_conditions = {
            "ee_predicted_x_out_of_workspace": (0, self.cfg.ee_x_limits_m),
            "ee_predicted_y_out_of_workspace": (1, self.cfg.ee_y_limits_m),
            "ee_predicted_z_out_of_workspace": (2, self.cfg.ee_z_limits_m),
        }
        if condition in axis_conditions:
            axis, limits = axis_conditions[condition]
            if limits is None:
                return None
            lo, hi = [float(v) for v in limits]
            direction[axis] = (
                1.0
                if abs(float(predicted_pos[axis]) - hi)
                <= abs(float(predicted_pos[axis]) - lo)
                else -1.0)
            return direction
        if condition == "racket_predicted_too_high":
            direction[2] = 1.0
            return direction
        if condition == "racket_predicted_too_low":
            direction[2] = -1.0
            return direction
        if condition == "racket_predicted_too_far_from_anchor":
            radial = predicted_pos - np.asarray(
                self.anchor(), dtype=np.float64).reshape(3)
            norm = float(np.linalg.norm(radial))
            if norm > 1e-9:
                return radial / norm
        return None

    def _predictive_workspace_constraint(self) -> str:
        """Map the latest positional prediction to a signed-distance term."""
        prediction = getattr(
            getattr(self, "done_monitor", None), "last_prediction", None)
        if not isinstance(prediction, dict):
            return ""
        condition = str(prediction.get("condition", ""))
        if condition == "racket_predicted_too_high":
            return "racket_z_high"
        if condition == "racket_predicted_too_low":
            return "racket_z_low"
        if condition == "racket_predicted_too_far_from_anchor":
            return "racket_anchor"
        axes = {
            "ee_predicted_x_out_of_workspace": (
                0, self.cfg.ee_x_limits_m, "ee_x"),
            "ee_predicted_y_out_of_workspace": (
                1, self.cfg.ee_y_limits_m, "ee_y"),
            "ee_predicted_z_out_of_workspace": (
                2, self.cfg.ee_z_limits_m, "ee_z"),
        }
        axis_info = axes.get(condition)
        if axis_info is None:
            return ""
        axis, limits, label = axis_info
        if limits is None:
            return ""
        try:
            predicted = np.asarray(
                prediction.get("value"), dtype=np.float64).reshape(-1)
        except (TypeError, ValueError):
            return ""
        if predicted.shape[0] < 3 or not np.all(np.isfinite(predicted[:3])):
            return ""
        lo, hi = [float(value) for value in limits]
        value = float(predicted[axis])
        side = "high" if abs(value - hi) <= abs(value - lo) else "low"
        return f"{label}_{side}"

    def _remove_predictive_outward_components(
        self,
        prev_cmd: np.ndarray,
        desired: np.ndarray,
    ) -> tuple[np.ndarray, list[int]]:
        """Brake predicted-outward motion without freezing the whole arm."""
        outward = self._predictive_workspace_translation_direction()
        if outward is None:
            # Orientation-only prediction currently has no reliable mapping
            # from cartesian feedback psi to the command FK. Keep the
            # conservative whole-command brake for that uncommon case.
            return prev_cmd.copy(), list(range(len(RIGHT_ARM_JOINTS)))
        try:
            prev_pos, _quat, prev_ok = (
                self.controller._compute_racket_pose_quat_base(prev_cmd))
        except Exception:
            return prev_cmd.copy(), list(range(len(RIGHT_ARM_JOINTS)))
        prev_pos = np.asarray(prev_pos, dtype=np.float64).reshape(-1)
        if (not prev_ok or prev_pos.shape[0] != 3
                or not np.all(np.isfinite(prev_pos))):
            return prev_cmd.copy(), list(range(len(RIGHT_ARM_JOINTS)))

        filtered = desired.copy()
        blocked: list[int] = []
        delta = desired - prev_cmd
        # Probe only the local joint direction; compensation can make the raw
        # target comparatively far away, while the 200 Hz command step remains
        # local after the dynamic limiter.
        for idx, joint_delta in enumerate(delta):
            if abs(float(joint_delta)) <= 1e-15:
                continue
            trial = prev_cmd.copy()
            trial[idx] += math.copysign(
                min(abs(float(joint_delta)), 0.01), float(joint_delta))
            try:
                trial_pos, _quat, trial_ok = (
                    self.controller._compute_racket_pose_quat_base(trial))
            except Exception:
                trial_ok = False
                trial_pos = None
            if not trial_ok or trial_pos is None:
                filtered[idx] = prev_cmd[idx]
                blocked.append(idx)
                continue
            trial_pos = np.asarray(trial_pos, dtype=np.float64).reshape(-1)
            if (trial_pos.shape[0] != 3
                    or not np.all(np.isfinite(trial_pos))):
                filtered[idx] = prev_cmd[idx]
                blocked.append(idx)
                continue
            outward_step = float(np.dot(trial_pos - prev_pos, outward))
            if outward_step > 1e-9:
                filtered[idx] = prev_cmd[idx]
                blocked.append(idx)
        return filtered, blocked

    def _workspace_soft_boundary_terms(
        self,
        position_m: np.ndarray,
    ) -> list[tuple[str, np.ndarray, float]]:
        """Return (name, outward normal, signed inward distance) constraints."""
        pos = np.asarray(position_m, dtype=np.float64).reshape(3)
        anchor = np.asarray(self.anchor(), dtype=np.float64).reshape(3)
        terms: list[tuple[str, np.ndarray, float]] = []

        radial = pos - anchor
        radial_norm = float(np.linalg.norm(radial))
        radial_limit = max(
            1e-6, float(self.cfg.done_racket_anchor_distance_m))
        if radial_norm > 1e-9:
            terms.append((
                "racket_anchor",
                radial / radial_norm,
                radial_limit - radial_norm,
            ))

        dz = float(pos[2] - anchor[2])
        z_axis = np.array([0.0, 0.0, 1.0], dtype=np.float64)
        terms.extend((
            (
                "racket_z_high",
                z_axis.copy(),
                float(self.cfg.done_racket_z_high_offset_m) - dz,
            ),
            (
                "racket_z_low",
                -z_axis.copy(),
                dz - float(self.cfg.done_racket_z_low_offset_m),
            ),
        ))

        for axis, limits, label in (
            (0, self.cfg.ee_x_limits_m, "ee_x"),
            (1, self.cfg.ee_y_limits_m, "ee_y"),
            (2, self.cfg.ee_z_limits_m, "ee_z"),
        ):
            if limits is None:
                continue
            lo, hi = [float(value) for value in limits]
            normal = np.zeros(3, dtype=np.float64)
            normal[axis] = 1.0
            terms.extend((
                (f"{label}_high", normal.copy(), hi - float(pos[axis])),
                (f"{label}_low", -normal.copy(), float(pos[axis]) - lo),
            ))
        return terms

    def _workspace_translation_jacobian(
        self,
        q: np.ndarray,
        base_position_m: np.ndarray,
    ) -> np.ndarray | None:
        """Numerically linearize racket translation with respect to arm q."""
        exact_getter = getattr(
            self.controller, "_compute_racket_pose_jacobians_base", None)
        if callable(exact_getter):
            try:
                _pos, _quat, translation, _angular, ok = exact_getter(q)
            except Exception:
                ok = False
                translation = None
            exact = (
                None if translation is None
                else np.asarray(translation, dtype=np.float64))
            if (ok and exact is not None
                    and exact.shape == (3, len(RIGHT_ARM_JOINTS))
                    and np.all(np.isfinite(exact))):
                return exact
        try:
            _position, base_quat, base_ok = (
                self.controller._compute_racket_pose_quat_base(q))
        except Exception:
            return None
        if not base_ok:
            return None
        jacobians = self._workspace_pose_jacobians(
            q, base_position_m, base_quat)
        return None if jacobians is None else jacobians[0]

    def _workspace_pose_linearization(
        self,
        q: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray] | None:
        """Return pose/Jacobians, preferring the exact deployment-model path."""
        exact_getter = getattr(
            self.controller, "_compute_racket_pose_jacobians_base", None)
        if callable(exact_getter):
            try:
                position, quat, translation, angular, ok = exact_getter(q)
            except Exception:
                ok = False
                position = quat = translation = angular = None
            arrays = tuple(
                None if value is None
                else np.asarray(value, dtype=np.float64)
                for value in (position, quat, translation, angular)
            )
            expected_shapes = (
                (3,), (4,), (3, len(RIGHT_ARM_JOINTS)),
                (3, len(RIGHT_ARM_JOINTS)),
            )
            if (ok and all(
                    value is not None
                    and value.shape == shape
                    and np.all(np.isfinite(value))
                    for value, shape in zip(arrays, expected_shapes))):
                return arrays  # type: ignore[return-value]

        try:
            position, quat, ok = (
                self.controller._compute_racket_pose_quat_base(q))
        except Exception:
            return None
        position_vec = np.asarray(position, dtype=np.float64).reshape(-1)
        quat_vec = np.asarray(quat, dtype=np.float64).reshape(-1)
        if (not ok or position_vec.shape[0] != 3 or quat_vec.shape[0] != 4
                or not np.all(np.isfinite(position_vec))
                or not np.all(np.isfinite(quat_vec))):
            return None
        jacobians = self._workspace_pose_jacobians(
            q, position_vec, quat_vec)
        if jacobians is None:
            return None
        return position_vec, quat_vec, jacobians[0], jacobians[1]

    def _workspace_pose_jacobians(
        self,
        q: np.ndarray,
        base_position_m: np.ndarray,
        base_quat_xyzw: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray] | None:
        """Numerically linearize racket translation and angular velocity."""
        q0 = np.asarray(q, dtype=np.float64).reshape(-1)
        base = np.asarray(base_position_m, dtype=np.float64).reshape(3)
        base_quat = np.asarray(base_quat_xyzw, dtype=np.float64).reshape(-1)
        if (q0.shape[0] != len(RIGHT_ARM_JOINTS)
                or base_quat.shape[0] != 4
                or not np.all(np.isfinite(base_quat))):
            return None
        translation = np.zeros(
            (3, len(RIGHT_ARM_JOINTS)), dtype=np.float64)
        angular = np.zeros((3, len(RIGHT_ARM_JOINTS)), dtype=np.float64)
        epsilon = 1e-4
        for idx in range(len(RIGHT_ARM_JOINTS)):
            q_trial = q0.copy()
            step = min(
                epsilon,
                float(RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD[idx]
                      - q0[idx]),
            )
            if step <= 1e-8:
                step = -min(
                    epsilon,
                    float(q0[idx]
                          - RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD[idx]),
                )
            if abs(step) <= 1e-8:
                continue
            q_trial[idx] += step
            try:
                trial_pos, trial_quat, trial_ok = (
                    self.controller._compute_racket_pose_quat_base(q_trial))
            except Exception:
                return None
            trial = np.asarray(trial_pos, dtype=np.float64).reshape(-1)
            if (not trial_ok or trial.shape[0] != 3
                    or not np.all(np.isfinite(trial))):
                return None
            relative_rotvec = _quat_relative_rotvec_xyzw(
                base_quat, trial_quat)
            if relative_rotvec is None:
                return None
            translation[:, idx] = (trial - base) / step
            angular[:, idx] = relative_rotvec / step
        return translation, angular

    def _workspace_hold_state(self, q: np.ndarray) -> dict[str, Any]:
        """Evaluate signed boundary distance for a joint command/measurement."""
        q_vec = self._right_arm_joint_vector_or_none(q)
        if q_vec is None:
            return {
                "valid": False,
                "positionM": None,
                "minDistanceM": None,
                "nearest": None,
                "violationScore": float("inf"),
            }
        try:
            position, _quat, fk_ok = (
                self.controller._compute_racket_pose_quat_base(q_vec))
        except Exception:
            fk_ok = False
            position = None
        pos = (
            None if position is None
            else np.asarray(position, dtype=np.float64).reshape(-1))
        if (not fk_ok or pos is None or pos.shape[0] != 3
                or not np.all(np.isfinite(pos))):
            return {
                "valid": False,
                "positionM": None,
                "minDistanceM": None,
                "nearest": None,
                "violationScore": float("inf"),
            }
        terms = self._workspace_soft_boundary_terms(pos)
        if terms:
            nearest_name, _normal, min_distance = min(
                terms, key=lambda item: float(item[2]))
        else:
            nearest_name = None
            min_distance = float("inf")
        return {
            "valid": True,
            "positionM": _rounded_vector(pos),
            "minDistanceM": float(min_distance),
            "nearest": nearest_name,
            "distancesM": {
                str(name): float(distance)
                for name, _normal, distance in terms
            },
            "violationScore": float(
                self._parking_workspace_violation_score(q_vec)),
        }

    def _filter_command_with_workspace_hold(
        self,
        raw: np.ndarray,
        *,
        profile: str,
        predictive: bool = False,
    ) -> np.ndarray:
        """Hold outward commands and immediately pass FK-verified inward ones.

        The fixed target is exactly the last published command, so engaging the
        hold creates no position-command discontinuity. While held, every new
        policy joint target is evaluated with FK. A target that moves the
        triggering EE constraint inward is passed immediately; an outward or
        worsening target is replaced by the fixed command. No time/dwell gate
        is involved.
        """
        prev_cmd = self.safety_limiter.last_cmd.copy()
        prev_vel = self.safety_limiter.last_vel.copy()
        trigger_margin = max(0.0, float(getattr(
            self.cfg, "workspace_hold_trigger_margin_m", 0.003)))

        feedback_q = None
        ros_bridge = getattr(self, "ros_bridge", None)
        if ros_bridge is not None:
            try:
                feedback_q, _feedback_dq = ros_bridge.get_joint_feedback()
            except Exception:
                feedback_q = None
        measured_q = self._right_arm_joint_vector_or_none(feedback_q)
        measured_state = (
            self._workspace_hold_state(measured_q)
            if measured_q is not None
            else self._workspace_hold_state(prev_cmd))
        feedback_used = measured_q is not None

        desired = np.asarray(raw, dtype=np.float64).reshape(-1)
        if (desired.shape[0] != len(RIGHT_ARM_JOINTS)
                or not np.all(np.isfinite(desired))):
            desired = prev_cmd.copy()
        candidate = self._limiter_free_joint_candidate(
            desired, profile=profile)
        candidate_state = self._workspace_hold_state(candidate)
        prediction_active = bool(
            predictive
            and getattr(self, "workspace_soft_prediction_active", False))
        predicted_constraint = (
            self._predictive_workspace_constraint()
            if prediction_active else "")

        def candidate_moves_inward(
            reference_state: dict[str, Any],
            constraint: str,
            *,
            allow_safely_inset: bool = True,
        ) -> bool:
            """Return true only for an FK candidate improving the boundary.

            The candidate may still be outside when the real arm has already
            crossed a boundary: an acceleration-limited inward step must be
            allowed to recover over successive control ticks. At the same
            time, it may not improve one constraint by creating a larger
            violation elsewhere.
            """
            if (not reference_state.get("valid", False)
                    or not candidate_state.get("valid", False)):
                return False
            reference_score = float(
                reference_state.get("violationScore", float("inf")))
            candidate_score = float(
                candidate_state.get("violationScore", float("inf")))
            candidate_min_distance = float(
                candidate_state.get("minDistanceM", float("-inf")))
            # A target whose FK is already clearly inside every enabled
            # workspace boundary is immediately admissible. This also lets a
            # hold clear as soon as a position target can bring the real arm
            # back in, without waiting for the measured EE pose to arrive.
            if (allow_safely_inset
                    and candidate_score <= 1e-12
                    and candidate_min_distance > trigger_margin):
                return True
            reference_distance = reference_state.get(
                "distancesM", {}).get(constraint)
            candidate_distance = candidate_state.get(
                "distancesM", {}).get(constraint)
            if (constraint and reference_distance is not None
                    and candidate_distance is not None):
                return bool(
                    float(candidate_distance)
                    > float(reference_distance) + 1e-7
                    and candidate_score <= reference_score + 1e-12
                )
            # Positional FK constraints normally have a signed-distance term.
            # This fallback covers any score-only constraint conservatively.
            return bool(candidate_score < reference_score - 1e-12)

        hold_active = bool(getattr(self, "workspace_hold_active", False))
        if hold_active:
            hold_q = self._right_arm_joint_vector_or_none(
                getattr(self, "workspace_hold_q", None))
            if hold_q is None:
                hold_q = prev_cmd.copy()
            hold_state = self._workspace_hold_state(hold_q)
            constraint = str(getattr(
                self, "workspace_hold_constraint", "") or "")
            reference_state = (
                measured_state
                if feedback_used and measured_state.get("valid", False)
                else hold_state)
            if not constraint:
                constraint = str(reference_state.get("nearest") or "")
            reference_distances = reference_state.get("distancesM", {})
            candidate_distances = candidate_state.get("distancesM", {})
            reference_distance = reference_distances.get(constraint)
            candidate_distance = candidate_distances.get(constraint)
            predictive_hold_active = bool(
                str(getattr(
                    self, "workspace_hold_trigger_reason", ""))
                == "predicted_crossing"
                and prediction_active)
            moves_inward = candidate_moves_inward(
                reference_state,
                constraint,
                allow_safely_inset=not predictive_hold_active,
            )
            if moves_inward:
                self.workspace_hold_active = False
                self.workspace_hold_trigger_reason = ""
                self.workspace_hold_constraint = ""
                self.workspace_hold_last_safe_q = candidate.copy()
                self.workspace_soft_filter = {
                    "active": False,
                    "intervened": False,
                    "released": True,
                    "releaseReason": "candidate_fk_moves_inward",
                    "predictive": bool(predictive),
                    "model": "boundary_hold",
                    "holdTargetPosition": _rounded_vector(hold_q),
                    "publishedPosition": _rounded_vector(candidate),
                    "constraint": constraint,
                    "referenceConstraintDistanceM": reference_distance,
                    "candidateConstraintDistanceM": candidate_distance,
                    "feedbackUsed": bool(feedback_used),
                    "measured": measured_state,
                    "candidate": candidate_state,
                    "triggerMarginM": round(float(trigger_margin), 6),
                }
                return candidate

            # The candidate filter was look-ahead only. Re-publish exactly the
            # same target as the previous tick and zero the command integrator;
            # this creates no joint-position step at hold engagement.
            self.safety_limiter.last_cmd = hold_q.copy()
            self.safety_limiter.last_vel = np.zeros_like(hold_q)
            self.workspace_soft_filter = {
                "active": True,
                "intervened": True,
                "released": False,
                "predictive": bool(predictive),
                "model": "boundary_hold",
                "triggerReason": str(getattr(
                    self, "workspace_hold_trigger_reason", "")),
                "constraint": constraint,
                "holdTargetPosition": _rounded_vector(hold_q),
                "publishedPosition": _rounded_vector(hold_q),
                "referenceConstraintDistanceM": reference_distance,
                "candidateConstraintDistanceM": candidate_distance,
                "candidateMovesInward": False,
                "feedbackUsed": bool(feedback_used),
                "measured": measured_state,
                "candidate": candidate_state,
                "triggerMarginM": round(float(trigger_margin), 6),
            }
            return hold_q.copy()

        trigger_reason = ""
        trigger_constraint = ""
        measured_at_boundary = bool(
            measured_state.get("valid", False)
            and (float(measured_state["minDistanceM"]) <= trigger_margin
                 or float(measured_state["violationScore"]) > 1e-12))
        if measured_at_boundary:
            trigger_constraint = str(measured_state.get("nearest") or "")
            if candidate_moves_inward(measured_state, trigger_constraint):
                # The real arm can be at or beyond the boundary while the new
                # joint target is already a recovery command. Pass it on this
                # very tick; waiting for feedback to recover would deadlock a
                # position-controlled robot against the fixed hold target.
                self.workspace_hold_last_safe_q = candidate.copy()
                self.workspace_soft_filter = {
                    "active": False,
                    "intervened": False,
                    "released": True,
                    "releaseReason": "candidate_fk_moves_inward",
                    "predictive": bool(predictive),
                    "model": "boundary_hold",
                    "publishedPosition": _rounded_vector(candidate),
                    "constraint": trigger_constraint,
                    "referenceConstraintDistanceM": measured_state.get(
                        "distancesM", {}).get(trigger_constraint),
                    "candidateConstraintDistanceM": candidate_state.get(
                        "distancesM", {}).get(trigger_constraint),
                    "feedbackUsed": bool(feedback_used),
                    "measured": measured_state,
                    "candidate": candidate_state,
                    "triggerMarginM": round(float(trigger_margin), 6),
                }
                return candidate
            trigger_reason = f"measured:{measured_state.get('nearest')}"
        elif (candidate_state.get("valid", False)
              and (float(candidate_state["minDistanceM"]) <= trigger_margin
                   or float(candidate_state["violationScore"]) > 1e-12)):
            trigger_reason = f"command:{candidate_state.get('nearest')}"
            trigger_constraint = str(candidate_state.get("nearest") or "")
        elif prediction_active:
            trigger_constraint = str(
                predicted_constraint
                or measured_state.get("nearest")
                or candidate_state.get("nearest") or "")
            if not candidate_moves_inward(
                    measured_state,
                    trigger_constraint,
                    allow_safely_inset=False):
                trigger_reason = "predicted_crossing"

        if trigger_reason:
            hold_q = prev_cmd.copy()
            self.workspace_hold_active = True
            self.workspace_hold_q = hold_q.copy()
            self.workspace_hold_trigger_reason = trigger_reason
            self.workspace_hold_constraint = trigger_constraint
            # The candidate was only look-ahead. Keep the exact previously
            # published position and discard its outward command velocity.
            self.safety_limiter.last_cmd = prev_cmd.copy()
            self.safety_limiter.last_vel = np.zeros_like(prev_vel)
            self.workspace_soft_filter = {
                "active": True,
                "intervened": True,
                "released": False,
                "predictive": bool(predictive),
                "model": "boundary_hold",
                "triggerReason": trigger_reason,
                "constraint": trigger_constraint,
                "holdTargetPosition": _rounded_vector(hold_q),
                "publishedPosition": _rounded_vector(hold_q),
                "feedbackUsed": bool(feedback_used),
                "measured": measured_state,
                "candidate": candidate_state,
                "triggerMarginM": round(float(trigger_margin), 6),
            }
            return hold_q.copy()

        if (candidate_state.get("valid", False)
                and float(candidate_state["violationScore"]) <= 1e-12):
            self.workspace_hold_last_safe_q = candidate.copy()
        self.workspace_soft_filter = {
            "active": False,
            "intervened": False,
            "released": False,
            "predictive": bool(predictive),
            "model": "boundary_hold",
            "feedbackUsed": bool(feedback_used),
            "measured": measured_state,
            "candidate": candidate_state,
            "triggerMarginM": round(float(trigger_margin), 6),
        }
        return candidate

    def _legacy_filter_command_with_workspace_soft_field(
        self,
        raw: np.ndarray,
        *,
        profile: str,
        predictive: bool = False,
    ) -> np.ndarray:
        """Apply a continuous Cartesian virtual spring/damper to a q target.

        This is an admittance-style virtual fixture implemented above the
        existing position interface, not a torque-level impedance controller.
        It gradually removes outward Cartesian velocity inside a soft margin
        and adds an inward spring velocity. Tangential policy motion is left
        intact, so the arm can move around near the boundary instead of
        alternating between a frozen target and a released target.
        """
        prev_cmd = self.safety_limiter.last_cmd.copy()
        prev_vel = self.safety_limiter.last_vel.copy()
        desired = np.asarray(raw, dtype=np.float64).reshape(-1)
        if (desired.shape[0] != len(RIGHT_ARM_JOINTS)
                or not np.all(np.isfinite(desired))):
            desired = prev_cmd.copy()

        # First obtain the dynamically reachable policy/compensation command
        # for this tick. The limiter state is restored below before filtering
        # the combined policy + virtual-field velocity.
        candidate = self._limiter_free_joint_candidate(
            desired, profile=profile)
        candidate_vel = (
            (candidate - prev_cmd) / max(self.safety_limiter.dt, 1e-9))
        linearization_q = prev_cmd.copy()
        measured_joint_velocity: np.ndarray | None = None
        feedback_used = False
        ros_bridge = getattr(self, "ros_bridge", None)
        if ros_bridge is not None:
            try:
                feedback_q, feedback_dq = ros_bridge.get_joint_feedback()
            except Exception:
                feedback_q, feedback_dq = None, None
            valid_feedback_q = self._right_arm_joint_vector_or_none(feedback_q)
            if valid_feedback_q is not None:
                linearization_q = valid_feedback_q.copy()
                feedback_used = True
            valid_feedback_dq = self._right_arm_joint_vector_or_none(feedback_dq)
            if valid_feedback_dq is not None:
                measured_joint_velocity = valid_feedback_dq.copy()
        try:
            position, _quat, fk_ok = (
                self.controller._compute_racket_pose_quat_base(
                    linearization_q))
        except Exception:
            fk_ok = False
            position = None
        position_vec = (
            None if position is None
            else np.asarray(position, dtype=np.float64).reshape(-1))
        if (not fk_ok or position_vec is None
                or position_vec.shape[0] != 3
                or not np.all(np.isfinite(position_vec))):
            self.workspace_soft_filter = {
                "active": False,
                "predictive": bool(predictive),
                "model": "virtual_impedance",
                "error": "fk_unavailable",
            }
            return candidate

        margin = max(
            1e-3, float(getattr(self.cfg, "workspace_soft_margin_m", 0.05)))
        boundary_terms = self._workspace_soft_boundary_terms(position_vec)
        active_terms = [
            (name, normal, distance)
            for name, normal, distance in boundary_terms
            if float(distance) < margin
        ]
        predicted_normal = (
            self._predictive_workspace_translation_direction()
            if predictive else None)
        if not active_terms and predicted_normal is None:
            self.workspace_soft_entry_q = None
            self.workspace_soft_filter = {
                "active": False,
                "predictive": False,
                "model": "virtual_impedance",
                "marginM": round(float(margin), 6),
            }
            return candidate

        jacobian = self._workspace_translation_jacobian(
            linearization_q, position_vec)
        if jacobian is None or not np.all(np.isfinite(jacobian)):
            self.workspace_soft_filter = {
                "active": False,
                "predictive": bool(predicted_normal is not None),
                "model": "virtual_impedance",
                "error": "jacobian_unavailable",
            }
            return candidate

        proximity_strengths = [
            float(np.clip(
                (margin - float(distance)) / margin, 0.0, 1.0))
            for _name, _normal, distance in active_terms
        ]
        prediction_urgency = 0.0
        if predicted_normal is not None:
            prediction = getattr(
                getattr(self, "done_monitor", None), "last_prediction", {})
            try:
                time_to_cross = max(0.0, float(prediction.get("time_s", 0.0)))
            except (TypeError, ValueError):
                time_to_cross = 0.0
            horizon = max(
                1e-4, float(getattr(
                    self.cfg, "done_prediction_horizon_s", 0.06)))
            prediction_urgency = float(np.clip(
                1.0 - time_to_cross / horizon, 0.15, 1.0))
        field_blend = max(proximity_strengths + [prediction_urgency, 0.0])
        boundary_speed_scale = float(np.clip(
            getattr(
                self.cfg,
                "workspace_soft_boundary_joint_speed_scale",
                0.35,
            ),
            0.05,
            1.0,
        ))
        policy_velocity_scale = (
            1.0 - field_blend * (1.0 - boundary_speed_scale))
        controlled_candidate_vel = candidate_vel * policy_velocity_scale

        task_velocity = jacobian @ controlled_candidate_vel
        measured_task_velocity = (
            None
            if measured_joint_velocity is None
            else jacobian @ measured_joint_velocity)
        damping_gain = max(
            0.0, float(getattr(self.cfg, "workspace_soft_damping", 1.0)))
        pull_speed = max(
            0.0,
            float(getattr(
                self.cfg, "workspace_soft_pull_speed_m_s", 0.08)),
        )
        correction_velocity = np.zeros(3, dtype=np.float64)
        term_payload: list[dict[str, Any]] = []
        for name, normal, distance in active_terms:
            penetration = max(0.0, -float(distance))
            proximity = float(np.clip(
                (margin - float(distance)) / margin, 0.0, 1.0))
            strength = proximity + min(1.0, penetration / margin)
            outward_speed = max(
                0.0,
                float(np.dot(task_velocity, normal)),
                0.0 if measured_task_velocity is None
                else float(np.dot(measured_task_velocity, normal)),
            )
            correction_speed = (
                damping_gain * proximity * outward_speed
                + pull_speed * strength * strength)
            correction_velocity -= normal * correction_speed
            term_payload.append({
                "name": name,
                "distanceM": round(float(distance), 6),
                "strength": round(float(strength), 6),
                "outwardSpeedMps": round(float(outward_speed), 6),
                "correctionSpeedMps": round(float(correction_speed), 6),
            })

        if predicted_normal is not None:
            urgency = prediction_urgency
            outward_speed = max(
                0.0,
                float(np.dot(task_velocity, predicted_normal)),
                0.0 if measured_task_velocity is None
                else float(np.dot(
                    measured_task_velocity, predicted_normal)),
            )
            correction_speed = (
                0.5 * damping_gain * urgency * outward_speed
                + 0.25 * pull_speed * urgency * urgency)
            correction_velocity -= predicted_normal * correction_speed
            term_payload.append({
                "name": "predicted",
                "distanceM": None,
                "strength": round(float(urgency), 6),
                "outwardSpeedMps": round(float(outward_speed), 6),
                "correctionSpeedMps": round(float(correction_speed), 6),
            })

        correction_limit = max(
            1e-3,
            float(getattr(
                self.cfg,
                "workspace_soft_max_correction_speed_m_s",
                0.30,
            )),
        )
        correction_norm = float(np.linalg.norm(correction_velocity))
        if correction_norm > correction_limit:
            correction_velocity *= correction_limit / correction_norm

        dls = max(
            1e-6,
            float(getattr(self.cfg, "workspace_soft_dls_damping", 0.03)),
        )
        task_matrix = jacobian @ jacobian.T + (dls * dls) * np.eye(3)
        try:
            jacobian_pinv = (
                jacobian.T @ np.linalg.solve(task_matrix, np.eye(3)))
        except np.linalg.LinAlgError:
            jacobian_pinv = np.linalg.pinv(jacobian, rcond=dls)
        joint_correction_velocity = jacobian_pinv @ correction_velocity

        nullspace = (
            np.eye(len(RIGHT_ARM_JOINTS)) - jacobian_pinv @ jacobian)
        nullspace_velocity = nullspace @ controlled_candidate_vel
        nullspace_damping = float(np.clip(
            getattr(self.cfg, "workspace_soft_nullspace_damping", 0.85),
            0.0,
            1.0,
        ))
        entry_q = getattr(self, "workspace_soft_entry_q", None)
        if entry_q is None:
            entry_q = prev_cmd.copy()
            self.workspace_soft_entry_q = entry_q.copy()
        entry_q = np.asarray(entry_q, dtype=np.float64).reshape(-1)
        posture_gain = max(
            0.0,
            float(getattr(
                self.cfg, "workspace_soft_posture_gain_s", 2.0)),
        )
        nullspace_posture_error = nullspace @ (prev_cmd - entry_q)
        joint_field_velocity = (
            joint_correction_velocity
            - field_blend * nullspace_damping * nullspace_velocity
            - field_blend * posture_gain * nullspace_posture_error)
        joint_field_velocity = np.clip(
            joint_field_velocity,
            -0.5 * self.safety_limiter.vel_limit_rad_s,
            0.5 * self.safety_limiter.vel_limit_rad_s,
        )

        combined_target = prev_cmd + self.safety_limiter.dt * (
            controlled_candidate_vel + joint_field_velocity)
        self.safety_limiter.last_cmd = prev_cmd.copy()
        self.safety_limiter.last_vel = prev_vel.copy()
        safe = self._limiter_free_joint_candidate(
            combined_target, profile=profile)
        self.workspace_soft_filter = {
            "active": True,
            "predictive": bool(predicted_normal is not None),
            "model": "virtual_impedance",
            "marginM": round(float(margin), 6),
            "positionM": _rounded_vector(position_vec),
            "feedbackUsed": bool(feedback_used),
            "policyVelocityScale": round(float(policy_velocity_scale), 6),
            "boundaryJointSpeedScale": round(
                float(boundary_speed_scale), 6),
            "candidateJointVelocityRadS": _rounded_vector(candidate_vel),
            "controlledJointVelocityRadS": _rounded_vector(
                controlled_candidate_vel),
            "taskVelocityMps": _rounded_vector(task_velocity),
            "measuredTaskVelocityMps": (
                None if measured_task_velocity is None
                else _rounded_vector(measured_task_velocity)),
            "correctionVelocityMps": _rounded_vector(correction_velocity),
            "jointCorrectionVelocityRadS": _rounded_vector(
                joint_correction_velocity),
            "jointFieldVelocityRadS": _rounded_vector(joint_field_velocity),
            "nullspaceVelocityRadS": _rounded_vector(nullspace_velocity),
            "nullspaceDamping": round(float(nullspace_damping), 6),
            "postureGainS": round(float(posture_gain), 6),
            "terms": term_payload,
            "candidateScore": round(float(
                self._parking_workspace_violation_score(candidate)), 9),
            "selectedScore": round(float(
                self._parking_workspace_violation_score(safe)), 9),
        }
        return safe

    def _legacy_filter_command_with_workspace_guard(
        self,
        raw: np.ndarray,
        *,
        profile: str,
        apply_joint_limits: bool,
        predictive_hold: bool = False,
    ) -> np.ndarray:
        """Keep a joint command near the feasible arm-workspace edge.

        A per-joint projection is preferred over scaling the whole 7-DOF
        displacement.  Scaling the whole displacement freezes valid inward or
        tangential motion whenever only one component points out of the
        workspace.  The component projection removes only the components
        needed to satisfy the boundary and therefore lets the policy move
        along, or return from, the edge.  Every input to this method from a
        soft runtime mode is rate limited before the workspace projection.
        """
        prev_cmd = self.safety_limiter.last_cmd.copy()
        prev_score = self._parking_workspace_violation_score(prev_cmd)
        desired = np.asarray(raw, dtype=np.float64).reshape(-1)
        if (desired.shape[0] != len(RIGHT_ARM_JOINTS)
                or not np.all(np.isfinite(desired))):
            desired = prev_cmd.copy()
        desired = np.clip(
            desired,
            RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
            RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
        )
        predictive_blocked: list[int] = []
        if predictive_hold and prev_score <= 1e-12:
            desired, predictive_blocked = (
                self._remove_predictive_outward_components(
                    prev_cmd, desired))
        if apply_joint_limits:
            candidate = self._limiter_free_joint_candidate(
                desired, profile=profile)
        else:
            candidate = desired.copy()
        candidate_score = self._parking_workspace_violation_score(candidate)
        score_eps = 1e-12
        # If startup/feedback already placed the command just outside the
        # configured envelope, permit motion that does not make the violation
        # worse.  This is the soft-mode recovery behaviour: stay near the edge
        # until the policy points inward, instead of latching done or freezing.
        score_ceiling = (
            float(prev_score) if prev_score > score_eps else score_eps)
        candidate_allowed = bool(
            np.isfinite(candidate_score)
            and candidate_score <= score_ceiling + score_eps)
        if candidate_allowed:
            if not apply_joint_limits:
                self.safety_limiter.last_cmd = candidate.copy()
                self.safety_limiter.last_vel = (
                    (candidate - prev_cmd) / max(float(self.cfg.control_dt), 1e-9))
            self.workspace_soft_filter = {
                "active": bool(
                    predictive_hold or candidate_score > score_eps),
                "intervened": bool(predictive_blocked),
                "predictive": bool(predictive_hold),
                "predictiveBlockedJoints": predictive_blocked,
                "alpha": 1.0,
                "projection": "none",
                "recovering": bool(
                    prev_score > score_eps
                    and candidate_score < prev_score - score_eps),
                "previousScore": round(float(prev_score), 9),
                "candidateScore": round(float(candidate_score), 9),
            }
            return candidate

        delta = candidate - prev_cmd
        selected = prev_cmd.copy()
        alpha_lo = 0.0
        projection = "segment"

        # First try to preserve most joint components.  Starting from the
        # candidate, greedily remove at most three components that contribute
        # most to the violation, then restore as much of each removed component
        # as the boundary permits.  This retains tangential/inward motion and
        # has a bounded number of FK calls in the 200 Hz control path.
        working = candidate.copy()
        working_score = float(candidate_score)
        remaining = [
            idx for idx, value in enumerate(delta)
            if abs(float(value)) > 1e-15
        ]
        removed: list[int] = []
        for _ in range(min(3, len(remaining))):
            best_idx: int | None = None
            best_trial: np.ndarray | None = None
            best_score = working_score
            for idx in remaining:
                trial = working.copy()
                trial[idx] = prev_cmd[idx]
                trial_score = self._parking_workspace_violation_score(trial)
                if (np.isfinite(trial_score)
                        and trial_score < best_score - score_eps):
                    best_idx = idx
                    best_trial = trial
                    best_score = float(trial_score)
            if best_idx is None or best_trial is None:
                break
            working = best_trial
            working_score = best_score
            remaining.remove(best_idx)
            removed.append(best_idx)
            if working_score <= score_ceiling + score_eps:
                selected = working.copy()
                projection = "component"
                # Re-introduce each removed component up to its local feasible
                # boundary. Six iterations are sufficient because the original
                # rate-limited 200 Hz step is already small.
                for idx in reversed(removed):
                    base = selected.copy()
                    full = selected.copy()
                    full[idx] = candidate[idx]
                    full_score = self._parking_workspace_violation_score(full)
                    if (np.isfinite(full_score)
                            and full_score <= score_ceiling + score_eps):
                        selected = full
                        continue
                    lo = 0.0
                    hi = 1.0
                    for _ in range(6):
                        fraction = 0.5 * (lo + hi)
                        trial = base.copy()
                        trial[idx] = (
                            base[idx]
                            + fraction * (candidate[idx] - base[idx]))
                        trial_score = self._parking_workspace_violation_score(
                            trial)
                        if (np.isfinite(trial_score)
                                and trial_score <= score_ceiling + score_eps):
                            lo = fraction
                            selected = trial
                        else:
                            hi = fraction
                break

        if projection == "segment":
            # General fallback for coupled/non-smooth constraints.  Unlike the
            # old implementation this also permits a non-worsening local step
            # when the previous command is already outside the envelope.
            alpha_hi = 1.0
            for _ in range(10):
                alpha = 0.5 * (alpha_lo + alpha_hi)
                trial = prev_cmd + alpha * delta
                trial_score = self._parking_workspace_violation_score(trial)
                if (np.isfinite(trial_score)
                        and trial_score <= score_ceiling + score_eps):
                    alpha_lo = alpha
                    selected = trial
                else:
                    alpha_hi = alpha

        nonzero = np.abs(delta) > 1e-15
        retained_fraction = 0.0
        if np.any(nonzero):
            retained_fraction = float(np.linalg.norm(selected - prev_cmd)
                                      / max(np.linalg.norm(delta), 1e-15))
            component_fractions = np.clip(
                (selected[nonzero] - prev_cmd[nonzero]) / delta[nonzero],
                0.0,
                1.0,
            )
            alpha_lo = float(np.min(component_fractions))
        self.safety_limiter.last_cmd = selected.copy()
        self.safety_limiter.last_vel = (
            (selected - prev_cmd) / self.safety_limiter.dt)
        self.workspace_soft_filter = {
            "active": True,
            "intervened": True,
            "predictive": bool(predictive_hold),
            "predictiveBlockedJoints": predictive_blocked,
            "alpha": round(float(alpha_lo), 6),
            "retainedFraction": round(float(retained_fraction), 6),
            "projection": projection,
            "recovering": bool(prev_score > score_eps),
            "previousScore": round(float(prev_score), 9),
            "candidateScore": round(float(candidate_score), 9),
        }
        return selected.copy()

    def _workspace_filter_feedback(
        self,
        fallback_q: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray | None, bool]:
        """Return the freshest finite arm feedback available to safety."""
        q = np.asarray(fallback_q, dtype=np.float64).reshape(-1).copy()
        dq: np.ndarray | None = None
        feedback_used = False
        feedback_age_s: float | None = None
        feedback_age_supported = False
        feedback_stale = False
        velocity_source = "unavailable"
        ros_bridge = getattr(self, "ros_bridge", None)
        if ros_bridge is not None:
            try:
                age_getter = getattr(
                    ros_bridge, "get_joint_feedback_with_age", None)
                if callable(age_getter):
                    feedback_age_supported = True
                    (feedback_q, feedback_dq, feedback_age_s,
                     velocity_source) = age_getter()
                else:
                    feedback_q, feedback_dq = ros_bridge.get_joint_feedback()
            except Exception:
                feedback_q, feedback_dq = None, None
                if feedback_age_supported:
                    feedback_stale = True
            if feedback_age_supported:
                freshness_limit_s = max(
                    0.025, 3.0 * float(self.safety_limiter.dt))
                feedback_stale = bool(
                    feedback_age_s is None
                    or not math.isfinite(float(feedback_age_s))
                    or float(feedback_age_s) > freshness_limit_s)
            valid_q = self._right_arm_joint_vector_or_none(feedback_q)
            valid_dq = self._right_arm_joint_vector_or_none(feedback_dq)
            if valid_q is not None and not feedback_stale:
                q = valid_q.copy()
                feedback_used = True
            if valid_dq is not None and not feedback_stale:
                dq = valid_dq.copy()
        self._workspace_feedback_age_s = feedback_age_s
        self._workspace_feedback_stale = bool(feedback_stale)
        self._workspace_feedback_age_supported = bool(feedback_age_supported)
        self._workspace_feedback_velocity_source = str(velocity_source)
        return q, dq, feedback_used

    def _workspace_dynamic_velocity_bounds(
        self,
        q: np.ndarray,
        qdot: np.ndarray,
        profile: str,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        """Joint speed/acceleration/position limits for the next control tick."""
        velocity_limit, acceleration_limit = (
            self._workspace_profile_limits(profile))
        dt = max(float(self.safety_limiter.dt), 1e-9)
        lower = np.maximum.reduce((
            -velocity_limit,
            np.asarray(qdot, dtype=np.float64) - acceleration_limit * dt,
            (RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD - q) / dt,
        ))
        upper = np.minimum.reduce((
            velocity_limit,
            np.asarray(qdot, dtype=np.float64) + acceleration_limit * dt,
            (RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD - q) / dt,
        ))
        return lower, upper, velocity_limit

    def _workspace_nonlinear_backstop(
        self,
        previous: np.ndarray,
        selected: np.ndarray,
        *,
        allowed_penetration_m: float = 0.001,
    ) -> tuple[np.ndarray, bool]:
        """Keep nonlinear FK error from turning a local step into a large exit.

        The CBF/QP is linearized at the measured pose.  Box faces are exact,
        while the spherical anchor boundary has curvature.  This final bounded
        line search is normally inactive; it only catches a command predicted
        to cross the outer boundary by more than one millimetre in one tick.
        """
        previous_state = self._workspace_hold_state(previous)
        selected_state = self._workspace_hold_state(selected)
        if (not previous_state.get("valid", False)
                or not selected_state.get("valid", False)):
            return previous.copy(), True
        previous_distance = float(previous_state.get(
            "minDistanceM", float("-inf")))
        selected_distance = float(selected_state.get(
            "minDistanceM", float("-inf")))
        distance_floor = (
            -abs(float(allowed_penetration_m))
            if previous_distance >= -abs(float(allowed_penetration_m))
            else previous_distance)
        if selected_distance >= distance_floor - 1e-9:
            return selected.copy(), False

        low = 0.0
        high = 1.0
        safe = previous.copy()
        delta = selected - previous
        for _ in range(14):
            alpha = 0.5 * (low + high)
            trial = previous + alpha * delta
            trial_state = self._workspace_hold_state(trial)
            trial_distance = float(trial_state.get(
                "minDistanceM", float("-inf")))
            if trial_state.get("valid", False) and trial_distance >= distance_floor:
                low = alpha
                safe = trial
            else:
                high = alpha
        return safe.copy(), True

    def _filter_command_with_workspace_cbf(
        self,
        raw: np.ndarray,
        *,
        profile: str,
        mode: str,
        apply_joint_limits: bool = True,
    ) -> np.ndarray:
        """Legacy helper that limits unsafe Cartesian outward velocity.

        Runtime soft modes now deliberately follow the hard command path and
        use reset-on-done semantics. This helper remains for focused safety
        analysis and compatibility tests. ``position_soft`` uses signed distance,
        ``predictive_soft`` reserves delay/horizon travel, and
        ``impedance_soft`` continuously damps the outward normal component in
        the influence band.  A joint-space QP projection handles simultaneous
        faces while retaining tangential and redundant policy motion.
        """
        mode_name = _workspace_safety_mode(mode, "position_soft")
        if mode_name not in WORKSPACE_SOFT_MODES:
            mode_name = "position_soft"
        predictive = mode_name == "predictive_soft"
        impedance = mode_name == "impedance_soft"
        prev_cmd = self.safety_limiter.last_cmd.copy()
        prev_vel = self.safety_limiter.last_vel.copy()
        dt = max(float(self.safety_limiter.dt), 1e-9)
        self._workspace_antiwindup_position_correction = None
        self._workspace_antiwindup_policy_velocity = None

        desired = np.asarray(raw, dtype=np.float64).reshape(-1)
        invalid_input = bool(
            desired.shape[0] != len(RIGHT_ARM_JOINTS)
            or not np.all(np.isfinite(desired)))
        if invalid_input:
            desired = prev_cmd.copy()
        desired = np.clip(
            desired,
            RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
            RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
        )

        # Preview the dynamically reachable reference exactly once.  Restore
        # state before committing the QP result so no post-projection overwrite
        # can bypass the acceleration limiter as the old implementation did.
        if apply_joint_limits:
            candidate = self._limiter_free_joint_candidate(
                desired, profile=profile)
            candidate_vel = (candidate - prev_cmd) / dt
            self.safety_limiter.last_cmd = prev_cmd.copy()
            self.safety_limiter.last_vel = prev_vel.copy()
        else:
            candidate = desired.copy()
            candidate_vel = (candidate - prev_cmd) / dt
        self._workspace_soft_candidate_q = candidate.copy()
        self._workspace_soft_candidate_vel = candidate_vel.copy()

        feedback_q, feedback_dq, feedback_used = (
            self._workspace_filter_feedback(prev_cmd))
        feedback_stale = bool(getattr(
            self, "_workspace_feedback_stale", False))
        feedback_age_s = getattr(self, "_workspace_feedback_age_s", None)
        if bool(getattr(
                self, "_workspace_feedback_age_supported", False)
                and feedback_stale):
            # No fresh plant state means no valid Cartesian linearization.
            # Smoothly brake the already-published command stream instead of
            # continuing policy on stale q/dq or jumping to a recovery pose.
            if apply_joint_limits:
                safe = self._limiter_free_joint_candidate(
                    prev_cmd, profile=profile)
            else:
                safe = prev_cmd.copy()
                self.safety_limiter.last_cmd = safe.copy()
                self.safety_limiter.last_vel = np.zeros_like(safe)
            self.workspace_soft_filter = {
                "active": True,
                "intervened": True,
                "predictive": bool(predictive),
                "model": "cartesian_velocity_cbf",
                "error": "joint_feedback_stale",
                "emergency": True,
                "feedbackAgeS": feedback_age_s,
                "feedbackVelocitySource": str(getattr(
                    self, "_workspace_feedback_velocity_source", "unavailable")),
                "invalidInput": invalid_input,
            }
            self.workspace_soft_emergency_active = True
            self.workspace_soft_emergency_reason = "feedback_stale"
            return safe
        try:
            position, base_quat, fk_ok = (
                self.controller._compute_racket_pose_quat_base(feedback_q))
        except Exception:
            position, base_quat, fk_ok = None, None, False
        position_vec = (
            None if position is None
            else np.asarray(position, dtype=np.float64).reshape(-1))
        if (not fk_ok or position_vec is None
                or position_vec.shape[0] != 3
                or not np.all(np.isfinite(position_vec))):
            # FK is part of the safety proof.  A missing model cannot justify
            # passing a new target, so brake toward the last published command.
            if apply_joint_limits:
                safe = self._limiter_free_joint_candidate(
                    prev_cmd, profile=profile)
            else:
                safe = prev_cmd.copy()
                self.safety_limiter.last_cmd = safe.copy()
                self.safety_limiter.last_vel = np.zeros_like(safe)
            self.workspace_soft_filter = {
                "active": True,
                "intervened": True,
                "predictive": bool(predictive),
                "model": "cartesian_velocity_cbf",
                "error": "fk_unavailable",
                "invalidInput": invalid_input,
            }
            self.workspace_soft_emergency_active = True
            self.workspace_soft_emergency_reason = "fk_unavailable"
            return safe

        # The optimization variable is the published reference velocity, so
        # its exact kinematic state is ``prev_cmd`` rather than the delayed
        # measured q.  The measured pose remains a second plant-envelope
        # constraint below.  This prevents a 72 ms lead in the command queue
        # from reaching the wall while feedback still appears far away.
        command_linearization = self._workspace_pose_linearization(prev_cmd)
        if command_linearization is None:
            if apply_joint_limits:
                safe = self._limiter_free_joint_candidate(
                    prev_cmd, profile=profile)
            else:
                safe = prev_cmd.copy()
                self.safety_limiter.last_cmd = safe.copy()
                self.safety_limiter.last_vel = np.zeros_like(safe)
            self.workspace_soft_filter = {
                "active": True,
                "intervened": True,
                "predictive": bool(predictive),
                "model": "cartesian_velocity_cbf",
                "error": "jacobian_unavailable",
                "invalidInput": invalid_input,
            }
            self.workspace_soft_emergency_active = True
            self.workspace_soft_emergency_reason = "jacobian_unavailable"
            return safe
        (command_position_vec, _command_quat,
         jacobian, angular_jacobian) = command_linearization

        if apply_joint_limits:
            lower, upper, velocity_scale = (
                self._workspace_dynamic_velocity_bounds(
                    prev_cmd, prev_vel, profile))
        else:
            lower = upper = None
            velocity_scale = self.safety_limiter.vel_limit_rad_s
        _velocity_limit, acceleration_limit = (
            self._workspace_profile_limits(profile))

        measured_vel = (
            prev_vel.copy() if feedback_dq is None else feedback_dq.copy())
        margin = max(
            1e-3, float(getattr(self.cfg, "workspace_soft_margin_m", 0.05)))
        max_approach_speed = max(
            1e-3,
            float(getattr(
                self.cfg,
                "workspace_soft_max_correction_speed_m_s",
                0.30,
            )),
        )
        recovery_speed = max(
            0.0,
            float(getattr(
                self.cfg, "workspace_soft_pull_speed_m_s", 0.08)),
        )
        cbf_gain = max_approach_speed / margin
        damping = float(np.clip(
            getattr(self.cfg, "workspace_soft_damping", 1.0), 0.0, 1.5))

        prediction_horizon = 0.0
        prediction_margin = 0.0
        prediction_signal = False
        predicted_constraint = ""
        predicted_distance: float | None = None
        if predictive:
            monitor = getattr(self, "done_monitor", None)
            prediction_horizon = max(
                0.0,
                float(getattr(
                    monitor,
                    "prediction_horizon_s",
                    getattr(self.cfg, "done_prediction_horizon_s", 0.06),
                )),
            )
            prediction_margin = max(
                0.0,
                float(getattr(
                    monitor,
                    "prediction_margin_m",
                    getattr(self.cfg, "done_prediction_margin_m", 0.005),
                )),
            )
            last_prediction = getattr(monitor, "last_prediction", None)
            prediction_signal = bool(
                feedback_dq is not None
                or getattr(self, "workspace_soft_prediction_active", False)
                or (isinstance(last_prediction, dict)
                    and bool(last_prediction.get("condition"))))
            predicted_constraint = self._predictive_workspace_constraint()
            if predicted_constraint and isinstance(last_prediction, dict):
                try:
                    predicted_position = np.asarray(
                        last_prediction.get("value"),
                        dtype=np.float64,
                    ).reshape(-1)[:3]
                except (TypeError, ValueError):
                    predicted_position = np.empty(0, dtype=np.float64)
                if (predicted_position.shape[0] == 3
                        and np.all(np.isfinite(predicted_position))):
                    for predicted_name, _normal, distance in (
                            self._workspace_soft_boundary_terms(
                                predicted_position)):
                        if str(predicted_name) == predicted_constraint:
                            predicted_distance = float(distance)
                            break

        # The candidate is one dynamically bounded velocity step from
        # ``prev_cmd``; its safety is represented directly by the Jacobian
        # rows below.  Avoid a redundant FK here in the 200 Hz path.
        candidate_distances: dict[str, float] = {}

        feedback_boundary_terms = self._workspace_soft_boundary_terms(
            position_vec)
        feedback_distances = {
            str(name): float(distance)
            for name, _normal, distance in feedback_boundary_terms
        }
        boundary_terms = self._workspace_soft_boundary_terms(
            command_position_vec)
        minimum_distance = min(
            [float(item[2]) for item in boundary_terms]
            + [float(item[2]) for item in feedback_boundary_terms],
            default=float("inf"),
        )
        hard_envelope_m = min(0.010, max(0.005, 0.20 * margin))
        hard_envelope_violation = bool(
            minimum_distance < -hard_envelope_m)
        emergency_active = bool(getattr(
            self, "workspace_soft_emergency_active", False))
        emergency_reason = str(getattr(
            self, "workspace_soft_emergency_reason", ""))
        if hard_envelope_violation:
            emergency_active = True
            emergency_reason = "hard_envelope"
        elif (emergency_active
              and emergency_reason == "hard_envelope"
              and minimum_distance >= min(0.005, 0.10 * margin)):
            emergency_active = False
            emergency_reason = ""

        configured_delay_s = max(
            0.0,
            float(getattr(
                self,
                "_workspace_actuation_delay_s",
                max(0.0, float(getattr(
                    self.cfg, "comp_delay_ms", 0.0))) * 1e-3,
            )),
        )
        actuator_tau_s = max(
            0.0,
            float(getattr(
                self,
                "_workspace_actuator_tau_s",
                getattr(self.cfg, "comp_actuator_tau_s", 0.0),
            )),
        )
        # Keep a 120 ms sampled-data/model uncertainty window (or a larger
        # configured prediction horizon).  This is required even for
        # position_soft: delay + first-order lag is an average response model,
        # not a worst-case bound on queued targets and controller jitter.
        sampled_data_preview_s = max(
            0.12,
            float(getattr(
                self.cfg, "done_prediction_horizon_s", 0.06)))
        plant_response_s = (
            configured_delay_s + actuator_tau_s + dt
            + sampled_data_preview_s)

        rows: list[np.ndarray] = []
        velocity_bounds: list[float] = []
        hard_cbf_bounds: list[float] = []
        impedance_comfort_bounds: list[float] = []
        antiwindup_bounds: list[float] = []
        term_payload: list[dict[str, Any]] = []
        any_bound_relaxed = False
        for name, normal, distance in boundary_terms:
            row = np.asarray(normal, dtype=np.float64) @ jacobian
            nominal_outward = float(np.dot(row, candidate_vel))
            measured_outward = float(np.dot(row, measured_vel))
            command_outward = float(np.dot(row, prev_vel))
            # Reserve only motion already present in the plant/published
            # stream.  ``candidate_vel`` is still a proposal and will be
            # constrained by this very QP; counting an arbitrarily distant
            # target as unavoidable travel would command a spurious inward
            # jump before the arm had begun moving.
            outward_speed = max(
                0.0, measured_outward, command_outward)
            raw_normal_acceleration = float(np.sum(
                np.abs(row) * np.asarray(
                    acceleration_limit, dtype=np.float64)))
            # Sum(|nJ| a_joint) is an optimistic single-face capability; it
            # cannot generally be achieved while respecting another face and
            # preserving racket twist.  Use a conservative Cartesian braking
            # capability for the safe-speed envelope, while the QP still uses
            # the exact per-joint acceleration box.
            normal_acceleration = min(
                raw_normal_acceleration,
                max(0.25, float(getattr(
                    self.cfg,
                    "workspace_soft_braking_acceleration_m_s2",
                    0.5,
                ))),
            )
            stopping_distance = (
                0.0 if outward_speed <= 0.0
                else outward_speed * outward_speed
                / (2.0 * max(normal_acceleration, 1e-6)))
            # All soft modes reserve the travel that is already unavoidable
            # while a newly filtered reference crosses the transport delay and
            # first-order actuator lag.  Predictive mode adds policy/model
            # look-ahead on top; it never replaces the physical reserve.
            plant_reserve = plant_response_s * outward_speed
            predictive_reserve = 0.0
            if predictive and prediction_signal:
                predictive_reserve = (
                    prediction_margin
                    + prediction_horizon * max(
                        outward_speed,
                        min(max_approach_speed, max(0.0, nominal_outward)),
                    ))
            reserve = plant_reserve + predictive_reserve
            feedback_distance = feedback_distances.get(
                str(name), float(distance))
            effective_distance = min(
                float(distance), float(feedback_distance) - reserve)
            if (str(name) == predicted_constraint
                    and predicted_distance is not None):
                effective_distance = min(
                    effective_distance,
                    float(predicted_distance) - prediction_margin,
                )
            candidate_distance = candidate_distances.get(
                str(name), float("inf"))
            if effective_distance >= margin:
                # Braking-feasible velocity damper: outside the influence band
                # allow high policy speed only while enough distance remains
                # to decelerate smoothly to max_approach_speed at the band.
                requested_cbf_bound = math.sqrt(max(
                    0.0,
                    max_approach_speed * max_approach_speed
                    + 2.0 * normal_acceleration
                    * (effective_distance - margin),
                ))
            else:
                requested_cbf_bound = float(np.clip(
                    cbf_gain * effective_distance,
                    -recovery_speed,
                    max_approach_speed,
                ))
            if (effective_distance >= margin
                    and candidate_distance >= margin
                    and nominal_outward <= requested_cbf_bound + 1e-9):
                continue
            reachable_min_outward = float("-inf")
            cbf_bound = requested_cbf_bound
            if lower is not None and upper is not None:
                reachable_min_outward = float(np.sum(np.where(
                    row >= 0.0, row * lower, row * upper)))
                if cbf_bound < reachable_min_outward:
                    cbf_bound = reachable_min_outward
                    any_bound_relaxed = True
            selected_bound = cbf_bound
            strength = _smoothstep01(
                (margin - float(distance)) / margin)
            spring_speed = 0.0
            if impedance:
                penetration = max(0.0, -float(distance))
                spring_speed = min(
                    recovery_speed,
                    cbf_gain * penetration,
                )
                # Comfort damping acts only on the candidate's outward normal
                # component.  Reacting again to delayed measured velocity can
                # over-correct an already-inward command and steer a redundant
                # arm toward another face; measured motion is already covered
                # by the plant reserve in the hard CBF bound.
                outward_reference = max(0.0, nominal_outward)
                requested_impedance_bound = (
                    nominal_outward
                    - damping * strength * outward_reference
                    - spring_speed)
                # The virtual wall is a comfort layer.  It may request more
                # inward speed than the CBF, but it may never request an
                # acceleration-discontinuous command.
                selected_bound = min(cbf_bound, requested_impedance_bound)
                if math.isfinite(reachable_min_outward):
                    if selected_bound < reachable_min_outward:
                        any_bound_relaxed = True
                    selected_bound = max(
                        selected_bound, reachable_min_outward)

            # An inward/sufficiently slow proposal already satisfies this
            # face.  Omitting the no-op inequality avoids over-constraining
            # corners and preserves tangential policy performance.  A
            # proactive impedance spring remains because its bound is strictly
            # below nominal_outward inside the influence band.
            if nominal_outward <= selected_bound + 1e-9:
                continue

            rows.append(np.asarray(row, dtype=np.float64))
            # The optimizer always receives the reachable hard CBF envelope.
            # ``selected_bound`` can be tighter in impedance mode, but that is
            # a best-effort comfort request applied only after hard safety is
            # feasible.  A virtual spring must never create a solver emergency
            # or a different recovery trajectory.
            velocity_bounds.append(float(cbf_bound))
            hard_cbf_bounds.append(float(cbf_bound))
            impedance_comfort_bounds.append(float(selected_bound))
            # Policy anti-windup is allowed to remove rejected outward motion,
            # never to integrate proactive CBF/impedance inward motion.
            antiwindup_bounds.append(max(0.0, float(cbf_bound)))
            term_payload.append({
                "name": str(name),
                "distanceM": round(float(distance), 6),
                "commandDistanceM": round(float(distance), 6),
                "measuredDistanceM": round(float(feedback_distance), 6),
                "effectiveDistanceM": round(float(effective_distance), 6),
                "reserveM": round(float(reserve), 6),
                "plantReserveM": round(float(plant_reserve), 6),
                "stoppingDistanceM": round(float(stopping_distance), 6),
                "predictiveReserveM": round(float(predictive_reserve), 6),
                "candidateDistanceM": (
                    None if not math.isfinite(candidate_distance)
                    else round(float(candidate_distance), 6)),
                "nominalOutwardMps": round(float(nominal_outward), 6),
                "measuredOutwardMps": round(float(measured_outward), 6),
                "commandOutwardMps": round(float(command_outward), 6),
                "normalAccelerationMps2": round(
                    float(normal_acceleration), 6),
                "rawNormalAccelerationMps2": round(
                    float(raw_normal_acceleration), 6),
                "requestedCbfBoundMps": round(
                    float(requested_cbf_bound), 6),
                "reachableMinOutwardMps": (
                    None if not math.isfinite(reachable_min_outward)
                    else round(float(reachable_min_outward), 6)),
                "boundMps": round(float(cbf_bound), 6),
                "comfortBoundMps": round(float(selected_bound), 6),
                "strength": round(float(strength), 6),
                "springSpeedMps": round(float(spring_speed), 6),
            })

        if not rows:
            if emergency_reason != "hard_envelope":
                self.workspace_soft_emergency_active = False
                self.workspace_soft_emergency_reason = ""
            if apply_joint_limits:
                self.safety_limiter.last_cmd = candidate.copy()
                self.safety_limiter.last_vel = candidate_vel.copy()
            else:
                self.safety_limiter.last_cmd = candidate.copy()
                self.safety_limiter.last_vel = candidate_vel.copy()
            self.workspace_soft_filter = {
                "active": False,
                "intervened": False,
                "predictive": bool(predictive),
                "model": (
                    "predictive_cartesian_cbf" if predictive
                    else "virtual_impedance_cbf" if impedance
                    else "cartesian_velocity_cbf"),
                "marginM": round(float(margin), 6),
                "feedbackUsed": bool(feedback_used),
                "feedbackAgeS": feedback_age_s,
                "feedbackVelocitySource": str(getattr(
                    self, "_workspace_feedback_velocity_source", "unavailable")),
                "invalidInput": invalid_input,
                "alpha": 1.0,
                "projection": "none",
            }
            return candidate.copy()

        row_matrix = np.asarray(rows, dtype=np.float64)
        bound_vector = np.asarray(velocity_bounds, dtype=np.float64)
        hard_cbf_bound_vector = np.asarray(
            hard_cbf_bounds, dtype=np.float64)
        impedance_comfort_bound_vector = np.asarray(
            impedance_comfort_bounds, dtype=np.float64)
        antiwindup_bound_vector = np.asarray(
            antiwindup_bounds, dtype=np.float64)
        # Preserve the whole Cartesian twist, not arbitrary joint components.
        # Translation has higher priority; angular tracking prevents the wrist
        # from rotating the racket to obtain a cheap positional correction.
        translation_scale_m_s = max(0.15, max_approach_speed)
        angular_scale_rad_s = 1.0
        joint_regularizer = 0.001 * np.diag(
            1.0 / np.maximum(velocity_scale, 1e-6) ** 2)
        objective_metric = (
            (jacobian.T @ jacobian) / translation_scale_m_s ** 2
            + (angular_jacobian.T @ angular_jacobian)
            / angular_scale_rad_s ** 2
            + joint_regularizer)
        optimization_nominal = candidate_vel
        if emergency_active:
            if lower is not None and upper is not None:
                # Monotonically brake the published joint-velocity stream to
                # zero through the acceleration box.  Chasing delayed feedback
                # here creates a positive-delay loop and can launch the target
                # toward the opposite face; zero-velocity braking is local and
                # contains no global recovery pose.
                optimization_nominal = np.clip(
                    np.zeros_like(candidate_vel),
                    lower,
                    upper,
                )
            else:
                optimization_nominal = np.zeros_like(candidate_vel)
        selected_vel, qp_info = _project_velocity_halfspaces(
            optimization_nominal,
            row_matrix,
            bound_vector,
            lower=lower,
            upper=upper,
            scale=velocity_scale,
            metric=objective_metric,
            max_sweeps=16,
        )
        impedance_comfort_relaxed = False
        if (not qp_info.get("feasible", False)
                and not qp_info.get("uncontrollable", False)):
            # A nearly singular task metric can make alternating projections
            # converge slowly even when the safety set is feasible.  Retry the
            # same (unrelaxed) constraints in well-conditioned scaled joint
            # coordinates.  Safety/dynamics win over objective optimality; the
            # task metric is retained on all ordinary one/two-face ticks.
            task_metric_info = dict(qp_info)
            fallback_vel, fallback_info = _project_velocity_halfspaces(
                optimization_nominal,
                row_matrix,
                bound_vector,
                lower=lower,
                upper=upper,
                scale=velocity_scale,
                max_sweeps=48,
            )
            if fallback_info.get("feasible", False):
                selected_vel = fallback_vel
                qp_info = dict(fallback_info)
                qp_info["taskMetricAttempt"] = task_metric_info
                qp_info["objectiveFallback"] = "scaled_joint_feasible"

        if not bool(qp_info.get("feasible", False)):
            # Never publish an intermediate iterate from an infeasible solve.
            # Its half-space violation can be large and, repeated at a corner,
            # moves the target toward an unrelated workspace face.  The only
            # universally local response is maximum reachable braking of the
            # already-published reference stream.  It obeys the joint dynamic
            # box on this very tick and the emergency latch keeps braking on
            # following ticks; the expanded outer envelope remains the final
            # plant-level containment signal.
            if lower is not None and upper is not None:
                selected_vel = np.clip(
                    np.zeros_like(candidate_vel), lower, upper)
            else:
                selected_vel = np.zeros_like(candidate_vel)
            qp_info = dict(qp_info)
            qp_info["publishedFallback"] = "reachable_zero_velocity_brake"

        impedance_comfort_applied = False
        if (impedance
                and bool(qp_info.get("feasible", False))
                and not emergency_active):
            # Apply the virtual spring/damper as a cheap best-effort projection
            # from the already safe solution.  Every accepted result is
            # rechecked against acceleration/velocity boxes and the hard CBF;
            # when a corner makes the comfort field incompatible, retain the
            # hard solution unchanged.  This preserves local policy motion and
            # makes comfort infeasibility incapable of selecting a far target.
            comfort_vel = selected_vel.copy()
            for _ in range(2):
                changed = False
                for comfort_row, comfort_bound in zip(
                        row_matrix, impedance_comfort_bound_vector):
                    comfort_violation = float(
                        np.dot(comfort_row, comfort_vel) - comfort_bound)
                    if comfort_violation <= 1e-9:
                        continue
                    try:
                        metric_direction = np.linalg.solve(
                            objective_metric, comfort_row)
                    except np.linalg.LinAlgError:
                        metric_direction = np.linalg.pinv(
                            objective_metric) @ comfort_row
                    denominator = float(
                        np.dot(comfort_row, metric_direction))
                    if denominator <= 1e-12:
                        impedance_comfort_relaxed = True
                        continue
                    comfort_vel -= (
                        comfort_violation / denominator) * metric_direction
                    changed = True
                if not changed:
                    break
            comfort_dynamic_ok = bool(
                (lower is None
                 or np.all(comfort_vel >= lower - 1e-8))
                and (upper is None
                     or np.all(comfort_vel <= upper + 1e-8)))
            comfort_hard_ok = bool(np.all(
                row_matrix @ comfort_vel
                <= hard_cbf_bound_vector + 1e-7))
            if comfort_dynamic_ok and comfort_hard_ok:
                impedance_comfort_applied = bool(
                    np.linalg.norm(comfort_vel - selected_vel) > 1e-10)
                selected_vel = comfort_vel
                impedance_comfort_relaxed = bool(np.any(
                    row_matrix @ selected_vel
                    > impedance_comfort_bound_vector + 1e-7))
            else:
                impedance_comfort_relaxed = True

        # Separate policy anti-windup from the published comfort field.  Solve
        # on the policy integrator velocity itself (not the compensated target
        # tracking error), so a zero-action policy remains exactly unchanged
        # while an impedance spring acts only at the actuator-reference layer.
        policy_vel = self._right_arm_joint_vector_or_none(
            getattr(self.controller, "arm_cmd_qvel", None))
        if policy_vel is not None:
            antiwindup_policy_vel, policy_aw_info = (
                _project_velocity_halfspaces(
                    policy_vel,
                    row_matrix,
                    antiwindup_bound_vector,
                    scale=velocity_scale,
                    metric=objective_metric,
                    max_sweeps=24,
                ))
            if (not policy_aw_info.get("feasible", False)
                    and not policy_aw_info.get("uncontrollable", False)):
                fallback_policy_vel, fallback_aw_info = (
                    _project_velocity_halfspaces(
                        policy_vel,
                        row_matrix,
                        antiwindup_bound_vector,
                        scale=velocity_scale,
                        max_sweeps=24,
                    ))
                if fallback_aw_info.get("feasible", False):
                    antiwindup_policy_vel = fallback_policy_vel
            self._workspace_antiwindup_policy_velocity = (
                antiwindup_policy_vel)
            self._workspace_antiwindup_position_correction = (
                (antiwindup_policy_vel - policy_vel) * dt)
        selected = np.clip(
            prev_cmd + selected_vel * dt,
            RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
            RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
        )
        nonlinear_backstop = False
        nonlinear_backstop_deferred = False
        # Never let a Cartesian position clip bypass the joint acceleration
        # limits.  The local FK backstop is accepted only when the QP was
        # feasible and the clipped velocity remains inside *all* dynamic and
        # Cartesian constraints.  Otherwise maximum reachable braking wins.
        linearized_next_distance = min(
            (
                float(term_payload[idx]["commandDistanceM"])
                - dt * float(np.dot(row_matrix[idx], selected_vel))
                for idx in range(row_matrix.shape[0])
            ),
            default=float("inf"),
        )
        backstop_near_outer_edge = bool(
            linearized_next_distance <= 0.006
            or hard_envelope_violation)
        if (bool(qp_info.get("feasible", False))
                and backstop_near_outer_edge):
            backstop_selected, backstop_requested = (
                self._workspace_nonlinear_backstop(prev_cmd, selected))
            if backstop_requested:
                backstop_vel = (backstop_selected - prev_cmd) / dt
                dynamic_ok = bool(
                    (lower is None or np.all(backstop_vel >= lower - 1e-8))
                    and (upper is None or np.all(backstop_vel <= upper + 1e-8)))
                cartesian_ok = bool(np.all(
                    row_matrix @ backstop_vel <= bound_vector + 1e-7))
                if dynamic_ok and cartesian_ok:
                    selected = backstop_selected
                    selected_vel = backstop_vel
                    nonlinear_backstop = True
                else:
                    nonlinear_backstop_deferred = True
        elif not qp_info.get("feasible", False):
            nonlinear_backstop_deferred = True
        selected_vel = (selected - prev_cmd) / dt
        self.safety_limiter.last_cmd = selected.copy()
        self.safety_limiter.last_vel = selected_vel.copy()

        solver_failure = bool(
            not qp_info.get("feasible", False)
            or qp_info.get("uncontrollable", False))
        if solver_failure:
            emergency_active = True
            emergency_reason = "solver_unreachable"
        elif hard_envelope_violation:
            emergency_active = True
            emergency_reason = "hard_envelope"
        elif emergency_reason in {
                "solver_unreachable", "feedback_stale",
                "fk_unavailable", "jacobian_unavailable"}:
            # One or more local tracking-brake ticks restored feasibility.
            emergency_active = False
            emergency_reason = ""
        self.workspace_soft_emergency_active = emergency_active
        self.workspace_soft_emergency_reason = emergency_reason

        correction_vel = selected_vel - candidate_vel
        correction_norm = float(np.linalg.norm(correction_vel))
        nominal_norm = float(np.linalg.norm(candidate_vel))
        retained_fraction = float(
            np.linalg.norm(selected_vel) / max(nominal_norm, 1e-12))
        intervened = bool(
            invalid_input or correction_norm > 1e-8 or nonlinear_backstop)
        model_name = (
            "predictive_cartesian_cbf" if predictive
            else "virtual_impedance_cbf" if impedance
            else "cartesian_velocity_cbf")
        self.workspace_soft_filter = {
            "active": True,
            "intervened": intervened,
            "predictive": bool(predictive),
            "model": model_name,
            "projection": "joint_velocity_qp",
            "alpha": round(float(min(1.0, retained_fraction)), 6),
            "retainedFraction": round(float(retained_fraction), 6),
            "marginM": round(float(margin), 6),
            "cbfGainS": round(float(cbf_gain), 6),
            "predictionHorizonS": round(float(prediction_horizon), 6),
            "predictionMarginM": round(float(prediction_margin), 6),
            "predictionSignal": bool(prediction_signal),
            "plantDelayS": round(float(configured_delay_s), 6),
            "actuatorTauS": round(float(actuator_tau_s), 6),
            "plantResponseReserveS": round(float(plant_response_s), 6),
            "positionM": _rounded_vector(position_vec),
            "commandPositionM": _rounded_vector(command_position_vec),
            "feedbackUsed": bool(feedback_used),
            "feedbackAgeS": feedback_age_s,
            "feedbackVelocitySource": str(getattr(
                self, "_workspace_feedback_velocity_source", "unavailable")),
            "invalidInput": invalid_input,
            "emergency": bool(emergency_active),
            "emergencyReason": str(emergency_reason),
            "hardEnvelopeM": round(float(hard_envelope_m), 6),
            "hardEnvelopeViolation": bool(hard_envelope_violation),
            "boundRelaxedForReachability": bool(any_bound_relaxed),
            "impedanceComfortApplied": bool(impedance_comfort_applied),
            "impedanceComfortRelaxed": bool(impedance_comfort_relaxed),
            "candidateJointVelocityRadS": _rounded_vector(candidate_vel),
            "selectedJointVelocityRadS": _rounded_vector(selected_vel),
            "jointCorrectionVelocityRadS": _rounded_vector(correction_vel),
            "taskVelocityMps": _rounded_vector(jacobian @ candidate_vel),
            "selectedTaskVelocityMps": _rounded_vector(jacobian @ selected_vel),
            "angularVelocityRadS": _rounded_vector(
                angular_jacobian @ candidate_vel),
            "selectedAngularVelocityRadS": _rounded_vector(
                angular_jacobian @ selected_vel),
            "terms": term_payload,
            "qp": dict(qp_info),
            "nonlinearBackstop": bool(nonlinear_backstop),
            "nonlinearBackstopDeferred": bool(nonlinear_backstop_deferred),
            "candidateScore": round(float(
                self._parking_workspace_violation_score(candidate)), 9),
            "selectedScore": round(float(
                self._parking_workspace_violation_score(selected)), 9),
        }
        return selected.copy()

    def _filter_command_with_workspace_soft_field(
        self,
        raw: np.ndarray,
        *,
        profile: str,
        predictive: bool = False,
    ) -> np.ndarray:
        """Compatibility entry point for the bounded virtual-wall mode."""
        return self._filter_command_with_workspace_cbf(
            raw,
            profile=profile,
            mode="predictive_soft" if predictive else "impedance_soft",
            apply_joint_limits=True,
        )

    def _filter_command_with_workspace_guard(
        self,
        raw: np.ndarray,
        *,
        profile: str,
        apply_joint_limits: bool,
        predictive_hold: bool = False,
    ) -> np.ndarray:
        """Legacy compatibility entry point for the workspace CBF helper."""
        return self._filter_command_with_workspace_cbf(
            raw,
            profile=profile,
            mode="predictive_soft" if predictive_hold else "position_soft",
            apply_joint_limits=apply_joint_limits,
        )

    def _apply_workspace_soft_anti_windup(
        self,
        safe: np.ndarray,
        *,
        nominal_q: np.ndarray | None = None,
    ) -> None:
        """Back-calculate only the rejected safety increment into the policy.

        ``safe`` belongs to the actuator-reference layer and can contain up to
        30 degrees of inverse-MPC pre-distortion.  Writing it directly into the
        policy integrator (the previous behavior) mixed two state layers and
        created the observed stop/large-jump release cycle.  Instead, project
        the policy integrator's own outward velocity through the hard CBF only.
        The compensation offset and impedance spring are never integrated into
        the policy, while a rejected outward policy increment cannot wind up.
        """
        published_q = np.asarray(safe, dtype=np.float64).reshape(-1)
        if (published_q.shape[0] != len(RIGHT_ARM_JOINTS)
                or not np.all(np.isfinite(published_q))):
            return

        policy_q = self._right_arm_joint_vector_or_none(nominal_q)
        if policy_q is None:
            policy_q = self._right_arm_joint_vector_or_none(
                getattr(self.controller, "arm_cmd_q", None))
        if policy_q is None:
            return
        policy_vel = self._right_arm_joint_vector_or_none(
            getattr(self.controller, "arm_cmd_qvel", None))
        if policy_vel is None:
            policy_vel = np.zeros(len(RIGHT_ARM_JOINTS), dtype=np.float64)

        position_correction = self._right_arm_joint_vector_or_none(
            getattr(
                self,
                "_workspace_antiwindup_position_correction",
                None,
            ))
        antiwindup_policy_vel = self._right_arm_joint_vector_or_none(
            getattr(
                self,
                "_workspace_antiwindup_policy_velocity",
                None,
            ))
        if position_correction is None and antiwindup_policy_vel is None:
            # FK/feedback/solver emergency braking belongs to the publication
            # layer; without a valid normal-only anti-windup solution, do not
            # invent a policy-state correction.
            self.workspace_soft_filter["antiWindup"] = False
            return
        if position_correction is None:
            position_correction = np.zeros(
                len(RIGHT_ARM_JOINTS), dtype=np.float64)
        if antiwindup_policy_vel is None:
            antiwindup_policy_vel = policy_vel.copy()

        corrected_policy_q = np.clip(
            policy_q + position_correction,
            RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
            RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
        ).astype(np.float32)
        corrected_policy_vel = antiwindup_policy_vel.copy()
        policy_velocity_limit = np.asarray(
            getattr(
                self.controller,
                "arm_vel_limit_rad_s",
                self.safety_limiter.vel_limit_rad_s,
            ),
            dtype=np.float64,
        ).reshape(-1)
        if policy_velocity_limit.shape[0] == len(RIGHT_ARM_JOINTS):
            corrected_policy_vel = np.clip(
                corrected_policy_vel,
                -policy_velocity_limit,
                policy_velocity_limit,
            )
        velocity_correction = corrected_policy_vel - policy_vel
        corrected_policy_vel = corrected_policy_vel.astype(np.float32)

        for name, value in (
            ("arm_cmd_q", corrected_policy_q),
            ("arm_cmd_qvel", corrected_policy_vel),
            ("last_cmd_q", corrected_policy_q),
            ("last_cmd_qvel", corrected_policy_vel),
        ):
            if hasattr(self.controller, name):
                setattr(self.controller, name, value.copy())

        history = getattr(self.controller, "_cmd_history", None)
        if isinstance(history, list) and history:
            # Older elements represent commands already issued in previous
            # ticks and must remain immutable.  Only replace the command just
            # appended by the current policy step.
            newest = self._right_arm_joint_vector_or_none(history[-1])
            if newest is None:
                newest = policy_q.copy()
            history[-1] = np.clip(
                newest + position_correction,
                RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
                RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
            ).astype(np.float32)

        active_tracker = None
        if getattr(self, "last_control_mode", None) == "racket_tracking":
            active_tracker = self.racket_tracker
        elif getattr(self, "last_control_mode", None) == "mpc_juggle":
            active_tracker = self.juggle_tracker
        if active_tracker is not None:
            try:
                active_tracker.observe_nominal_applied(
                    corrected_policy_q, corrected_policy_vel)
                if self.last_control_mode == "racket_tracking":
                    self.last_tracking_info = dict(
                        active_tracker.last_diagnostics)
                else:
                    self.last_juggle_info = dict(self.last_juggle_info)
                    self.last_juggle_info["lowLevel"] = dict(
                        active_tracker.last_diagnostics)
            except Exception as exc:  # noqa: BLE001 - safety output is valid.
                if self.last_control_mode == "racket_tracking":
                    self.last_tracking_info = dict(self.last_tracking_info)
                    self.last_tracking_info["antiWindupError"] = str(exc)
                else:
                    self.last_juggle_info = dict(self.last_juggle_info)
                    self.last_juggle_info["antiWindupError"] = str(exc)

        self.workspace_soft_filter["antiWindup"] = True
        self.workspace_soft_filter["antiWindupModel"] = (
            "outward_rejection_only")
        self.workspace_soft_filter["nominalPositionCorrectionRad"] = (
            _rounded_vector(position_correction))
        self.workspace_soft_filter["nominalVelocityCorrectionRadS"] = (
            _rounded_vector(velocity_correction))

    def _filter_parking_command_with_workspace_guard(
        self,
        raw: np.ndarray,
        *,
        profile: str,
    ) -> np.ndarray:
        """Compatibility wrapper for the existing parking safety path."""
        return self._filter_command_with_workspace_guard(
            raw,
            profile=profile,
            apply_joint_limits=True,
        )

    def _arm_command_stream_from_feedback(self) -> bool:
        """Explicitly arm publishing with one local measured-position hold.

        Dry-run policy state can be far from the physical simulator.  The first
        publish-enabled tick therefore must not use that accumulated target.
        Require fresh joint feedback, reseed every policy/limiter/compensator
        layer from it, and publish exactly one hold.  Normal policy execution
        begins on the following 200 Hz tick.
        """
        if self.ros_bridge is None:
            return False
        feedback_q = None
        feedback_age_s = None
        try:
            getter = getattr(
                self.ros_bridge, "get_joint_feedback_with_age", None)
            if callable(getter):
                feedback_q, _dq, feedback_age_s, _source = getter()
            else:
                feedback_q, _dq = self.ros_bridge.get_joint_feedback()
        except Exception:
            feedback_q = None
        hold_q = self._right_arm_joint_vector_or_none(feedback_q)
        requires_timed_feedback = bool(
            getattr(self, "active_policy_profile", "") in {
                OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85,
                OBSERVATION_PROFILE_GPU1_QACC_FT_V153,
                *FPLC_PROFILES})
        maximum_arm_age_s = (
            0.010 if requires_timed_feedback
            else 0.05
        )
        fresh = bool(
            hold_q is not None
            and ((feedback_age_s is None and not requires_timed_feedback)
                 or (feedback_age_s is not None
                     and math.isfinite(float(feedback_age_s))
                     and float(feedback_age_s) <= maximum_arm_age_s)))
        if not fresh or hold_q is None:
            self.last_command_arm = {
                "armed": False,
                "reason": "fresh_joint_feedback_required",
                "feedbackAgeS": feedback_age_s,
            }
            if self._reset_recovery_active():
                self.reset_publish_blocked = True
                self._require_publish_rearm(
                    "reset_arm_fresh_joint_feedback_required", details={
                        "jointFeedbackAgeS": feedback_age_s,
                        "maximumJointFeedbackAgeS": maximum_arm_age_s,
                    })
            return False
        is_fplc = getattr(self, "active_policy_profile", "") in FPLC_PROFILES
        if not is_fplc:
            hold_q = np.clip(
                hold_q,
                RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
                RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
            )
        self._resume_or_reanchor_active_reset(hold_q)
        # This helper resets recurrent policy command history from current ROS
        # feedback rather than the fixed reset/safe pose.
        self._reset_real_policy_for_sim_reentry()
        if not is_fplc:
            self.safety_limiter.last_cmd = hold_q.copy()
            self.safety_limiter.last_vel = np.zeros_like(hold_q)
            self._reset_servo_target_planner(hold_q)
            self._reset_compensator_to_current_arm(hold_q)
        self._hold_racket_tracker("command_stream_arm_hold", hold_q)
        self._hold_juggle_controller(
            "command stream armed; toggle juggling Start off then on",
            hold_q,
            fault=True,
        )
        self.ros_bridge.publish_right_arm_command(hold_q)
        self.last_policy_nominal_reference = hold_q.copy()
        self.last_compensated_reference = hold_q.copy()
        self.last_published_safe_reference = hold_q.copy()
        self.last_published_command_profile = "arm_hold"
        self.command_stream_active = True
        self.last_command_arm = {
            "armed": True,
            "reason": "explicit_publish_enable",
            "feedbackAgeS": feedback_age_s,
            "jointPosition": _rounded_vector(hold_q),
        }
        return True

    def _publish_hold_on_command_disable(self) -> bool:
        """Stop an active position stream at the latest measured joint pose."""
        if not self.command_stream_active or self.ros_bridge is None:
            return False
        feedback_q = None
        feedback_age_s = None
        try:
            getter = getattr(
                self.ros_bridge, "get_joint_feedback_with_age", None)
            if callable(getter):
                feedback_q, _dq, feedback_age_s, _source = getter()
            else:
                feedback_q, _dq = self.ros_bridge.get_joint_feedback()
        except Exception:
            feedback_q = None
        hold_q = self._right_arm_joint_vector_or_none(feedback_q)
        is_fplc = getattr(self, "active_policy_profile", "") in FPLC_PROFILES
        fresh = bool(
            hold_q is not None
            and ((feedback_age_s is None and not is_fplc)
                 or (feedback_age_s is not None and math.isfinite(float(feedback_age_s))
                     and float(feedback_age_s) <= (0.010 if is_fplc else 0.05))))
        if not fresh or hold_q is None:
            self._hold_racket_tracker(
                "command_stream_disabled_no_fresh_feedback")
            self._hold_juggle_controller(
                "command stream disabled without fresh feedback; "
                "juggling requires rearm",
                fault=True,
            )
            self.command_stream_active = False
            self.last_command_disable_hold = {
                "published": False,
                "feedbackAvailable": bool(hold_q is not None),
                "feedbackFresh": False,
                "feedbackAgeS": feedback_age_s,
                "jointPosition": None,
            }
            print(
                "[CommandSafety][STOP] Send command disabled without fresh "
                "joint feedback; no new target published, stream closed",
                flush=True,
            )
            return False
        if not is_fplc:
            hold_q = np.clip(
                np.asarray(hold_q, dtype=np.float64),
                RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
                RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
            )
        self.ros_bridge.publish_right_arm_command(hold_q)
        if not is_fplc:
            self.safety_limiter.last_cmd = hold_q.copy()
            self.safety_limiter.last_vel = np.zeros_like(hold_q)
            self._reset_servo_target_planner(hold_q)
            self._reset_compensator_to_current_arm(hold_q)
        self._hold_racket_tracker("command_stream_disabled", hold_q)
        self._hold_juggle_controller(
            "command stream disabled; juggling requires rearm",
            hold_q,
            fault=True,
        )
        self.command_stream_active = False
        self.last_published_command_profile = "disabled_hold"
        self.last_command_disable_hold = {
            "published": True,
            "feedbackAvailable": True,
            "feedbackFresh": True,
            "feedbackAgeS": feedback_age_s,
            "jointPosition": _rounded_vector(hold_q),
        }
        print(
            "[CommandSafety][INFO] Send command disabled; published one-shot "
            "hold target from fresh feedback",
            flush=True,
        )
        return True

    def _publish_measured_stop_hold(self) -> bool:
        """Publish exactly one fresh measured-position hold for hard stops."""
        if not self.command_stream_active or self.ros_bridge is None:
            self.command_stream_active = False
            self.last_command_disable_hold = {
                "published": False,
                "feedbackAvailable": False,
                "reason": "stream_inactive_or_ros_unavailable",
                "jointPosition": None,
            }
            return False
        feedback_q = None
        feedback_age_s = None
        try:
            getter = getattr(
                self.ros_bridge, "get_joint_feedback_with_age", None)
            if callable(getter):
                feedback_q, _dq, feedback_age_s, _source = getter()
            else:
                feedback_q, _dq = self.ros_bridge.get_joint_feedback()
        except Exception:
            feedback_q = None
        hold_q = self._right_arm_joint_vector_or_none(feedback_q)
        is_fplc = getattr(self, "active_policy_profile", "") in FPLC_PROFILES
        fresh = bool(
            hold_q is not None
            and ((feedback_age_s is None and not is_fplc)
                 or (feedback_age_s is not None and math.isfinite(float(feedback_age_s))
                     and float(feedback_age_s) <= (0.010 if is_fplc else 0.05))))
        if not fresh or hold_q is None:
            self.command_stream_active = False
            self.last_command_disable_hold = {
                "published": False,
                "feedbackAvailable": False,
                "feedbackAgeS": feedback_age_s,
                "jointPosition": None,
            }
            print(
                "[CommandSafety][STOP] Hard workspace stop could not publish "
                "measured hold; no fresh joint feedback, command stream closed",
                flush=True,
            )
            return False
        if not is_fplc:
            hold_q = np.clip(
                np.asarray(hold_q, dtype=np.float64),
                RightArmCommandSafetyLimiter.POS_LIMIT_LOW_RAD,
                RightArmCommandSafetyLimiter.POS_LIMIT_HIGH_RAD,
            )
        self.ros_bridge.publish_right_arm_command(hold_q)
        if not is_fplc:
            self.safety_limiter.last_cmd = hold_q.copy()
            self.safety_limiter.last_vel = np.zeros_like(hold_q)
            self._reset_servo_target_planner(hold_q)
            self._reset_compensator_to_current_arm(hold_q)
        self._hold_racket_tracker("hard_workspace_stop", hold_q)
        self.last_policy_nominal_reference = hold_q.copy()
        self.last_compensated_reference = hold_q.copy()
        self.last_published_safe_reference = hold_q.copy()
        self.last_published_command_profile = "hard_stop_hold"
        self.command_stream_active = False
        self.last_command_disable_hold = {
            "published": True,
            "feedbackAvailable": True,
            "feedbackAgeS": feedback_age_s,
            "jointPosition": _rounded_vector(hold_q),
        }
        print(
            "[CommandSafety][STOP] Hard workspace done; published one-shot "
            "measured-position hold and closed command stream",
            flush=True,
        )
        return True

    def _hard_workspace_stop_active(self) -> bool:
        return bool(
            getattr(self, "hard_workspace_stop_latched", False)
            and self.done_failsafe_active
        )

    def _latch_hard_workspace_stop(
        self,
        reason: str,
        conditions: dict[str, bool],
    ) -> None:
        self.hard_workspace_stop_latched = True
        self.hard_workspace_stop_reason = str(reason or "hard_workspace_done")
        self.hard_workspace_stop_conditions = {
            str(name): bool(active)
            for name, active in conditions.items()
            if bool(active)
        }
        self.hard_workspace_stop_hold_sent = False
        self.hard_workspace_stop_hold_attempted = False
        print(
            "[CommandSafety][STOP] Hard workspace done latched; "
            "publishing one measured-position hold then rejecting commands "
            f"until reset (reason={self.hard_workspace_stop_reason})",
            flush=True,
        )

    def _stop_hard_workspace_command_stream(self) -> bool:
        """Reject all commands after hard workspace done, except one stop hold."""
        self.compensation_was_enabled = False
        if (not bool(getattr(self, "hard_workspace_stop_hold_sent", False))
                and not bool(getattr(self, "hard_workspace_stop_hold_attempted", False))):
            self.hard_workspace_stop_hold_attempted = True
            held = self._publish_measured_stop_hold()
            self.hard_workspace_stop_hold_sent = bool(held)
            if not held:
                self.command_stream_active = False
                if not isinstance(
                        getattr(self, "last_command_disable_hold", None),
                        dict):
                    self.last_command_disable_hold = {
                        "published": False,
                        "feedbackAvailable": False,
                        "jointPosition": None,
                    }
        else:
            self.command_stream_active = False
        self.last_command_arm = {
            "armed": False,
            "reason": "hard_workspace_done_latched",
            "doneReason": getattr(
                self, "hard_workspace_stop_reason", self.done_failsafe_reason),
            "conditions": dict(getattr(
                self, "hard_workspace_stop_conditions", {})),
        }
        return False

    def _hard_workspace_stop_payload(self) -> dict[str, Any]:
        return {
            "active": bool(getattr(self, "hard_workspace_stop_latched", False)),
            "reason": str(getattr(self, "hard_workspace_stop_reason", "")),
            "conditions": dict(getattr(
                self, "hard_workspace_stop_conditions", {})),
            "holdSent": bool(getattr(
                self, "hard_workspace_stop_hold_sent", False)),
            "holdAttempted": bool(getattr(
                self, "hard_workspace_stop_hold_attempted", False)),
        }

    def _soft_workspace_reset_active(self) -> bool:
        return bool(
            getattr(self, "soft_workspace_reset_latched", False)
            and self.done_failsafe_active
        )

    def _latch_soft_workspace_reset(
        self,
        reason: str,
        conditions: dict[str, bool],
    ) -> None:
        self.soft_workspace_reset_latched = True
        self.soft_workspace_reset_reason = str(
            reason or "soft_workspace_done")
        self.soft_workspace_reset_conditions = {
            str(name): bool(active)
            for name, active in conditions.items()
            if bool(active)
        }
        # Re-anchor the independent bounded reset trajectory at the measured
        # or last-published state.  The safety limiter is never entered.
        reset_seed_q = self._current_arm_reset_reference()
        self._start_supervised_reset(
            reset_seed_q,
            self._current_reset_pose_q(),
            reason=self.soft_workspace_reset_reason,
        )
        if hasattr(self.safety_limiter, "last_cmd"):
            self.safety_limiter.last_cmd = np.asarray(
                reset_seed_q, dtype=np.float64).copy()
            self.safety_limiter.last_vel = np.zeros(
                len(RIGHT_ARM_JOINTS), dtype=np.float64)
        self._reset_servo_target_planner(reset_seed_q)
        self._reset_compensator_to_current_arm(reset_seed_q)
        print(
            "[CommandSafety][RESET] Soft workspace done latched; "
            "commanding the selected reset joint pose until operator reset "
            f"(reason={self.soft_workspace_reset_reason})",
            flush=True,
        )

    def _publish_soft_workspace_reset_command(
        self,
        reset_command_q: object,
    ) -> bool:
        """Publish the reset command already advanced by the control step.

        Advancing here as well as in `_run_one_control_step` used to consume
        two trajectory samples per 200 Hz tick after a soft workspace reset.
        The publication layer must never advance motion state.
        """
        if self.ros_bridge is None or not self.command_stream_active:
            return False
        reset_q = np.asarray(
            reset_command_q, dtype=np.float64).reshape(
                len(RIGHT_ARM_JOINTS)).copy()
        if bool(getattr(self, "reset_publish_blocked", False)):
            self.command_stream_active = False
            return False
        self.ros_bridge.publish_right_arm_command(reset_q)
        self.last_policy_nominal_reference = reset_q.copy()
        self.last_compensated_reference = reset_q.copy()
        self.last_published_safe_reference = np.asarray(
            reset_q, dtype=np.float64).copy()
        self.last_published_command_profile = "reset"
        self.command_stream_active = True
        self.last_command_arm = {
            "armed": False,
            "reason": "soft_workspace_reset_latched",
            "doneReason": str(getattr(
                self,
                "soft_workspace_reset_reason",
                self.done_failsafe_reason,
            )),
            "conditions": dict(getattr(
                self, "soft_workspace_reset_conditions", {})),
            "resetJointPosition": _rounded_vector(reset_q),
        }
        self.last_command_disable_hold = {
            "published": False,
            "feedbackAvailable": False,
            "jointPosition": None,
        }
        return True

    def _soft_workspace_reset_payload(self) -> dict[str, Any]:
        return {
            "active": bool(getattr(
                self, "soft_workspace_reset_latched", False)),
            "reason": str(getattr(
                self, "soft_workspace_reset_reason", "")),
            "conditions": dict(getattr(
                self, "soft_workspace_reset_conditions", {})),
            "targetJointPosition": _rounded_vector(
                self._current_reset_pose_q()),
            "targetJointPositionDeg": _rounded_vector(
                np.rad2deg(self._current_reset_pose_q()), 3),
        }

    def _publish_control_command(
        self,
        q: np.ndarray,
        options: RuntimeOptions,
        *,
        apply_compensation: bool = False,
        compensation_feedback_q: np.ndarray | None = None,
        profile: str = "normal",
    ) -> bool:
        # Avoid carrying a previous tick's source into telemetry when this
        # command exits through a hold/stop path before compensation runs.
        self.last_compensation_feedback_source = "not_applied"
        self.last_compensation_feedback_q = None
        if self._hard_workspace_stop_active():
            return self._stop_hard_workspace_command_stream()
        if self.ros_bridge is None:
            self.compensation_was_enabled = False
            return False
        if not options.publish_commands:
            self.compensation_was_enabled = False
            return self._publish_hold_on_command_disable()
        publish_profile_name = str(profile).strip().lower()
        if (getattr(self, "active_policy_profile", "") in FPLC_PROFILES
                and publish_profile_name != "reset"
                and bool(getattr(self, "publish_rearm_required", False))):
            # The caller can still hold this tick's old RuntimeOptions after
            # inference/profile failure. Never re-arm from that stale request.
            return self._publish_hold_on_command_disable()
        if (publish_profile_name == "reset"
                and bool(getattr(self, "reset_publish_blocked", False))):
            self.compensation_was_enabled = False
            self.command_stream_active = False
            return False
        dq_mode = PolicyDqMode.parse(getattr(
            getattr(self, "cfg", None),
            "policy_dq_mode",
            PolicyDqMode.RAW_COHERENT.value,
        ))
        if (apply_compensation
                and dq_mode is PolicyDqMode.LEGACY_DQ_ONLY_ABLATION):
            impact_limit = int(getattr(
                self.cfg, "incoherent_dq_ablation_max_impacts", 0))
            impact_count = int(getattr(
                self, "incoherent_dq_ablation_inferred_impacts", 0))
            allowed = bool(getattr(
                self.cfg, "allow_incoherent_dq_ablation", False))
            self.last_incoherent_dq_ablation_gate = {
                "allowed": allowed,
                "impactLimit": impact_limit,
                "inferredImpactCount": impact_count,
                "observationCoherence": "incoherent_legacy_ablation",
            }
            if not allowed or impact_limit <= 0 or impact_count >= impact_limit:
                self.compensation_was_enabled = False
                self.last_incoherent_dq_ablation_gate["blocked"] = True
                self.last_incoherent_dq_ablation_gate["reason"] = (
                    "explicit allow and positive remaining impact limit required")
                held = self._publish_hold_on_command_disable()
                self._require_publish_rearm("incoherent_dq_gate_blocked")
                return held
        if not self.command_stream_active:
            self.compensation_was_enabled = False
            return self._arm_command_stream_from_feedback()
        if self._soft_workspace_reset_active():
            self.compensation_was_enabled = False
            reset_command_q = (
                np.asarray(q, dtype=np.float64).copy()
                if publish_profile_name == "reset"
                else self._slow_reset_current_q()
            )
            return self._publish_soft_workspace_reset_command(
                reset_command_q)
        options = self._real_compensation_options(options)
        profile_name = normalize_observation_profile(getattr(
            options,
            "policy_profile",
            OBSERVATION_PROFILE_LEGACY_BUG_COMPAT,
        ))
        is_simcode4_real = bool(
            apply_compensation
            and profile_name == OBSERVATION_PROFILE_SIMCODE4_SERVO67)
        simcode4_upstream_servo = bool(
            is_simcode4_real
            and getattr(self.cfg, "simcode4_real_servo_planner", False))
        self.last_servo_planner_input_q = None
        self.last_servo_planner_output_q = None
        if is_simcode4_real:
            checkpoint_cfg = dict(getattr(
                self.controller, "_checkpoint_env_cfg", {}) or {})
            checkpoint_supports_upstream_servo = bool(
                checkpoint_cfg.get(
                    "arm_servo_target_planner_before_actuator", False))
            self.last_simcode4_plant_order_matches_checkpoint = bool(
                simcode4_upstream_servo
                and checkpoint_supports_upstream_servo)
            if (simcode4_upstream_servo
                    and not checkpoint_supports_upstream_servo):
                # The frozen V5 actor was trained with FOPDT -> planner and
                # cannot be paired silently with an upstream real planner.
                # This gate does not apply to the default planner-off path,
                # which publishes the compensated angle to physical joints.
                self.compensation_was_enabled = False
                self.last_simcode4_publish_block_reason = (
                    "simcode4 checkpoint plant order is FOPDT->planner; "
                    "the optional real servo planner requires a deployable "
                    "V6 checkpoint with planner_before_actuator=true"
                )
                held = self._publish_hold_on_command_disable()
                self._require_publish_rearm("simcode4_plant_order_blocked")
                return held
            self.last_simcode4_publish_block_reason = ""
        raw = np.asarray(q, dtype=np.float64).reshape(-1)
        nominal_q = raw.copy()
        self.last_policy_nominal_reference = nominal_q.copy()
        if apply_compensation:
            raw = self._apply_actuator_compensation(
                raw,
                options,
                feedback_q_override=compensation_feedback_q,
            )
        else:
            self.compensation_was_enabled = False
        matcher_proposed = False
        matcher = getattr(self, "policy_plant_matcher", None)
        matcher_mode = PlantMatcherMode.parse(getattr(
            self.cfg, "policy_plant_matcher_mode", PlantMatcherMode.OFF.value))
        if (matcher is not None
                and matcher_mode is not PlantMatcherMode.OFF
                and apply_compensation
                and str(getattr(options, "control_mode", "")) == "policy"):
            sample = getattr(self, "current_policy_joint_sample", None)
            try:
                if sample is None:
                    raise PlantMatcherFailClosed("joint_state_uninitialized")
                proposal = matcher.propose(nominal_q, sample)
                self.last_matcher_shadow_q = np.asarray(
                    proposal.matcher_shadow_q, dtype=np.float64).copy()
                self.last_matcher_pre_safety_q = np.asarray(
                    proposal.selected_pre_safety_q, dtype=np.float64).copy()
                self.last_policy_plant_matcher_info = dict(
                    proposal.diagnostics)
                raw = self.last_matcher_pre_safety_q.copy()
                matcher_proposed = True
            except (PlantMatcherFailClosed, TypeError, ValueError) as exc:
                self.last_policy_plant_matcher_info = {
                    "mode": matcher_mode.value,
                    "failClosed": True,
                    "reason": str(exc),
                }
                held = self._publish_hold_on_command_disable()
                self._require_publish_rearm("policy_plant_matcher_fault")
                return held
        else:
            self.last_matcher_shadow_q = nominal_q.copy()
            self.last_matcher_pre_safety_q = raw.copy()
        self.last_servo_drive_model_advanced = False
        if simcode4_upstream_servo:
            # Deployable hardware order when MCControlNode/the joint drive does
            # not own simcode4's planner:
            #   inverse MPC -> software planner -> physical delay/FOPDT.
            # Never replay the delay/FOPDT in software: those dynamics are the
            # real joints.  This deliberately differs from the frozen
            # checkpoint's non-deployable simulated order (FOPDT -> planner),
            # and telemetry exposes that mismatch instead of claiming exact
            # plant-order equivalence.
            self.last_servo_planner_input_q = raw.copy()
            raw = np.asarray(
                self.servo_target_planner.step(raw),
                dtype=np.float64,
            ).reshape(-1)
            self.last_servo_planner_output_q = raw.copy()
        self.last_compensated_reference = raw.copy()
        # The workspace filter is downstream of inverse compensation, so an
        # intervention still has to propagate through the real transport
        # delay and actuator lag.  Keep the currently applied runtime plant
        # values available to its stopping-distance reserve.
        self._workspace_actuation_delay_s = max(
            0.0,
            float(getattr(
                options,
                "comp_delay_ms",
                getattr(self.cfg, "comp_delay_ms", 72.0),
            )) * 1e-3,
        )
        self._workspace_actuator_tau_s = max(
            0.0,
            float(getattr(
                options,
                "comp_actuator_tau_s",
                getattr(self.cfg, "comp_actuator_tau_s", 0.074),
            )),
        )
        # Policy, hold, parking, and failsafe commands have no route into
        # RightArmCommandSafetyLimiter.  This is intentionally not a runtime
        # option: mode transitions must never create hidden limiter velocity.
        # Reset uses its independent supervised S-curve. Other parking gates
        # use the local limiter-free rate state below so capture/release/ball-
        # loss transitions cannot turn a reset-pose target into a one-tick
        # jump.
        safe = (
            self._limiter_free_parking_candidate(raw)
            if publish_profile_name == "parking"
            else raw.copy()
        )
        # V85 keeps its own persistent q_ref, so any remaining upstream
        # matcher/compensation rewrite of an *executed actor* target would
        # desynchronise the next observation's q_ref_error and must fail
        # closed. Hold/reset targets do not come from that actor state.
        gpu0_actor_boundary_guard = bool(
            profile_name == OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85
            and publish_profile_name == "normal"
            and str(getattr(options, "control_mode", "policy")) == "policy"
        )
        if gpu0_actor_boundary_guard:
            delta = np.asarray(safe, dtype=np.float64) - nominal_q
            intervened = bool(np.max(np.abs(delta)) > 1e-6)
            streak = int(getattr(
                self, "gpu0_rmp_safety_intervention_streak", 0))
            streak = streak + 1 if intervened else 0
            self.gpu0_rmp_safety_intervention_streak = streak
            self.last_gpu0_rmp_boundary_info = {
                "intervened": intervened,
                "consecutiveTicks": streak,
                "maxAbsCorrectionRad": float(np.max(np.abs(delta))),
                "policyQref": _rounded_vector(nominal_q),
                "safeTarget": _rounded_vector(safe),
                "failClosed": bool(streak >= 3),
            }
            if streak >= 3:
                # A persistent rewrite means the physical path no longer
                # matches the V85 q_ref state. Hold measured position and
                # require an explicit operator re-arm.
                held = self._publish_hold_on_command_disable()
                self._require_publish_rearm(
                    "gpu0_persistent_boundary_intervention")
                self._mark_policy_paused()
                return held
        else:
            self.gpu0_rmp_safety_intervention_streak = 0
        if (getattr(self, "active_policy_profile", profile_name) in FPLC_PROFILES
                and publish_profile_name != "reset"):
            limits = fplc_workspace_intersection((
                self.cfg.ee_x_limits_m, self.cfg.ee_y_limits_m, self.cfg.ee_z_limits_m))
            try:
                feedback_wait_ok = self._wait_for_fplc_joint_feedback(reserve_s=0.0005)
                measured_q, _measured_dq, feedback_age, _source = (
                    self.ros_bridge.get_joint_feedback_with_age())
            except Exception:
                feedback_wait_ok = False
                measured_q, feedback_age = None, None
            actor_target = self._right_arm_joint_vector_or_none(
                getattr(self.controller, "last_cmd_q", None))
            actor_command = bool(
                publish_profile_name == "normal"
                and str(getattr(options, "control_mode", "policy")) == "policy")
            feedback_fresh = bool(
                feedback_wait_ok and measured_q is not None and feedback_age is not None
                and math.isfinite(float(feedback_age))
                and 0.0 <= float(feedback_age) <= FPLC_JOINT_FEEDBACK_MAX_AGE_S)
            command_delta = (
                None if actor_target is None
                else float(np.max(np.abs(safe - actor_target))))
            faults = {
                "joint_feedback_not_fresh": not feedback_fresh,
                "measured_pose_outside_envelope": bool(
                    measured_q is not None
                    and not self.controller.pose_is_safe(measured_q, limits)),
                "target_pose_outside_envelope": not self.controller.pose_is_safe(safe, limits),
                "actor_target_missing": bool(actor_command and actor_target is None),
                "actor_target_rewritten": bool(
                    actor_command and command_delta is not None and command_delta > 1e-6),
            }
            if any(faults.values()):
                details = {
                    "faults": [name for name, active in faults.items() if active],
                    "jointFeedbackAgeS": (
                        float(feedback_age) if feedback_age is not None
                        and math.isfinite(float(feedback_age)) else None),
                    "maximumJointFeedbackAgeS": FPLC_JOINT_FEEDBACK_MAX_AGE_S,
                    "feedbackWaitSucceeded": feedback_wait_ok,
                    "actorCommandDeltaMaxAbsRad": command_delta,
                    "positionLimitsM": [list(pair) for pair in limits],
                    "relativeRollPitchLimitDeg": np.rad2deg(self.controller.real_rp_outer).tolist(),
                }
                # Extra FK only on a stop, never on the normal 200 Hz path.
                for name, q in (("measuredPose", measured_q), ("targetPose", safe)):
                    if self._right_arm_joint_vector_or_none(q) is not None:
                        try:
                            pose = self.controller._pose(q)
                            details[name] = {
                                "positionM": _rounded_vector(pose[2]),
                                "relativeRpyDeg": _rounded_vector(np.rad2deg(pose[3])),
                            }
                        except (RuntimeError, ValueError, np.linalg.LinAlgError):
                            pass
                self.controller.invalidate_after_intervention()
                self._mark_policy_paused()
                self._require_publish_rearm(
                    "fplc_workspace_or_command_boundary_fault", details=details)
                self.done_failsafe_active = True
                self.done_failsafe_reason = "fplc_workspace_or_command_boundary_fault"
                self.done_failsafe_conditions = {"fplc_hard_envelope": True}
                self._latch_hard_workspace_stop(
                    "fplc_workspace_or_command_boundary_fault", {"fplc_hard_envelope": True})
                return self._stop_hard_workspace_command_stream()
        self.ros_bridge.publish_right_arm_command(safe)
        publish_intervals = getattr(self, "policy_publish_intervals", None)
        if (publish_intervals is not None and publish_profile_name == "normal"
                and getattr(options, "control_mode", "policy") == "policy"):
            published_perf = time.perf_counter()
            previous_publish = getattr(self, "policy_publish_last_perf", None)
            if previous_publish is not None:
                publish_intervals.append(published_perf - previous_publish)
            self.policy_publish_last_perf = published_perf
        else:
            self.policy_publish_last_perf = None
        self.last_published_safe_reference = np.asarray(
            safe, dtype=np.float64).copy()
        self.last_published_command_profile = publish_profile_name
        if matcher_proposed and matcher is not None:
            try:
                matcher.observe_published(safe)
            except (PlantMatcherFailClosed, TypeError, ValueError) as exc:
                # Publishing has already succeeded this tick. Fence the next
                # tick to a measured hold and expose the exact failure.
                self.last_policy_plant_matcher_info = {
                    **dict(self.last_policy_plant_matcher_info),
                    "postPublishModelFault": str(exc),
                    "failClosedNextTick": True,
                }
                self.command_stream_active = False
        if (getattr(self, "compensator", None) is not None
                and getattr(self, "compensation_was_enabled", False)):
            try:
                observe_published = getattr(
                    self.compensator, "observe_published", None)
                if callable(observe_published):
                    # The inverse predictor must remember the angle that
                    # actually entered the physical plant. For default
                    # simcode4 this is the compensated angle; with the
                    # explicit planner opt-in it is the planned angle.
                    observe_published(np.asarray(safe, dtype=np.float32))
                    self.workspace_soft_filter[
                        "compensatorAntiWindup"] = True
                if not is_simcode4_real:
                    # simcode3's planner-free plant consumes the published
                    # command directly. Its model advances after downstream
                    # safety feedback, preserving the established contract.
                    advance_applied = getattr(
                        self.compensator, "advance_applied_model", None)
                    if callable(advance_applied):
                        advance_applied()
                # Simcode4 does not advance a software FOPDT.  Encoder feedback
                # supplies actual_q next tick and the physical joint supplies
                # the only actuator delay/lag in the command path.
            except Exception as exc:  # noqa: BLE001 - publishing already succeeded.
                self.compensation_error = f"published feedback failed: {exc}"
        self.command_stream_active = True
        self.last_command_disable_hold = {
            "published": False,
            "feedbackAvailable": False,
            "jointPosition": None,
        }
        return True

    def _start_backend_control_loop(self) -> None:
        if self.control_loop_thread is not None and self.control_loop_thread.is_alive():
            return
        if (self.ros_bridge is not None
                and self.active_policy_profile not in {
                    *FPLC_PROFILES, OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85}):
            self.control_loop_stop.clear()
            self.control_loop_uses_ros_timer = True
            self.ros_bridge.start_backend_control_timer(
                self.cfg.control_dt, self._backend_control_timer_callback)
            return
        self.control_loop_stop.clear()
        self.control_loop_uses_ros_timer = False
        # The fixed 5 ms FPLC/GPU0 loop runs independently of the ROS executor's
        # feedback/camera callback queue. Reads still use atomic measured
        # samples and the same freshness gates; no samples are manufactured.
        self.control_loop_thread = threading.Thread(
            target=self._backend_control_loop,
            name="policy_probe_200hz_control",
            daemon=True,
        )
        self.control_loop_thread.start()

    def shutdown(self) -> None:
        self.control_loop_stop.set()
        if self.ros_bridge is not None:
            self.ros_bridge.stop_backend_control_timer()
        if self.control_loop_thread is not None and self.control_loop_thread.is_alive():
            self.control_loop_thread.join(timeout=1.0)
        self.recorder.shutdown()
        if self.ros_bridge is not None:
            self.ros_bridge.shutdown()
        if self.sim_mirror is not None:
            self.sim_mirror.close()

    def start_recording(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = payload if isinstance(payload, dict) else {}
        if self.recorder.active is True:
            return self.recording_status()
        save_camera_images = payload.get("saveCameraImages", self.cfg.recording_save_camera_images)
        if not isinstance(save_camera_images, bool):
            raise ValueError("saveCameraImages must be a boolean")
        trajectory_only = payload.get("trajectoryOnly", self.cfg.recording_trajectory_only)
        if not isinstance(trajectory_only, bool):
            raise ValueError("trajectoryOnly must be a boolean")
        view = payload.get("view")
        view_payload = view if isinstance(view, dict) else None
        try:
            policy_step_limit = int(payload.get("policyStepLimit", 0) or 0)
        except (TypeError, ValueError):
            policy_step_limit = 0
        policy_step_limit = min(1_000_000, max(0, policy_step_limit))
        with self.lock:
            self.recording_policy_step_limit = policy_step_limit
            self.recording_policy_step_count = 0
            self.recording_policy_step_limit_reached = False
        status = self.recorder.start(
            self.browser_config(), initial_view=view_payload,
            save_camera_images=save_camera_images, trajectory_only=trajectory_only)
        self.recording_save_camera_images = save_camera_images
        status["saveCameraImages"] = save_camera_images
        status["trajectoryOnly"] = trajectory_only
        bridge = getattr(self, 'ros_bridge', None)
        if (save_camera_images and bridge is not None and bool(getattr(self.cfg, 'enable_raw_camera_recording', False))
                and status.get('runDir') and not status.get('error')):
            bridge.set_raw_camera_recording(str(Path(status['runDir'])/'raw_camera'))
        status['rawCamera'] = self.raw_camera_recording_status()
        status["policyStepLimit"] = int(policy_step_limit)
        status["policyStepCount"] = 0
        status["policyStepLimitReached"] = False
        return status

    def stop_recording(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = payload if isinstance(payload, dict) else {}
        bridge = getattr(self, 'ros_bridge', None)
        if bridge is not None and bool(getattr(self.cfg, 'enable_raw_camera_recording', False)):
            bridge.set_raw_camera_recording(None)
        view = payload.get("view")
        freeze_source_seq = max(-1, int(self.control_loop_tick) - 1)
        self.recorder.freeze(freeze_source_seq)
        if not getattr(self.recorder, "trajectory_only", False):
            alignment = {
                "event": "sim_alignment",
                "wallTimeS": time.time(),
                "freezeSourceSeq": freeze_source_seq,
                "simEnabled": bool(self.sim_mirror is not None),
                "flushComplete": self.sim_mirror is None,
                "alignmentValid": self.sim_mirror is None,
            }
            if isinstance(self.sim_mirror, SimMirrorSubprocess):
                try:
                    flush_timeout_s = max(0.0, float(os.environ.get(
                        "SIM_RECORDING_FLUSH_TIMEOUT_S", "5.0")))
                except (TypeError, ValueError):
                    flush_timeout_s = 5.0
                flush = self.sim_mirror.flush(
                    self.sim_mirror.stream_seq, flush_timeout_s)
                self.recorder.record_sim_control_samples(
                    self.sim_mirror.drain_completed_samples())
                alignment.update({
                    "flushComplete": bool(flush.get("complete", False)),
                    "alignmentValid": bool(
                        flush.get("alignmentValid", False)),
                    "flush": flush,
                })
            elif self.sim_mirror is not None:
                alignment.update({
                    "flushComplete": True,
                    "alignmentValid": True,
                })
            self.recorder.record_event(alignment)
        analyze = bool(payload.get("analyze", False))
        status = self.recorder.stop(
            final_view=view if isinstance(view, dict) else None,
            analyze=analyze)
        if not analyze and status.get("runDir") and not status.get("error"):
            # Always generate sensor comparison plots after flush, even when
            # full video/policy analysis was unchecked in the browser.
            status = self.recorder.start_analysis(str(status["runDir"]), ball_sensors_only=True)
        status['rawCamera'] = self.raw_camera_recording_status()
        return status

    def raw_camera_recording_status(self) -> dict[str, Any]:
        if (not bool(getattr(self.cfg, 'enable_raw_camera_recording', False))
                or not getattr(self, "recording_save_camera_images", self.cfg.recording_save_camera_images)):
            return {'enabled': False, 'state': 'disabled'}
        bridge = getattr(self, 'ros_bridge', None)
        if bridge is None:
            return {'enabled': True, 'state': 'unavailable', 'error': 'Camera bridge unavailable'}
        return bridge.raw_camera_recording_status()

    def recording_status(self) -> dict[str, Any]:
        status = self.recorder.status()
        status['rawCamera'] = self.raw_camera_recording_status()
        return status

    def cached_recording_status(self) -> dict[str, Any]:
        return self.recording_status()

    def record_browser_view(self, view: dict[str, Any] | None) -> None:
        self.recorder.record_view(view)

    def record_camera_frame(
        self,
        frame: bytes | None,
        info: dict[str, Any] | None,
    ) -> None:
        self.recorder.record_camera_frame(frame, info)

    def record_sim_frame(
        self,
        frame: bytes | None,
        info: dict[str, Any] | None,
    ) -> None:
        self.recorder.record_sim_frame(frame, info)

    def _run_backend_control_once(self) -> None:
        start = time.perf_counter()
        self.control_tick_started_perf = start
        try:
            self._run_backend_control_tick()
            self.control_loop_last_error = None
        except Exception as exc:
            self.control_loop_last_error = str(exc)
            return
        finally:
            work_s = time.perf_counter() - start
            if work_s > 0.0:
                self.control_loop_run_times.append(work_s)
                if work_s > self.cfg.control_dt:
                    self.control_loop_overrun_count += 1
        now = time.perf_counter()
        if self.control_loop_last_wall is not None:
            elapsed = now - self.control_loop_last_wall
            if elapsed > 0.0:
                self.control_loop_times.append(elapsed)
        self.control_loop_last_wall = now

    def _backend_control_timer_callback(self) -> None:
        if self.control_loop_stop.is_set():
            return
        self._run_backend_control_once()

    def _backend_control_loop(self) -> None:
        if self.active_policy_profile in {*FPLC_PROFILES, OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85}:
            from pingpong_controller.control_runtime import configure_control_thread
            self.control_thread_runtime = configure_control_thread()
            print('[ControlTiming][SCHEDULER] ' + json.dumps(self.control_thread_runtime), flush=True)
        next_t = time.perf_counter()
        dt = self.cfg.control_dt
        while not self.control_loop_stop.is_set():
            self.control_tick_deadline_perf = next_t + dt
            self._run_backend_control_once()
            next_t += dt
            sleep_s = next_t - time.perf_counter()
            if sleep_s > 0.0:
                time.sleep(sleep_s)
            elif sleep_s <= -dt:
                # Drop whole missed periods only when more than one complete
                # control slot late.  A small diagnostic-induced overrun is
                # caught up immediately instead of permanently shifting the
                # 200 Hz schedule by another full 5 ms.
                missed = int((-sleep_s) // dt)
                next_t += missed * dt

    def _control_loop_hz(self) -> float:
        if not self.control_loop_times:
            return 0.0
        avg = sum(self.control_loop_times) / len(self.control_loop_times)
        return 1.0 / avg if avg > 0.0 else 0.0

    def _control_loop_work_ms(self) -> float:
        if not self.control_loop_run_times:
            return 0.0
        avg = sum(self.control_loop_run_times) / len(self.control_loop_run_times)
        return 1000.0 * avg

    def _run_backend_control_tick(self) -> None:
        with self.lock:
            options = self.runtime_options or self._runtime_options_from_payload({})
            scheduling = getattr(self, 'control_thread_runtime', {})
            if (options.publish_commands
                    and scheduling.get('requestedRealtimePriority', 0) > 0
                    and scheduling.get('realtimeApplied') is False
                    and getattr(self.cfg, 'ros_bridge', False)):
                self._require_publish_rearm('control_realtime_unavailable', details=dict(scheduling))
                self._mark_policy_paused()
                held = self._publish_hold_on_command_disable()
                self.latest_snapshot_payload = self.snapshot(
                    'control_schedule_hold', 'control_realtime_unavailable',
                    {'control_realtime_unavailable': True},
                    self.last_ball_pos, self.last_observed_ball_pos,
                    self.last_observed_ball_vel, False, 0., 0.,
                    runtime_options=replace(options, publish_commands=False),
                    use_ros_state=options.use_ros_state, publish_commands=False,
                    command_published=held, raw_valid=False)
                return
            deadline_fault = self.policy_deadline_monitor.start(
                time.perf_counter(),
                self.policy_tick_active and options.publish_commands
                and self.active_policy_profile in {
                    *FPLC_PROFILES, OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85},
                self.active_policy_profile)
            if deadline_fault is not None:
                self.policy_tick_active = False
                self._require_publish_rearm('policy_control_timing_fault', details=deadline_fault)
                self._mark_policy_paused()
                if hasattr(self.controller, 'invalidate_after_intervention'):
                    self.controller.invalidate_after_intervention()
                held = self._publish_hold_on_command_disable()
                self.latest_snapshot_payload = self.snapshot(
                    'policy_timing_hold', 'policy_control_timing_fault',
                    {'policy_control_timing_fault': True},
                    self.last_ball_pos, self.last_observed_ball_pos,
                    self.last_observed_ball_vel, False, 0., 0.,
                    runtime_options=replace(options, publish_commands=False),
                    use_ros_state=options.use_ros_state, publish_commands=False,
                    command_published=held, raw_valid=False)
                return
            if (options.publish_commands
                    and time.monotonic()
                    > float(self.command_publish_lease_deadline_wall)):
                # The browser/client supplies the arm heartbeat.  Losing it
                # follows the normal disable path: one measured-position hold,
                # then no further command stream.
                options = replace(options, publish_commands=False)
                self.runtime_options = options
                self.command_publish_lease_expired = True
                self._require_publish_rearm("command_lease_expired")
            drag_pos = self.web_drag_ball_pos.copy()
            drag_vel = self.web_drag_ball_vel.copy()
            drag_valid = bool(self.web_drag_valid)
            noise_std_m = float(self.web_noise_std_m)
            if (self.ros_bridge is not None
                    and self.cfg.enable_camera_ball
                    and options.camera != self.last_camera_runtime_options):
                self.ros_bridge.set_camera_runtime_options(options.camera)
                self.last_camera_runtime_options = options.camera
            now_wall = time.perf_counter()
            make_snapshot = now_wall >= self.backend_next_snapshot_wall
            snapshot = self._run_control_tick_locked(
                drag_pos, drag_vel, drag_valid, noise_std_m, options,
                make_snapshot=make_snapshot)
            if snapshot is not None:
                self.latest_snapshot_payload = snapshot
                self.recorder.record_snapshot(snapshot)
                self.backend_next_snapshot_wall = (
                    now_wall + self.backend_snapshot_period_s)

    def _racket_pos(self) -> tuple[np.ndarray, bool]:
        pos, ok = self.controller._compute_racket_pose_base(self.controller.arm_cmd_q)
        return np.asarray(pos, dtype=np.float32).reshape(3), bool(ok)

    def _racket_pose(self) -> tuple[np.ndarray, np.ndarray | None, bool]:
        pos, quat, ok = self.controller._compute_racket_pose_quat_base(
            self.controller.arm_cmd_q)
        return (
            np.asarray(pos, dtype=np.float32).reshape(3),
            None if not ok else np.asarray(quat, dtype=np.float32).reshape(4),
            bool(ok),
        )

    def _workspace_safety_racket_pose(
        self,
        options: RuntimeOptions,
    ) -> tuple[np.ndarray, np.ndarray | None, bool]:
        """Select the EE pose used by the real-time workspace monitor.

        Dry-run safety evaluates the command FK. Once hardware publishing is
        enabled, physical joint-state FK is authoritative even if the policy's
        ``useRosState`` option is off. Falling back to command FK is retained
        only when no finite joint feedback/FK is available and is exposed in
        telemetry so it cannot be mistaken for measured safety coverage.
        """
        try:
            command_pos, command_quat, command_ok = self._racket_pose()
        except Exception:
            command_pos = np.zeros(3, dtype=np.float32)
            command_quat = None
            command_ok = False
        selected_pos = command_pos
        selected_quat = command_quat
        selected_ok = bool(command_ok)
        source = "command_fk" if command_ok else "unavailable"
        feedback_age_s: float | None = None

        if bool(getattr(options, "publish_commands", False)):
            source = "command_fk_fallback_no_joint_state"
            q_feedback = None
            if self.ros_bridge is not None:
                try:
                    getter = getattr(
                        self.ros_bridge, "get_joint_feedback_with_age", None)
                    if callable(getter):
                        q_feedback, _dq, feedback_age_s, _dq_source = getter()
                    else:
                        q_feedback, _dq = self.ros_bridge.get_joint_feedback()
                except Exception:
                    q_feedback = None
            q = self._right_arm_joint_vector_or_none(q_feedback)
            if q is not None:
                try:
                    feedback_pos, feedback_quat, feedback_ok = (
                        self.controller._compute_racket_pose_quat_base(q))
                except Exception:
                    feedback_ok = False
                if feedback_ok:
                    selected_pos = np.asarray(
                        feedback_pos, dtype=np.float32).reshape(3)
                    selected_quat = np.asarray(
                        feedback_quat, dtype=np.float32).reshape(4)
                    selected_ok = True
                    fresh = feedback_age_s is None
                    if feedback_age_s is not None:
                        try:
                            age_value_s = float(feedback_age_s)
                            fresh = bool(
                                math.isfinite(age_value_s)
                                and age_value_s <= 0.05)
                        except (TypeError, ValueError):
                            fresh = False
                    source = (
                        "joint_state_fk" if fresh
                        else "stale_joint_state_fk")

        self.last_workspace_safety_pose_source = source
        self.last_workspace_safety_joint_age_s = feedback_age_s
        self.last_workspace_safety_ee_pos = (
            np.asarray(selected_pos, dtype=np.float64).reshape(3).copy()
            if selected_ok else None)
        self.last_workspace_safety_fk_ok = bool(selected_ok)
        return selected_pos, selected_quat, bool(selected_ok)

    def _workspace_safety_pose_payload(self) -> dict[str, Any]:
        ee_pos = getattr(self, "last_workspace_safety_ee_pos", None)
        age_raw = getattr(
            self, "last_workspace_safety_joint_age_s", None)
        age_s = None
        if age_raw is not None:
            try:
                candidate_age_s = float(age_raw)
                if math.isfinite(candidate_age_s):
                    age_s = max(0.0, candidate_age_s)
            except (TypeError, ValueError):
                age_s = None
        return {
            "poseSource": str(getattr(
                self, "last_workspace_safety_pose_source", "unavailable")),
            "jointAgeS": None if age_s is None else round(age_s, 6),
            "fkOk": bool(getattr(
                self, "last_workspace_safety_fk_ok", False)),
            "eePosition": (
                None if ee_pos is None else _rounded_vector(ee_pos)),
        }

    def _workspace_translation_done_conditions(
        self,
        position_m: np.ndarray | None,
        fk_ok: bool,
        workspace_mode: str,
    ) -> dict[str, bool]:
        """Check measured EE x/y/z bounds without any lifecycle gating."""
        if (not fk_ok
                or position_m is None
                or _workspace_safety_mode(workspace_mode) == "off"):
            return {}
        position = np.asarray(position_m, dtype=np.float64).reshape(-1)
        if position.shape[0] != 3 or not np.all(np.isfinite(position)):
            return {}
        out: dict[str, bool] = {}
        for index, (axis, limits) in enumerate(zip(
            ("x", "y", "z"),
            (
                self.cfg.ee_x_limits_m,
                self.cfg.ee_y_limits_m,
                self.cfg.ee_z_limits_m,
            ),
        )):
            if limits is None:
                continue
            lo, hi = limits
            if not bool(float(lo) <= position[index] <= float(hi)):
                out[f"ee_{axis}_out_of_workspace"] = True
        return out

    def _estimator_racket_plane(
        self,
        options: RuntimeOptions,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray] | None:
        """Return the freshest racket plane and linear velocity in SI units."""
        q = np.asarray(self.controller.arm_cmd_q, dtype=np.float64).reshape(-1)
        dq = np.asarray(
            self.controller.arm_cmd_qvel, dtype=np.float64).reshape(-1)
        if options.use_ros_state and self.ros_bridge is not None:
            q_feedback, dq_feedback = self.ros_bridge.get_joint_feedback()
            if q_feedback is not None:
                q = np.asarray(q_feedback, dtype=np.float64).reshape(-1)
                dq = (
                    np.zeros_like(q)
                    if dq_feedback is None
                    else np.asarray(
                        dq_feedback, dtype=np.float64).reshape(-1))
        try:
            position, quaternion, jacobian_position, _jacobian_rotation, ok = (
                self.controller._compute_racket_pose_jacobians_base(q))
            if not ok:
                return None
            position = np.asarray(position, dtype=np.float64).reshape(3)
            normal = racket_normal_from_quaternion_xyzw(quaternion)
            jacobian_position = np.asarray(
                jacobian_position, dtype=np.float64).reshape(3, q.shape[0])
            if dq.shape != q.shape or not np.all(np.isfinite(dq)):
                velocity = np.zeros(3, dtype=np.float64)
            else:
                velocity = jacobian_position @ dq
            return position, normal, velocity
        except Exception:
            return None

    def _ros_joint_racket_pos(self) -> tuple[np.ndarray | None, bool]:
        if self.ros_bridge is None:
            return None, False
        q_fb, _dq_fb = self.ros_bridge.get_joint_feedback()
        if q_fb is None:
            return None, False
        pos, ok = self.controller._compute_racket_pose_base(q_fb)
        if not ok:
            return None, False
        return np.asarray(pos, dtype=np.float32).reshape(3), True

    def _ros_cart_pose(
        self,
    ) -> tuple[np.ndarray | None, np.ndarray | None, float | None]:
        if self.ros_bridge is None:
            return None, None, None
        return self.ros_bridge.get_cart_feedback()

