def _prewarm_jax_cuda_for_mjx(cfg: ProbeConfig) -> None:
    if (not bool(cfg.enable_sim_mirror)
            or bool(getattr(cfg, "sim_subprocess", False))
            or str(cfg.sim_backend).strip().lower() != "mjx"):
        return
    _prewarm_jax_cuda_backend(str(cfg.sim_backend))


def _validate_release_before_runtime(args: argparse.Namespace) -> dict[str, Any]:
    """Verify selected bytes before constructing anything that can publish."""
    profile = normalize_observation_profile(args.policy_profile)
    if profile in FPLC_PROFILES:
        checkpoint_path, xml_path = fplc_assets(profile)
    elif profile == OBSERVATION_PROFILE_SIMCODE5_PURE_ACTUATOR67:
        checkpoint_path = args.simcode5_model_path
        xml_path = args.simcode5_policy_xml_path
    elif profile == OBSERVATION_PROFILE_SIMCODE6_QVEL67:
        checkpoint_path = args.simcode6_model_path
        xml_path = args.simcode6_policy_xml_path
    elif profile == OBSERVATION_PROFILE_GPU0_QVEL_REAL_RMP_V85:
        checkpoint_path = args.simcode7_model_path
        xml_path = args.simcode7_policy_xml_path
    elif profile == OBSERVATION_PROFILE_GPU1_QACC_FT_V153:
        checkpoint_path = args.gpu1_qacc_ft_model_path
        xml_path = args.gpu1_qacc_ft_policy_xml_path
    else:
        raise ReleaseContractError(
            f"policy profile {profile!r} has no versioned live release")
    environment_overrides = {
        key: os.environ[key]
        for key in (
            "POLICY_RELEASE_ID",
            "POLICY_PROFILE",
            "SIMCODE5_MODEL_PATH",
            "SIMCODE5_POLICY_XML_PATH",
            "SIMCODE6_MODEL_PATH",
            "SIMCODE6_POLICY_XML_PATH",
            "SIMCODE7_MODEL_PATH",
            "SIMCODE7_POLICY_XML_PATH",
            "SIMCODE7_V97_MODEL_PATH",
            "SIMCODE8_POLICY_XML_PATH",
            "GPU1_QACC_FT_MODEL_PATH",
            "GPU1_QACC_FT_POLICY_XML_PATH",
            "POLICY_OBS_DIM",
            "CONTROL_RATE_HZ",
            "BALL_OBSERVATION_RATE_HZ",
            "POLICY_DQ_MODE",
            "POLICY_PLANT_MATCHER_MODE",
            "POLICY_PLANT_MATCHER_REAL_CONFIG",
            "ALLOW_POLICY_PLANT_MATCHER_APPLY",
        )
        if key in os.environ
    }
    # Persist effective parser values as well as the literal environment.
    # This keeps direct Python CLI launches just as auditable as the shell
    # entry point, without trying to infer which argparse values were defaults.
    explicit = {
        "environment": environment_overrides,
        "effective_cli": {
            "policy_release_manifest": str(args.policy_release_manifest),
            "policy_release_id": str(args.policy_release_id),
            "policy_profile": profile,
            "checkpoint_path": str(checkpoint_path),
            "policy_xml_path": str(xml_path),
            "policy_obs_dim": int(args.policy_obs_dim),
            "control_rate_hz": float(args.control_rate_hz),
            "ball_observation_rate_hz": float(
                args.ball_observation_rate_hz),
            "policy_dq_mode": str(getattr(
                args, "policy_dq_mode", "raw_coherent")),
            "policy_plant_matcher_mode": str(getattr(
                args, "policy_plant_matcher_mode", "shadow")),
            "policy_plant_matcher_real_config": str(getattr(
                args, "policy_plant_matcher_real_config", "")),
            "allow_policy_plant_matcher_apply": bool(getattr(
                args, "allow_policy_plant_matcher_apply", False)),
            "policy_ball_handover_mode": str(getattr(
                args, "policy_ball_handover_mode",
                "legacy_force_fresh")),
        },
    }
    validated = validate_policy_release(
        args.policy_release_manifest,
        args.policy_release_id,
        REPO_ROOT,
        policy_profile=profile,
        checkpoint_path=checkpoint_path,
        policy_xml_path=xml_path,
        observation_dim=int(args.policy_obs_dim),
        control_rate_hz=float(args.control_rate_hz),
        deployment_ball_observation_rate_hz=float(
            args.ball_observation_rate_hz),
        policy_dq_mode=str(getattr(args, "policy_dq_mode", "raw_coherent")),
        explicit_overrides=explicit,
    )
    payload = validated.as_dict()
    os.environ["POLICY_RELEASE_CONTRACT_JSON"] = json.dumps(
        payload, sort_keys=True, separators=(",", ":"))
    return payload


def main(argv: list[str] | None = None) -> int:
    args = build_arg_parser().parse_args(argv)
    try:
        release_contract = _validate_release_before_runtime(args)
    except ReleaseContractError as exc:
        print(f"ERROR: policy release contract failed: {exc}", file=sys.stderr)
        return 2
    print(
        "[ProbeConfig] validated release "
        f"id={release_contract['release_id']} "
        f"manifest_sha256={release_contract['manifest_sha256']} "
        f"checkpoint_sha256={release_contract['checkpoint_sha256']} "
        f"xml_sha256={release_contract['policy_xml_sha256']}")
    cfg = config_from_args(args)
    if bool(args.control_subprocess):
        cfg.backend_control_loop = True
    if not (bool(args.control_subprocess) and not bool(args.smoke_test)):
        _prewarm_jax_cuda_for_mjx(cfg)
    probe = (
        ControlSubprocessProxy(cfg)
        if bool(args.control_subprocess) and not bool(args.smoke_test)
        else PolicySafetyProbe(cfg)
    )

    def _main_shutdown_signal(_signum, _frame) -> None:
        raise KeyboardInterrupt

    for sig_name in ("SIGINT", "SIGTERM"):
        sig = getattr(signal, sig_name, None)
        if sig is None:
            continue
        try:
            signal.signal(sig, _main_shutdown_signal)
        except Exception:
            pass

    if args.smoke_test:
        try:
            ball = np.asarray(probe.initial_ball_pos(), dtype=np.float32)
            first = probe.step({"ball": ball.tolist(), "velocity": [0, 0, 0], "valid": True, "dt": 0.02})
            released_ball = ball.copy()
            released_ball[2] -= max(0.03, cfg.ball_release_min_z_drop_m * 2.0)
            released = probe.step({
                "ball": released_ball.tolist(),
                "velocity": [0, 0, -0.6],
                "valid": True,
                "dt": max(0.04, cfg.ball_release_window_s),
            })
            probe.step({"ball": ball.tolist(), "velocity": [0, 0, 0], "valid": False, "dt": 0.25})
            hidden = probe.step({"ball": ball.tolist(), "velocity": [0, 0, 0], "valid": False, "dt": 0.25})
            noisy = probe.step({
                "ball": ball.tolist(),
                "velocity": [0, 0, 0],
                "valid": True,
                "noiseStdM": max(0.003, cfg.ball_noise_std_m),
                "dt": 0.02,
            })
            print(json.dumps({
                "first_mode": first["mode"],
                "released_mode": released["mode"],
                "hidden_mode": hidden["mode"],
                "noisy_observed_ball": noisy["observedBall"],
                "ros_enabled": first["ros"]["enabled"],
                "ros_publish_commands": first["ros"]["publishCommands"],
                "anchor": first["anchor"],
                "racket": first["racket"],
                "actionAbsMax": first["actionAbsMax"],
            }, indent=2))
        finally:
            probe.shutdown()
        return 0

    httpd = None
    try:
        ProbeRequestHandler.probe = probe
        httpd = ThreadingHTTPServer((cfg.host, cfg.port), ProbeRequestHandler)
        url = f"http://{cfg.host}:{cfg.port}/"
        print("========================================================================")
        print("Interactive policy safety probe")
        print("========================================================================")
        print(f"URL: {url}")
        print(
            f"RL profile: {cfg.policy_profile} "
            "(runtime-switchable with sim mirror lockstep)")
        print(f"Legacy model: {cfg.model_path}")
        print(f"Simcode2 ideal-PD67 model: {cfg.simcode2_model_path}")
        print(f"Simcode3 actuator67 model: {cfg.simcode3_model_path}")
        print(f"Simcode4 servo67 model: {cfg.simcode4_model_path}")
        print(f"Simcode5 pure-actuator67 model: {cfg.simcode5_model_path}")
        print(f"Simcode6 qvel67 model: {cfg.simcode6_model_path}")
        print(f"GPU0-QVEL/REAL-RMP selected model: {cfg.simcode7_model_path}")
        print(f"GPU0-QVEL/REAL-RMP V85 model: {cfg.simcode7_v85_model_path}")
        print(f"GPU0-QVEL/REAL-RMP V91 model: {cfg.simcode7_v91_model_path}")
        print(f"GPU0-QVEL/REAL-RMP V97 model: {cfg.simcode7_v97_model_path}")
        print(f"GPU1-QACC-FT V153 model: {cfg.gpu1_qacc_ft_model_path}")
        print(f"Robot XML: {cfg.robot_xml_path}")
        if cfg.enable_sim_mirror:
            print(
                "Sim mirror: "
                f"backend={cfg.sim_backend}, xml={cfg.sim_xml_path}, "
                f"renderer={cfg.sim_use_mujoco_renderer}")
        if cfg.enable_camera_ball:
            if cfg.camera_source_mode == "direct_realsense":
                print(
                    "Camera: "
                    f"source=direct_realsense, hybrid={cfg.use_hybrid_detector}, "
                    f"depth={cfg.use_depth_sensor}, "
                    f"{cfg.image_width}x{cfg.image_height}@{cfg.realsense_fps}, "
                    f"ir={cfg.ir_params_json}")
            else:
                print(
                    "Camera: "
                    f"source=ros_topic, transport={cfg.camera_image_transport}, "
                    f"compressed={cfg.camera_image_topic}, "
                    f"raw={cfg.camera_raw_image_topic}, "
                    f"info={cfg.camera_info_topic}")
        if cfg.enable_mocap_ball:
            print(
                "Mocap: "
                f"udp={cfg.mocap_udp_host}:{cfg.mocap_udp_port}, "
                f"marker={cfg.mocap_marker_id}, "
                f"unit={cfg.mocap_position_unit}, "
                f"calibration={cfg.mocap_calibration_path or 'identity'}")
        print("Press Ctrl-C to stop.")
        print("")
        if args.open_browser:
            try:
                webbrowser.open(url)
            except Exception:
                pass
        httpd.serve_forever(poll_interval=0.25)
    except KeyboardInterrupt:
        print("\n[probe] stopped")
    finally:
        if httpd is not None:
            httpd.server_close()
        probe.shutdown()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
